/// Pure, engine-owned musical authority.  It is deliberately independent of
/// the 25 ms UI/media poll and can therefore be reused by the future native
/// audio worker without duplicating tempo or meter arithmetic.
#[derive(Debug, Clone, PartialEq)]
pub struct TimelineTempoMeterAuthority {
    fallback_bpm: f64,
    points: Vec<TimelineTempoMeterPoint>,
}

impl TimelineTempoMeterAuthority {
    pub fn new(fallback_bpm: f64, points: Vec<TimelineTempoMeterPoint>) -> Result<Self, String> {
        if !fallback_bpm.is_finite()
            || !(protocol::TIMELINE_TEMPO_MIN_BPM..=protocol::TIMELINE_TEMPO_MAX_BPM)
                .contains(&fallback_bpm)
        {
            return Err("Timeline fallback BPM must be finite and within 20..=300".to_string());
        }
        validate_timeline_tempo_meter_map(protocol::TIMELINE_TEMPO_METER_MAP_VERSION, &points)?;
        Ok(Self {
            fallback_bpm,
            points,
        })
    }

    pub fn from_timeline(timeline: &TimelineSnapshot, fallback_bpm: f64) -> Result<Self, String> {
        if timeline.tempo_meter_map_version > protocol::TIMELINE_TEMPO_METER_MAP_VERSION {
            return Err(format!(
                "Timeline tempo/meter map version {} is newer than supported version {}",
                timeline.tempo_meter_map_version,
                protocol::TIMELINE_TEMPO_METER_MAP_VERSION
            ));
        }
        if timeline.tempo_meter_map.is_empty() {
            return Self::new(fallback_bpm, Vec::new());
        }
        validate_timeline_tempo_meter_map(
            timeline.tempo_meter_map_version,
            &timeline.tempo_meter_map,
        )?;
        Self::new(fallback_bpm, timeline.tempo_meter_map.clone())
    }

    pub fn fallback_bpm(&self) -> f64 {
        self.fallback_bpm
    }

    pub fn points(&self) -> &[TimelineTempoMeterPoint] {
        &self.points
    }

    pub fn bpm_at_quarter_beat(&self, quarter_beat: f64) -> Result<f64, String> {
        if !quarter_beat.is_finite() || quarter_beat < 0.0 {
            return Err(
                "Timeline quarter-beat position must be finite and non-negative".to_string(),
            );
        }
        let mut previous_position = 0.0;
        let mut previous_bpm = self.fallback_bpm;
        for (index, point) in self.points.iter().enumerate() {
            let position = timeline_point_quarter_beats(point)?;
            if quarter_beat < position {
                return Ok(previous_bpm);
            }
            if quarter_beat == position {
                return Ok(point.bpm);
            }
            let Some(next) = self.points.get(index + 1) else {
                return Ok(point.bpm);
            };
            if quarter_beat < timeline_point_quarter_beats(next)? {
                return interpolate_timeline_bpm(point, next, quarter_beat - position);
            }
            previous_position = position;
            previous_bpm = point.bpm;
        }
        let _ = previous_position;
        Ok(previous_bpm)
    }

    pub fn meter_at_quarter_beat(&self, quarter_beat: f64) -> Result<(u8, u8), String> {
        if !quarter_beat.is_finite() || quarter_beat < 0.0 {
            return Err(
                "Timeline quarter-beat position must be finite and non-negative".to_string(),
            );
        }
        let mut meter = (4, 4);
        for point in &self.points {
            if quarter_beat < timeline_point_quarter_beats(point)? {
                break;
            }
            meter = (point.numerator, point.denominator);
        }
        Ok(meter)
    }

    /// Return elapsed seconds from the Timeline origin using exact analytic
    /// integration for linear BPM slew.  `round` is deliberately deferred to
    /// sample-frame conversion so phase remains continuous across segments.
    pub fn seconds_at_quarter_beat(&self, quarter_beat: f64) -> Result<f64, String> {
        if !quarter_beat.is_finite() || quarter_beat < 0.0 {
            return Err(
                "Timeline quarter-beat position must be finite and non-negative".to_string(),
            );
        }
        let Some(first) = self.points.first() else {
            return finite_seconds(timeline_bpm_segment_seconds(
                self.fallback_bpm,
                quarter_beat,
                self.fallback_bpm,
                TimelineTempoInterpolation::Step,
            )?);
        };
        let first_position = timeline_point_quarter_beats(first)?;
        if quarter_beat <= first_position {
            return finite_seconds(timeline_bpm_segment_seconds(
                self.fallback_bpm,
                quarter_beat,
                self.fallback_bpm,
                TimelineTempoInterpolation::Step,
            )?);
        }
        let mut elapsed = if first_position > 0.0 {
            timeline_bpm_segment_seconds(
                self.fallback_bpm,
                first_position,
                self.fallback_bpm,
                TimelineTempoInterpolation::Step,
            )?
        } else {
            0.0
        };
        for (index, point) in self.points.iter().enumerate() {
            let start = timeline_point_quarter_beats(point)?;
            let Some(next) = self.points.get(index + 1) else {
                elapsed += timeline_bpm_segment_seconds(
                    point.bpm,
                    quarter_beat - start,
                    point.bpm,
                    TimelineTempoInterpolation::Step,
                )?;
                return finite_seconds(elapsed);
            };
            let end = timeline_point_quarter_beats(next)?;
            if quarter_beat <= start {
                return finite_seconds(elapsed);
            }
            if quarter_beat < end {
                let partial_span = quarter_beat - start;
                let partial_end_bpm = match point.interpolation {
                    TimelineTempoInterpolation::Step => point.bpm,
                    TimelineTempoInterpolation::Linear => {
                        interpolate_timeline_bpm(point, next, partial_span)?
                    }
                };
                elapsed += timeline_bpm_segment_seconds(
                    point.bpm,
                    partial_span,
                    partial_end_bpm,
                    point.interpolation,
                )?;
                return finite_seconds(elapsed);
            }
            elapsed += timeline_bpm_segment_seconds(
                point.bpm,
                end - start,
                next.bpm,
                point.interpolation,
            )?;
        }
        finite_seconds(elapsed)
    }

    pub fn sample_frame_at_quarter_beat(
        &self,
        quarter_beat: f64,
        sample_rate: u32,
    ) -> Result<u64, String> {
        if sample_rate == 0 {
            return Err("Timeline click sample rate must be non-zero".to_string());
        }
        let frames = self.seconds_at_quarter_beat(quarter_beat)? * f64::from(sample_rate);
        if !frames.is_finite() || frames < 0.0 || frames >= u64::MAX as f64 {
            return Err("Timeline click sample-frame conversion overflowed".to_string());
        }
        Ok(frames.round() as u64)
    }

    pub fn quarter_beat_at_seconds(&self, seconds: f64) -> Result<f64, String> {
        if !seconds.is_finite() || seconds < 0.0 {
            return Err("Timeline elapsed seconds must be finite and non-negative".to_string());
        }
        if seconds == 0.0 {
            return Ok(0.0);
        }
        let mut high = (seconds * self.fallback_bpm / 60.0).max(1.0) + 1.0;
        for _ in 0..64 {
            if self.seconds_at_quarter_beat(high)? >= seconds {
                break;
            }
            high *= 2.0;
            if !high.is_finite()
                || high > (protocol::TIMELINE_TEMPO_METER_MAX_SIXTEENTH_STEPS as f64 / 4.0)
            {
                return Err("Timeline elapsed position exceeds checked musical range".to_string());
            }
        }
        let mut low = 0.0;
        for _ in 0..80 {
            let middle = (low + high) * 0.5;
            if self.seconds_at_quarter_beat(middle)? < seconds {
                low = middle;
            } else {
                high = middle;
            }
        }
        Ok(high)
    }

    pub fn quarter_beat_at_sample_frame(
        &self,
        sample_frame: u64,
        sample_rate: u32,
    ) -> Result<f64, String> {
        if sample_rate == 0 {
            return Err("Timeline click sample rate must be non-zero".to_string());
        }
        self.quarter_beat_at_seconds(sample_frame as f64 / f64::from(sample_rate))
    }

    /// Compare the audible click schedule over the native lookahead window.
    /// A MIDI-clock PLL may perturb its floating BPM estimate on every one of
    /// the 24 pulses per quarter note.  Replacing a future batch is only
    /// semantic when that perturbation moves a queued onset by more than one
    /// output frame (or changes its meter identity).
    fn differs_audibly_within_lookahead(
        &self,
        candidate: &Self,
        position_ms: u64,
        sample_rate: u32,
        lookahead_frames: u64,
    ) -> Result<bool, String> {
        type TimelineClickScheduleEntry = (u64, u64, u16, u8, u8);
        let schedule = |authority: &Self| -> Result<Vec<TimelineClickScheduleEntry>, String> {
            let position_seconds = position_ms as f64 / 1_000.0;
            let start_quarter = authority.quarter_beat_at_seconds(position_seconds)?;
            let start_frame = authority.sample_frame_at_quarter_beat(start_quarter, sample_rate)?;
            let end_frame = start_frame
                .checked_add(lookahead_frames)
                .ok_or_else(|| "Timeline click lookahead frame overflowed".to_string())?;
            let end_quarter = authority.quarter_beat_at_sample_frame(end_frame, sample_rate)?;
            let start_units =
                (start_quarter * f64::from(TIMELINE_CLICK_QUARTER_UNITS as u32)).ceil();
            let end_units = (end_quarter * f64::from(TIMELINE_CLICK_QUARTER_UNITS as u32)).ceil();
            if !start_units.is_finite()
                || !end_units.is_finite()
                || start_units < 0.0
                || end_units < 0.0
                || end_units >= u64::MAX as f64
            {
                return Err("Timeline click PLL comparison overflowed".to_string());
            }
            let minimum_end = (start_units as u64)
                .checked_add(1)
                .ok_or_else(|| "Timeline click PLL comparison overflowed".to_string())?;
            let comparison_identity = TimelineClickScheduleIdentity::default();
            let events = authority
                .enumerate_clicks(
                    start_units as u64,
                    (end_units as u64).max(minimum_end),
                    sample_rate,
                    comparison_identity,
                )?
                .into_iter()
                .filter_map(|event| {
                    event.sample_frame.checked_sub(start_frame).map(|relative| {
                        (
                            relative,
                            event.measure,
                            event.beat,
                            event.numerator,
                            event.denominator,
                        )
                    })
                })
                .filter(|event| event.0 <= lookahead_frames)
                .collect::<Vec<_>>();
            Ok(events)
        };
        let current = schedule(self)?;
        let candidate = schedule(candidate)?;
        if current.len() != candidate.len() {
            return Ok(true);
        }
        Ok(current.iter().zip(candidate).any(|(current, candidate)| {
            current.1 != candidate.1
                || current.2 != candidate.2
                || current.3 != candidate.3
                || current.4 != candidate.4
                || current.0.abs_diff(candidate.0) > 1
        }))
    }

    /// Resolve the performance click immediately before an authored Guide
    /// boundary. The caller supplies a canonical sample frame, never a
    /// millisecond value, so Guide placement is derived from the same musical
    /// map and rounding path as metronome events. Frame zero is the sole
    /// no-preroll exception decided by the caller.
    fn guide_onset_before_frame(
        &self,
        declared_frame: u64,
        sample_rate: u32,
        identity: TimelineClickScheduleIdentity,
    ) -> Result<Option<u64>, String> {
        if declared_frame == 0 {
            return Ok(None);
        }
        let declared_quarter = self.quarter_beat_at_sample_frame(declared_frame, sample_rate)?;
        let declared_units =
            (declared_quarter * f64::from(TIMELINE_CLICK_QUARTER_UNITS as u32)).ceil();
        if !declared_units.is_finite() || declared_units < 0.0 || declared_units >= u64::MAX as f64
        {
            return Err("Timeline Guide musical boundary overflowed".to_string());
        }
        let declared_units = declared_units as u64;
        let start_units = declared_units.saturating_sub(TIMELINE_CLICK_QUARTER_UNITS * 8);
        let end_units = declared_units
            .checked_add(TIMELINE_CLICK_QUARTER_UNITS)
            .ok_or_else(|| "Timeline Guide musical boundary overflowed".to_string())?;
        Ok(self
            .enumerate_clicks(start_units, end_units, sample_rate, identity)?
            .into_iter()
            .filter(|event| event.sample_frame < declared_frame)
            .map(|event| event.sample_frame)
            .max())
    }

    /// Enumerate every denominator-note click in a bounded quarter-beat
    /// range.  The caller may poll repeatedly with overlapping ranges; the
    /// returned event identity is stable and the scheduler owns de-duplication.
    pub fn enumerate_clicks(
        &self,
        start_quarter_units: u64,
        end_quarter_units: u64,
        sample_rate: u32,
        identity: TimelineClickScheduleIdentity,
    ) -> Result<Vec<TimelineClickEventSummary>, String> {
        if end_quarter_units < start_quarter_units {
            return Err("Timeline click lookahead end precedes its start".to_string());
        }
        if end_quarter_units == start_quarter_units {
            return Ok(Vec::new());
        }
        if sample_rate == 0 {
            return Err("Timeline click sample rate must be non-zero".to_string());
        }
        let (mut cursor, mut segment_index) = self.cursor_at_units(start_quarter_units)?;
        let mut events = Vec::new();
        loop {
            let segment_end = match self.points.get(segment_index) {
                Some(point) => timeline_point_units(point)?,
                None => end_quarter_units,
            };
            let limit = end_quarter_units.min(segment_end);
            while cursor.next_units < limit {
                if events.len() >= TIMELINE_CLICK_BATCH_CAPACITY {
                    return Err(
                        "Timeline click lookahead exceeded its bounded event batch".to_string()
                    );
                }
                let quarter_beat =
                    cursor.next_units as f64 / f64::from(TIMELINE_CLICK_QUARTER_UNITS as u32);
                let sample_frame = self.sample_frame_at_quarter_beat(quarter_beat, sample_rate)?;
                let downbeat = cursor.beat == 1;
                events.push(TimelineClickEventSummary {
                    sample_frame,
                    measure: cursor.measure,
                    beat: cursor.beat,
                    numerator: cursor.numerator,
                    denominator: cursor.denominator,
                    downbeat,
                    frequency_hz: if downbeat {
                        TIMELINE_CLICK_DOWNBEAT_FREQUENCY_HZ
                    } else {
                        TIMELINE_CLICK_BEAT_FREQUENCY_HZ
                    },
                    duration_frames: ((u64::from(sample_rate) * TIMELINE_CLICK_DURATION_MS)
                        / 1_000)
                        .try_into()
                        .map_err(|_| "Timeline click duration exceeded frame bounds".to_string())?,
                    epoch: identity.epoch,
                    transport_generation: identity.transport_generation,
                    schedule_generation: identity.schedule_generation,
                    source: identity.source,
                    count_in: false,
                });
                self.advance_click_cursor(&mut cursor)?;
            }
            if limit >= end_quarter_units {
                break;
            }
            // A meter point is an exact new measure boundary.  Tempo-only
            // points preserve the current beat phase and therefore do not
            // duplicate a downbeat.
            if let Some(point) = self.points.get(segment_index) {
                if (point.numerator, point.denominator) != (cursor.numerator, cursor.denominator)
                    || point.measure_number.is_some()
                {
                    self.move_cursor_to_measure_boundary(&mut cursor, point)?;
                }
            }
            segment_index = segment_index.saturating_add(1);
            if segment_index > self.points.len() {
                break;
            }
        }
        Ok(events)
    }

    /// Generate one exact count-in measure.  The returned frame positions are
    /// relative to count-in start, so the first event is frame zero and the
    /// caller can offset the batch to the native playback start frame.
    pub fn count_in_clicks(
        &self,
        playback_start_quarter_units: u64,
        sample_rate: u32,
        identity: TimelineClickScheduleIdentity,
    ) -> Result<Vec<TimelineClickEventSummary>, String> {
        if sample_rate == 0 {
            return Err("Timeline click sample rate must be non-zero".to_string());
        }
        let quarter =
            playback_start_quarter_units as f64 / f64::from(TIMELINE_CLICK_QUARTER_UNITS as u32);
        let (numerator, denominator) = self.meter_at_quarter_beat(quarter)?;
        let cadence_quarter_beats = 4.0 / f64::from(denominator);
        let bpm = self.bpm_at_quarter_beat(quarter)?;
        let cadence_frames = (60.0 * cadence_quarter_beats / bpm * f64::from(sample_rate)).round();
        if !cadence_frames.is_finite() || cadence_frames < 1.0 || cadence_frames >= u64::MAX as f64
        {
            return Err("Timeline count-in frame cadence overflowed".to_string());
        }
        let cadence_frames = cadence_frames as u64;
        let (cursor, _) = self.cursor_at_units(playback_start_quarter_units)?;
        let measure = cursor.measure;
        let mut events = Vec::with_capacity(usize::from(numerator));
        for index in 0..numerator {
            let frame = cadence_frames
                .checked_mul(u64::from(index))
                .ok_or_else(|| "Timeline count-in frame position overflowed".to_string())?;
            events.push(TimelineClickEventSummary {
                sample_frame: frame,
                measure,
                beat: u16::from(index) + 1,
                numerator,
                denominator,
                downbeat: index == 0,
                frequency_hz: if index == 0 {
                    TIMELINE_CLICK_DOWNBEAT_FREQUENCY_HZ
                } else {
                    TIMELINE_CLICK_BEAT_FREQUENCY_HZ
                },
                duration_frames: ((u64::from(sample_rate) * TIMELINE_CLICK_DURATION_MS) / 1_000)
                    .try_into()
                    .map_err(|_| "Timeline click duration exceeded frame bounds".to_string())?,
                epoch: identity.epoch,
                transport_generation: identity.transport_generation,
                schedule_generation: identity.schedule_generation,
                source: identity.source,
                count_in: true,
            });
        }
        Ok(events)
    }

    fn cursor_at_units(&self, target: u64) -> Result<(TimelineClickCursor, usize), String> {
        let mut cursor = TimelineClickCursor {
            next_units: 0,
            measure: 1,
            beat: 1,
            numerator: 4,
            denominator: 4,
        };
        let mut segment_index = 0usize;
        if let Some(first) = self.points.first() {
            let first_units = timeline_point_units(first)?;
            if first_units == 0 {
                cursor.numerator = first.numerator;
                cursor.denominator = first.denominator;
                cursor.measure = first.measure_number.unwrap_or(1);
                segment_index = 1;
            }
        }
        loop {
            let segment_end = match self.points.get(segment_index) {
                Some(point) => timeline_point_units(point)?,
                None => target.max(cursor.next_units).saturating_add(1),
            };
            let limit = target.min(segment_end);
            self.advance_cursor_before(&mut cursor, limit)?;
            if target < segment_end || segment_index >= self.points.len() {
                return Ok((cursor, segment_index));
            }
            let point = &self.points[segment_index];
            if (point.numerator, point.denominator) != (cursor.numerator, cursor.denominator)
                || point.measure_number.is_some()
            {
                self.move_cursor_to_measure_boundary(&mut cursor, point)?;
            }
            segment_index = segment_index.saturating_add(1);
        }
    }

    fn move_cursor_to_measure_boundary(
        &self,
        cursor: &mut TimelineClickCursor,
        point: &TimelineTempoMeterPoint,
    ) -> Result<(), String> {
        let boundary = timeline_point_units(point)?;
        let measure = match point.measure_number {
            Some(measure) => measure,
            None if cursor.beat == 1 => cursor.measure,
            None => cursor
                .measure
                .checked_add(1)
                .ok_or_else(|| "Timeline click measure overflowed".to_string())?,
        };
        cursor.next_units = boundary;
        cursor.numerator = point.numerator;
        cursor.denominator = point.denominator;
        cursor.beat = 1;
        cursor.measure = measure;
        Ok(())
    }

    fn advance_cursor_before(
        &self,
        cursor: &mut TimelineClickCursor,
        limit: u64,
    ) -> Result<(), String> {
        if cursor.next_units >= limit {
            return Ok(());
        }
        let cadence = TIMELINE_CLICK_QUARTER_UNITS
            .checked_mul(4)
            .and_then(|value| value.checked_div(u64::from(cursor.denominator)))
            .ok_or_else(|| "Timeline click cadence overflowed".to_string())?;
        let steps = (limit - cursor.next_units - 1)
            .checked_div(cadence)
            .and_then(|value| value.checked_add(1))
            .ok_or_else(|| "Timeline click cursor overflowed".to_string())?;
        cursor.next_units = cursor
            .next_units
            .checked_add(
                cadence
                    .checked_mul(steps)
                    .ok_or_else(|| "Timeline click cursor span overflowed".to_string())?,
            )
            .ok_or_else(|| "Timeline click cursor overflowed".to_string())?;
        advance_measure_beat(cursor, steps)
    }

    fn advance_click_cursor(&self, cursor: &mut TimelineClickCursor) -> Result<(), String> {
        let cadence = TIMELINE_CLICK_QUARTER_UNITS
            .checked_mul(4)
            .and_then(|value| value.checked_div(u64::from(cursor.denominator)))
            .ok_or_else(|| "Timeline click cadence overflowed".to_string())?;
        cursor.next_units = cursor
            .next_units
            .checked_add(cadence)
            .ok_or_else(|| "Timeline click cursor overflowed".to_string())?;
        advance_measure_beat(cursor, 1)
    }
}

#[derive(Debug, Clone)]
pub struct TimelineClickScheduler {
    sample_rate: u32,
    lookahead_frames: u64,
    authority: Option<TimelineTempoMeterAuthority>,
    identity: TimelineClickScheduleIdentity,
    queue: VecDeque<TimelineClickEventSummary>,
    armed: bool,
    count_in_active: bool,
    last_position_units: Option<u64>,
    overflow: Option<String>,
}

impl Default for TimelineClickScheduler {
    fn default() -> Self {
        Self::new()
    }
}

impl TimelineClickScheduler {
    pub fn new() -> Self {
        Self {
            sample_rate: TIMELINE_CLICK_SAMPLE_RATE,
            lookahead_frames: u64::from(TIMELINE_CLICK_SAMPLE_RATE)
                .saturating_mul(TIMELINE_CLICK_LOOKAHEAD_MS)
                / 1_000,
            authority: None,
            identity: TimelineClickScheduleIdentity {
                epoch: 1,
                transport_generation: 1,
                schedule_generation: 1,
                source: TimelineScheduleSource::Root,
            },
            queue: VecDeque::with_capacity(TIMELINE_CLICK_QUEUE_CAPACITY),
            armed: false,
            count_in_active: false,
            last_position_units: None,
            overflow: None,
        }
    }

    pub fn identity(&self) -> TimelineClickScheduleIdentity {
        self.identity
    }

    pub fn queued_events(&self) -> &VecDeque<TimelineClickEventSummary> {
        &self.queue
    }

    pub fn overflow(&self) -> Option<&str> {
        self.overflow.as_deref()
    }

    pub fn configure_authority(
        &mut self,
        authority: TimelineTempoMeterAuthority,
    ) -> Result<(), String> {
        self.authority = Some(authority);
        Ok(())
    }

    fn next_identity(
        &self,
        source: TimelineScheduleSource,
    ) -> Result<TimelineClickScheduleIdentity, String> {
        Ok(TimelineClickScheduleIdentity {
            epoch: self.identity.epoch,
            transport_generation: self.identity.transport_generation,
            schedule_generation: self
                .identity
                .schedule_generation
                .checked_add(1)
                .ok_or_else(|| "Timeline click schedule generation is exhausted".to_string())?,
            source,
        })
    }

    fn clear_for_identity(&mut self, identity: TimelineClickScheduleIdentity) {
        self.identity = identity;
        self.authority = None;
        self.queue.clear();
        self.armed = false;
        self.count_in_active = false;
        self.last_position_units = None;
        self.overflow = None;
    }

    /// Rotate only the engine-owned schedule generation.  This is used for
    /// source/map/count-in/toggle changes that keep the public transport
    /// epoch and generation stable but must cancel already-issued frames.
    pub fn rotate_schedule_generation(&mut self) -> Result<(), String> {
        let identity = self.next_identity(self.identity.source)?;
        self.clear_for_identity(identity);
        Ok(())
    }

    pub fn preflight_schedule_generation_rotation(&self) -> Result<(), String> {
        self.next_identity(self.identity.source).map(|_| ())
    }

    pub fn rotate_source(&mut self, source: TimelineScheduleSource) -> Result<(), String> {
        if self.identity.source == source {
            return Ok(());
        }
        let identity = self.next_identity(source)?;
        self.clear_for_identity(identity);
        Ok(())
    }

    pub fn rotate_identity(&mut self, epoch: u64, transport_generation: u64) -> Result<(), String> {
        let schedule_generation = self
            .identity
            .schedule_generation
            .checked_add(1)
            .ok_or_else(|| "Timeline click schedule generation is exhausted".to_string())?;
        self.identity = TimelineClickScheduleIdentity {
            epoch,
            transport_generation,
            schedule_generation,
            source: self.identity.source,
        };
        self.queue.clear();
        self.armed = false;
        self.count_in_active = false;
        self.last_position_units = None;
        self.overflow = None;
        Ok(())
    }

    pub fn disarm(&mut self) {
        self.queue.clear();
        self.armed = false;
        self.count_in_active = false;
        self.last_position_units = None;
        self.overflow = None;
    }

    pub fn invalidate(&mut self, epoch: u64, transport_generation: u64) -> Result<(), String> {
        self.rotate_identity(epoch, transport_generation)
    }

    pub fn rearm(
        &mut self,
        authority: TimelineTempoMeterAuthority,
        current_position_units: u64,
        lookahead_end_units: u64,
    ) -> Result<usize, String> {
        let events = match authority.enumerate_clicks(
            current_position_units,
            lookahead_end_units,
            self.sample_rate,
            self.identity,
        ) {
            Ok(events) => events,
            Err(error) => {
                self.overflow = Some(error.clone());
                return Err(error);
            }
        };
        if events.len() > TIMELINE_CLICK_QUEUE_CAPACITY {
            let error = "Timeline click queue capacity exceeded".to_string();
            self.overflow = Some(error.clone());
            return Err(error);
        }
        self.authority = Some(authority);
        self.queue = events.into_iter().collect();
        self.overflow = None;
        self.armed = true;
        self.count_in_active = false;
        self.last_position_units = Some(current_position_units);
        Ok(self.queue.len())
    }

    pub fn rearm_count_in(&mut self, playback_start_units: u64) -> Result<usize, String> {
        let Some(authority) = self.authority.as_ref() else {
            return Ok(0);
        };
        let next_identity = self.next_identity(self.identity.source)?;
        let events = match authority.count_in_clicks(
            playback_start_units,
            self.sample_rate,
            next_identity,
        ) {
            Ok(events) => events,
            Err(error) => {
                self.overflow = Some(error.clone());
                return Err(error);
            }
        };
        if events.len() > TIMELINE_CLICK_QUEUE_CAPACITY {
            let error = "Timeline count-in exceeded click queue capacity".to_string();
            self.overflow = Some(error.clone());
            return Err(error);
        }
        self.queue.clear();
        self.queue.extend(events);
        self.identity = next_identity;
        self.armed = true;
        self.count_in_active = true;
        self.last_position_units = Some(playback_start_units);
        Ok(self.queue.len())
    }

    pub fn end_count_in(&mut self) -> Result<(), String> {
        if self.count_in_active {
            self.rotate_schedule_generation()?;
        }
        Ok(())
    }

    pub fn poll(
        &mut self,
        current_position_units: u64,
        lookahead_end_units: u64,
    ) -> Result<usize, String> {
        if !self.armed {
            return Ok(0);
        }
        if current_position_units < self.last_position_units.unwrap_or(current_position_units) {
            return Err(
                "Timeline click poll moved backwards without a transport rearm".to_string(),
            );
        }
        let previous_queue = self.queue.clone();
        let previous_position = self.last_position_units;
        self.last_position_units = Some(current_position_units);
        if let Some(authority) = self.authority.as_ref() {
            let current_frame = authority.sample_frame_at_quarter_beat(
                current_position_units as f64 / f64::from(TIMELINE_CLICK_QUARTER_UNITS as u32),
                self.sample_rate,
            )?;
            self.queue
                .retain(|event| event.sample_frame >= current_frame);
        }
        match self.fill(current_position_units, lookahead_end_units) {
            Ok(added) => Ok(added),
            Err(error) => {
                self.queue = previous_queue;
                self.last_position_units = previous_position;
                self.overflow = Some(error.clone());
                Err(error)
            }
        }
    }

    fn fill(&mut self, start_units: u64, end_units: u64) -> Result<usize, String> {
        let Some(authority) = self.authority.as_ref() else {
            return Ok(0);
        };
        let events = match authority.enumerate_clicks(
            start_units,
            end_units,
            self.sample_rate,
            self.identity,
        ) {
            Ok(events) => events,
            Err(error) => {
                self.overflow = Some(error.clone());
                return Err(error);
            }
        };
        let mut new_events = Vec::new();
        for event in events {
            if self.queue.iter().any(|queued| {
                queued.sample_frame == event.sample_frame
                    && queued.epoch == event.epoch
                    && queued.transport_generation == event.transport_generation
                    && queued.schedule_generation == event.schedule_generation
                    && queued.source == event.source
                    && queued.count_in == event.count_in
            }) {
                continue;
            }
            new_events.push(event);
        }
        if self
            .queue
            .len()
            .checked_add(new_events.len())
            .is_none_or(|length| length > TIMELINE_CLICK_QUEUE_CAPACITY)
        {
            let error = "Timeline click queue capacity exceeded".to_string();
            self.overflow = Some(error.clone());
            return Err(error);
        }
        let added = new_events.len();
        self.queue.extend(new_events);
        Ok(added)
    }

    pub fn take_current_events(
        &mut self,
        identity: TimelineClickScheduleIdentity,
    ) -> Vec<TimelineClickEventSummary> {
        // An overflow is a visible, fail-closed producer fault.  Preserve the
        // queued image for diagnostics/retry, but never let a native consumer
        // emit a partial or stale batch while the fault is latched.
        if identity != self.identity || self.overflow.is_some() {
            return Vec::new();
        }
        let mut events = Vec::with_capacity(self.queue.len());
        while let Some(event) = self.queue.pop_front() {
            if event.epoch == identity.epoch
                && event.transport_generation == identity.transport_generation
                && event.schedule_generation == identity.schedule_generation
                && event.source == identity.source
            {
                events.push(event);
            }
        }
        events
    }
}

fn advance_measure_beat(cursor: &mut TimelineClickCursor, count: u64) -> Result<(), String> {
    let numerator = u64::from(cursor.numerator);
    let beat = u64::from(cursor.beat);
    let first = numerator
        .checked_sub(beat)
        .and_then(|value| value.checked_add(1))
        .ok_or_else(|| "Timeline click beat state is invalid".to_string())?;
    if count < first {
        cursor.beat =
            beat.checked_add(count)
                .ok_or_else(|| "Timeline click beat overflowed".to_string())? as u16;
        return Ok(());
    }
    let remainder = count - first;
    cursor.measure = cursor
        .measure
        .checked_add(1 + remainder / numerator)
        .ok_or_else(|| "Timeline click measure overflowed".to_string())?;
    cursor.beat = (remainder % numerator + 1)
        .try_into()
        .map_err(|_| "Timeline click beat overflowed".to_string())?;
    Ok(())
}

fn timeline_point_units(point: &TimelineTempoMeterPoint) -> Result<u64, String> {
    point
        .position_sixteenth_steps
        .checked_mul(TIMELINE_CLICK_SIXTEENTH_UNITS)
        .ok_or_else(|| "Timeline tempo/meter point span overflowed".to_string())
}

fn timeline_measure_start_sixteenth_steps(
    points: &[TimelineTempoMeterPoint],
    target_measure: u64,
) -> Result<u64, String> {
    let anchor = points
        .iter()
        .filter_map(|point| point.measure_number.map(|measure| (measure, point)))
        .filter(|(measure, _)| *measure <= target_measure)
        .max_by_key(|(measure, _)| *measure)
        .ok_or_else(|| "Timeline Guide target measure has no authored anchor".to_string())?;
    let (mut measure, anchor_point) = anchor;
    let mut position = anchor_point.position_sixteenth_steps;
    while measure < target_measure {
        let meter = points
            .iter()
            .take_while(|point| point.position_sixteenth_steps <= position)
            .last()
            .unwrap_or(anchor_point);
        let span = u64::from(meter.numerator)
            .checked_mul(16)
            .and_then(|value| value.checked_div(u64::from(meter.denominator)))
            .filter(|span| *span > 0)
            .ok_or_else(|| "Timeline Guide target measure span overflowed".to_string())?;
        position = position
            .checked_add(span)
            .ok_or_else(|| "Timeline Guide target measure position overflowed".to_string())?;
        measure = measure
            .checked_add(1)
            .ok_or_else(|| "Timeline Guide target measure identity overflowed".to_string())?;
    }
    Ok(position)
}

fn timeline_point_quarter_beats(point: &TimelineTempoMeterPoint) -> Result<f64, String> {
    Ok(timeline_point_units(point)? as f64 / TIMELINE_CLICK_QUARTER_UNITS as f64)
}

fn interpolate_timeline_bpm(
    point: &TimelineTempoMeterPoint,
    next: &TimelineTempoMeterPoint,
    offset: f64,
) -> Result<f64, String> {
    let span = timeline_point_quarter_beats(next)? - timeline_point_quarter_beats(point)?;
    if span <= 0.0 || !span.is_finite() {
        return Err("Timeline tempo points have an ambiguous or zero span".to_string());
    }
    let value = match point.interpolation {
        TimelineTempoInterpolation::Step => point.bpm,
        TimelineTempoInterpolation::Linear => point.bpm + (next.bpm - point.bpm) * offset / span,
    };
    if value.is_finite() && value > 0.0 {
        Ok(value)
    } else {
        Err("Timeline tempo interpolation produced a non-finite BPM".to_string())
    }
}

fn timeline_bpm_segment_seconds(
    start_bpm: f64,
    span_quarter_beats: f64,
    end_bpm: f64,
    interpolation: TimelineTempoInterpolation,
) -> Result<f64, String> {
    if span_quarter_beats < 0.0 || !span_quarter_beats.is_finite() {
        return Err("Timeline tempo segment span is invalid".to_string());
    }
    if span_quarter_beats == 0.0 {
        return Ok(0.0);
    }
    let seconds = match interpolation {
        TimelineTempoInterpolation::Step => 60.0 * span_quarter_beats / start_bpm,
        TimelineTempoInterpolation::Linear => {
            let slope = (end_bpm - start_bpm) / span_quarter_beats;
            if slope.abs() < f64::EPSILON {
                60.0 * span_quarter_beats / start_bpm
            } else {
                60.0 / slope * (end_bpm / start_bpm).ln()
            }
        }
    };
    finite_seconds(seconds)
}

fn finite_seconds(seconds: f64) -> Result<f64, String> {
    if seconds.is_finite() && seconds >= 0.0 {
        Ok(seconds)
    } else {
        Err("Timeline tempo conversion produced a non-finite duration".to_string())
    }
}

const OUTPUT_OWNERSHIP_TRANSITION_TIMEOUT: Duration = Duration::from_secs(3);

/// A physical output operation must hold one of these permits from immediately
/// before the operation through its completion.  The permit is intentionally
/// separate from the status snapshot: a transition fences new permits and
/// waits for existing permits before it tears down an output.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OutputCapability {
    Lighting,
    Video,
}

#[derive(Debug)]
struct OutputOwnershipGateState {
    status: OutputOwnershipStatus,
    in_flight: usize,
    transition_active: bool,
}

#[derive(Debug)]
struct OutputOwnershipGateInner {
    state: Mutex<OutputOwnershipGateState>,
    changed: Condvar,
}

/// Shared local capability gate used by the engine and app-owned output
/// transports. It is local-only by design; authenticated peer leases are a
/// future capability that can be combined with this gate.
#[derive(Debug, Clone)]
pub struct OutputOwnershipGate {
    inner: Arc<OutputOwnershipGateInner>,
}

#[derive(Debug)]
pub struct OutputOwnershipPermit {
    inner: Arc<OutputOwnershipGateInner>,
}

/// Lease held by a physical output teardown until the underlying SDK/device
/// has actually released its resource. Unlike an output frame permit, this
/// lease may be acquired while the gate is already fenced. That lets a
/// transition account for asynchronous SDK cleanup without allowing a later
/// transition to overlap the old resource.
#[derive(Debug)]
pub struct OutputOwnershipTeardownLease {
    inner: Arc<OutputOwnershipGateInner>,
}

/// Admission for creating an external output resource. This is separate from
/// the per-frame permit: resource creation must be serialized with the
/// ownership transition that authorizes it, not merely fenced on the first
/// frame.
#[derive(Debug, Clone)]
pub struct OutputOwnershipActivation {
    inner: Arc<OutputOwnershipGateInner>,
    role: MachineOutputRole,
    epoch: u64,
    transition_owned: bool,
}

/// RAII admission held from immediately before an external resource
/// constructor through publication or physical retirement. It deliberately
/// uses the gate's in-flight count instead of holding the gate mutex across a
/// potentially blocking SDK/window call.
#[derive(Debug)]
pub struct OutputOwnershipCreationLease {
    inner: Arc<OutputOwnershipGateInner>,
    role: MachineOutputRole,
    epoch: u64,
    transition_owned: bool,
    released: bool,
}

#[derive(Debug)]
pub struct OutputOwnershipTransition {
    gate: OutputOwnershipGate,
    target: MachineOutputRole,
    pre_transition_desired_role: MachineOutputRole,
    pre_transition_persisted_role: Option<MachineOutputRole>,
    finished: bool,
}

impl OutputOwnershipGate {
    pub fn startup_denied() -> Self {
        Self::with_status(OutputOwnershipStatus::failed(
            MachineOutputRole::Standby,
            None,
            0,
            0,
            OutputOwnershipReason::StartupDenied,
            "Machine output ownership has not been initialized".to_string(),
        ))
    }

    pub fn for_role(role: MachineOutputRole) -> Self {
        Self::with_status(OutputOwnershipStatus::for_role(role))
    }

    fn with_status(status: OutputOwnershipStatus) -> Self {
        Self {
            inner: Arc::new(OutputOwnershipGateInner {
                state: Mutex::new(OutputOwnershipGateState {
                    status,
                    in_flight: 0,
                    transition_active: false,
                }),
                changed: Condvar::new(),
            }),
        }
    }

    pub fn status(&self) -> OutputOwnershipStatus {
        self.inner
            .state
            .lock()
            .map(|state| state.status.clone())
            .unwrap_or_else(|_| {
                OutputOwnershipStatus::failed(
                    MachineOutputRole::Standby,
                    None,
                    0,
                    0,
                    OutputOwnershipReason::TransitionFailed,
                    "Output ownership gate lock was poisoned".to_string(),
                )
            })
    }

    pub fn try_status(&self) -> Option<OutputOwnershipStatus> {
        match self.inner.state.try_lock() {
            Ok(state) => Some(state.status.clone()),
            Err(std::sync::TryLockError::Poisoned(_)) => Some(OutputOwnershipStatus::failed(
                MachineOutputRole::Standby,
                None,
                0,
                0,
                OutputOwnershipReason::TransitionFailed,
                "Output ownership gate lock was poisoned".to_string(),
            )),
            Err(std::sync::TryLockError::WouldBlock) => None,
        }
    }

    pub fn acquire(&self, capability: OutputCapability) -> Result<OutputOwnershipPermit, String> {
        let mut state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if state.transition_active || state.status.state != OutputOwnershipState::Ready {
            return Err(output_capability_blocked_message(
                capability,
                state.status.clone(),
            ));
        }
        let allowed = match capability {
            OutputCapability::Lighting => state.status.lighting_allowed,
            OutputCapability::Video => state.status.video_allowed,
        };
        if !allowed {
            return Err(output_capability_blocked_message(
                capability,
                state.status.clone(),
            ));
        }
        state.in_flight = state.in_flight.saturating_add(1);
        Ok(OutputOwnershipPermit {
            inner: Arc::clone(&self.inner),
        })
    }

    fn acquire_teardown_lease(&self) -> Result<OutputOwnershipTeardownLease, String> {
        let mut state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if !state.transition_active
            || !matches!(
                state.status.state,
                OutputOwnershipState::Transitioning
                    | OutputOwnershipState::Activating
                    | OutputOwnershipState::Failed
            )
        {
            return Err(
                "Output teardown lease requires an active all-deny ownership transition"
                    .to_string(),
            );
        }
        state.in_flight = state.in_flight.saturating_add(1);
        Ok(OutputOwnershipTeardownLease {
            inner: Arc::clone(&self.inner),
        })
    }

    /// Atomically fence the local output capability after an output worker
    /// detects a physical send/render failure. The returned lease is passed to
    /// the SDK/device cleanup path and keeps the failed fence active until
    /// that cleanup is acknowledged. Recovering a poisoned mutex here is
    /// intentional: failure handling must still be able to account for the
    /// resource that is about to be torn down.
    fn begin_failure_fence(&self, error: impl Into<String>) -> OutputOwnershipTeardownLease {
        let mut state = match self.inner.state.lock() {
            Ok(state) => state,
            Err(poisoned) => poisoned.into_inner(),
        };
        let epoch = state.status.epoch.saturating_add(1);
        let status = OutputOwnershipStatus::failed(
            state.status.desired_role,
            state.status.persisted_role,
            state.status.generation,
            epoch,
            OutputOwnershipReason::TransitionFailed,
            error.into(),
        );
        state.status = status;
        state.transition_active = true;
        state.in_flight = state.in_flight.saturating_add(1);
        self.inner.changed.notify_all();
        OutputOwnershipTeardownLease {
            inner: Arc::clone(&self.inner),
        }
    }

    pub fn begin_transition(
        &self,
        target: MachineOutputRole,
    ) -> Result<OutputOwnershipTransition, String> {
        self.begin_transition_with_timeout(target, OUTPUT_OWNERSHIP_TRANSITION_TIMEOUT)
    }

    #[cfg(test)]
    fn begin_transition_with_test_timeout(
        &self,
        target: MachineOutputRole,
        timeout: Duration,
    ) -> Result<OutputOwnershipTransition, String> {
        self.begin_transition_with_timeout(target, timeout)
    }

    fn begin_transition_with_timeout(
        &self,
        target: MachineOutputRole,
        timeout: Duration,
    ) -> Result<OutputOwnershipTransition, String> {
        let mut state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if state.transition_active {
            return Err("Output ownership transition is already in progress".to_string());
        }
        let pre_transition_desired_role = state.status.desired_role;
        let pre_transition_persisted_role = state.status.persisted_role;
        let next_epoch = state.status.epoch.saturating_add(1);
        let generation = state.status.generation;
        let persisted_role = state.status.persisted_role;
        state.transition_active = true;
        state.status =
            OutputOwnershipStatus::transitioning(target, persisted_role, generation, next_epoch);
        self.inner.changed.notify_all();

        let deadline = Instant::now() + timeout;
        while state.in_flight != 0 {
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                let error =
                    "Output ownership transition timed out waiting for an in-flight output operation"
                        .to_string();
                // Keep the transition fence authoritative while the old
                // physical operation drains. Returning here would permit a
                // later role change to overlap the operation that timed out.
                state.status = OutputOwnershipStatus::failed(
                    target,
                    state.status.persisted_role,
                    generation,
                    next_epoch,
                    OutputOwnershipReason::TransitionFailed,
                    error.clone(),
                );
                state.transition_active = true;
                self.inner.changed.notify_all();
                // Return the timeout to the caller without dropping the
                // fence. The last physical permit releases only this failed
                // transition fence; an explicit retry is still required to
                // reach Ready.
                return Err(error);
            }
            state = match self.inner.changed.wait_timeout(state, remaining) {
                Ok((state, _)) => state,
                Err(poisoned) => {
                    let (mut state, _) = poisoned.into_inner();
                    state.status = OutputOwnershipStatus::failed(
                        target,
                        state.status.persisted_role,
                        generation,
                        next_epoch,
                        OutputOwnershipReason::TransitionFailed,
                        "Output ownership gate wait was poisoned".to_string(),
                    );
                    // Poison is also a hard fence. Drain the real permits
                    // before allowing any later recovery transition. The
                    // poisoned lock remains fail-closed even after permits
                    // drop, so return without attempting to rearm it.
                    state.transition_active = true;
                    self.inner.changed.notify_all();
                    return Err(
                        "Output ownership gate wait was poisoned; outputs remain Standby"
                            .to_string(),
                    );
                }
            };
        }

        Ok(OutputOwnershipTransition {
            gate: self.clone(),
            target,
            pre_transition_desired_role,
            pre_transition_persisted_role,
            finished: false,
        })
    }

    fn admit_ready_activation(
        &self,
        role: MachineOutputRole,
    ) -> Result<OutputOwnershipActivation, String> {
        let state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if state.transition_active
            || state.status.state != OutputOwnershipState::Ready
            || state.status.effective_role != role
            || !role.video_allowed()
        {
            return Err(format!(
                "External video resource activation is not admitted for machine role {role:?}"
            ));
        }
        Ok(OutputOwnershipActivation {
            inner: Arc::clone(&self.inner),
            role,
            epoch: state.status.epoch,
            transition_owned: false,
        })
    }

    fn admit_transition_activation(
        &self,
        target: MachineOutputRole,
    ) -> Result<OutputOwnershipActivation, String> {
        let state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if !state.transition_active
            || state.status.state != OutputOwnershipState::Activating
            || state.status.desired_role != target
            || !target.video_allowed()
        {
            return Err(format!(
                "External video resource preparation is not admitted for machine role {target:?}"
            ));
        }
        Ok(OutputOwnershipActivation {
            inner: Arc::clone(&self.inner),
            role: target,
            epoch: state.status.epoch,
            transition_owned: true,
        })
    }

    fn admit_resource_creation(
        &self,
        activation: &OutputOwnershipActivation,
    ) -> Result<OutputOwnershipCreationLease, String> {
        if !activation.role.video_allowed() {
            return Err(format!(
                "External video resource creation role mismatch for {:?}",
                activation.role
            ));
        }
        let mut state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if !Arc::ptr_eq(&activation.inner, &self.inner) || state.status.epoch != activation.epoch {
            return Err("External video resource creation activation epoch is stale".to_string());
        }
        if activation.transition_owned {
            if !state.transition_active
                || state.status.state != OutputOwnershipState::Activating
                || state.status.desired_role != activation.role
            {
                return Err(
                    "External video resource creation preparation fence is no longer active"
                        .to_string(),
                );
            }
        } else if state.transition_active
            || state.status.state != OutputOwnershipState::Ready
            || state.status.effective_role != activation.role
        {
            return Err("External video resource creation fence is no longer ready".to_string());
        }
        state.in_flight = state.in_flight.saturating_add(1);
        Ok(OutputOwnershipCreationLease {
            inner: Arc::clone(&self.inner),
            role: activation.role,
            epoch: activation.epoch,
            transition_owned: activation.transition_owned,
            released: false,
        })
    }

    fn can_publish_resource_creation(
        &self,
        lease: &OutputOwnershipCreationLease,
    ) -> Result<(), String> {
        let state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if state.status.epoch != lease.epoch {
            return Err("External video resource creation lease epoch is stale".to_string());
        }
        if lease.transition_owned {
            if !state.transition_active
                || state.status.state != OutputOwnershipState::Activating
                || state.status.desired_role != lease.role
            {
                return Err(
                    "External video resource creation preparation fence was invalidated"
                        .to_string(),
                );
            }
        } else if state.transition_active
            || state.status.state != OutputOwnershipState::Ready
            || state.status.effective_role != lease.role
        {
            return Err("External video resource creation fence was invalidated".to_string());
        }
        Ok(())
    }

    fn begin_activation(&self, target: MachineOutputRole) -> Result<(), String> {
        let mut state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if !state.transition_active
            || state.status.state != OutputOwnershipState::Transitioning
            || state.status.desired_role != target
            || !target.video_allowed()
        {
            return Err(format!(
                "External video activation phase is not available for machine role {target:?}"
            ));
        }
        state.status = OutputOwnershipStatus::activating(
            target,
            state.status.persisted_role,
            state.status.generation,
            state.status.epoch,
        );
        self.inner.changed.notify_all();
        Ok(())
    }

    fn validate_activation(
        &self,
        activation: &OutputOwnershipActivation,
        role: MachineOutputRole,
    ) -> Result<(), String> {
        if activation.role != role || !role.video_allowed() {
            return Err(format!(
                "External video resource activation role mismatch for {role:?}"
            ));
        }
        let state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if !Arc::ptr_eq(&activation.inner, &self.inner) || state.status.epoch != activation.epoch {
            return Err("External video resource activation epoch is stale".to_string());
        }
        if activation.transition_owned {
            if !state.transition_active
                || state.status.state != OutputOwnershipState::Activating
                || state.status.desired_role != role
            {
                return Err(
                    "External video resource preparation fence is no longer active".to_string(),
                );
            }
        } else if state.transition_active
            || state.status.state != OutputOwnershipState::Ready
            || state.status.effective_role != role
        {
            return Err("External video resource activation fence is no longer ready".to_string());
        }
        Ok(())
    }

    fn record_persisted_role_without_transition(
        &self,
        role: MachineOutputRole,
    ) -> Result<(), String> {
        let mut state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        state.status.persisted_role = Some(role);
        Ok(())
    }

    fn update_persisted_role(&self, role: MachineOutputRole) -> Result<(), String> {
        let mut state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if !state.transition_active {
            return Err("Output ownership is not transitioning".to_string());
        }
        state.status.persisted_role = Some(role);
        Ok(())
    }

    fn complete_transition(
        &self,
        target: MachineOutputRole,
    ) -> Result<OutputOwnershipStatus, String> {
        let mut state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if !state.transition_active {
            return Err("Output ownership transition is not active".to_string());
        }
        if state.in_flight != 0 {
            return Err(
                "Output ownership cannot become Ready while an output operation is in flight"
                    .to_string(),
            );
        }
        let generation = state.status.generation.saturating_add(1);
        let epoch = state.status.epoch;
        let persisted_role = state.status.persisted_role.or(Some(target));
        state.status = OutputOwnershipStatus::ready(target, persisted_role, generation, epoch);
        state.transition_active = false;
        self.inner.changed.notify_all();
        Ok(state.status.clone())
    }

    fn complete_project_swap_disarmed(
        &self,
        desired_role: MachineOutputRole,
        persisted_role: Option<MachineOutputRole>,
    ) -> Result<OutputOwnershipStatus, String> {
        let mut state = self
            .inner
            .state
            .lock()
            .map_err(|_| "Output ownership gate lock was poisoned".to_string())?;
        if !state.transition_active {
            return Err("Output ownership transition is not active".to_string());
        }
        if !matches!(
            state.status.state,
            OutputOwnershipState::Transitioning | OutputOwnershipState::Activating
        ) {
            return Err("Output ownership transition is not in progress".to_string());
        }
        if state.in_flight != 0 {
            return Err(
                "Project swap output ownership cannot disarm while an output operation is in flight"
                    .to_string(),
            );
        }
        let generation = state.status.generation.saturating_add(1);
        let epoch = state.status.epoch;
        state.status = OutputOwnershipStatus::project_swap_disarmed(
            desired_role,
            persisted_role,
            generation,
            epoch,
        );
        state.transition_active = false;
        self.inner.changed.notify_all();
        Ok(state.status.clone())
    }

    fn fail_transition(&self, target: MachineOutputRole, error: String) -> OutputOwnershipStatus {
        match self.inner.state.lock() {
            Ok(mut state) => {
                let status = OutputOwnershipStatus::failed(
                    target,
                    state.status.persisted_role,
                    state.status.generation,
                    state.status.epoch,
                    OutputOwnershipReason::TransitionFailed,
                    error,
                );
                state.status = status.clone();
                state.transition_active = state.in_flight != 0;
                self.inner.changed.notify_all();
                status
            }
            Err(_) => OutputOwnershipStatus::failed(
                MachineOutputRole::Standby,
                None,
                0,
                0,
                OutputOwnershipReason::TransitionFailed,
                "Output ownership gate lock was poisoned while recording transition failure"
                    .to_string(),
            ),
        }
    }

    pub fn mark_startup_failure(&self, error: impl Into<String>) -> OutputOwnershipStatus {
        match self.inner.state.lock() {
            Ok(mut state) => {
                let status = OutputOwnershipStatus::failed(
                    MachineOutputRole::Standby,
                    state.status.persisted_role,
                    state.status.generation,
                    state.status.epoch,
                    OutputOwnershipReason::StartupDenied,
                    error.into(),
                );
                state.status = status.clone();
                state.transition_active = state.in_flight != 0;
                self.inner.changed.notify_all();
                status
            }
            Err(_) => OutputOwnershipStatus::failed(
                MachineOutputRole::Standby,
                None,
                0,
                0,
                OutputOwnershipReason::StartupDenied,
                "Output ownership gate lock was poisoned while recording startup failure"
                    .to_string(),
            ),
        }
    }

    pub fn publish_startup_preference(
        &self,
        preferred_role: MachineOutputRole,
    ) -> Result<OutputOwnershipStatus, String> {
        match self.inner.state.lock() {
            Ok(mut state) => {
                if state.transition_active || state.in_flight != 0 {
                    return Err(
                        "Cannot publish a startup ownership preference while outputs are active"
                            .to_string(),
                    );
                }
                let status = OutputOwnershipStatus::failed(
                    preferred_role,
                    Some(preferred_role),
                    state.status.generation,
                    state.status.epoch,
                    OutputOwnershipReason::StartupDenied,
                    format!(
                        "Startup is fail-closed; explicitly arm machine output role {preferred_role:?}"
                    ),
                );
                state.status = status.clone();
                state.transition_active = false;
                self.inner.changed.notify_all();
                Ok(status)
            }
            Err(_) => Err("Output ownership gate lock was poisoned".to_string()),
        }
    }

    pub fn mark_transition_failure(&self, error: impl Into<String>) -> OutputOwnershipStatus {
        match self.inner.state.lock() {
            Ok(mut state) => {
                let desired_role = state.status.desired_role;
                let status = OutputOwnershipStatus::failed(
                    desired_role,
                    state.status.persisted_role,
                    state.status.generation,
                    state.status.epoch,
                    OutputOwnershipReason::TransitionFailed,
                    error.into(),
                );
                state.status = status.clone();
                state.transition_active = state.in_flight != 0;
                self.inner.changed.notify_all();
                status
            }
            Err(_) => OutputOwnershipStatus::failed(
                MachineOutputRole::Standby,
                None,
                0,
                0,
                OutputOwnershipReason::TransitionFailed,
                "Output ownership gate lock was poisoned while recording transition failure"
                    .to_string(),
            ),
        }
    }

    pub fn mark_durable_standby_failure(
        &self,
        desired_role: MachineOutputRole,
        error: impl Into<String>,
    ) -> OutputOwnershipStatus {
        match self.inner.state.lock() {
            Ok(mut state) => {
                let status = OutputOwnershipStatus::failed(
                    desired_role,
                    Some(MachineOutputRole::Standby),
                    state.status.generation,
                    state.status.epoch,
                    OutputOwnershipReason::TransitionFailed,
                    error.into(),
                );
                state.status = status.clone();
                state.transition_active = state.in_flight != 0;
                self.inner.changed.notify_all();
                status
            }
            Err(_) => OutputOwnershipStatus::failed(
                MachineOutputRole::Standby,
                Some(MachineOutputRole::Standby),
                0,
                0,
                OutputOwnershipReason::TransitionFailed,
                "Output ownership gate lock was poisoned while recording durable Standby failure"
                    .to_string(),
            ),
        }
    }

    /// Runtime-only publication hook used by the engine after a test/runtime
    /// role mutation. Production role changes use `OutputOwnershipTransition`.
    fn publish_runtime_role(&self, role: MachineOutputRole) {
        if let Ok(mut state) = self.inner.state.lock() {
            if !state.transition_active {
                let generation = state.status.generation;
                let epoch = state.status.epoch;
                let persisted_role = state.status.persisted_role.or(Some(role));
                state.status =
                    OutputOwnershipStatus::ready(role, persisted_role, generation, epoch);
                self.inner.changed.notify_all();
            }
        }
    }
}

impl OutputOwnershipTransition {
    pub fn target(&self) -> MachineOutputRole {
        self.target
    }

    pub fn record_persisted_role(&mut self, role: MachineOutputRole) -> Result<(), String> {
        if role != self.target {
            return Err(format!(
                "Persisted output ownership role {role:?} does not match transition target {:?}",
                self.target
            ));
        }
        self.gate.update_persisted_role(role)
    }

    pub fn admit_output_activation(&self) -> Result<OutputOwnershipActivation, String> {
        self.gate.admit_transition_activation(self.target)
    }

    pub fn begin_activation(&mut self) -> Result<(), String> {
        self.gate.begin_activation(self.target)
    }

    pub fn complete(mut self) -> Result<OutputOwnershipStatus, String> {
        let status = self.gate.complete_transition(self.target)?;
        self.finished = true;
        Ok(status)
    }

    pub fn complete_project_swap_disarmed(mut self) -> Result<OutputOwnershipStatus, String> {
        let status = self.gate.complete_project_swap_disarmed(
            self.pre_transition_desired_role,
            self.pre_transition_persisted_role,
        )?;
        self.finished = true;
        Ok(status)
    }

    pub fn fail(mut self, error: impl Into<String>) -> OutputOwnershipStatus {
        let status = self.gate.fail_transition(self.target, error.into());
        self.finished = true;
        status
    }
}

impl OutputOwnershipActivation {
    /// Atomically revalidate this activation and admit the physical resource
    /// constructor. The returned lease must remain live until the resource is
    /// published or retired.
    pub fn admit_resource_creation(&self) -> Result<OutputOwnershipCreationLease, String> {
        OutputOwnershipGate {
            inner: Arc::clone(&self.inner),
        }
        .admit_resource_creation(self)
    }
}

impl OutputOwnershipCreationLease {
    /// Publish the resource after its owner has made it reachable for normal
    /// teardown. If a fence or role transition won the race, return the lease
    /// so the caller can retire the resource while it is still accounted as
    /// in-flight.
    pub fn publish(mut self) -> Result<(), Self> {
        let gate = OutputOwnershipGate {
            inner: Arc::clone(&self.inner),
        };
        if gate.can_publish_resource_creation(&self).is_err() {
            return Err(self);
        }
        self.released = true;
        release_output_ownership_in_flight(&self.inner);
        Ok(())
    }

    /// Make the retirement acknowledgement explicit at call sites. Dropping
    /// the lease is the acknowledgement because resource-specific cleanup has
    /// already completed before this method is called.
    pub fn retire(self) {}
}

impl Drop for OutputOwnershipTransition {
    fn drop(&mut self) {
        if !self.finished {
            let _ = self.gate.fail_transition(
                self.target,
                "Output ownership transition was abandoned before completion".to_string(),
            );
        }
    }
}

impl Drop for OutputOwnershipPermit {
    fn drop(&mut self) {
        release_output_ownership_in_flight(&self.inner);
    }
}

impl Drop for OutputOwnershipTeardownLease {
    fn drop(&mut self) {
        release_output_ownership_in_flight(&self.inner);
    }
}

impl Drop for OutputOwnershipCreationLease {
    fn drop(&mut self) {
        if !self.released {
            release_output_ownership_in_flight(&self.inner);
        }
    }
}

fn release_output_ownership_in_flight(inner: &Arc<OutputOwnershipGateInner>) {
    let mut state = match inner.state.lock() {
        Ok(state) => state,
        Err(poisoned) => poisoned.into_inner(),
    };
    state.in_flight = state.in_flight.saturating_sub(1);
    if state.in_flight == 0
        && state.transition_active
        && state.status.state == OutputOwnershipState::Failed
    {
        // A failed transition remains fenced while physical teardown is
        // pending. Once the last lease acknowledges completion, release only
        // the transition mutex fence; the Failed status still requires an
        // explicit operator retry before re-arming.
        state.transition_active = false;
    }
    inner.changed.notify_all();
}

fn output_capability_blocked_message(
    capability: OutputCapability,
    status: OutputOwnershipStatus,
) -> String {
    let (label, reason) = match capability {
        OutputCapability::Lighting => ("Lighting", status.lighting_reason),
        OutputCapability::Video => ("Video", status.video_reason),
    };
    if let Some(error) = status.error {
        return format!("{label} output is blocked: {error}");
    }
    format!("{label} output is blocked ({reason:?})")
}

struct ChaserAttributeHasher(u64);

impl Default for ChaserAttributeHasher {
    fn default() -> Self {
        Self(0xcbf2_9ce4_8422_2325)
    }
}

impl Hasher for ChaserAttributeHasher {
    fn write(&mut self, bytes: &[u8]) {
        for byte in bytes {
            self.0 ^= u64::from(*byte);
            self.0 = self.0.wrapping_mul(0x0000_0100_0000_01b3);
        }
    }

    fn finish(&self) -> u64 {
        self.0
    }
}

type ChaserAttributeMap<V> = HashMap<String, V, BuildHasherDefault<ChaserAttributeHasher>>;

#[cfg(target_os = "windows")]
mod realtime_thread {
    use std::ffi::c_void;

    type Handle = *mut c_void;
    const AVRT_PRIORITY_CRITICAL: i32 = 2;

    #[link(name = "Avrt")]
    extern "system" {
        fn AvSetMmThreadCharacteristicsW(task_name: *const u16, task_index: *mut u32) -> Handle;
        fn AvSetMmThreadPriority(handle: Handle, priority: i32) -> i32;
        fn AvRevertMmThreadCharacteristics(handle: Handle) -> i32;
    }

    #[link(name = "Winmm")]
    extern "system" {
        fn timeBeginPeriod(period: u32) -> u32;
        fn timeEndPeriod(period: u32) -> u32;
    }

    pub struct Guard {
        mmcss_handle: Handle,
        timer_period_enabled: bool,
    }

    impl Drop for Guard {
        fn drop(&mut self) {
            unsafe {
                if !self.mmcss_handle.is_null() {
                    AvRevertMmThreadCharacteristics(self.mmcss_handle);
                }
                if self.timer_period_enabled {
                    timeEndPeriod(1);
                }
            }
        }
    }

    pub fn configure() -> Guard {
        let timer_period_enabled = unsafe { timeBeginPeriod(1) == 0 };
        let task_name = "Pro Audio\0".encode_utf16().collect::<Vec<_>>();
        let mut task_index = 0_u32;
        let mmcss_handle =
            unsafe { AvSetMmThreadCharacteristicsW(task_name.as_ptr(), &mut task_index) };
        if !mmcss_handle.is_null() {
            unsafe {
                AvSetMmThreadPriority(mmcss_handle, AVRT_PRIORITY_CRITICAL);
            }
        }
        Guard {
            mmcss_handle,
            timer_period_enabled,
        }
    }
}

#[cfg(target_os = "macos")]
mod realtime_thread {
    pub struct Guard;

    #[link(name = "System")]
    extern "C" {
        fn pthread_set_qos_class_self_np(qos_class: u32, relative_priority: i32) -> i32;
    }

    pub fn configure() -> Guard {
        const QOS_CLASS_USER_INTERACTIVE: u32 = 0x21;
        unsafe {
            pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0);
        }
        Guard
    }
}

#[cfg(not(any(target_os = "windows", target_os = "macos")))]
mod realtime_thread {
    pub struct Guard;

    pub fn configure() -> Guard {
        Guard
    }
}

