    pub fn load_project_snapshot(&self, snapshot: EngineSnapshot) -> Result<(), EngineError> {
        self.send(EngineCommand::LoadProjectSnapshot(snapshot))
    }

    /// Queue a project replacement and return only after the runtime has
    /// validated it and published the resulting snapshot. The bounded wait is
    /// only the admission window. Once the runtime admits this request, the
    /// caller waits for the definitive publish-or-fail acknowledgement.
    pub fn load_project_snapshot_and_wait(&self, snapshot: EngineSnapshot) -> Result<(), String> {
        self.load_project_snapshot_and_wait_with_timeout(
            snapshot,
            PROJECT_SNAPSHOT_LOAD_ACK_TIMEOUT,
        )
    }

    /// Enqueue the real project-load command for an integration harness that
    /// must prove admission and the pending-publication boundary separately.
    /// The support feature is intentionally nondefault; production callers
    /// continue through `load_project_snapshot_and_wait` above.
    #[cfg(any(test, feature = "test-support"))]
    #[doc(hidden)]
    pub fn submit_project_snapshot_load_for_test(
        &self,
        snapshot: EngineSnapshot,
    ) -> Result<ProjectSnapshotLoadTestSubmission, String> {
        let timeout = PROJECT_SNAPSHOT_LOAD_ACK_TIMEOUT;
        let deadline = Instant::now() + timeout;
        let publication_barrier = ProjectSnapshotLoadPublicationBarrier::new();
        let admission = ProjectSnapshotLoadAdmission::new_with_publication_barrier(Arc::clone(
            &publication_barrier,
        ));
        let (ack, receiver) = mpsc::sync_channel(1);
        self.send(EngineCommand::LoadProjectSnapshotPublished {
            snapshot,
            expires_at: deadline,
            admission: admission.clone(),
            ack,
        })
        .map_err(|error| error.to_string())?;
        Ok(ProjectSnapshotLoadTestSubmission {
            admission,
            receiver: Some(receiver),
            deadline,
            timeout,
            publication_barrier,
        })
    }

    fn load_project_snapshot_and_wait_with_timeout(
        &self,
        snapshot: EngineSnapshot,
        timeout: Duration,
    ) -> Result<(), String> {
        let deadline = Instant::now() + timeout;
        let admission = ProjectSnapshotLoadAdmission::new();
        let (ack, receiver) = mpsc::sync_channel(1);
        self.send(EngineCommand::LoadProjectSnapshotPublished {
            snapshot,
            expires_at: deadline,
            admission: admission.clone(),
            ack,
        })
        .map_err(|error| error.to_string())?;
        receive_project_snapshot_load_ack(receiver, &admission, deadline, timeout)
    }

    pub fn snapshot(&self) -> EngineSnapshot {
        self.snapshot
            .read()
            .map(|snapshot| {
                let mut public = snapshot.clone();
                // The shared runtime publication carries an exact authored
                // video image for backend consumers that must distinguish
                // renderer-only Timeline projections from authored layers.
                // Keep the established public/UI snapshot shape unchanged.
                public.authored_video = None;
                public
            })
            .unwrap_or_default()
    }

    /// Read the latest complete public snapshot without waiting behind a
    /// writer. Listener/shutdown infrastructure uses this with a retained
    /// last-good image, so a project publication can never pin an unrelated
    /// network worker inside `RwLock::read` during serial stop/replacement.
    /// A successful clone is structurally bounded by the validated project
    /// collection limits and performs no I/O or callbacks.
    pub fn try_snapshot(&self) -> Option<EngineSnapshot> {
        let snapshot = match self.snapshot.try_read() {
            Ok(snapshot) => snapshot,
            Err(std::sync::TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
            Err(std::sync::TryLockError::WouldBlock) => return None,
        };
        let mut public = snapshot.clone();
        public.authored_video = None;
        Some(public)
    }

    /// Return the public, runtime-only Follow status stamped with the caller's
    /// authority epoch. The epoch is supplied by the backend fence; the
    /// generation in the returned payload is the required abort ABA token.
    pub fn timeline_follow_runtime_status(
        &self,
        epoch: u64,
    ) -> TimelineFollowRuntimeStatusSnapshot {
        let runtime = self.timeline_follow_runtime_summary();
        TimelineFollowRuntimeStatusSnapshot::from_runtime(epoch, &runtime)
    }

    /// Raw runtime Follow summary for engine-local consumers. This is sourced
    /// from the published snapshot and is never part of persistence.
    pub fn timeline_follow_runtime_summary(&self) -> TimelineFollowRuntimeSummary {
        self.snapshot().timeline.follow_runtime
    }

    /// Return the active Follow's exact source/target render inputs. `None`
    /// means no Follow presenter is active; callers must never synthesize a
    /// transition from the legacy weighted `video_snapshot`.
    pub fn timeline_follow_video_render_snapshot(
        &self,
    ) -> Option<TimelineFollowVideoRenderSnapshot> {
        self.timeline_follow_video_render_snapshot
            .read()
            .ok()
            .and_then(|snapshot| snapshot.clone())
    }

    /// Request a definitive runtime-only Follow abort for exactly the observed
    /// generation. A stale generation is rejected; an exact idle generation is
    /// a no-op. Once admitted, acknowledgement reports shared-snapshot
    /// publication or its failure (the abort itself deliberately remains
    /// applied, matching other runtime ownership fences).
    pub fn abort_timeline_follow_published(
        &self,
        expected_epoch: u64,
        expected_generation: u64,
        expires_at: Instant,
    ) -> Result<(), String> {
        let (ack, receiver) = mpsc::sync_channel(1);
        self.send(EngineCommand::AbortTimelineFollow {
            expected_epoch,
            expected_generation,
            expires_at,
            ack,
        })
        .map_err(|error| error.to_string())?;
        receiver
            .recv_timeout(Duration::from_secs(3))
            .map_err(|error| format!("Timeline Follow abort acknowledgement failed: {error}"))?
    }

    /// Definitively acknowledge one captured Follow settlement consumer. The
    /// acknowledgement is runtime-only; accepted state becomes visible at the
    /// same shared-snapshot publication barrier as the reply.
    pub fn acknowledge_timeline_follow_settlement_published(
        &self,
        settlement_ack: TimelineFollowSettlementAck,
        expires_at: Instant,
    ) -> Result<(), String> {
        let (ack, receiver) = mpsc::sync_channel(1);
        self.send(EngineCommand::AcknowledgeTimelineFollowSettlement {
            settlement_ack,
            expires_at,
            ack,
        })
        .map_err(|error| error.to_string())?;
        receiver
            .recv_timeout(Duration::from_secs(3))
            .map_err(|error| {
                format!("Timeline Follow settlement acknowledgement failed: {error}")
            })?
    }

    pub fn output_ownership_status(&self) -> OutputOwnershipStatus {
        self.output_ownership_gate.status()
    }

    /// Current engine-issued video presentation configuration token. It
    /// advances only for semantic presentation mutations published by the
    /// engine, never for ordinary playhead/transition progress.
    pub fn video_presentation_config_token(&self) -> u64 {
        self.video_presentation_config_token.load(Ordering::Acquire)
    }

    /// Capture one presentation sample: the configuration token strictly
    /// before a full snapshot read. The order is load-bearing. The engine
    /// publishes a bumped token only after its mutated snapshot is visible,
    /// so sampling the token first guarantees that the paired snapshot is at
    /// least as new as the token: a later pre-dispatch comparison against the
    /// live token rejects every mutation that happened after this capture.
    /// Reversing the order could certify an older token against a newer
    /// snapshot and miss a revocation.
    pub fn video_presentation_sample(&self) -> VideoPresentationSample {
        let config_token = self.video_presentation_config_token();
        let snapshot = self.snapshot();
        VideoPresentationSample {
            config_token,
            snapshot,
        }
    }

