#[derive(Clone)]
enum CompiledDaslightGridLines {
    Grid {
        palette: Vec<ColorEffectColor>,
        grayscale: bool,
        spacing: i32,
        layer_count: i32,
        travel: f64,
        line_width: f64,
        half_width: f64,
    },
    Lines {
        palette: Vec<ColorEffectColor>,
        grayscale: bool,
        stride: f64,
        line_width: f64,
    },
}

impl CompiledDaslightGridLines {
    const RASTER_SIZE: i32 = 100;

    fn compile(request: &ColorEffectRequest) -> Result<Option<Self>, String> {
        let Some(pattern) = request.spatial_pattern.as_ref() else {
            return Ok(None);
        };
        let palette = || {
            request
                .stops
                .iter()
                .map(|stop| stop.color)
                .collect::<Vec<_>>()
        };
        match &pattern.recipe {
            ColorEffectSpatialRecipe::Grid {
                grayscale,
                size,
                width,
            } => {
                if !(2..=5).contains(&request.stops.len()) {
                    return Err("Grid requires between 2 and 5 palette stops".to_string());
                }
                if !(1..=5).contains(size) || !(2..=20).contains(width) {
                    return Err("Grid Size must be within 1..5 and Width within 2..20".to_string());
                }
                let spacing = (Self::RASTER_SIZE / 2) / i32::from(*size);
                let layer_count = (Self::RASTER_SIZE / spacing) / 2;
                let line_width = f64::from(*width);
                Ok(Some(Self::Grid {
                    palette: palette(),
                    grayscale: *grayscale,
                    spacing,
                    layer_count,
                    travel: f64::from((Self::RASTER_SIZE - i32::from(*width) + 1) / 2),
                    line_width,
                    half_width: f64::from(*width / 2),
                }))
            }
            ColorEffectSpatialRecipe::Lines { grayscale, size } => {
                if !(2..=protocol::DASLIGHT_COLOR_PALETTE_MAX_STOPS).contains(&request.stops.len())
                {
                    return Err("Lines requires between 2 and 255 palette stops".to_string());
                }
                if !(2..=20).contains(size) {
                    return Err("Lines Size must be within 2..20".to_string());
                }
                let intervals = (request.stops.len() - 1) as f64;
                let available = f64::from(Self::RASTER_SIZE - i32::from(*size));
                let integer_stride = (available / intervals).floor();
                let stride = if integer_stride >= 1.0 {
                    integer_stride
                } else {
                    available / intervals
                };
                Ok(Some(Self::Lines {
                    palette: palette(),
                    grayscale: *grayscale,
                    stride,
                    line_width: f64::from(*size),
                }))
            }
            _ => Ok(None),
        }
    }

    fn finish_color(
        palette: &[ColorEffectColor],
        grayscale: bool,
        palette_index: usize,
    ) -> ColorEffectColor {
        let color = palette[palette_index];
        if grayscale {
            daslight_grayscale_color(color)
        } else {
            color
        }
    }

    fn raster_pixel(normalized: f32) -> f64 {
        f64::from(normalized.clamp(0.0, 1.0) * Self::RASTER_SIZE as f32)
            .floor()
            .min(f64::from(Self::RASTER_SIZE - 1))
    }

    fn sample_at_phase(
        &self,
        time_phase: f64,
        normalized_x: f32,
        normalized_y: f32,
    ) -> ColorEffectColor {
        let x = Self::raster_pixel(normalized_x);
        let y = Self::raster_pixel(normalized_y);
        let motion = (2.0 * time_phase).rem_euclid(1.0);
        match self {
            Self::Grid {
                palette,
                grayscale,
                spacing,
                layer_count,
                travel,
                line_width,
                half_width,
            } => {
                let mut palette_index = 0;
                for layer in 0..*layer_count {
                    let q = (*travel * motion + f64::from(layer * *spacing)).rem_euclid(*travel);
                    let color_index = 1 + layer as usize % (palette.len() - 1);
                    let left = q - *half_width;
                    let right = f64::from(Self::RASTER_SIZE) - *half_width - q;
                    let top = q - *half_width;
                    let bottom = f64::from(Self::RASTER_SIZE) - *half_width - q;
                    // This is the source paint order. Assigning on every hit
                    // preserves later-wins overlap exactly without a raster.
                    if x >= left && x < left + *line_width {
                        palette_index = color_index;
                    }
                    if x >= right && x < right + *line_width {
                        palette_index = color_index;
                    }
                    if y >= top && y < top + *line_width {
                        palette_index = color_index;
                    }
                    if y >= bottom && y < bottom + *line_width {
                        palette_index = color_index;
                    }
                }
                Self::finish_color(palette, *grayscale, palette_index)
            }
            Self::Lines {
                palette,
                grayscale,
                stride,
                line_width,
            } => {
                let q = *stride * motion;
                let last = palette.len() - 2;
                let greatest_cover = |second_train: bool| -> Option<usize> {
                    if *stride <= 0.0 {
                        return None;
                    }
                    let start_at = |index: usize| {
                        if second_train {
                            (index + 1) as f64 * *stride - q
                        } else {
                            index as f64 * *stride + q
                        }
                    };
                    let base = if second_train {
                        ((x + q) / *stride).floor() as i64 - 1
                    } else {
                        ((x - q) / *stride).floor() as i64
                    };
                    // Division can round across an integer boundary. Check a
                    // constant five-index neighbourhood, but evaluate every
                    // start with that train's original operation order and the
                    // strict half-open source predicate. No epsilon is used.
                    let mut previous = None;
                    let mut greatest = None;
                    for delta in -2_i64..=2 {
                        let candidate = (base + delta).clamp(0, last as i64) as usize;
                        if previous == Some(candidate) {
                            continue;
                        }
                        previous = Some(candidate);
                        let start = start_at(candidate);
                        if x >= start && x < start + *line_width {
                            greatest = Some(candidate);
                        }
                    }
                    greatest
                };
                let first = greatest_cover(false);
                let second = greatest_cover(true);
                let palette_index = match (first, second) {
                    (Some(first), Some(second)) => 1 + first.max(second),
                    (Some(index), None) | (None, Some(index)) => 1 + index,
                    (None, None) => 0,
                };
                Self::finish_color(palette, *grayscale, palette_index)
            }
        }
    }
}

#[derive(Clone)]
struct CompiledDaslightGraphPhaseCache {
    phase_bits: Option<u64>,
    anchor_count: usize,
    tile_y: [i32; 100],
    #[cfg(test)]
    rebuild_count: u64,
    #[cfg(test)]
    anchor_evaluation_count: u64,
}

impl Default for CompiledDaslightGraphPhaseCache {
    fn default() -> Self {
        Self {
            phase_bits: None,
            anchor_count: 0,
            tile_y: [0; 100],
            #[cfg(test)]
            rebuild_count: 0,
            #[cfg(test)]
            anchor_evaluation_count: 0,
        }
    }
}

#[derive(Clone)]
struct CompiledDaslightGraph {
    palette: Vec<ColorEffectColor>,
    grayscale: bool,
    height: i32,
    width: i32,
    pitch: i32,
    frequency: f64,
    amplitude: f64,
    offset: f64,
    source_pixel_phase: f64,
    /// Fixed-size per-effect work image equivalent. The runtime evaluates one
    /// Graph phase for every target in a tick, so cache the at-most-100 Y
    /// anchors once without allocating in the tick path.
    phase_cache: RefCell<CompiledDaslightGraphPhaseCache>,
}

impl CompiledDaslightGraph {
    const RASTER_SIZE: i32 = 100;
    const SOURCE_PIXEL_MS: f64 = 40.0;

    fn compile(request: &ColorEffectRequest) -> Result<Option<Self>, String> {
        let Some(pattern) = request.spatial_pattern.as_ref() else {
            return Ok(None);
        };
        let ColorEffectSpatialRecipe::Graph {
            grayscale,
            height,
            width,
            pitch,
            frequency,
            amplitude,
            offset,
        } = &pattern.recipe
        else {
            return Ok(None);
        };
        if !(2..=10).contains(&request.stops.len()) {
            return Err("Graph requires between 2 and 10 palette stops".to_string());
        }
        if !(1..=100).contains(height)
            || !(1..=100).contains(width)
            || *pitch > 100
            || *frequency > 10
            || !amplitude.is_finite()
            || !(0.0..=2.0).contains(amplitude)
            || !offset.is_finite()
            || !(-1.0..=1.0).contains(offset)
        {
            return Err(
                "Graph requires Height and Width 1..100, Pitch 0..100, Frequency 0..10, Amplitude 0..2, and Offset -1..1"
                    .to_string(),
            );
        }
        Ok(Some(Self {
            palette: request.stops.iter().map(|stop| stop.color).collect(),
            grayscale: *grayscale,
            height: i32::from(*height),
            width: i32::from(*width),
            pitch: i32::from((*pitch).max(1)),
            frequency: f64::from(*frequency),
            amplitude: f64::from(*amplitude),
            offset: f64::from(*offset),
            source_pixel_phase: Self::SOURCE_PIXEL_MS / request.period_ms.max(10) as f64,
            phase_cache: RefCell::new(CompiledDaslightGraphPhaseCache::default()),
        }))
    }

    fn raster_pixel(normalized: f32) -> i32 {
        (normalized.clamp(0.0, 1.0) * Self::RASTER_SIZE as f32)
            .floor()
            .min((Self::RASTER_SIZE - 1) as f32) as i32
    }

    fn finish_color(&self, color: ColorEffectColor) -> ColorEffectColor {
        if self.grayscale {
            daslight_grayscale_color(color)
        } else {
            color
        }
    }

    fn prepare_phase_cache(&self, time_phase: f64) {
        let phase_bits = time_phase.to_bits();
        let mut cache = self.phase_cache.borrow_mut();
        if cache.phase_bits == Some(phase_bits) {
            return;
        }

        let anchor_count = ((Self::RASTER_SIZE - 1) / self.pitch + 1) as usize;
        for anchor_index in 0..anchor_count {
            let origin_x = anchor_index as i32 * self.pitch;
            let theta = std::f64::consts::TAU
                * self.frequency
                * (time_phase + f64::from(origin_x) * self.source_pixel_phase);
            let wave = 0.5 * theta.sin();
            let center = (self.amplitude * wave - self.offset + 0.5) * f64::from(Self::RASTER_SIZE);
            cache.tile_y[anchor_index] = (center - f64::from(self.height / 2)).trunc() as i32;
        }
        cache.phase_bits = Some(phase_bits);
        cache.anchor_count = anchor_count;
        #[cfg(test)]
        {
            cache.rebuild_count += 1;
            cache.anchor_evaluation_count += anchor_count as u64;
        }
    }

    #[cfg(test)]
    fn phase_cache_stats(&self) -> (u64, u64, usize) {
        let cache = self.phase_cache.borrow();
        (
            cache.rebuild_count,
            cache.anchor_evaluation_count,
            cache.anchor_count,
        )
    }

    fn sample_at_phase(
        &self,
        time_phase: f64,
        normalized_x: f32,
        normalized_y: f32,
    ) -> ColorEffectColor {
        let pixel_x = Self::raster_pixel(normalized_x);
        let pixel_y = Self::raster_pixel(normalized_y);
        let background = self.palette[0];
        let first_origin = (pixel_x - self.width + 1).max(0);
        let first_index = (first_origin + self.pitch - 1) / self.pitch;
        let last_index = (pixel_x / self.pitch).min((Self::RASTER_SIZE - 1) / self.pitch);
        if first_index > last_index {
            return self.finish_color(background);
        }

        self.prepare_phase_cache(time_phase);
        let phase_cache = self.phase_cache.borrow();
        debug_assert!(last_index < phase_cache.anchor_count as i32);

        // Graph paints anchors in increasing X order. Search backwards so the
        // first tile containing this pixel is the exact last-wins source tile;
        // even a zero-weight edge row overwrites an earlier tile with palette0.
        for anchor_index in (first_index..=last_index).rev() {
            let tile_y = phase_cache.tile_y[anchor_index as usize];
            if pixel_y < tile_y || pixel_y >= tile_y + self.height {
                continue;
            }
            let row = pixel_y - tile_y;
            let weight = if self.height == 1 {
                // Daslight's Height=1 tile computes 1/0 and leaves its sole row
                // transparent. The corrected route keeps the authored minimum
                // visible as one fully opaque row.
                1.0
            } else {
                let half = self.height / 2;
                let ramp = f64::from(row) / f64::from(half);
                if ramp <= 1.0 {
                    ramp
                } else {
                    2.0 - ramp
                }
            } as f32;
            let foreground = self.palette[1 + anchor_index as usize % (self.palette.len() - 1)];
            let color = interpolate_color_effect_color(
                background,
                foreground,
                weight,
                ColorEffectInterpolation::Rgb,
            );
            return self.finish_color(color);
        }
        self.finish_color(background)
    }
}

const DASLIGHT_RAIN_PARTICLE_COUNT: usize = 100;

#[derive(Clone, Copy)]
struct CompiledDaslightRainParticle {
    start_x: f32,
    start_y: f32,
    fall: f32,
    color: ColorEffectColor,
}

#[derive(Clone)]
struct CompiledDaslightRainPhaseCache {
    phase_bits: Option<u32>,
    current_y: [i32; DASLIGHT_RAIN_PARTICLE_COUNT],
}

impl Default for CompiledDaslightRainPhaseCache {
    fn default() -> Self {
        Self {
            phase_bits: None,
            current_y: [0; DASLIGHT_RAIN_PARTICLE_COUNT],
        }
    }
}

#[derive(Clone)]
struct CompiledDaslightRain {
    background: ColorEffectColor,
    grayscale: bool,
    speed: f32,
    #[cfg(test)]
    width: i32,
    height: i32,
    trail: i32,
    particles: [CompiledDaslightRainParticle; DASLIGHT_RAIN_PARTICLE_COUNT],
    number: usize,
    /// Compile-time column coverage keeps the hot sampler on only the
    /// particles that can write the requested X pixel. A u128 is sufficient
    /// for Rain's validated maximum of 100 particles and preserves ascending
    /// source order, including later-wins replacement.
    x_particle_masks: [u128; 100],
    /// All targets of one effect observe the same phase in a tick. Cache the
    /// recovered f32/truncation Y update once per particle without allocating
    /// on the tick path.
    phase_cache: RefCell<CompiledDaslightRainPhaseCache>,
}

impl CompiledDaslightRain {
    const RASTER_SIZE: i32 = 100;

    fn compile(request: &ColorEffectRequest) -> Result<Option<Self>, String> {
        let Some(pattern) = request.spatial_pattern.as_ref() else {
            return Ok(None);
        };
        let ColorEffectSpatialRecipe::Rain {
            grayscale,
            rng_seed,
            speed,
            width,
            height,
            number,
            trail,
        } = &pattern.recipe
        else {
            return Ok(None);
        };
        if !(protocol::DASLIGHT_COLOR_PALETTE_MIN_STOPS
            ..=protocol::DASLIGHT_COLOR_PALETTE_MAX_STOPS)
            .contains(&request.stops.len())
        {
            return Err("Rain requires between 1 and 255 palette stops".to_string());
        }
        if *speed > 10
            || !(5..=10).contains(width)
            || !(10..=30).contains(height)
            || !(1..=100).contains(number)
            || !(1..=30).contains(trail)
        {
            return Err(
                "Rain Speed must be within 0..10, Width within 5..10, Height within 10..30, Number within 1..100, and Trail within 1..30"
                    .to_string(),
            );
        }
        let random_pairs = syndocal_tube_random_pairs(*rng_seed);
        let particles = std::array::from_fn(|index| {
            let (random_x, random_y) = random_pairs[index];
            let palette_word = (1_u32 + (u16::MAX as f32 * random_y).trunc() as u32) as u16;
            CompiledDaslightRainParticle {
                start_x: (Self::RASTER_SIZE as f32 * random_x).floor(),
                start_y: (Self::RASTER_SIZE as f32 * random_y).floor(),
                fall: 1.0 + random_x,
                color: spatial_palette_color(
                    request,
                    f32::from(palette_word) / u16::MAX as f32,
                    100.0,
                ),
            }
        });
        let number = usize::from(*number);
        let width = i32::from(*width);
        let mut x_particle_masks = [0_u128; 100];
        for (particle_index, particle) in particles[..number].iter().enumerate() {
            let start_x = particle.start_x as i32;
            for pixel_x in start_x..(start_x + width).min(Self::RASTER_SIZE) {
                x_particle_masks[pixel_x as usize] |= 1_u128 << particle_index;
            }
        }
        Ok(Some(Self {
            background: request.stops[0].color,
            grayscale: *grayscale,
            speed: f32::from(*speed),
            #[cfg(test)]
            width,
            height: i32::from(*height),
            trail: i32::from(*trail),
            particles,
            number,
            x_particle_masks,
            phase_cache: RefCell::new(CompiledDaslightRainPhaseCache::default()),
        }))
    }

    #[inline(always)]
    fn raster_pixel(normalized: f32) -> i32 {
        (normalized.clamp(0.0, 1.0) * Self::RASTER_SIZE as f32)
            .floor()
            .min((Self::RASTER_SIZE - 1) as f32) as i32
    }

    fn prepare_phase_cache(&self, time_phase: f64) {
        let time_phase = time_phase as f32;
        let phase_bits = time_phase.to_bits();
        let mut cache = self.phase_cache.borrow_mut();
        if cache.phase_bits == Some(phase_bits) {
            return;
        }
        for (particle_index, particle) in self.particles[..self.number].iter().enumerate() {
            // Corrected continuous form of the recovered source update:
            // floor(y0 + (100/F)*Speed*(1+qx)*frame) % 100, with frame/F
            // replaced by authored-period phase. Keep the f32 multiplication
            // order explicit because truncation boundaries are observable.
            let travel_per_period = (Self::RASTER_SIZE as f32 * self.speed) * particle.fall;
            cache.current_y[particle_index] = (particle.start_y + travel_per_period * time_phase)
                .floor()
                .rem_euclid(Self::RASTER_SIZE as f32)
                as i32;
        }
        cache.phase_bits = Some(phase_bits);
    }

    fn sample_at_phase(
        &self,
        time_phase: f64,
        normalized_x: f32,
        normalized_y: f32,
    ) -> ColorEffectColor {
        let pixel_x = Self::raster_pixel(normalized_x);
        let pixel_y = Self::raster_pixel(normalized_y);
        let mut color = self.background;
        self.prepare_phase_cache(time_phase);
        let cache = self.phase_cache.borrow();
        let mut particle_mask = self.x_particle_masks[pixel_x as usize];
        while particle_mask != 0 {
            let particle_index = particle_mask.trailing_zeros() as usize;
            particle_mask &= particle_mask - 1;
            let particle = &self.particles[particle_index];
            let row = (cache.current_y[particle_index] - pixel_y).rem_euclid(Self::RASTER_SIZE);
            if row >= self.height + self.trail {
                continue;
            }
            // The source writes every covered pixel, including the final
            // zero-alpha trail row, so a later particle replaces rather than
            // composites over an earlier particle.
            let weight = if row < self.height {
                1.0
            } else {
                1.0 - (row - self.height + 1) as f32 / self.trail as f32
            };
            color = interpolate_color_effect_color(
                self.background,
                particle.color,
                weight,
                ColorEffectInterpolation::Rgb,
            );
        }
        if self.grayscale {
            daslight_grayscale_color(color)
        } else {
            color
        }
    }
}

const DASLIGHT_BOUNCE_RASTER_SIZE: usize = 100;
const DASLIGHT_BOUNCE_RANDOM_COUNT: usize = 5_000;
const DASLIGHT_BOUNCE_FRAME_CAP: usize = 750;

#[derive(Clone)]
struct CompiledDaslightBounceState {
    x: Vec<f32>,
    y: Vec<f32>,
    vx: Vec<f32>,
    vy: Vec<f32>,
}

impl CompiledDaslightBounceState {
    fn copy_from(&mut self, source: &Self) {
        self.x.copy_from_slice(&source.x);
        self.y.copy_from_slice(&source.y);
        self.vx.copy_from_slice(&source.vx);
        self.vy.copy_from_slice(&source.vy);
    }
}

#[derive(Clone)]
struct CompiledDaslightBounceFrames {
    red: Vec<u16>,
    green: Vec<u16>,
    blue: Vec<u16>,
    sampled_pixel_count: usize,
}

#[derive(Clone, Copy, Default)]
struct CompiledDaslightBounceSampleRow {
    x_mask: u128,
    slot_start: usize,
}

#[derive(Clone)]
struct CompiledDaslightBounceRasterCache {
    generation: Option<usize>,
    state: CompiledDaslightBounceState,
    red: Vec<u16>,
    green: Vec<u16>,
    blue: Vec<u16>,
    #[cfg(test)]
    rebuild_count: u64,
}

impl CompiledDaslightBounceRasterCache {
    fn new(initial_state: &CompiledDaslightBounceState, sampled_pixel_count: usize) -> Self {
        Self {
            generation: None,
            state: initial_state.clone(),
            red: vec![0; sampled_pixel_count],
            green: vec![0; sampled_pixel_count],
            blue: vec![0; sampled_pixel_count],
            #[cfg(test)]
            rebuild_count: 0,
        }
    }
}

#[derive(Clone)]
struct CompiledDaslightBounceGlyph {
    outer: Arc<[(f32, f32)]>,
    inner: Arc<[(f32, f32)]>,
}

impl CompiledDaslightBounceGlyph {
    fn compile() -> Self {
        const OUTER: &[(f32, f32, bool)] = &[
            (965.0, 781.0, true),
            (930.0, 822.0, false),
            (843.0, 888.0, false),
            (744.0, 935.0, false),
            (634.0, 960.0, false),
            (576.0, 960.0, true),
            (470.0, 960.0, false),
            (283.0, 880.0, false),
            (144.0, 741.0, false),
            (64.0, 554.0, false),
            (64.0, 448.0, true),
            (64.0, 342.0, false),
            (144.0, 155.0, false),
            (283.0, 16.0, false),
            (470.0, -64.0, false),
            (576.0, -64.0, true),
            (634.0, -64.0, false),
            (744.0, -39.0, false),
            (843.0, 8.0, false),
            (930.0, 74.0, false),
            (965.0, 115.0, true),
            (640.0, 448.0, true),
        ];
        const INNER: &[(f32, f32, bool)] = &[
            (704.0, 839.0, true),
            (734.0, 839.0, false),
            (775.0, 798.0, false),
            (775.0, 768.0, true),
            (775.0, 738.0, false),
            (734.0, 697.0, false),
            (704.0, 697.0, true),
            (674.0, 697.0, false),
            (633.0, 738.0, false),
            (633.0, 768.0, true),
            (633.0, 798.0, false),
            (674.0, 839.0, false),
        ];
        Self {
            outer: Self::flatten_true_type_contour(OUTER).into(),
            inner: Self::flatten_true_type_contour(INNER).into(),
        }
    }

    fn flatten_true_type_contour(points: &[(f32, f32, bool)]) -> Vec<(f32, f32)> {
        debug_assert!(points.first().is_some_and(|point| point.2));
        let start = (points[0].0, points[0].1);
        let mut flattened = vec![start];
        let mut current = start;
        let mut index = 1;
        while index < points.len() {
            let point = points[index];
            if point.2 {
                flattened.push((point.0, point.1));
                current = (point.0, point.1);
                index += 1;
                continue;
            }
            let next = if index + 1 < points.len() {
                points[index + 1]
            } else {
                points[0]
            };
            let end = if next.2 {
                (next.0, next.1)
            } else {
                ((point.0 + next.0) * 0.5, (point.1 + next.1) * 0.5)
            };
            for step in 1..=8 {
                let t = step as f32 / 8.0;
                let inverse = 1.0 - t;
                flattened.push((
                    inverse * inverse * current.0 + 2.0 * inverse * t * point.0 + t * t * end.0,
                    inverse * inverse * current.1 + 2.0 * inverse * t * point.1 + t * t * end.1,
                ));
            }
            current = end;
            index += if next.2 { 2 } else { 1 };
        }
        if flattened.last().copied() != Some(start) {
            flattened.push(start);
        }
        flattened
    }

    fn contains(
        &self,
        pixel_x: f32,
        pixel_y: f32,
        origin_x: f32,
        origin_y: f32,
        size: f32,
    ) -> bool {
        let glyph_x = 514.5 + (pixel_x - origin_x) * 400.0 / size;
        let glyph_y = 448.0 - (pixel_y - origin_y) * 400.0 / size;
        Self::point_in_polygon(glyph_x, glyph_y, &self.outer)
            ^ Self::point_in_polygon(glyph_x, glyph_y, &self.inner)
    }

    fn point_in_polygon(x: f32, y: f32, polygon: &[(f32, f32)]) -> bool {
        let mut inside = false;
        for edge in polygon.windows(2) {
            let (x1, y1) = edge[0];
            let (x2, y2) = edge[1];
            if (y1 > y) != (y2 > y) && x < (x2 - x1) * (y - y1) / (y2 - y1) + x1 {
                inside = !inside;
            }
        }
        inside
    }
}

#[derive(Clone)]
struct CompiledDaslightBounce {
    #[cfg(test)]
    random_a: Arc<[f32; DASLIGHT_BOUNCE_RANDOM_COUNT]>,
    palette: Arc<[ColorEffectColor]>,
    glyph: Arc<CompiledDaslightBounceGlyph>,
    initial_state: Arc<CompiledDaslightBounceState>,
    item: ColorEffectSpatialBounceItem,
    number: usize,
    size: f32,
    speed: f32,
    collide: bool,
    fill: bool,
    points: usize,
    grayscale: bool,
    rendered_frame_count: usize,
    sample_x: Arc<[u8]>,
    sample_y: Arc<[u8]>,
    sampled_rows: [CompiledDaslightBounceSampleRow; DASLIGHT_BOUNCE_RASTER_SIZE],
    precomputed_frames: Option<Arc<CompiledDaslightBounceFrames>>,
    raster_cache: Option<RefCell<CompiledDaslightBounceRasterCache>>,
}

impl CompiledDaslightBounce {
    #[cfg(test)]
    fn compile(request: &ColorEffectRequest) -> Result<Option<Self>, String> {
        Self::compile_with_sampled_rows(
            request,
            [(1_u128 << DASLIGHT_BOUNCE_RASTER_SIZE) - 1; DASLIGHT_BOUNCE_RASTER_SIZE],
            false,
        )
    }

    fn compile_for_targets(
        request: &ColorEffectRequest,
        targets: &[RuntimeColorSpatialTarget],
    ) -> Result<Option<Self>, String> {
        let mut sampled_rows = [0_u128; DASLIGHT_BOUNCE_RASTER_SIZE];
        for target in targets {
            let pixel_x = Self::raster_pixel(target.x);
            let pixel_y = Self::raster_pixel(target.z);
            sampled_rows[pixel_y] |= 1_u128 << pixel_x;
        }
        Self::compile_with_sampled_rows(
            request,
            sampled_rows,
            targets.len() <= SUPPORTED_EFFECT_ENVELOPE_FIXTURES,
        )
    }

    fn compile_with_sampled_rows(
        request: &ColorEffectRequest,
        sampled_rows: [u128; DASLIGHT_BOUNCE_RASTER_SIZE],
        precompute_supported_frames: bool,
    ) -> Result<Option<Self>, String> {
        let Some(pattern) = request.spatial_pattern.as_ref() else {
            return Ok(None);
        };
        let ColorEffectSpatialRecipe::Bounce {
            grayscale,
            rng_seed,
            item,
            shape,
            number,
            size,
            speed,
            collide,
            fill,
            points,
        } = &pattern.recipe
        else {
            return Ok(None);
        };
        if *item == ColorEffectSpatialBounceItem::Shape && *shape != 0 {
            return Err("Bounce supports only XEEL glyph Shape 0".to_string());
        }
        if !(2..=protocol::DASLIGHT_COLOR_PALETTE_MAX_STOPS).contains(&request.stops.len()) {
            return Err("Bounce requires between 2 and 255 palette stops".to_string());
        }
        if !(1..=20).contains(number)
            || !(1..=100).contains(size)
            || *speed > 10
            || !(2..=10).contains(points)
        {
            return Err("Bounce Number must be within 1..20, Size within 1..100, Speed within 0..10, and Points within 2..10".to_string());
        }
        let random_a = Arc::new(std::array::from_fn(|index| {
            let even_key = (index as u64 * 2).wrapping_mul(0x9E37_79B9_7F4A_7C15);
            let odd_key = (index as u64 * 2 + 1).wrapping_mul(0x9E37_79B9_7F4A_7C15);
            let a = (splitmix64(u64::from(*rng_seed) ^ even_key) >> 49) as u16;
            let _discarded_b = (splitmix64(u64::from(*rng_seed) ^ odd_key) >> 49) as u16;
            f32::from(a) / 32_767.0
        }));
        let initial_state = Arc::new(Self::initial_state(
            *item,
            usize::from(*number),
            usize::from(*points),
            &random_a,
        ));
        let mut sample_x = Vec::new();
        let mut sample_y = Vec::new();
        let mut slot_start = 0;
        let sampled_rows = sampled_rows.map(|x_mask| {
            let row = CompiledDaslightBounceSampleRow { x_mask, slot_start };
            slot_start += x_mask.count_ones() as usize;
            row
        });
        for (pixel_y, row) in sampled_rows.iter().copied().enumerate() {
            let mut pending = row.x_mask;
            while pending != 0 {
                let pixel_x = pending.trailing_zeros() as usize;
                sample_x.push(pixel_x as u8);
                sample_y.push(pixel_y as u8);
                pending &= pending - 1;
            }
        }
        let sampled_pixel_count = sample_x.len();
        let rendered_frame_count =
            (request.period_ms as usize / 40).clamp(1, DASLIGHT_BOUNCE_FRAME_CAP);
        let mut compiled = Self {
            #[cfg(test)]
            random_a,
            palette: request.stops.iter().map(|stop| stop.color).collect(),
            glyph: Arc::new(CompiledDaslightBounceGlyph::compile()),
            initial_state,
            item: *item,
            number: usize::from(*number),
            size: f32::from(*size),
            speed: f32::from(*speed),
            collide: *collide,
            fill: *fill,
            points: usize::from(*points),
            grayscale: *grayscale,
            rendered_frame_count,
            sample_x: sample_x.into(),
            sample_y: sample_y.into(),
            sampled_rows,
            precomputed_frames: None,
            raster_cache: None,
        };
        if precompute_supported_frames {
            compiled.precompute_frames(sampled_pixel_count);
        } else {
            compiled.raster_cache = Some(RefCell::new(CompiledDaslightBounceRasterCache::new(
                &compiled.initial_state,
                sampled_pixel_count,
            )));
        }
        Ok(Some(compiled))
    }

    fn initial_state(
        item: ColorEffectSpatialBounceItem,
        number: usize,
        points: usize,
        random: &[f32; DASLIGHT_BOUNCE_RANDOM_COUNT],
    ) -> CompiledDaslightBounceState {
        let item_width = if item == ColorEffectSpatialBounceItem::Points {
            points
        } else {
            1
        };
        let count = number * item_width;
        let mut state = CompiledDaslightBounceState {
            x: Vec::with_capacity(count),
            y: Vec::with_capacity(count),
            vx: Vec::with_capacity(count),
            vy: Vec::with_capacity(count),
        };
        for item_index in 0..number {
            let base = 2 + 10 * item_index;
            for point_index in 0..item_width {
                let key = (base + 10 * point_index) % DASLIGHT_BOUNCE_RANDOM_COUNT;
                state.x.push(
                    1.0 + 99.0
                        * random[(key + DASLIGHT_BOUNCE_RANDOM_COUNT - 2)
                            % DASLIGHT_BOUNCE_RANDOM_COUNT],
                );
                state.y.push(
                    1.0 + 99.0
                        * random[(key + DASLIGHT_BOUNCE_RANDOM_COUNT - 1)
                            % DASLIGHT_BOUNCE_RANDOM_COUNT],
                );
                if item == ColorEffectSpatialBounceItem::Points {
                    state.vx.push(1.0 + 99.0 * random[key]);
                    state
                        .vy
                        .push(1.0 + 99.0 * random[(key + 1) % DASLIGHT_BOUNCE_RANDOM_COUNT]);
                } else {
                    state.vx.push(2.0 * random[key] - 1.0);
                    state
                        .vy
                        .push(2.0 * random[(key + 1) % DASLIGHT_BOUNCE_RANDOM_COUNT] - 1.0);
                }
            }
        }
        state
    }

    #[inline(always)]
    fn raster_pixel(normalized: f32) -> usize {
        (normalized.clamp(0.0, 1.0) * DASLIGHT_BOUNCE_RASTER_SIZE as f32)
            .floor()
            .min((DASLIGHT_BOUNCE_RASTER_SIZE - 1) as f32) as usize
    }

    fn advance_state_dimensions(
        &self,
        state: &mut CompiledDaslightBounceState,
        width: f32,
        height: f32,
    ) {
        let boundary_size = if self.item == ColorEffectSpatialBounceItem::Points {
            0.0
        } else {
            self.size
        };
        for index in 0..state.x.len() {
            state.x[index] += state.vx[index] * self.speed;
            state.y[index] += state.vy[index] * self.speed;
            if state.x[index] < 0.0 && state.vx[index] < 0.0 {
                state.vx[index] = -state.vx[index];
            }
            if state.y[index] < 0.0 && state.vy[index] < 0.0 {
                state.vy[index] = -state.vy[index];
            }
            // Preserve the recovered source W/H swap defect and its lack of clamping.
            if state.x[index] > height - boundary_size && state.vx[index] > 0.0 {
                state.vx[index] = -state.vx[index];
            }
            if state.y[index] > width - boundary_size && state.vy[index] > 0.0 {
                state.vy[index] = -state.vy[index];
            }
        }
        if self.item == ColorEffectSpatialBounceItem::Shape && self.collide {
            self.collide_shapes(state);
        }
    }

    fn collide_shapes(&self, state: &mut CompiledDaslightBounceState) {
        for left in 0..self.number {
            for right in left + 1..self.number {
                let dx = state.x[right] - state.x[left];
                let dy = state.y[right] - state.y[left];
                if dx.abs() > self.size || dy.abs() > self.size {
                    continue;
                }
                let dist2 = dx * dx + dy * dy;
                if dist2 == 0.0 || dist2 > self.size * self.size {
                    continue;
                }
                let dvx = state.vx[right] - state.vx[left];
                let dvy = state.vy[right] - state.vy[left];
                let dot = dx * dvx + dy * dvy;
                if dot > 0.0 {
                    continue;
                }
                let impulse = dot / dist2;
                state.vx[left] += impulse * dx;
                state.vy[left] += impulse * dy;
                state.vx[right] -= impulse * dx;
                state.vy[right] -= impulse * dy;
            }
        }
    }

    fn point_hits_closed_path(
        &self,
        state: &CompiledDaslightBounceState,
        item: usize,
        x: f32,
        y: f32,
    ) -> bool {
        let start = item * self.points;
        let vertices =
            (0..self.points).map(|offset| (state.x[start + offset], state.y[start + offset]));
        if self.fill {
            let mut inside = false;
            let mut previous = (
                state.x[start + self.points - 1],
                state.y[start + self.points - 1],
            );
            for current in vertices {
                if (previous.1 > y) != (current.1 > y)
                    && x < (current.0 - previous.0) * (y - previous.1) / (current.1 - previous.1)
                        + previous.0
                {
                    inside = !inside;
                }
                previous = current;
            }
            inside
        } else {
            let radius2 = (self.size * 0.5) * (self.size * 0.5);
            let mut previous = (
                state.x[start + self.points - 1],
                state.y[start + self.points - 1],
            );
            for current in vertices {
                let dx = current.0 - previous.0;
                let dy = current.1 - previous.1;
                let length2 = dx * dx + dy * dy;
                let amount = if length2 == 0.0 {
                    0.0
                } else {
                    (((x - previous.0) * dx + (y - previous.1) * dy) / length2).clamp(0.0, 1.0)
                };
                let nearest_x = previous.0 + amount * dx;
                let nearest_y = previous.1 + amount * dy;
                let delta_x = x - nearest_x;
                let delta_y = y - nearest_y;
                if delta_x * delta_x + delta_y * delta_y <= radius2 {
                    return true;
                }
                previous = current;
            }
            false
        }
    }

    fn sampled_color(
        &self,
        state: &CompiledDaslightBounceState,
        pixel_x: u8,
        pixel_y: u8,
    ) -> ColorEffectColor {
        let x = f32::from(pixel_x) + 0.5;
        let y = f32::from(pixel_y) + 0.5;
        // Coverage is binary in the corrected deterministic pixel-centre
        // raster. Therefore reverse source order can stop at the first hit
        // while remaining exactly equivalent to later-wins painting.
        let mut color = self.palette[0];
        for item in (0..self.number).rev() {
            let hit = match self.item {
                ColorEffectSpatialBounceItem::Shape => {
                    self.glyph
                        .contains(x, y, state.x[item], state.y[item], self.size)
                }
                ColorEffectSpatialBounceItem::Points => {
                    self.point_hits_closed_path(state, item, x, y)
                }
            };
            if hit {
                color = self.palette[1 + item % (self.palette.len() - 1)];
                break;
            }
        }
        if self.grayscale {
            daslight_grayscale_color(color)
        } else {
            color
        }
    }

    fn render_sampled(
        &self,
        state: &CompiledDaslightBounceState,
        red: &mut [u16],
        green: &mut [u16],
        blue: &mut [u16],
    ) {
        for slot in 0..self.sample_x.len() {
            let color = self.sampled_color(state, self.sample_x[slot], self.sample_y[slot]);
            red[slot] = color.red;
            green[slot] = color.green;
            blue[slot] = color.blue;
        }
    }

    fn precompute_frames(&mut self, sampled_pixel_count: usize) {
        let mut state = (*self.initial_state).clone();
        let mut frames = CompiledDaslightBounceFrames {
            red: vec![0; self.rendered_frame_count * sampled_pixel_count],
            green: vec![0; self.rendered_frame_count * sampled_pixel_count],
            blue: vec![0; self.rendered_frame_count * sampled_pixel_count],
            sampled_pixel_count,
        };
        for generation in 0..self.rendered_frame_count {
            self.advance_state_dimensions(
                &mut state,
                DASLIGHT_BOUNCE_RASTER_SIZE as f32,
                DASLIGHT_BOUNCE_RASTER_SIZE as f32,
            );
            let start = generation * sampled_pixel_count;
            self.render_sampled(
                &state,
                &mut frames.red[start..start + sampled_pixel_count],
                &mut frames.green[start..start + sampled_pixel_count],
                &mut frames.blue[start..start + sampled_pixel_count],
            );
        }
        self.precomputed_frames = Some(Arc::new(frames));
    }

    fn generation(&self, time_phase: f64) -> usize {
        ((time_phase.rem_euclid(1.0) * self.rendered_frame_count as f64).floor() as usize)
            .min(self.rendered_frame_count - 1)
    }

    fn prepare_generation(&self, generation: usize) {
        if self.precomputed_frames.is_some() {
            return;
        }
        let mut cache = self
            .raster_cache
            .as_ref()
            .expect("dynamic Bounce evaluator must retain a raster cache")
            .borrow_mut();
        if cache.generation == Some(generation) {
            return;
        }
        let first_generation = if cache
            .generation
            .is_some_and(|previous| previous + 1 == generation)
        {
            generation
        } else {
            cache.state.copy_from(&self.initial_state);
            0
        };
        for _ in first_generation..=generation {
            self.advance_state_dimensions(
                &mut cache.state,
                DASLIGHT_BOUNCE_RASTER_SIZE as f32,
                DASLIGHT_BOUNCE_RASTER_SIZE as f32,
            );
        }
        let mut red = std::mem::take(&mut cache.red);
        let mut green = std::mem::take(&mut cache.green);
        let mut blue = std::mem::take(&mut cache.blue);
        self.render_sampled(&cache.state, &mut red, &mut green, &mut blue);
        cache.red = red;
        cache.green = green;
        cache.blue = blue;
        cache.generation = Some(generation);
        #[cfg(test)]
        {
            cache.rebuild_count += 1;
        }
    }

    fn sample_at_phase(
        &self,
        time_phase: f64,
        normalized_x: f32,
        normalized_y: f32,
    ) -> ColorEffectColor {
        let generation = self.generation(time_phase);
        let pixel_x = Self::raster_pixel(normalized_x) as u8;
        let pixel_y = Self::raster_pixel(normalized_y) as u8;
        let row = self.sampled_rows[usize::from(pixel_y)];
        debug_assert_ne!(row.x_mask & (1_u128 << pixel_x), 0);
        let preceding = row.x_mask & ((1_u128 << pixel_x) - 1);
        let slot = row.slot_start + preceding.count_ones() as usize;
        if let Some(frames) = &self.precomputed_frames {
            let index = generation * frames.sampled_pixel_count + slot;
            ColorEffectColor {
                red: frames.red[index],
                green: frames.green[index],
                blue: frames.blue[index],
            }
        } else {
            self.prepare_generation(generation);
            let cache = self
                .raster_cache
                .as_ref()
                .expect("dynamic Bounce cache missing")
                .borrow();
            ColorEffectColor {
                red: cache.red[slot],
                green: cache.green[slot],
                blue: cache.blue[slot],
            }
        }
    }

    #[cfg(test)]
    fn storage_pointers(&self) -> (usize, usize, usize, usize, usize, usize) {
        let frames = self
            .precomputed_frames
            .as_ref()
            .map_or((0, 0, 0), |frames| {
                (
                    frames.red.as_ptr() as usize,
                    frames.green.as_ptr() as usize,
                    frames.blue.as_ptr() as usize,
                )
            });
        (
            self.random_a.as_ptr() as usize,
            self.palette.as_ptr() as usize,
            frames.0,
            frames.1,
            frames.2,
            self.initial_state.x.as_ptr() as usize,
        )
    }

    #[cfg(test)]
    fn cache_state(&self) -> (Option<usize>, u64) {
        self.raster_cache.as_ref().map_or((None, 0), |cache| {
            let cache = cache.borrow();
            (cache.generation, cache.rebuild_count)
        })
    }
}

const DASLIGHT_FIRE_RASTER_WIDTH: usize = 100;
const DASLIGHT_FIRE_BUFFER_HEIGHT: usize = 102;
const DASLIGHT_FIRE_BUFFER_PIXELS: usize = DASLIGHT_FIRE_RASTER_WIDTH * DASLIGHT_FIRE_BUFFER_HEIGHT;
const DASLIGHT_FIRE_RANDOM_COUNT: usize = 5_000;
const DASLIGHT_FIRE_FRAME_CAP: usize = 750;

#[derive(Clone, Copy, Default)]
struct CompiledDaslightFireSampleRow {
    x_mask: u128,
    slot_start: usize,
}

#[derive(Clone)]
struct CompiledDaslightFireFrames {
    heat: Vec<u8>,
    sampled_pixel_count: usize,
}

#[derive(Clone)]
struct CompiledDaslightFireRasterCache {
    generation: Option<usize>,
    image: Box<[u8; DASLIGHT_FIRE_BUFFER_PIXELS]>,
    sampled_heat: Vec<u8>,
    #[cfg(test)]
    rebuild_count: u64,
}

impl CompiledDaslightFireRasterCache {
    fn new(sampled_pixel_count: usize) -> Self {
        Self {
            generation: None,
            image: Box::new([0; DASLIGHT_FIRE_BUFFER_PIXELS]),
            sampled_heat: vec![0; sampled_pixel_count],
            #[cfg(test)]
            rebuild_count: 0,
        }
    }
}

#[derive(Clone)]
struct CompiledDaslightFire {
    random_q15: Arc<[u16; DASLIGHT_FIRE_RANDOM_COUNT]>,
    palette_lut: Arc<[ColorEffectColor; 256]>,
    flames: f32,
    width: usize,
    hotspot: u8,
    rendered_frame_count: usize,
    sampled_rows: [CompiledDaslightFireSampleRow; DASLIGHT_FIRE_RASTER_WIDTH],
    precomputed_frames: Option<Arc<CompiledDaslightFireFrames>>,
    raster_cache: Option<RefCell<CompiledDaslightFireRasterCache>>,
}

impl CompiledDaslightFire {
    #[cfg(test)]
    fn compile(request: &ColorEffectRequest) -> Result<Option<Self>, String> {
        Self::compile_with_sampled_rows(
            request,
            [(1_u128 << DASLIGHT_FIRE_RASTER_WIDTH) - 1; DASLIGHT_FIRE_RASTER_WIDTH],
            false,
        )
    }

    fn compile_for_targets(
        request: &ColorEffectRequest,
        targets: &[RuntimeColorSpatialTarget],
    ) -> Result<Option<Self>, String> {
        let mut sampled_rows = [0_u128; DASLIGHT_FIRE_RASTER_WIDTH];
        for target in targets {
            let pixel_x = Self::raster_pixel(target.x);
            let pixel_y = Self::raster_pixel(target.z);
            sampled_rows[pixel_y] |= 1_u128 << pixel_x;
        }
        Self::compile_with_sampled_rows(
            request,
            sampled_rows,
            targets.len() <= SUPPORTED_EFFECT_ENVELOPE_FIXTURES,
        )
    }

    fn compile_with_sampled_rows(
        request: &ColorEffectRequest,
        sampled_rows: [u128; DASLIGHT_FIRE_RASTER_WIDTH],
        precompute_supported_frames: bool,
    ) -> Result<Option<Self>, String> {
        let Some(pattern) = request.spatial_pattern.as_ref() else {
            return Ok(None);
        };
        let ColorEffectSpatialRecipe::Fire {
            grayscale,
            rng_seed,
            flames,
            width,
            height,
            hotspot,
        } = &pattern.recipe
        else {
            return Ok(None);
        };
        if !(2..=4).contains(&request.stops.len()) {
            return Err("Fire requires between 2 and 4 palette stops".to_string());
        }
        if !(1..=100).contains(flames)
            || !(10..=200).contains(width)
            || !(1..=100).contains(height)
            || !(10..=255).contains(hotspot)
        {
            return Err(
                "Fire Flames must be within 1..100, Width within 10..200, Height within 1..100, and Hotspot within 10..255"
                    .to_string(),
            );
        }
        let random_q15 = Arc::new(std::array::from_fn(|index| {
            let even_key = (index as u64 * 2).wrapping_mul(0x9E37_79B9_7F4A_7C15);
            let odd_key = (index as u64 * 2 + 1).wrapping_mul(0x9E37_79B9_7F4A_7C15);
            let a = (splitmix64(u64::from(*rng_seed) ^ even_key) >> 49) as u16;
            let _discarded_b = (splitmix64(u64::from(*rng_seed) ^ odd_key) >> 49) as u16;
            a
        }));
        let cutoff = 100_u8 - *height as u8;
        let palette_lut = Arc::new(std::array::from_fn(|heat| {
            let color = if heat < usize::from(cutoff) {
                request.stops[0].color
            } else {
                let position = (heat as f32 - f32::from(cutoff)) / (255.0 - f32::from(cutoff));
                Self::nonwrapping_palette_color(request, position)
            };
            if *grayscale {
                daslight_grayscale_color(color)
            } else {
                color
            }
        }));
        let mut sampled_pixel_count = 0;
        let sampled_rows = sampled_rows.map(|x_mask| {
            let row = CompiledDaslightFireSampleRow {
                x_mask,
                slot_start: sampled_pixel_count,
            };
            sampled_pixel_count += x_mask.count_ones() as usize;
            row
        });
        let rendered_frame_count =
            (request.period_ms as usize / 40).clamp(1, DASLIGHT_FIRE_FRAME_CAP);
        let mut compiled = Self {
            random_q15,
            palette_lut,
            flames: f32::from(*flames),
            width: usize::from(*width),
            hotspot: *hotspot as u8,
            rendered_frame_count,
            sampled_rows,
            precomputed_frames: None,
            raster_cache: None,
        };
        if precompute_supported_frames {
            compiled.precompute_frames(sampled_pixel_count);
        } else {
            compiled.raster_cache = Some(RefCell::new(CompiledDaslightFireRasterCache::new(
                sampled_pixel_count,
            )));
        }
        Ok(Some(compiled))
    }

    fn nonwrapping_palette_color(request: &ColorEffectRequest, position: f32) -> ColorEffectColor {
        let position = position.clamp(0.0, 1.0);
        let upper = request
            .stops
            .partition_point(|stop| stop.position < position);
        if upper == 0 {
            return request.stops[0].color;
        }
        if upper >= request.stops.len() {
            return request.stops[request.stops.len() - 1].color;
        }
        let left = &request.stops[upper - 1];
        let right = &request.stops[upper];
        let amount =
            (position - left.position) / (right.position - left.position).max(f32::EPSILON);
        interpolate_color_effect_color(
            left.color,
            right.color,
            amount,
            ColorEffectInterpolation::Rgb,
        )
    }

    #[inline(always)]
    fn raster_pixel(normalized: f32) -> usize {
        (normalized.clamp(0.0, 1.0) * DASLIGHT_FIRE_RASTER_WIDTH as f32)
            .floor()
            .min((DASLIGHT_FIRE_RASTER_WIDTH - 1) as f32) as usize
    }

    fn advance_image(&self, image: &mut [u8; DASLIGHT_FIRE_BUFFER_PIXELS], generation: usize) {
        image[DASLIGHT_FIRE_RASTER_WIDTH..DASLIGHT_FIRE_RASTER_WIDTH * 2].fill(0);
        let mut x = 0;
        while x < DASLIGHT_FIRE_RASTER_WIDTH {
            let random = self.random_q15
                [(x + DASLIGHT_FIRE_RASTER_WIDTH * generation) % DASLIGHT_FIRE_RANDOM_COUNT];
            let a = f32::from(random) / 32_767.0;
            if 100.0 * a < self.flames {
                let run = (((self.width - 1) as f32 * a + 1.0).trunc() as usize)
                    .min(DASLIGHT_FIRE_RASTER_WIDTH - x);
                image[DASLIGHT_FIRE_RASTER_WIDTH + x..DASLIGHT_FIRE_RASTER_WIDTH + x + run]
                    .fill(self.hotspot);
                x += run;
            } else {
                x += 1;
            }
        }
        // The source walks X first and Y=1..100 second while updating the
        // flattened buffer in place. X edge neighbours intentionally spill
        // into adjacent flattened rows; replacing them with clamping changes
        // both the flame outline and every later dependent cell.
        for x in 0..DASLIGHT_FIRE_RASTER_WIDTH {
            for y in 1..=100 {
                let center = y * DASLIGHT_FIRE_RASTER_WIDTH + x;
                let sum = u16::from(image[center - DASLIGHT_FIRE_RASTER_WIDTH])
                    + u16::from(image[center - 2])
                    + u16::from(image[center - 1])
                    + u16::from(image[center])
                    + u16::from(image[center + 1])
                    + u16::from(image[center + 2])
                    + u16::from(image[center + DASLIGHT_FIRE_RASTER_WIDTH]);
                image[center + DASLIGHT_FIRE_RASTER_WIDTH] = (sum / 7) as u8;
            }
        }
    }

    fn copy_sampled_heat(&self, image: &[u8; DASLIGHT_FIRE_BUFFER_PIXELS], destination: &mut [u8]) {
        for (pixel_y, row) in self.sampled_rows.iter().enumerate() {
            let mut pending = row.x_mask;
            while pending != 0 {
                let pixel_x = pending.trailing_zeros() as usize;
                let preceding = row.x_mask & ((1_u128 << pixel_x) - 1);
                let slot = row.slot_start + preceding.count_ones() as usize;
                destination[slot] = image[(101 - pixel_y) * DASLIGHT_FIRE_RASTER_WIDTH + pixel_x];
                pending &= pending - 1;
            }
        }
    }

    fn precompute_frames(&mut self, sampled_pixel_count: usize) {
        let mut image = Box::new([0; DASLIGHT_FIRE_BUFFER_PIXELS]);
        let mut frames = CompiledDaslightFireFrames {
            heat: vec![0; self.rendered_frame_count * sampled_pixel_count],
            sampled_pixel_count,
        };
        for generation in 0..self.rendered_frame_count {
            self.advance_image(&mut image, generation);
            let start = generation * sampled_pixel_count;
            self.copy_sampled_heat(&image, &mut frames.heat[start..start + sampled_pixel_count]);
        }
        self.precomputed_frames = Some(Arc::new(frames));
    }

    fn generation(&self, time_phase: f64) -> usize {
        ((time_phase.rem_euclid(1.0) * self.rendered_frame_count as f64).floor() as usize)
            .min(self.rendered_frame_count - 1)
    }

    fn prepare_generation(&self, generation: usize) {
        if self.precomputed_frames.is_some() {
            return;
        }
        let mut cache = self
            .raster_cache
            .as_ref()
            .expect("dynamic Fire evaluator must retain a raster cache")
            .borrow_mut();
        if cache.generation == Some(generation) {
            return;
        }
        let first_generation = if cache
            .generation
            .is_some_and(|previous| previous + 1 == generation)
        {
            generation
        } else {
            cache.image.fill(0);
            0
        };
        for next in first_generation..=generation {
            self.advance_image(&mut cache.image, next);
        }
        let mut sampled_heat = std::mem::take(&mut cache.sampled_heat);
        self.copy_sampled_heat(&cache.image, &mut sampled_heat);
        cache.sampled_heat = sampled_heat;
        cache.generation = Some(generation);
        #[cfg(test)]
        {
            cache.rebuild_count += 1;
        }
    }

    fn sample_at_phase(
        &self,
        time_phase: f64,
        normalized_x: f32,
        normalized_y: f32,
    ) -> ColorEffectColor {
        let generation = self.generation(time_phase);
        let pixel_x = Self::raster_pixel(normalized_x);
        let pixel_y = Self::raster_pixel(normalized_y);
        let row = self.sampled_rows[pixel_y];
        debug_assert_ne!(row.x_mask & (1_u128 << pixel_x), 0);
        let preceding = row.x_mask & ((1_u128 << pixel_x) - 1);
        let slot = row.slot_start + preceding.count_ones() as usize;
        let heat = if let Some(frames) = &self.precomputed_frames {
            frames.heat[generation * frames.sampled_pixel_count + slot]
        } else {
            self.prepare_generation(generation);
            self.raster_cache
                .as_ref()
                .expect("dynamic Fire evaluator must retain a raster cache")
                .borrow()
                .sampled_heat[slot]
        };
        self.palette_lut[usize::from(heat)]
    }

    #[cfg(test)]
    fn storage_pointers(&self) -> (usize, usize, usize, usize, usize) {
        let frames = self
            .precomputed_frames
            .as_ref()
            .map_or(0, |frames| frames.heat.as_ptr() as usize);
        let (image, sampled) = self.raster_cache.as_ref().map_or((0, 0), |cache| {
            let cache = cache.borrow();
            (
                cache.image.as_ptr() as usize,
                cache.sampled_heat.as_ptr() as usize,
            )
        });
        (
            self.random_q15.as_ptr() as usize,
            self.palette_lut.as_ptr() as usize,
            frames,
            image,
            sampled,
        )
    }

    #[cfg(test)]
    fn cache_state(&self) -> (Option<usize>, u64) {
        self.raster_cache.as_ref().map_or((None, 0), |cache| {
            let cache = cache.borrow();
            (cache.generation, cache.rebuild_count)
        })
    }
}

const DASLIGHT_PARTICLE_RASTER_SIZE: usize = 100;
#[cfg(test)]
const DASLIGHT_PARTICLE_RASTER_PIXELS: usize =
    DASLIGHT_PARTICLE_RASTER_SIZE * DASLIGHT_PARTICLE_RASTER_SIZE;
const SYNDOCAL_PARTICLE_RANDOM_PAIR_COUNT: usize = 5_000;
const SYNDOCAL_PARTICLE_FRAME_CAP: usize = 750;
const DASLIGHT_PARTICLE_MAX_LAYERS: usize = 26;

#[derive(Clone, Copy)]
enum CompiledDaslightParticleRecipe {
    Explosion {
        explosion_number: usize,
        explosion_size: f32,
        particle_number: usize,
        particle_size: f32,
        particle_life: f32,
        trail_size: usize,
        gravity: f32,
    },
    Starfield {
        particles: usize,
        size: f32,
        trail: usize,
        rotation: f32,
    },
}

#[derive(Clone)]
struct CompiledDaslightParticleRasterCache {
    generation: Option<usize>,
    red: Vec<u16>,
    green: Vec<u16>,
    blue: Vec<u16>,
    #[cfg(test)]
    rebuild_count: u64,
}

impl CompiledDaslightParticleRasterCache {
    fn new(background: ColorEffectColor, sampled_pixel_count: usize) -> Self {
        Self {
            generation: None,
            red: vec![background.red; sampled_pixel_count],
            green: vec![background.green; sampled_pixel_count],
            blue: vec![background.blue; sampled_pixel_count],
            #[cfg(test)]
            rebuild_count: 0,
        }
    }

    fn fill(&mut self, background: ColorEffectColor) {
        self.red.fill(background.red);
        self.green.fill(background.green);
        self.blue.fill(background.blue);
    }

    fn color(&self, slot: usize) -> ColorEffectColor {
        ColorEffectColor {
            red: self.red[slot],
            green: self.green[slot],
            blue: self.blue[slot],
        }
    }
}

#[derive(Clone, Copy, Default)]
struct CompiledDaslightParticleSampleRow {
    x_mask: u128,
    slot_start: usize,
}

#[derive(Clone)]
struct CompiledDaslightParticleFrames {
    red: Vec<u16>,
    green: Vec<u16>,
    blue: Vec<u16>,
    sampled_pixel_count: usize,
}

#[derive(Clone)]
struct CompiledDaslightParticles {
    palette: Arc<[ColorEffectColor]>,
    grayscale: bool,
    source_frame_count: usize,
    rendered_frame_count: usize,
    random_pairs: Arc<[(f32, f32); SYNDOCAL_PARTICLE_RANDOM_PAIR_COUNT]>,
    sampled_rows: [CompiledDaslightParticleSampleRow; DASLIGHT_PARTICLE_RASTER_SIZE],
    sampled_y_rows: u128,
    recipe: CompiledDaslightParticleRecipe,
    raster_cache: Option<RefCell<CompiledDaslightParticleRasterCache>>,
    precomputed_frames: Option<Arc<CompiledDaslightParticleFrames>>,
}

type ParticleEllipse = (f64, f64, f64);

struct ExplosionRenderParams {
    explosion_number: usize,
    explosion_size: f32,
    particle_number: usize,
    particle_size: f32,
    particle_life: f32,
    trail_size: usize,
    gravity: f32,
}

impl CompiledDaslightParticles {
    #[cfg(test)]
    fn compile(request: &ColorEffectRequest) -> Result<Option<Self>, String> {
        Self::compile_with_sampled_rows(
            request,
            [(1_u128 << DASLIGHT_PARTICLE_RASTER_SIZE) - 1; DASLIGHT_PARTICLE_RASTER_SIZE],
            false,
        )
    }

    fn compile_for_targets(
        request: &ColorEffectRequest,
        targets: &[RuntimeColorSpatialTarget],
    ) -> Result<Option<Self>, String> {
        let mut sampled_rows = [0_u128; DASLIGHT_PARTICLE_RASTER_SIZE];
        for target in targets {
            let pixel_x = Self::raster_pixel(target.x);
            let pixel_y = Self::raster_pixel(target.z);
            sampled_rows[pixel_y] |= 1_u128 << pixel_x;
        }
        Self::compile_with_sampled_rows(
            request,
            sampled_rows,
            targets.len() <= SUPPORTED_EFFECT_ENVELOPE_FIXTURES,
        )
    }

    fn compile_with_sampled_rows(
        request: &ColorEffectRequest,
        sampled_rows: [u128; DASLIGHT_PARTICLE_RASTER_SIZE],
        precompute_supported_frames: bool,
    ) -> Result<Option<Self>, String> {
        let Some(pattern) = request.spatial_pattern.as_ref() else {
            return Ok(None);
        };
        let (grayscale, rng_seed, recipe) = match &pattern.recipe {
            ColorEffectSpatialRecipe::Explosion {
                grayscale,
                rng_seed,
                shape,
                explosion_number,
                explosion_size,
                particle_number,
                particle_size,
                particle_life,
                trail_size,
                gravity,
            } => {
                if *shape != 0 {
                    return Err("Explosion supports only filled-ellipse Shape 0".to_string());
                }
                (
                    *grayscale,
                    *rng_seed,
                    CompiledDaslightParticleRecipe::Explosion {
                        explosion_number: usize::from(*explosion_number),
                        explosion_size: f32::from(*explosion_size) / 10.0,
                        particle_number: usize::from(*particle_number),
                        particle_size: f32::from(*particle_size),
                        particle_life: *particle_life,
                        trail_size: usize::from(*trail_size),
                        gravity: *gravity,
                    },
                )
            }
            ColorEffectSpatialRecipe::Starfield {
                grayscale,
                rng_seed,
                shape,
                particles,
                size,
                trail,
                rotation,
            } => {
                if *shape != 0 {
                    return Err("Starfield supports only filled-ellipse Shape 0".to_string());
                }
                (
                    *grayscale,
                    *rng_seed,
                    CompiledDaslightParticleRecipe::Starfield {
                        particles: usize::from(*particles),
                        size: f32::from(*size),
                        trail: usize::from(*trail),
                        rotation: *rotation,
                    },
                )
            }
            _ => return Ok(None),
        };
        if !(2..=protocol::DASLIGHT_COLOR_PALETTE_MAX_STOPS).contains(&request.stops.len()) {
            return Err(
                "Explosion and Starfield require between 2 and 255 palette stops".to_string(),
            );
        }
        let source_frame_count = (request.period_ms as usize / 40).max(1);
        let rendered_frame_count = source_frame_count.min(SYNDOCAL_PARTICLE_FRAME_CAP);
        let random_pairs = Arc::new(std::array::from_fn(|index| {
            let index = index as u64;
            (
                syndocal_sparkle_unit_fraction(
                    u64::from(rng_seed) ^ index.wrapping_mul(0xA24B_AED4_963E_E407),
                ),
                syndocal_sparkle_unit_fraction(
                    u64::from(rng_seed)
                        ^ 0xC6BC_2796_92B5_CC83
                        ^ index.wrapping_mul(0x9E37_79B9_7F4A_7C15),
                ),
            )
        }));
        let palette = request
            .stops
            .iter()
            .map(|stop| stop.color)
            .collect::<Arc<[_]>>();
        let mut sampled_pixel_count = 0;
        let sampled_rows = sampled_rows.map(|x_mask| {
            let row = CompiledDaslightParticleSampleRow {
                x_mask,
                slot_start: sampled_pixel_count,
            };
            sampled_pixel_count += x_mask.count_ones() as usize;
            row
        });
        let raster_cache = (!precompute_supported_frames).then(|| {
            RefCell::new(CompiledDaslightParticleRasterCache::new(
                palette[0],
                sampled_pixel_count,
            ))
        });
        let sampled_y_rows = sampled_rows
            .iter()
            .enumerate()
            .fold(0_u128, |mask, (row, sampled)| {
                mask | (u128::from(sampled.x_mask != 0) << row)
            });
        let mut compiled = Self {
            palette,
            grayscale,
            source_frame_count,
            rendered_frame_count,
            random_pairs,
            sampled_rows,
            sampled_y_rows,
            recipe,
            raster_cache,
            precomputed_frames: None,
        };
        if precompute_supported_frames {
            compiled.precompute_frames(sampled_pixel_count);
        }
        Ok(Some(compiled))
    }

    fn random_pair(&self, index: usize) -> (f32, f32) {
        self.random_pairs[index % SYNDOCAL_PARTICLE_RANDOM_PAIR_COUNT]
    }

    fn raster_pixel(normalized: f32) -> usize {
        (normalized.clamp(0.0, 1.0) * DASLIGHT_PARTICLE_RASTER_SIZE as f32)
            .floor()
            .min((DASLIGHT_PARTICLE_RASTER_SIZE - 1) as f32) as usize
    }

    fn generation(&self, time_phase: f64) -> usize {
        (time_phase.rem_euclid(1.0) * self.rendered_frame_count as f64)
            .floor()
            .min((self.rendered_frame_count - 1) as f64) as usize
    }

    fn sampled_slot(&self, pixel_x: usize, pixel_y: usize) -> Option<usize> {
        let row = self.sampled_rows[pixel_y];
        let pixel_bit = 1_u128 << pixel_x;
        if row.x_mask & pixel_bit == 0 {
            return None;
        }
        let lower_bits = pixel_bit - 1;
        Some(row.slot_start + (row.x_mask & lower_bits).count_ones() as usize)
    }

    fn source_over_ellipse_sampled(
        sampled_rows: &[CompiledDaslightParticleSampleRow; DASLIGHT_PARTICLE_RASTER_SIZE],
        sampled_y_rows: u128,
        cache: &mut CompiledDaslightParticleRasterCache,
        ellipse: ParticleEllipse,
        color: ColorEffectColor,
        opacity: f32,
    ) {
        let (x, y, size) = ellipse;
        let opacity = opacity.clamp(0.0, 1.0);
        if opacity <= 0.0 || size <= 0.0 {
            return;
        }
        let minimum_x = x.floor().max(0.0) as i32;
        let minimum_y = y.floor().max(0.0) as i32;
        let maximum_x = (x + size).ceil().min(DASLIGHT_PARTICLE_RASTER_SIZE as f64) as i32;
        let maximum_y = (y + size).ceil().min(DASLIGHT_PARTICLE_RASTER_SIZE as f64) as i32;
        if minimum_x >= maximum_x || minimum_y >= maximum_y {
            return;
        }
        let radius = size * 0.5;
        let center_x = x + radius;
        let center_y = y + radius;
        let inverse_radius = 1.0 / radius;
        let y_span_width = (maximum_y - minimum_y) as u32;
        let y_span_mask = ((1_u128 << y_span_width) - 1) << minimum_y;
        let mut pending_y = sampled_y_rows & y_span_mask;
        while pending_y != 0 {
            let pixel_y = pending_y.trailing_zeros() as i32;
            pending_y &= pending_y - 1;
            let row = sampled_rows[pixel_y as usize];
            let normalized_y = (f64::from(pixel_y) + 0.5 - center_y) * inverse_radius;
            let remaining = 1.0 - normalized_y * normalized_y;
            if remaining < 0.0 {
                continue;
            }
            let half_span = radius * remaining.sqrt();
            let row_minimum = (center_x - half_span - 0.5)
                .ceil()
                .max(f64::from(minimum_x)) as i32;
            let row_maximum = (center_x + half_span - 0.5)
                .floor()
                .min(f64::from(maximum_x - 1)) as i32;
            if row_minimum > row_maximum {
                continue;
            }
            let span_width = (row_maximum - row_minimum + 1) as u32;
            let span_mask = ((1_u128 << span_width) - 1) << row_minimum;
            let mut pending = row.x_mask & span_mask;
            while pending != 0 {
                let run_x = pending.trailing_zeros() as usize;
                let run_len = (pending >> run_x).trailing_ones() as usize;
                let run_mask = ((1_u128 << run_len) - 1) << run_x;
                pending &= !run_mask;
                let lower_bits = (1_u128 << run_x) - 1;
                let slot_start = row.slot_start + (row.x_mask & lower_bits).count_ones() as usize;
                let slot_range = slot_start..slot_start + run_len;
                if opacity >= 1.0 {
                    cache.red[slot_range.clone()].fill(color.red);
                    cache.green[slot_range.clone()].fill(color.green);
                    cache.blue[slot_range].fill(color.blue);
                } else {
                    syndocal_tube_blend_channel_slice(
                        &mut cache.red[slot_range.clone()],
                        color.red,
                        opacity,
                    );
                    syndocal_tube_blend_channel_slice(
                        &mut cache.green[slot_range.clone()],
                        color.green,
                        opacity,
                    );
                    syndocal_tube_blend_channel_slice(
                        &mut cache.blue[slot_range],
                        color.blue,
                        opacity,
                    );
                }
            }
        }
    }

    #[cfg(test)]
    fn source_over_ellipse_masked(
        sampled_rows: &[u128; DASLIGHT_PARTICLE_RASTER_SIZE],
        sampled_y_rows: u128,
        raster: &mut [ColorEffectColor; DASLIGHT_PARTICLE_RASTER_PIXELS],
        ellipse: ParticleEllipse,
        color: ColorEffectColor,
        opacity: f32,
    ) {
        let (x, y, size) = ellipse;
        let opacity = opacity.clamp(0.0, 1.0);
        if opacity <= 0.0 || size <= 0.0 {
            return;
        }
        let minimum_x = x.floor().max(0.0) as i32;
        let minimum_y = y.floor().max(0.0) as i32;
        let maximum_x = (x + size).ceil().min(DASLIGHT_PARTICLE_RASTER_SIZE as f64) as i32;
        let maximum_y = (y + size).ceil().min(DASLIGHT_PARTICLE_RASTER_SIZE as f64) as i32;
        if minimum_x >= maximum_x || minimum_y >= maximum_y {
            return;
        }
        let radius = size * 0.5;
        let center_x = x + radius;
        let center_y = y + radius;
        let inverse_radius = 1.0 / radius;
        let y_span_width = (maximum_y - minimum_y) as u32;
        let y_span_mask = ((1_u128 << y_span_width) - 1) << minimum_y;
        let mut pending_y = sampled_y_rows & y_span_mask;
        while pending_y != 0 {
            let pixel_y = pending_y.trailing_zeros() as i32;
            pending_y &= pending_y - 1;
            let sampled_row = sampled_rows[pixel_y as usize];
            let normalized_y = (f64::from(pixel_y) + 0.5 - center_y) * inverse_radius;
            let remaining = 1.0 - normalized_y * normalized_y;
            if remaining < 0.0 {
                continue;
            }
            let half_span = radius * remaining.sqrt();
            let row_minimum = (center_x - half_span - 0.5)
                .ceil()
                .max(f64::from(minimum_x)) as i32;
            let row_maximum = (center_x + half_span - 0.5)
                .floor()
                .min(f64::from(maximum_x - 1)) as i32;
            if row_minimum > row_maximum {
                continue;
            }
            let row = pixel_y as usize * DASLIGHT_PARTICLE_RASTER_SIZE;
            let span_width = (row_maximum - row_minimum + 1) as u32;
            let span_mask = ((1_u128 << span_width) - 1) << row_minimum;
            let mut pending = sampled_row & span_mask;
            while pending != 0 {
                let pixel_x = pending.trailing_zeros() as usize;
                let destination = &mut raster[row + pixel_x];
                if opacity >= 1.0 {
                    *destination = color;
                } else if *destination != color {
                    *destination = interpolate_color_effect_color(
                        *destination,
                        color,
                        opacity,
                        ColorEffectInterpolation::Rgb,
                    );
                }
                pending &= pending - 1;
            }
        }
    }

    #[cfg(test)]
    fn source_over_ellipse(
        raster: &mut [ColorEffectColor; DASLIGHT_PARTICLE_RASTER_PIXELS],
        x: f64,
        y: f64,
        size: f64,
        color: ColorEffectColor,
        opacity: f32,
    ) {
        Self::source_over_ellipse_masked(
            &[(1_u128 << DASLIGHT_PARTICLE_RASTER_SIZE) - 1; DASLIGHT_PARTICLE_RASTER_SIZE],
            (1_u128 << DASLIGHT_PARTICLE_RASTER_SIZE) - 1,
            raster,
            (x, y, size),
            color,
            opacity,
        );
    }

    #[cfg(test)]
    fn source_over_ellipse_reference(
        raster: &mut [ColorEffectColor; DASLIGHT_PARTICLE_RASTER_PIXELS],
        x: f64,
        y: f64,
        size: f64,
        color: ColorEffectColor,
        opacity: f32,
    ) {
        let opacity = opacity.clamp(0.0, 1.0);
        if opacity <= 0.0 || size <= 0.0 {
            return;
        }
        let minimum_x = x.floor().max(0.0) as i32;
        let minimum_y = y.floor().max(0.0) as i32;
        let maximum_x = (x + size).ceil().min(DASLIGHT_PARTICLE_RASTER_SIZE as f64) as i32;
        let maximum_y = (y + size).ceil().min(DASLIGHT_PARTICLE_RASTER_SIZE as f64) as i32;
        if minimum_x >= maximum_x || minimum_y >= maximum_y {
            return;
        }
        let radius = size * 0.5;
        let center_x = x + radius;
        let center_y = y + radius;
        let inverse_radius = 1.0 / radius;
        for pixel_y in minimum_y..maximum_y {
            let normalized_y = (f64::from(pixel_y) + 0.5 - center_y) * inverse_radius;
            let remaining = 1.0 - normalized_y * normalized_y;
            if remaining < 0.0 {
                continue;
            }
            let half_span = radius * remaining.sqrt();
            let row_minimum = (center_x - half_span - 0.5)
                .ceil()
                .max(f64::from(minimum_x)) as i32;
            let row_maximum = (center_x + half_span - 0.5)
                .floor()
                .min(f64::from(maximum_x - 1)) as i32;
            if row_minimum > row_maximum {
                continue;
            }
            let row = pixel_y as usize * DASLIGHT_PARTICLE_RASTER_SIZE;
            for pixel_x in row_minimum..=row_maximum {
                let destination = &mut raster[row + pixel_x as usize];
                *destination = interpolate_color_effect_color(
                    *destination,
                    color,
                    opacity,
                    ColorEffectInterpolation::Rgb,
                );
            }
        }
    }

    fn paint_layers_masked(
        &self,
        cache: &mut CompiledDaslightParticleRasterCache,
        layers: &[(f64, f64, f64, ColorEffectColor, f32)],
    ) {
        for &(x, y, size, color, opacity) in layers {
            Self::source_over_ellipse_sampled(
                &self.sampled_rows,
                self.sampled_y_rows,
                cache,
                (x, y, size),
                color,
                opacity,
            );
        }
    }

    #[cfg(test)]
    fn paint_layers(
        raster: &mut [ColorEffectColor; DASLIGHT_PARTICLE_RASTER_PIXELS],
        layers: &[(f64, f64, f64, ColorEffectColor, f32)],
    ) {
        for &(x, y, size, color, opacity) in layers {
            Self::source_over_ellipse(raster, x, y, size, color, opacity);
        }
    }

    #[cfg(test)]
    fn explosion_position(
        center_x: f32,
        center_y: f32,
        velocity_x: f32,
        velocity_y: f32,
        motion: f32,
        gravity: f32,
        age: usize,
    ) -> (f32, f32) {
        let (x, y, _) = Self::explosion_trajectory(
            center_x, center_y, velocity_x, velocity_y, motion, gravity, age,
        );
        (x, y)
    }

    fn explosion_trajectory(
        center_x: f32,
        center_y: f32,
        velocity_x: f32,
        velocity_y: f32,
        motion: f32,
        gravity: f32,
        age: usize,
    ) -> (f32, f32, f32) {
        let mut x = center_x;
        let mut y = center_y;
        let mut velocity_y = velocity_y;
        for _ in 0..age {
            Self::advance_explosion_trajectory(
                &mut x,
                &mut y,
                velocity_x,
                &mut velocity_y,
                motion,
                gravity,
            );
        }
        (x, y, velocity_y)
    }

    fn advance_explosion_trajectory(
        x: &mut f32,
        y: &mut f32,
        velocity_x: f32,
        velocity_y: &mut f32,
        motion: f32,
        gravity: f32,
    ) {
        *x += velocity_x * motion;
        *y += *velocity_y * motion;
        *velocity_y += gravity / 50.0;
    }

    #[cfg(test)]
    fn explosion_position_reference(
        center_x: f32,
        center_y: f32,
        velocity_x: f32,
        velocity_y: f32,
        motion: f32,
        gravity: f32,
        age: usize,
    ) -> (f32, f32) {
        let mut x = center_x;
        let mut y = center_y;
        let mut velocity_y = velocity_y;
        for _ in 0..age {
            x += velocity_x * motion;
            y += velocity_y * motion;
            velocity_y += gravity / 50.0;
        }
        (x, y)
    }

    fn explosion_spawn_period(rendered_frame_count: usize, explosion_number: usize) -> usize {
        (rendered_frame_count / explosion_number).max(1)
    }

    #[cfg(test)]
    fn explosion_spawn_count(
        rendered_frame_count: usize,
        explosion_number: usize,
        generation: usize,
    ) -> usize {
        generation / Self::explosion_spawn_period(rendered_frame_count, explosion_number) + 1
    }

    #[cfg(test)]
    fn starfield_position(angle: f32, rotation: f32, radius: f32, age: usize) -> (f32, f32) {
        let (x, y, _, _) = Self::starfield_trajectory(angle, rotation, radius, age);
        (x, y)
    }

    fn starfield_trajectory(
        angle: f32,
        rotation: f32,
        radius: f32,
        age: usize,
    ) -> (f32, f32, f32, f32) {
        let initial_angle = angle.to_radians();
        let initial_x = (initial_angle.cos() * radius).trunc();
        let initial_y = (initial_angle.sin() * radius).trunc();
        let mut angle = angle;
        let mut radius = initial_x.hypot(initial_y);
        let mut x = (DASLIGHT_PARTICLE_RASTER_SIZE / 2) as f32 + initial_x;
        let mut y = (DASLIGHT_PARTICLE_RASTER_SIZE / 2) as f32 + initial_y;
        for _ in 0..age {
            Self::advance_starfield_trajectory(&mut x, &mut y, &mut radius, &mut angle, rotation);
        }
        (x, y, radius, angle)
    }

    fn advance_starfield_trajectory(
        x: &mut f32,
        y: &mut f32,
        radius: &mut f32,
        angle: &mut f32,
        rotation: f32,
    ) {
        *radius += 1.0;
        let radians = angle.to_radians();
        *x = (DASLIGHT_PARTICLE_RASTER_SIZE / 2) as f32 + radians.cos() * *radius;
        *y = (DASLIGHT_PARTICLE_RASTER_SIZE / 2) as f32 + radians.sin() * *radius;
        *angle += rotation;
    }

    #[cfg(test)]
    fn starfield_position_reference(
        angle: f32,
        rotation: f32,
        radius: f32,
        age: usize,
    ) -> (f32, f32) {
        let initial_angle = angle.to_radians();
        let initial_x = (initial_angle.cos() * radius).trunc();
        let initial_y = (initial_angle.sin() * radius).trunc();
        if age == 0 {
            return (
                (DASLIGHT_PARTICLE_RASTER_SIZE / 2) as f32 + initial_x,
                (DASLIGHT_PARTICLE_RASTER_SIZE / 2) as f32 + initial_y,
            );
        }
        let mut angle = angle;
        let mut radius = initial_x.hypot(initial_y);
        let mut x = (DASLIGHT_PARTICLE_RASTER_SIZE / 2) as f32 + initial_x;
        let mut y = (DASLIGHT_PARTICLE_RASTER_SIZE / 2) as f32 + initial_y;
        for _ in 0..age {
            radius += 1.0;
            let radians = angle.to_radians();
            x = (DASLIGHT_PARTICLE_RASTER_SIZE / 2) as f32 + radians.cos() * radius;
            y = (DASLIGHT_PARTICLE_RASTER_SIZE / 2) as f32 + radians.sin() * radius;
            angle += rotation;
        }
        (x, y)
    }

    fn render_explosion(
        &self,
        cache: &mut CompiledDaslightParticleRasterCache,
        generation: usize,
        params: ExplosionRenderParams,
    ) {
        let ExplosionRenderParams {
            explosion_number,
            explosion_size,
            particle_number,
            particle_size,
            particle_life,
            trail_size,
            gravity,
        } = params;
        let spawn_period =
            Self::explosion_spawn_period(self.rendered_frame_count, explosion_number);
        let decay = (1.0 - particle_life) * 0.05;
        let lower = (DASLIGHT_PARTICLE_RASTER_SIZE / 6) as f32;
        let upper = (DASLIGHT_PARTICLE_RASTER_SIZE * 5 / 6) as f32;
        for spawn_frame in (0..=generation).step_by(spawn_period) {
            let (center_random_x, center_random_y) = self.random_pair(spawn_frame);
            let center_x = lower + center_random_x * (upper - lower);
            let center_y = lower + center_random_y * (upper - lower);
            let color_index = 1 + (spawn_frame / spawn_period) % (self.palette.len() - 1);
            let color = self.palette[color_index];
            let age = generation - spawn_frame;
            let parent_opacity = 1.0 - decay * age as f32;
            if parent_opacity <= 0.0 {
                continue;
            }
            for particle_index in 0..particle_number {
                let (random_x, random_y) = self.random_pair(spawn_frame + particle_index);
                let velocity_x = 4.0 * random_x - 2.0;
                let velocity_y = 4.0 * random_y - 2.0;
                let child_count = age.min(trail_size).min(DASLIGHT_PARTICLE_MAX_LAYERS - 1);
                let mut layers =
                    [(0.0, 0.0, 0.0, self.palette[0], 0.0); DASLIGHT_PARTICLE_MAX_LAYERS];
                let first_age = age - child_count;
                let (mut x, mut y, mut trajectory_velocity_y) = Self::explosion_trajectory(
                    center_x,
                    center_y,
                    velocity_x,
                    velocity_y,
                    explosion_size,
                    gravity,
                    first_age,
                );
                if child_count > 0 {
                    let previous_opacity = 1.0 - decay * (age - 1) as f32;
                    for (oldest_index, layer) in layers.iter_mut().take(child_count).enumerate() {
                        let newest_index = child_count - 1 - oldest_index;
                        let child_opacity =
                            previous_opacity * (1.0 - newest_index as f32 / trail_size as f32);
                        *layer = (
                            f64::from(x),
                            f64::from(y),
                            f64::from(particle_size),
                            color,
                            child_opacity,
                        );
                        Self::advance_explosion_trajectory(
                            &mut x,
                            &mut y,
                            velocity_x,
                            &mut trajectory_velocity_y,
                            explosion_size,
                            gravity,
                        );
                    }
                }
                layers[child_count] = (
                    f64::from(x),
                    f64::from(y),
                    f64::from(particle_size),
                    color,
                    parent_opacity,
                );
                self.paint_layers_masked(cache, &layers[..=child_count]);
            }
        }
    }

    fn render_starfield(
        &self,
        cache: &mut CompiledDaslightParticleRasterCache,
        generation: usize,
        particles: usize,
        size: f32,
        trail: usize,
        rotation: f32,
    ) {
        let spawn_interval = 12 - particles;
        let decay = 1.0 / self.source_frame_count as f32;
        for spawn_frame in (0..=generation).step_by(spawn_interval) {
            let (random_x, random_y) = self.random_pair(spawn_frame);
            let palette_index = (1 + ((self.palette.len() - 1) as f32 * random_x).trunc() as usize)
                .min(self.palette.len() - 1);
            let color = self.palette[palette_index];
            let radius = (random_x * 10.0 + 5.0).trunc();
            let angle = random_y * 360.0;
            let age = generation - spawn_frame;
            let parent_opacity = 1.0 - decay * age as f32;
            if parent_opacity <= 0.0 {
                continue;
            }
            let child_count = age.min(trail).min(DASLIGHT_PARTICLE_MAX_LAYERS - 1);
            let mut layers = [(0.0, 0.0, 0.0, self.palette[0], 0.0); DASLIGHT_PARTICLE_MAX_LAYERS];
            let first_age = age - child_count;
            let (mut x, mut y, mut trajectory_radius, mut trajectory_angle) =
                Self::starfield_trajectory(angle, rotation, radius, first_age);
            if child_count > 0 {
                let previous_opacity = 1.0 - decay * (age - 1) as f32;
                for (oldest_index, layer) in layers.iter_mut().take(child_count).enumerate() {
                    let newest_index = child_count - 1 - oldest_index;
                    let child_opacity =
                        previous_opacity * (1.0 - newest_index as f32 / trail as f32);
                    *layer = (
                        f64::from(x),
                        f64::from(y),
                        f64::from(size),
                        color,
                        child_opacity,
                    );
                    Self::advance_starfield_trajectory(
                        &mut x,
                        &mut y,
                        &mut trajectory_radius,
                        &mut trajectory_angle,
                        rotation,
                    );
                }
            }
            layers[child_count] = (
                f64::from(x),
                f64::from(y),
                f64::from(size),
                color,
                parent_opacity,
            );
            self.paint_layers_masked(cache, &layers[..=child_count]);
        }
    }

    fn render_generation_into(
        &self,
        cache: &mut CompiledDaslightParticleRasterCache,
        generation: usize,
    ) {
        cache.fill(self.palette[0]);
        match self.recipe {
            CompiledDaslightParticleRecipe::Explosion {
                explosion_number,
                explosion_size,
                particle_number,
                particle_size,
                particle_life,
                trail_size,
                gravity,
            } => self.render_explosion(
                cache,
                generation,
                ExplosionRenderParams {
                    explosion_number,
                    explosion_size,
                    particle_number,
                    particle_size,
                    particle_life,
                    trail_size,
                    gravity,
                },
            ),
            CompiledDaslightParticleRecipe::Starfield {
                particles,
                size,
                trail,
                rotation,
            } => self.render_starfield(cache, generation, particles, size, trail, rotation),
        }
    }

    fn precompute_frames(&mut self, sampled_pixel_count: usize) {
        let color_count = self.rendered_frame_count * sampled_pixel_count;
        let mut frames = CompiledDaslightParticleFrames {
            red: Vec::with_capacity(color_count),
            green: Vec::with_capacity(color_count),
            blue: Vec::with_capacity(color_count),
            sampled_pixel_count,
        };
        let mut generation_cache =
            CompiledDaslightParticleRasterCache::new(self.palette[0], sampled_pixel_count);
        for generation in 0..self.rendered_frame_count {
            self.render_generation_into(&mut generation_cache, generation);
            frames.red.extend_from_slice(&generation_cache.red);
            frames.green.extend_from_slice(&generation_cache.green);
            frames.blue.extend_from_slice(&generation_cache.blue);
        }
        self.precomputed_frames = Some(Arc::new(frames));
    }

    fn prepare_generation(&self, generation: usize) {
        if self.precomputed_frames.is_some() {
            return;
        }
        let mut cache = self
            .raster_cache
            .as_ref()
            .expect("dynamic particle evaluator must retain a generation cache")
            .borrow_mut();
        if cache.generation == Some(generation) {
            return;
        }
        self.render_generation_into(&mut cache, generation);
        cache.generation = Some(generation);
        #[cfg(test)]
        {
            cache.rebuild_count += 1;
        }
    }

    fn sample_at_phase(
        &self,
        time_phase: f64,
        normalized_x: f32,
        normalized_y: f32,
    ) -> ColorEffectColor {
        let generation = self.generation(time_phase);
        self.prepare_generation(generation);
        let pixel_x = Self::raster_pixel(normalized_x);
        let pixel_y = Self::raster_pixel(normalized_y);
        let slot = self
            .sampled_slot(pixel_x, pixel_y)
            .expect("compiled particle target mask must contain every sampled runtime pixel");
        let color = if let Some(frames) = &self.precomputed_frames {
            let index = generation * frames.sampled_pixel_count + slot;
            ColorEffectColor {
                red: frames.red[index],
                green: frames.green[index],
                blue: frames.blue[index],
            }
        } else {
            self.raster_cache
                .as_ref()
                .expect("dynamic particle evaluator must retain a generation cache")
                .borrow()
                .color(slot)
        };
        if self.grayscale {
            daslight_grayscale_color(color)
        } else {
            color
        }
    }

    #[cfg(test)]
    fn cache_state(&self) -> (Option<usize>, u64) {
        self.raster_cache
            .as_ref()
            .map(|cache| {
                let cache = cache.borrow();
                (cache.generation, cache.rebuild_count)
            })
            .unwrap_or((None, 0))
    }

    #[cfg(test)]
    fn storage_pointers(&self) -> (usize, usize, usize, usize, usize, usize, usize, usize) {
        let (cache_red, cache_green, cache_blue) = self
            .raster_cache
            .as_ref()
            .map(|cache| {
                let cache = cache.borrow();
                (
                    cache.red.as_ptr() as usize,
                    cache.green.as_ptr() as usize,
                    cache.blue.as_ptr() as usize,
                )
            })
            .unwrap_or_default();
        let (frames_red, frames_green, frames_blue) = self
            .precomputed_frames
            .as_ref()
            .map(|frames| {
                (
                    frames.red.as_ptr() as usize,
                    frames.green.as_ptr() as usize,
                    frames.blue.as_ptr() as usize,
                )
            })
            .unwrap_or_default();
        (
            self.palette.as_ptr() as usize,
            self.random_pairs.as_ptr() as usize,
            cache_red,
            cache_green,
            cache_blue,
            frames_red,
            frames_green,
            frames_blue,
        )
    }
}

#[derive(Clone)]
struct RuntimeColorMappingEffect {
    request: ColorMappingEffectRequest,
    /// Packed protocol pixels decoded once on command/rebuild.
    frames: Vec<Vec<ColorEffectColor>>,
    targets: Vec<RuntimeColorMappingTarget>,
    attribute_indices: HashMap<FixtureId, HashMap<String, usize>>,
}

#[derive(Clone)]
struct RuntimeColorMappingTarget {
    sample: RuntimeColorMappingSample,
    binding: RuntimeColorBinding,
    feature_range: Option<(u16, u16)>,
    cached: Cell<Option<RuntimeColorEvaluation>>,
}

#[derive(Debug, Clone, Copy)]
struct RuntimeColorMappingSample {
    indices: [usize; 4],
    weights: [f32; 4],
}

#[derive(Debug, Clone)]
struct RuntimeMoveEffect {
    request: MoveEffectRequest,
    path: CompiledMovePath,
    targets: Vec<RuntimeMoveTarget>,
    target_indices: HashMap<FixtureId, usize>,
    single_target_indices: HashMap<FixtureId, usize>,
    last_single_target_index: Cell<Option<usize>>,
    /// Fixture/control identity is compiled once on add/update/rebuild. The
    /// 44 Hz evaluator performs two fixed hash reads and no beam search.
    attribute_indices: HashMap<FixtureId, HashMap<String, usize>>,
    rotation_cosine: f32,
    rotation_sine: f32,
}

#[derive(Debug, Clone)]
struct RuntimeMoveTarget {
    fixture_id: FixtureId,
    pan_attribute: String,
    tilt_attribute: String,
    phase_offset: f32,
    reverse_time: bool,
    mirror_pan: bool,
    /// Corrected continuous fixture phasing. This preserves authored selection
    /// order without tying the offset to a 40 ms frame count.
    daslight_phase_delta: f32,
    daslight_reverse_wing: bool,
    cached: Cell<Option<RuntimeMoveEvaluation>>,
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct RuntimeMoveEvaluation {
    at: Instant,
    delta: MovePathPoint,
}

#[derive(Debug, Clone)]
struct RuntimeChaserEffect {
    request: ChaserEffectRequest,
    step_order: Vec<usize>,
    target_phase_offsets: HashMap<FixtureId, f32>,
    #[cfg(test)]
    target_step_levels: HashMap<FixtureId, Vec<u16>>,
    #[cfg(test)]
    target_step_maxima: HashMap<FixtureId, CompiledChaserStepMaxima>,
    hot_targets: Vec<RuntimeChaserHotTarget>,
    hot_target_indices: HashMap<FixtureId, usize>,
    last_hot_target_index: Cell<Option<usize>>,
    #[cfg(test)]
    feature_indices: ChaserAttributeMap<usize>,
    hot_feature_slots: [RuntimeChaserFeatureSlot; 32],
    #[cfg(test)]
    feature_fixture_ids: Vec<Vec<FixtureId>>,
    beam_targets: Vec<RuntimeChaserBeamTarget>,
    beam_attribute_indices: HashMap<FixtureId, HashMap<String, usize>>,
}

#[derive(Debug, Clone, Copy)]
struct RuntimeChaserFeatureSlot {
    hash: u64,
    feature_index: u8,
}

const EMPTY_CHASER_FEATURE_INDEX: u8 = u8::MAX;

impl Default for RuntimeChaserFeatureSlot {
    fn default() -> Self {
        Self {
            hash: 0,
            feature_index: EMPTY_CHASER_FEATURE_INDEX,
        }
    }
}

#[derive(Debug, Clone)]
struct RuntimeChaserHotTarget {
    fixture_id: FixtureId,
    phase_offset: f32,
    step_levels: Vec<u16>,
    step_maxima: CompiledChaserStepMaxima,
    build_up_down_levels: Option<Vec<u16>>,
    block_levels: Option<CompiledChaserBlockLevels>,
    feature_mask: u16,
    control_feature_indices: Vec<Option<u8>>,
    cache: Cell<Option<RuntimeChaserEvaluation>>,
}

#[derive(Debug, Clone)]
enum CompiledChaserBlockLevels {
    Constant(u16),
    Cyclic(Vec<u16>),
}

#[derive(Debug, Clone, Default)]
struct CompiledChaserStepMaxima {
    prefix: Vec<u16>,
    suffix: Vec<u16>,
}

impl CompiledChaserStepMaxima {
    fn compile(levels: &[u16]) -> Self {
        let mut prefix = Vec::with_capacity(levels.len() + 1);
        prefix.push(0);
        for level in levels {
            prefix.push(prefix.last().copied().unwrap_or(0).max(*level));
        }

        let mut suffix = vec![0; levels.len() + 1];
        for index in (0..levels.len()).rev() {
            suffix[index] = suffix[index + 1].max(levels[index]);
        }
        Self { prefix, suffix }
    }
}

fn compile_chaser_build_up_down_levels(
    step_count: usize,
    wing_count: usize,
    maxima: &CompiledChaserStepMaxima,
) -> Vec<u16> {
    let cycle_len = step_count.max(1) * 2;
    (0..cycle_len)
        .map(|absolute_slot| {
            (0..wing_count.max(1)).fold(0_u16, |level, wing| {
                let wing_offset = wing * cycle_len / wing_count.max(1);
                let cycle_position = (absolute_slot + wing_offset) % cycle_len;
                let filling = cycle_position < step_count;
                let frontier = if filling {
                    cycle_position
                } else {
                    cycle_position - step_count
                };
                let wing_level = if filling {
                    maxima.prefix[frontier + 1]
                } else {
                    maxima.suffix[frontier + 1]
                };
                level.max(wing_level)
            })
        })
        .collect()
}

fn compile_chaser_block_levels(
    step_order: &[usize],
    step_levels: &[u16],
    active_step_count: usize,
    wing_count: usize,
) -> CompiledChaserBlockLevels {
    let path_len = step_order.len().max(1);
    let wing_count = wing_count.max(1);
    let largest_wing_gap = path_len.div_ceil(wing_count);
    if active_step_count >= largest_wing_gap {
        let level = step_order.iter().fold(0_u16, |level, step_index| {
            level.max(step_levels.get(*step_index).copied().unwrap_or(0))
        });
        return CompiledChaserBlockLevels::Constant(level);
    }
    CompiledChaserBlockLevels::Cyclic(
        (0..path_len)
            .map(|absolute_slot| {
                (0..wing_count).fold(0_u16, |level, wing| {
                    let wing_offset = wing * path_len / wing_count;
                    level.max(chaser_block_level_for_order(
                        step_order,
                        step_levels,
                        active_step_count,
                        (absolute_slot + wing_offset) as i64,
                    ))
                })
            })
            .collect(),
    )
}

