#[derive(Debug, Clone, Copy)]
struct CompiledColorSpatialPlacement {
    mask_center_x: f64,
    mask_center_y: f64,
    mask_half_width: f64,
    mask_half_height: f64,
    mask_cosine: f64,
    mask_sine: f64,
    vertical_symmetry: bool,
    horizontal_symmetry: bool,
    raster_cosine: f64,
    raster_sine: f64,
}

impl CompiledColorSpatialPlacement {
    fn compile(placement: &protocol::ColorEffectSpatialPlacement) -> Result<Self, String> {
        if placement.source_coordinate_frame
            != ColorEffectSpatialCoordinateFrame::DaslightPatchCanvas
        {
            return Err("Color spatial placement coordinate frame is unsupported".to_string());
        }
        if placement.mapping_shape != ColorEffectSpatialMappingShape::Rectangle {
            return Err("Color spatial placement mapping shape is unsupported".to_string());
        }
        if placement.sampling_rule
            != ColorEffectSpatialSamplingRule::RotatedInclusionMaskAxisAlignedRaster
        {
            return Err("Color spatial placement sampling rule is unsupported".to_string());
        }
        if placement.sx <= 0 || placement.sy <= 0 {
            return Err("Color spatial placement extents must be greater than zero".to_string());
        }
        if !placement.mapping_angle_degrees.is_finite() {
            return Err("Color spatial placement angle must be finite".to_string());
        }
        if !placement.raster_rotation_degrees.is_finite() {
            return Err("Color spatial placement raster rotation must be finite".to_string());
        }
        if placement.vertical_symmetry && placement.horizontal_symmetry {
            return Err("Color spatial placement supports at most one Transform axis".to_string());
        }

        let mask_half_width = placement.sx as f64 * 0.5;
        let mask_half_height = placement.sy as f64 * 0.5;
        let radians = f64::from(placement.mapping_angle_degrees).to_radians();
        let mask_cosine = radians.cos();
        let mask_sine = radians.sin();
        let raster_radians = f64::from(placement.raster_rotation_degrees).to_radians();
        // Daslight rotates the scaled Rectangle about its centre, then moves
        // the rotated AABB's top-left back to the authored raw X/Y.
        let rotated_aabb_width =
            placement.sx as f64 * mask_cosine.abs() + placement.sy as f64 * mask_sine.abs();
        let rotated_aabb_height =
            placement.sx as f64 * mask_sine.abs() + placement.sy as f64 * mask_cosine.abs();

        Ok(Self {
            mask_center_x: placement.x as f64 + rotated_aabb_width * 0.5,
            mask_center_y: placement.y as f64 + rotated_aabb_height * 0.5,
            mask_half_width,
            mask_half_height,
            mask_cosine,
            mask_sine,
            vertical_symmetry: placement.vertical_symmetry,
            horizontal_symmetry: placement.horizontal_symmetry,
            raster_cosine: raster_radians.cos(),
            raster_sine: raster_radians.sin(),
        })
    }

    fn sample(self, patch_x: i64, patch_y: i64) -> Option<CompiledColorSpatialPlacementSample> {
        let delta_x = patch_x as f64 - self.mask_center_x;
        let delta_y = patch_y as f64 - self.mask_center_y;
        // The Rectangle's authored X/Y anchor describes the rotated AABB, so
        // first return the patch point to the Rectangle's local frame. Using
        // that same local frame for sampling avoids the recovered Daslight bug
        // where only the hit mask rotated while the colour raster stayed
        // axis-aligned.
        let mask_x = delta_x * self.mask_cosine + delta_y * self.mask_sine;
        let mask_y = -delta_x * self.mask_sine + delta_y * self.mask_cosine;
        if mask_x.abs() > self.mask_half_width || mask_y.abs() > self.mask_half_height {
            return None;
        }

        let mut normalized_x =
            ((mask_x + self.mask_half_width) / (self.mask_half_width * 2.0)).clamp(0.0, 1.0);
        let mut normalized_y =
            ((mask_y + self.mask_half_height) / (self.mask_half_height * 2.0)).clamp(0.0, 1.0);

        if self.vertical_symmetry {
            normalized_x = f64::from(daslight_symmetry_coordinate(normalized_x as f32));
        }
        if self.horizontal_symmetry {
            normalized_y = f64::from(daslight_symmetry_coordinate(normalized_y as f32));
        }
        let delta_x = normalized_x - 0.5;
        let delta_y = normalized_y - 0.5;
        normalized_x = delta_x * self.raster_cosine + delta_y * self.raster_sine + 0.5;
        normalized_y = -delta_x * self.raster_sine + delta_y * self.raster_cosine + 0.5;

        // Raster rotation is applied inside the authored Rectangle. Pixels
        // rotated outside that finite image are transparent in Daslight, so
        // do not let downstream samplers clamp or integer-cast them back onto
        // an edge colour.
        if !(0.0..=1.0).contains(&normalized_x) || !(0.0..=1.0).contains(&normalized_y) {
            return None;
        }

        Some(CompiledColorSpatialPlacementSample {
            normalized_x: normalized_x as f32,
            normalized_y: normalized_y as f32,
        })
    }
}

#[derive(Debug, Clone, Copy)]
struct CompiledRainbowProjection {
    vertical_symmetry: bool,
    horizontal_symmetry: bool,
    cosine: f64,
    sine: f64,
}

impl CompiledRainbowProjection {
    fn compile(recipe: &ColorEffectSpatialRecipe) -> Option<Self> {
        let ColorEffectSpatialRecipe::Rainbow {
            vertical_symmetry,
            horizontal_symmetry,
            rotation_degrees,
            angle_degrees,
            ..
        } = recipe
        else {
            return None;
        };
        let radians = f64::from(*rotation_degrees + *angle_degrees).to_radians();
        Some(Self {
            vertical_symmetry: *vertical_symmetry,
            horizontal_symmetry: *horizontal_symmetry,
            cosine: radians.cos(),
            sine: radians.sin(),
        })
    }

    fn project(self, x: f32, z: f32) -> f32 {
        let x = if self.vertical_symmetry {
            daslight_symmetry_coordinate(x)
        } else {
            x
        } - 0.5;
        let z = if self.horizontal_symmetry {
            daslight_symmetry_coordinate(z)
        } else {
            z
        } - 0.5;
        (f64::from(x) * self.cosine + f64::from(z) * self.sine) as f32
    }
}

#[derive(Clone)]
struct RuntimeColorBinding {
    outputs: HashMap<String, RuntimeColorOutput>,
    conversions: RuntimeColorConversionFlags,
}

#[derive(Clone, Copy, Default)]
struct RuntimeColorConversionFlags {
    rgbw: bool,
    cmy: bool,
    hsv: bool,
}

const MAX_CALIBRATED_COLOR_EMITTERS: usize = 16;
const CALIBRATED_COLOR_LUT_GRID: usize = 2;

#[derive(Clone)]
struct RuntimeColorCalibration {
    samples: [[u16; MAX_CALIBRATED_COLOR_EMITTERS]; 8],
}

#[derive(Clone)]
enum RuntimeColorOutput {
    Red { extract_white: bool },
    Green { extract_white: bool },
    Blue { extract_white: bool },
    White,
    CalibratedEmitter([u16; 8]),
    Intensity,
    Cyan,
    Magenta,
    Yellow,
    Hue,
    Saturation,
    Value,
    Zero,
    OpenWheel(u16),
    Wheel(Vec<RuntimeColorWheelSlot>),
}

impl RuntimeColorBinding {
    fn new(outputs: HashMap<String, RuntimeColorOutput>) -> Self {
        let mut conversions = RuntimeColorConversionFlags::default();
        for output in outputs.values() {
            match output {
                RuntimeColorOutput::Red {
                    extract_white: true,
                }
                | RuntimeColorOutput::Green {
                    extract_white: true,
                }
                | RuntimeColorOutput::Blue {
                    extract_white: true,
                }
                | RuntimeColorOutput::White => conversions.rgbw = true,
                RuntimeColorOutput::CalibratedEmitter(_) | RuntimeColorOutput::Intensity => {}
                RuntimeColorOutput::Cyan
                | RuntimeColorOutput::Magenta
                | RuntimeColorOutput::Yellow => conversions.cmy = true,
                RuntimeColorOutput::Hue
                | RuntimeColorOutput::Saturation
                | RuntimeColorOutput::Value => conversions.hsv = true,
                RuntimeColorOutput::Red {
                    extract_white: false,
                }
                | RuntimeColorOutput::Green {
                    extract_white: false,
                }
                | RuntimeColorOutput::Blue {
                    extract_white: false,
                }
                | RuntimeColorOutput::Zero
                | RuntimeColorOutput::OpenWheel(_)
                | RuntimeColorOutput::Wheel(_) => {}
            }
        }
        Self {
            outputs,
            conversions,
        }
    }
}

