#[allow(clippy::too_many_arguments)]
fn evaluate_daslight_perlin_color_at_rate(
    request: &ColorEffectRequest,
    target: &RuntimeColorSpatialTarget,
    compiled: &CompiledDaslightPerlin,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f32,
) -> ColorEffectColor {
    let valid_rate = valid_effect_rate(rate);
    let time_phase = request
        .clock_sync
        .map(|clock_sync| {
            (clock.beat_counter as f64 + clock.beat_phase as f64)
                / clock_sync.beats.max(0.000_1) as f64
                * f64::from(valid_rate)
        })
        .unwrap_or_else(|| {
            now.saturating_duration_since(created_at).as_secs_f64() * f64::from(valid_rate)
                / (request.period_ms.max(10) as f64 / 1_000.0)
        })
        + request.phase as f64;
    compiled.sample_at_phase(time_phase, target.daslight_target_index)
}

fn time_phase_for_continuous_spatial(
    request: &ColorEffectRequest,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f32,
) -> f64 {
    let rate = f64::from(valid_effect_rate(rate));
    request
        .clock_sync
        .map(|clock_sync| {
            (clock.beat_counter as f64 + clock.beat_phase as f64)
                / clock_sync.beats.max(0.000_1) as f64
                * rate
        })
        .unwrap_or_else(|| {
            now.saturating_duration_since(created_at).as_secs_f64() * rate
                / (request.period_ms.max(10) as f64 / 1000.0)
        })
        + request.phase as f64
}

#[allow(clippy::too_many_arguments)]
fn evaluate_color_spatial_sample_at_rate(
    request: &ColorEffectRequest,
    target: &RuntimeColorSpatialTarget,
    daslight_knight_rider: Option<&CompiledDaslightKnightRider>,
    daslight_burst: Option<&CompiledDaslightBurst>,
    daslight_sweep: Option<&CompiledDaslightSweep>,
    syndocal_random_fx: Option<&CompiledSyndocalRandomFx>,
    daslight_perlin: Option<&CompiledDaslightPerlin>,
    daslight_grid_lines: Option<&CompiledDaslightGridLines>,
    daslight_graph: Option<&CompiledDaslightGraph>,
    daslight_rain: Option<&CompiledDaslightRain>,
    daslight_bounce: Option<&CompiledDaslightBounce>,
    daslight_fire: Option<&CompiledDaslightFire>,
    daslight_particles: Option<&CompiledDaslightParticles>,
    effect_id: EffectId,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f32,
) -> RuntimeColorSpatialSample {
    let Some(pattern) = request.spatial_pattern.as_ref() else {
        return RuntimeColorSpatialSample {
            color: evaluate_color_effect_at_rate(
                request,
                0.0,
                effect_id,
                target.fixture_id,
                created_at,
                now,
                clock,
                rate,
            ),
            opacity: 1.0,
        };
    };
    if let Some(daslight_grid_lines) = daslight_grid_lines {
        return RuntimeColorSpatialSample {
            color: daslight_grid_lines.sample_at_phase(
                time_phase_for_continuous_spatial(request, created_at, now, clock, rate),
                target.x,
                target.z,
            ),
            opacity: 1.0,
        };
    }
    if let Some(daslight_graph) = daslight_graph {
        return RuntimeColorSpatialSample {
            color: daslight_graph.sample_at_phase(
                time_phase_for_continuous_spatial(request, created_at, now, clock, rate),
                target.x,
                target.z,
            ),
            opacity: 1.0,
        };
    }
    if let Some(daslight_rain) = daslight_rain {
        return RuntimeColorSpatialSample {
            color: daslight_rain.sample_at_phase(
                time_phase_for_continuous_spatial(request, created_at, now, clock, rate),
                target.x,
                target.z,
            ),
            opacity: 1.0,
        };
    }
    if let Some(daslight_bounce) = daslight_bounce {
        return RuntimeColorSpatialSample {
            color: daslight_bounce.sample_at_phase(
                time_phase_for_continuous_spatial(request, created_at, now, clock, rate),
                target.x,
                target.z,
            ),
            opacity: 1.0,
        };
    }
    if let Some(daslight_fire) = daslight_fire {
        return RuntimeColorSpatialSample {
            color: daslight_fire.sample_at_phase(
                time_phase_for_continuous_spatial(request, created_at, now, clock, rate),
                target.x,
                target.z,
            ),
            opacity: 1.0,
        };
    }
    if let Some(daslight_particles) = daslight_particles {
        return RuntimeColorSpatialSample {
            color: daslight_particles.sample_at_phase(
                time_phase_for_continuous_spatial(request, created_at, now, clock, rate),
                target.x,
                target.z,
            ),
            opacity: 1.0,
        };
    }
    if let Some(daslight_knight_rider) = daslight_knight_rider {
        return RuntimeColorSpatialSample {
            color: evaluate_daslight_knight_rider_color_at_rate(
                request,
                target,
                daslight_knight_rider,
                created_at,
                now,
                clock,
                rate,
            ),
            opacity: 1.0,
        };
    }
    if let Some(daslight_burst) = daslight_burst {
        return RuntimeColorSpatialSample {
            color: evaluate_daslight_burst_color_at_rate(
                request,
                target,
                daslight_burst,
                created_at,
                now,
                clock,
                rate,
            ),
            opacity: 1.0,
        };
    }
    if let Some(daslight_sweep) = daslight_sweep {
        return RuntimeColorSpatialSample {
            color: evaluate_daslight_sweep_color_at_rate(
                request,
                target,
                daslight_sweep,
                created_at,
                now,
                clock,
                rate,
            ),
            opacity: 1.0,
        };
    }
    if let Some(syndocal_random_fx) = syndocal_random_fx {
        return RuntimeColorSpatialSample {
            color: syndocal_random_fx.sample_at_mapping_time(
                time_phase_for_continuous_spatial(request, created_at, now, clock, rate),
                target.strip_index,
                target.strip_count,
                target.x,
                target.z,
                (created_at, now),
            ),
            opacity: 1.0,
        };
    }
    if let Some(daslight_perlin) = daslight_perlin {
        return RuntimeColorSpatialSample {
            color: evaluate_daslight_perlin_color_at_rate(
                request,
                target,
                daslight_perlin,
                created_at,
                now,
                clock,
                rate,
            ),
            opacity: 1.0,
        };
    }
    let time_phase = time_phase_for_continuous_spatial(request, created_at, now, clock, rate);
    let strip_count = target.strip_count.max(1);
    let strip_position = if strip_count <= 1 {
        0.5
    } else {
        target.strip_index as f32 / (strip_count - 1) as f32
    };
    let color = match &pattern.recipe {
        ColorEffectSpatialRecipe::KnightRider { .. }
        | ColorEffectSpatialRecipe::Sweep { .. }
        | ColorEffectSpatialRecipe::Burst { .. }
        | ColorEffectSpatialRecipe::RandomFill { .. }
        | ColorEffectSpatialRecipe::Sparkle { .. }
        | ColorEffectSpatialRecipe::Perlin { .. }
        | ColorEffectSpatialRecipe::Grid { .. }
        | ColorEffectSpatialRecipe::Lines { .. }
        | ColorEffectSpatialRecipe::Graph { .. }
        | ColorEffectSpatialRecipe::Rain { .. }
        | ColorEffectSpatialRecipe::Bounce { .. }
        | ColorEffectSpatialRecipe::Fire { .. }
        | ColorEffectSpatialRecipe::Explosion { .. }
        | ColorEffectSpatialRecipe::Starfield { .. } => {
            unreachable!("unified spatial recipes are evaluated by their compiled analytic route")
        }
        ColorEffectSpatialRecipe::Spiral {
            grayscale,
            radius,
            arms,
            gradient,
        } => {
            let delta_x = f64::from(target.x) * 99.0 + 0.5 - 50.0;
            let delta_y = 50.0 - (f64::from(target.z) * 99.0 + 0.5);
            let polar_degrees = delta_y.atan2(delta_x).to_degrees().rem_euclid(360.0);
            // CSpiralEffect advances its QConicalGradient by 360 degrees per
            // authored period and then by floor(Radius / 10) degrees for each
            // one-pixel annulus. This continuous sampler preserves that
            // recovered geometry without the source QImage cache.
            let radial_pixel = delta_x.hypot(delta_y).floor();
            let ring_rotation = radial_pixel * f64::from((*radius as i32) / 10);
            let gradient_angle = time_phase.rem_euclid(1.0) * 360.0 + ring_rotation;
            let position = (((polar_degrees - gradient_angle) / 360.0) * f64::from(*arms))
                .rem_euclid(1.0) as f32;
            let color = spatial_palette_color(request, position, *gradient);
            if *grayscale {
                daslight_grayscale_color(color)
            } else {
                color
            }
        }
        ColorEffectSpatialRecipe::Butterfly {
            grayscale,
            color_width,
            gradient,
            clockwise,
        } => {
            let delta_x = f64::from(target.x) * 99.0 + 0.5 - 50.0;
            let delta_y = 50.0 - (f64::from(target.z) * 99.0 + 0.5);
            let polar_degrees = delta_y.atan2(delta_x).to_degrees().rem_euclid(360.0);
            let direction = if *clockwise { -1.0 } else { 1.0 };
            let sector_angle = (direction * time_phase.rem_euclid(1.0) * 360.0).rem_euclid(360.0);
            // CButterflyEffect fills one conical sector and a second sector at
            // +180 degrees, then crops the doubled raster back to the mapping
            // rectangle. Sampling modulo 180 is the analytic equivalent.
            let sector_progress = (polar_degrees - sector_angle).rem_euclid(180.0);
            let color = if sector_progress > f64::from(*color_width) {
                black_color()
            } else {
                spatial_palette_color(
                    request,
                    (sector_progress / f64::from(*color_width)).clamp(0.0, 1.0) as f32,
                    *gradient,
                )
            };
            if *grayscale {
                daslight_grayscale_color(color)
            } else {
                color
            }
        }
        ColorEffectSpatialRecipe::Plasma {
            grayscale,
            vertical_symmetry,
            size_x,
            param_x,
            size_y,
            param_y,
            speed_x,
            param_sx,
            speed_y,
            param_sy,
        } => {
            let phase = (time_phase.rem_euclid(1.0) * 128.0).trunc() as u8;
            let mapping_raster = pattern.placement.is_some();
            // COLOR FX is a profile-order strip. Placed MAPPINGS samples the
            // recovered two-dimensional byte formula in Rectangle-local space.
            let x = if mapping_raster {
                (target.x * 99.0).round() as u8
            } else if *vertical_symmetry {
                let transformed = daslight_symmetry_coordinate(strip_position);
                (transformed * strip_count.saturating_sub(1) as f32).round() as usize as u8
            } else {
                target.strip_index as u8
            };
            let y = if mapping_raster {
                (target.z * 99.0).round() as u8
            } else {
                0_u8
            };
            let value = daslight_plasma_palette_byte(
                phase,
                x,
                y,
                *size_x as i32,
                *param_x as i32,
                *size_y as i32,
                *param_y as i32,
                *speed_x as i32,
                *param_sx as i32,
                *speed_y as i32,
                *param_sy as i32,
            );
            let color = spatial_palette_color(request, f32::from(value) / 255.0, 100.0);
            if *grayscale {
                daslight_grayscale_color(color)
            } else {
                color
            }
        }
        ColorEffectSpatialRecipe::ColorRainbow {
            grayscale,
            vertical_symmetry,
            color_width,
            angle_degrees,
            gradient,
        } => {
            let angle = f64::from(*angle_degrees).to_radians();
            let source_position = if *vertical_symmetry {
                daslight_symmetry_coordinate(strip_position)
            } else {
                strip_position
            };
            let projected = (f64::from(source_position) * angle.cos()) as f32;
            let position = daslight_rainbow_palette_position(
                projected,
                time_phase as f32,
                *color_width,
                request.stops.len(),
            );
            let color = spatial_palette_color(request, position, *gradient);
            if *grayscale {
                daslight_grayscale_color(color)
            } else {
                color
            }
        }
        ColorEffectSpatialRecipe::Rainbow {
            grayscale,
            color_width,
            gradient,
            ..
        } => {
            let projected = target.rainbow_projected_coordinate.unwrap_or_default();
            let position = daslight_rainbow_palette_position(
                projected,
                time_phase as f32,
                (*color_width / 100.0).clamp(0.0, 1.0),
                request.stops.len(),
            );
            let color = spatial_palette_color(request, position, *gradient);
            if *grayscale {
                daslight_grayscale_color(color)
            } else {
                color
            }
        }
    };
    RuntimeColorSpatialSample {
        color,
        opacity: 1.0,
    }
}

fn black_color() -> ColorEffectColor {
    ColorEffectColor {
        red: 0,
        green: 0,
        blue: 0,
    }
}

fn daslight_grayscale_color(color: ColorEffectColor) -> ColorEffectColor {
    // QColor/qGray uses the 8-bit integer formula below. Daslight applies it
    // after rendering the RGB palette into a QImage, so quantize before the
    // conversion and expand the result back to the engine's 16-bit channels.
    let red = u32::from(color.red >> 8);
    let green = u32::from(color.green >> 8);
    let blue = u32::from(color.blue >> 8);
    let gray = ((red * 11 + green * 16 + blue * 5) / 32) as u16;
    let value = gray * 257;
    ColorEffectColor {
        red: value,
        green: value,
        blue: value,
    }
}

fn daslight_symmetry_coordinate(coordinate: f32) -> f32 {
    // Daslight draws the full source image into the first half, then draws a
    // mirrored copy into the second half. This tent map is the equivalent
    // source coordinate for the normalized beam/mapping position.
    1.0 - (coordinate * 2.0 - 1.0).abs()
}

fn corrected_triangle_motion(cycle: f64) -> (f64, f64) {
    if cycle <= 0.5 {
        (cycle * 2.0, 1.0)
    } else {
        ((1.0 - cycle) * 2.0, -1.0)
    }
}

fn daslight_corrected_source_position(
    destination_index: usize,
    source_width: usize,
    vertical_symmetry: bool,
) -> f64 {
    let source_width = source_width.max(1);
    let destination_index = destination_index.min(source_width - 1);
    if !vertical_symmetry || source_width == 1 {
        return destination_index as f64;
    }
    let coordinate = destination_index as f32 / (source_width - 1) as f32;
    f64::from(daslight_symmetry_coordinate(coordinate)) * (source_width - 1) as f64
}

fn daslight_vertical_fold_source_index(
    destination_index: usize,
    source_width: usize,
) -> Option<usize> {
    if source_width == 0 || destination_index >= source_width {
        return None;
    }
    Some(daslight_corrected_source_position(destination_index, source_width, true).round() as usize)
}

#[allow(clippy::too_many_arguments)]
fn daslight_plasma_palette_byte(
    phase: u8,
    x: u8,
    y: u8,
    size_x: i32,
    param_x: i32,
    size_y: i32,
    param_y: i32,
    speed_x: i32,
    param_sx: i32,
    speed_y: i32,
    param_sy: i32,
) -> u8 {
    let index = |phase_param: i32, coordinate: u8, coordinate_param: i32| {
        (i32::from(phase) * phase_param + i32::from(coordinate) * coordinate_param) as u8
    };
    let wave = |index: u8| {
        // Literal recovered from CPlasmaEffect's table builder. Keeping the
        // double-precision multiply matters at integer-truncation boundaries.
        let radians = f64::from(index) * 0.049_087_343_75_f64;
        (radians.sin() * 30.0).trunc() as i32 as u8
    };
    wave(index(param_sy, y, param_y))
        .wrapping_add(wave(index(speed_x, y, size_y)))
        .wrapping_add(wave(index(param_sx, x, param_x)))
        .wrapping_add(wave(index(speed_y, x, size_x)))
}

fn daslight_rainbow_palette_position(
    projected_coordinate: f32,
    time_phase: f32,
    color_width: f32,
    palette_count: usize,
) -> f32 {
    let palette_count = palette_count.max(2) as f32;
    let gradient_length = 1.0 + (palette_count - 1.0) * color_width.clamp(0.0, 1.0);
    (projected_coordinate / gradient_length - time_phase).rem_euclid(1.0)
}

fn spatial_palette_color(
    request: &ColorEffectRequest,
    position: f32,
    gradient_percent: f32,
) -> ColorEffectColor {
    let position = position.clamp(0.0, 1.0);
    let discrete_index = request
        .stops
        .partition_point(|stop| stop.position <= position)
        .saturating_sub(1);
    let discrete = request.stops[discrete_index].color;
    let gradient = (gradient_percent / 100.0).clamp(0.0, 1.0);
    if gradient <= f32::EPSILON {
        discrete
    } else {
        let continuous = evaluate_linear_stop_color(request, position);
        interpolate_color_effect_color(
            discrete,
            continuous,
            gradient,
            ColorEffectInterpolation::Rgb,
        )
    }
}

fn evaluate_cycle_color(request: &ColorEffectRequest, position: f32) -> ColorEffectColor {
    let stops = &request.stops;
    let upper = stops.partition_point(|stop| stop.position <= position);
    if upper > 0 && upper < stops.len() {
        let first = &stops[upper - 1];
        let second = &stops[upper];
        let amount =
            (position - first.position) / (second.position - first.position).max(f32::EPSILON);
        return interpolate_color_effect_color(
            first.color,
            second.color,
            amount,
            request.interpolation,
        );
    }
    let first = &stops[0];
    let last = &stops[stops.len() - 1];
    let (from_position, to_position, sample_position) = if position < first.position {
        (last.position - 1.0, first.position, position)
    } else {
        (last.position, first.position + 1.0, position)
    };
    let distance = to_position - from_position;
    if distance <= f32::EPSILON {
        return first.color;
    }
    interpolate_color_effect_color(
        last.color,
        first.color,
        (sample_position - from_position) / distance,
        request.interpolation,
    )
}

fn evaluate_linear_stop_color(request: &ColorEffectRequest, position: f32) -> ColorEffectColor {
    let stops = &request.stops;
    let upper = stops.partition_point(|stop| stop.position < position);
    if upper == 0 {
        return stops[0].color;
    }
    if upper < stops.len() {
        let first = &stops[upper - 1];
        let second = &stops[upper];
        let amount =
            (position - first.position) / (second.position - first.position).max(f32::EPSILON);
        return interpolate_color_effect_color(
            first.color,
            second.color,
            amount,
            request.interpolation,
        );
    }
    stops[stops.len() - 1].color
}

fn interpolate_color_effect_color(
    from: ColorEffectColor,
    to: ColorEffectColor,
    amount: f32,
    interpolation: ColorEffectInterpolation,
) -> ColorEffectColor {
    let amount = amount.clamp(0.0, 1.0);
    if matches!(interpolation, ColorEffectInterpolation::Rgb) {
        return ColorEffectColor {
            red: interpolate_u16(from.red, to.red, amount),
            green: interpolate_u16(from.green, to.green, amount),
            blue: interpolate_u16(from.blue, to.blue, amount),
        };
    }
    let (mut from_hue, from_saturation, from_value) = color_to_hsv(from);
    let (mut to_hue, to_saturation, to_value) = color_to_hsv(to);
    if from_saturation <= f32::EPSILON {
        from_hue = to_hue;
    }
    if to_saturation <= f32::EPSILON {
        to_hue = from_hue;
    }
    let mut delta = (to_hue - from_hue + 540.0).rem_euclid(360.0) - 180.0;
    if (delta + 180.0).abs() <= f32::EPSILON {
        delta = 180.0;
    }
    if matches!(interpolation, ColorEffectInterpolation::HsvLongest) {
        if delta.abs() <= f32::EPSILON {
            if from_saturation > f32::EPSILON && to_saturation > f32::EPSILON {
                delta = 360.0;
            }
        } else {
            delta = if delta > 0.0 {
                delta - 360.0
            } else {
                delta + 360.0
            };
        }
    }
    hsv_to_color(
        (from_hue + delta * amount).rem_euclid(360.0),
        from_saturation + (to_saturation - from_saturation) * amount,
        from_value + (to_value - from_value) * amount,
    )
}

fn color_to_hsv(color: ColorEffectColor) -> (f32, f32, f32) {
    let red = color.red as f32 / u16::MAX as f32;
    let green = color.green as f32 / u16::MAX as f32;
    let blue = color.blue as f32 / u16::MAX as f32;
    let max = red.max(green).max(blue);
    let min = red.min(green).min(blue);
    let delta = max - min;
    let hue = if delta <= f32::EPSILON {
        0.0
    } else if max == red {
        60.0 * ((green - blue) / delta).rem_euclid(6.0)
    } else if max == green {
        60.0 * ((blue - red) / delta + 2.0)
    } else {
        60.0 * ((red - green) / delta + 4.0)
    };
    let saturation = if max <= f32::EPSILON {
        0.0
    } else {
        delta / max
    };
    (hue.rem_euclid(360.0), saturation, max)
}

fn color_to_hsv_u16(color: ColorEffectColor) -> [u16; 3] {
    let (hue, saturation, value) = color_to_hsv(color);
    [
        ((hue / 360.0) * u16::MAX as f32).round() as u16,
        (saturation * u16::MAX as f32).round() as u16,
        (value * u16::MAX as f32).round() as u16,
    ]
}

fn hsv_to_color(hue: f32, saturation: f32, value: f32) -> ColorEffectColor {
    let saturation = saturation.clamp(0.0, 1.0);
    let value = value.clamp(0.0, 1.0);
    let chroma = value * saturation;
    let section = hue.rem_euclid(360.0) / 60.0;
    let x = chroma * (1.0 - (section.rem_euclid(2.0) - 1.0).abs());
    let (red, green, blue) = match section.floor() as u8 {
        0 => (chroma, x, 0.0),
        1 => (x, chroma, 0.0),
        2 => (0.0, chroma, x),
        3 => (0.0, x, chroma),
        4 => (x, 0.0, chroma),
        _ => (chroma, 0.0, x),
    };
    let offset = value - chroma;
    ColorEffectColor {
        red: ((red + offset) * u16::MAX as f32).round() as u16,
        green: ((green + offset) * u16::MAX as f32).round() as u16,
        blue: ((blue + offset) * u16::MAX as f32).round() as u16,
    }
}

fn blend_runtime_color(
    base: ColorEffectColor,
    effect: ColorEffectColor,
    blend_mode: &EffectBlendMode,
) -> ColorEffectColor {
    ColorEffectColor {
        red: blend_effect_value(base.red, effect.red, blend_mode),
        green: blend_effect_value(base.green, effect.green, blend_mode),
        blue: blend_effect_value(base.blue, effect.blue, blend_mode),
    }
}

fn nearest_runtime_color_wheel_value(
    slots: &[RuntimeColorWheelSlot],
    color: ColorEffectColor,
) -> Option<u16> {
    let target = color_to_oklab(color);
    slots
        .iter()
        .min_by(|left, right| {
            oklab_distance_squared(left.oklab, target)
                .total_cmp(&oklab_distance_squared(right.oklab, target))
                .then_with(|| left.dmx_value.cmp(&right.dmx_value))
        })
        .map(|slot| slot.dmx_value)
}

fn color_to_oklab(color: ColorEffectColor) -> [f32; 3] {
    fn linear(value: u16) -> f32 {
        let value = value as f32 / u16::MAX as f32;
        if value <= 0.040_45 {
            value / 12.92
        } else {
            ((value + 0.055) / 1.055).powf(2.4)
        }
    }
    let red = linear(color.red);
    let green = linear(color.green);
    let blue = linear(color.blue);
    let l = (0.412_221_46 * red + 0.536_332_55 * green + 0.051_445_995 * blue).cbrt();
    let m = (0.211_903_5 * red + 0.680_699_5 * green + 0.107_396_96 * blue).cbrt();
    let s = (0.088_302_46 * red + 0.281_718_85 * green + 0.629_978_7 * blue).cbrt();
    [
        0.210_454_26 * l + 0.793_617_8 * m - 0.004_072_047 * s,
        1.977_998_5 * l - 2.428_592_2 * m + 0.450_593_7 * s,
        0.025_904_037 * l + 0.782_771_77 * m - 0.808_675_77 * s,
    ]
}

fn oklab_distance_squared(left: [f32; 3], right: [f32; 3]) -> f32 {
    left.iter()
        .zip(right)
        .map(|(left, right)| (left - right).powi(2))
        .sum()
}

fn splitmix64(mut value: u64) -> u64 {
    value = value.wrapping_add(0x9e37_79b9_7f4a_7c15);
    let mut mixed = value;
    mixed = (mixed ^ (mixed >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    mixed = (mixed ^ (mixed >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    mixed ^ (mixed >> 31)
}

fn dmx_preview_to_frame(preview: &[u8]) -> [u8; 512] {
    let mut frame = [0u8; 512];
    let len = preview.len().min(frame.len());
    frame[..len].copy_from_slice(&preview[..len]);
    frame
}

fn dmx_previews_to_frames(previews: &[DmxUniversePreview]) -> HashMap<u16, [u8; 512]> {
    previews
        .iter()
        .map(|preview| (preview.universe, dmx_preview_to_frame(&preview.values)))
        .collect()
}

fn blend_effect_value(base: u16, effect: u16, blend_mode: &EffectBlendMode) -> u16 {
    match blend_mode {
        EffectBlendMode::Override => effect,
        EffectBlendMode::Add => base.saturating_add(effect),
        EffectBlendMode::Multiply => ((base as u32 * effect as u32) / 65_535) as u16,
    }
}

fn blend_effect_value_with_opacity(
    base: u16,
    effect: u16,
    blend_mode: &EffectBlendMode,
    opacity: f32,
) -> u16 {
    interpolate_u16(
        base,
        blend_effect_value(base, effect, blend_mode),
        opacity.clamp(0.0, 1.0),
    )
}

fn blend_effect_float(base: f32, effect: f32, blend_mode: &EffectBlendMode) -> f32 {
    match blend_mode {
        EffectBlendMode::Override => effect,
        EffectBlendMode::Add => base + effect,
        EffectBlendMode::Multiply => base * effect,
    }
}

