#[cfg(test)]
fn evaluate_lfo_effect_normalized(
    request: &LfoEffectRequest,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f32,
) -> f32 {
    evaluate_lfo_effect_normalized_with_offset(request, 0.0, created_at, now, clock, rate)
}

fn evaluate_lfo_effect_normalized_with_offset(
    request: &LfoEffectRequest,
    fixture_phase_offset: f32,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f32,
) -> f32 {
    let rate = f64::from(valid_effect_rate(rate));
    if let Some(source) = &request.daslight_custom_curve {
        let phase =
            lfo_continuous_phase(request, fixture_phase_offset, created_at, now, clock, rate);
        return evaluate_daslight_custom_points(&source.points, phase);
    }
    if let Some(source) = &request.daslight_curve {
        return evaluate_daslight_curve_normalized_with_offset(
            request,
            source,
            fixture_phase_offset,
            created_at,
            now,
            clock,
            rate as f32,
        );
    }
    if let Some(clock_sync) = request.clock_sync {
        let beats = f64::from(clock_sync.beats.max(0.000_1));
        let beat_position = clock.beat_counter as f64 + f64::from(clock.beat_phase);
        let phase = (beat_position / beats * rate
            + f64::from(request.phase)
            + f64::from(fixture_phase_offset))
        .rem_euclid(1.0);
        return evaluate_lfo_shape(&request.shape, phase as f32);
    }
    let period = request.period_ms.max(10) as f64 / 1000.0;
    let elapsed = now.saturating_duration_since(created_at).as_secs_f64();
    let phase =
        (elapsed * rate / period + f64::from(request.phase) + f64::from(fixture_phase_offset))
            .rem_euclid(1.0);
    evaluate_lfo_shape(&request.shape, phase as f32)
}

fn evaluate_runtime_lfo_effect_normalized_with_offset(
    runtime: &RuntimeLfoEffect,
    fixture_phase_offset: f32,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f32,
) -> f32 {
    if let Some(curve) = &runtime.custom_curve {
        let phase = lfo_continuous_phase(
            &runtime.request,
            fixture_phase_offset,
            created_at,
            now,
            clock,
            f64::from(valid_effect_rate(rate)),
        );
        return curve.sample(phase);
    }
    evaluate_lfo_effect_normalized_with_offset(
        &runtime.request,
        fixture_phase_offset,
        created_at,
        now,
        clock,
        rate,
    )
}

fn lfo_continuous_phase(
    request: &LfoEffectRequest,
    fixture_phase_offset: f32,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f64,
) -> f32 {
    let cycle = if let Some(clock_sync) = request.clock_sync {
        let beats = f64::from(clock_sync.beats.max(0.000_1));
        let beat_position = clock.beat_counter as f64 + f64::from(clock.beat_phase);
        beat_position / beats * rate
    } else {
        let period = request.period_ms.max(10) as f64 / 1_000.0;
        now.saturating_duration_since(created_at).as_secs_f64() * rate / period
    };
    (cycle + f64::from(fixture_phase_offset)).rem_euclid(1.0) as f32
}

fn evaluate_daslight_custom_points(points: &[DaslightCustomCurvePoint], phase: f32) -> f32 {
    let phase = phase.rem_euclid(1.0);
    for pair in points.windows(2) {
        let left = &pair[0];
        let right = &pair[1];
        if left.x <= phase && phase < right.x {
            let Some((left_value, _)) = decode_daslight_custom_raw_y(left.raw_y) else {
                return 0.0;
            };
            let Some((right_value, easing)) = decode_daslight_custom_raw_y(right.raw_y) else {
                return 0.0;
            };
            let progress = (phase - left.x) / (right.x - left.x);
            return left_value
                + (right_value - left_value) * evaluate_daslight_custom_easing(easing, progress);
        }
    }
    points
        .last()
        .and_then(|point| decode_daslight_custom_raw_y(point.raw_y))
        .map_or(0.0, |(value, _)| value)
}

fn evaluate_daslight_curve_normalized_with_offset(
    request: &LfoEffectRequest,
    source: &DaslightCurveSource,
    fixture_phase_offset: f32,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f32,
) -> f32 {
    let outer_phase = if let Some(clock_sync) = request.clock_sync {
        let beats = f64::from(clock_sync.beats.max(0.000_1));
        let beat_position = clock.beat_counter as f64 + f64::from(clock.beat_phase);
        (beat_position / beats * f64::from(rate)).rem_euclid(1.0)
    } else {
        let duration_seconds = request.period_ms.max(10) as f64 / 1_000.0;
        let elapsed = now.saturating_duration_since(created_at).as_secs_f64();
        (elapsed * f64::from(rate) / duration_seconds).rem_euclid(1.0)
    };
    let shifted_outer_phase =
        (outer_phase + f64::from(fixture_phase_offset)).rem_euclid(1.0) as f32;

    let source_value = match &request.shape {
        LfoShape::Sine => {
            let phase = shifted_outer_phase * source.rate * 0.5 - request.phase;
            ((phase * std::f32::consts::TAU).sin() * source.size * 0.5
                + source.offset
                + source.size * 0.5)
                .clamp(0.0, 1.0)
        }
        LfoShape::Sinus3 => {
            let phase = shifted_outer_phase * source.rate * 0.5 - request.phase;
            let carrier = (phase * std::f32::consts::TAU).sin();
            (carrier.powi(3) * source.size * 0.5 + source.offset + source.size * 0.5)
                .clamp(0.0, 1.0)
        }
        LfoShape::Tangeant => {
            let phase = shifted_outer_phase * source.rate * 0.5 - request.phase;
            ((phase * std::f32::consts::TAU).tan() * source.size * 0.5
                + source.offset
                + source.size * 0.5)
                .clamp(0.0, 1.0)
        }
        LfoShape::Pulse => corrected_pulse_curve_source_value(
            shifted_outer_phase,
            source.rate as i32,
            source.size,
            request.phase,
            source.offset,
        ),
        LfoShape::Saw => {
            let source_phase = shifted_outer_phase * source.rate * 0.5 - request.phase;
            let centered = source_phase - (source_phase + 0.5).floor();
            (source.offset - centered * source.size + source.size - 0.5).clamp(0.0, 1.0)
        }
        LfoShape::Ramp => {
            let source_phase = shifted_outer_phase * source.rate * 0.5 - request.phase;
            let centered = source_phase - (source_phase + 0.5).floor();
            (source.offset + centered * source.size + source.size - 0.5).clamp(0.0, 1.0)
        }
        LfoShape::Triangle => {
            let source_phase = shifted_outer_phase * source.rate * 0.5 - request.phase;
            let triangle = evaluate_lfo_shape(&LfoShape::Triangle, source_phase + 0.75);
            (source.offset + triangle * source.size).clamp(0.0, 1.0)
        }
        LfoShape::Random => {
            let source_phase = shifted_outer_phase * source.rate * std::f32::consts::PI
                - request.phase * std::f32::consts::TAU;
            let step = source_phase.abs().floor() as u32;
            let bucket = corrected_curve_random_bucket(source.rng_seed.unwrap_or_default(), step);
            (source.size * (bucket + source.offset)).clamp(0.0, 1.0)
        }
        LfoShape::Square => corrected_square_curve_source_value(
            shifted_outer_phase,
            source.rate as i32,
            source.size,
            request.phase,
            source.offset,
        ),
        LfoShape::Strobe => {
            // Free-run traverses period_ms of authored content in period_ms, so
            // flashes remain exactly source.rate Hz. Clock sync compresses that
            // same content into the beat window, scaling by period/beat-window.
            let elapsed_in_buffer_seconds =
                shifted_outer_phase * request.period_ms.max(10) as f32 / 1_000.0;
            let cycle_position = (elapsed_in_buffer_seconds * source.rate).rem_euclid(1.0);
            let cycle_position = if 1.0 - cycle_position <= STROBE_PHASE_EPSILON {
                0.0
            } else {
                cycle_position
            };
            let duty = STROBE_DUTY_CYCLE.max(request.phase * 0.5).clamp(0.0, 1.0);
            if cycle_position < duty {
                (source.offset + source.size * 0.5).clamp(0.0, 1.0)
            } else {
                source.offset.clamp(0.0, 1.0)
            }
        }
        _ => {
            let phase = shifted_outer_phase + request.phase;
            evaluate_lfo_shape(&request.shape, phase)
        }
    };
    let low = f32::from(request.low) / f32::from(u16::MAX);
    let high = f32::from(request.high) / f32::from(u16::MAX);
    let span = high - low;
    if span.abs() <= f32::EPSILON {
        0.0
    } else {
        ((source_value - low) / span).clamp(0.0, 1.0)
    }
}

/// Preserves the carrier recovered from `CPulseEffect::evaluate` at
/// `0x14036F8D0`, but corrects two source-buffer artifacts. Daslight multiplies
/// by a fixed 0.005 triangle slope, so buffers shorter than 400 samples never
/// reach the authored Size, and then holds the result on its 40 ms work grid.
/// Syndocal evaluates a normalized triangle continuously while retaining Rate,
/// Phase, Size, Offset, and the zero-valued cycle endpoints.
fn corrected_pulse_curve_source_value(
    source_position: f32,
    rate: i32,
    size: f32,
    phase: f32,
    offset: f32,
) -> f32 {
    debug_assert!((1..=10).contains(&rate));
    let source_position = source_position.rem_euclid(1.0);
    let rate_angle = (f64::from(rate * 2) * std::f64::consts::TAU) as f32;
    let phase_angle = (-f64::from(phase) * std::f64::consts::TAU) as f32;
    let angle = rate_angle * source_position + phase_angle;
    let window = 1.0 - (source_position * 2.0 - 1.0).abs();
    let amplitude = size * window;
    ((f64::from(angle).sin() * f64::from(amplitude)) + f64::from(offset) + 0.5).clamp(0.0, 1.0)
        as f32
}

fn corrected_square_curve_source_value(
    source_position: f32,
    rate: i32,
    size: f32,
    phase: f32,
    offset: f32,
) -> f32 {
    debug_assert!((1..=10).contains(&rate));
    let position = (source_position - phase).rem_euclid(1.0);
    let band = (position * rate as f32).floor() as i32;
    let unit = if band & 1 == 0 { 1.0 } else { 0.0 };
    (offset + unit * size).clamp(0.0, 1.0)
}

