fn evaluate_position_wave_effect_normalized(
    request: &PositionWaveEffectRequest,
    position: Vec3,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f32,
) -> f32 {
    let rate = f64::from(valid_effect_rate(rate));
    let wavelength = f64::from(request.wavelength.abs().max(0.001));
    let elapsed = now.saturating_duration_since(created_at).as_secs_f64();
    let distance_phase = f64::from(projected_distance(
        position,
        request.origin,
        request.direction,
    )) / wavelength;
    let time_phase = request
        .clock_sync
        .map(|clock_sync| {
            let beats = f64::from(clock_sync.beats.max(0.000_1));
            let beat_position = clock.beat_counter as f64 + f64::from(clock.beat_phase);
            beat_position / beats * rate
        })
        .unwrap_or_else(|| elapsed * rate * f64::from(request.speed) / wavelength);
    let phase = (f64::from(request.phase) + time_phase - distance_phase).rem_euclid(1.0);
    evaluate_lfo_shape(&request.shape, phase as f32)
}

#[cfg(test)]
fn chaser_path_len(direction: ChaserDirection, step_count: usize) -> usize {
    match direction {
        ChaserDirection::Bounce if step_count > 1 => step_count * 2 - 2,
        ChaserDirection::BuildUpDown => step_count.max(1) * 2,
        ChaserDirection::Forward
        | ChaserDirection::Reverse
        | ChaserDirection::Random
        | ChaserDirection::Bounce => step_count.max(1),
    }
}

#[cfg(test)]
fn chaser_step_order(
    direction: ChaserDirection,
    step_count: usize,
    random_seed: u64,
) -> Vec<usize> {
    chaser_step_order_with_cycles(direction, step_count, random_seed, 1)
}

fn chaser_step_order_with_cycles(
    direction: ChaserDirection,
    step_count: usize,
    random_seed: u64,
    random_cycle_count: u8,
) -> Vec<usize> {
    let step_count = step_count.max(1);
    match direction {
        ChaserDirection::Forward => (0..step_count).collect(),
        ChaserDirection::Reverse => (0..step_count).rev().collect(),
        ChaserDirection::Bounce if step_count > 1 => {
            (0..step_count).chain((1..step_count - 1).rev()).collect()
        }
        ChaserDirection::Bounce => vec![0],
        ChaserDirection::BuildUpDown => (0..step_count).collect(),
        ChaserDirection::Random => {
            let mut state = (random_seed ^ (random_seed >> 32)) as u32;
            let mut sequence =
                Vec::with_capacity(step_count.saturating_mul(random_cycle_count.max(1) as usize));
            for _ in 0..random_cycle_count.max(1) {
                let mut cycle = (0..step_count).collect::<Vec<_>>();
                for index in (1..cycle.len()).rev() {
                    state = state.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
                    let target = state as usize % (index + 1);
                    cycle.swap(index, target);
                }
                sequence.extend(cycle);
            }
            sequence
        }
    }
}

#[cfg(test)]
fn chaser_step_index(
    direction: ChaserDirection,
    step_count: usize,
    absolute_slot: i64,
    random_seed: u64,
) -> usize {
    if step_count <= 1 {
        return 0;
    }
    match direction {
        ChaserDirection::Forward => absolute_slot.rem_euclid(step_count as i64) as usize,
        ChaserDirection::Reverse => {
            step_count - 1 - absolute_slot.rem_euclid(step_count as i64) as usize
        }
        ChaserDirection::Bounce => {
            let path_len = chaser_path_len(direction, step_count);
            let position = absolute_slot.rem_euclid(path_len as i64) as usize;
            if position < step_count {
                position
            } else {
                path_len - position
            }
        }
        ChaserDirection::BuildUpDown => {
            absolute_slot.rem_euclid((step_count * 2) as i64) as usize % step_count
        }
        ChaserDirection::Random => {
            let order = chaser_step_order(direction, step_count, random_seed);
            order[absolute_slot.rem_euclid(order.len() as i64) as usize]
        }
    }
}

fn chaser_cycle_len(direction: ChaserDirection, step_order_len: usize) -> usize {
    match direction {
        ChaserDirection::BuildUpDown => step_order_len.max(1) * 2,
        ChaserDirection::Forward
        | ChaserDirection::Reverse
        | ChaserDirection::Bounce
        | ChaserDirection::Random => step_order_len.max(1),
    }
}

fn chaser_slot_weights(fraction: f64, duty_cycle: f32, overlap: f32) -> (f32, f32) {
    let overlap = overlap as f64;
    if overlap > f64::EPSILON {
        let fade_end = (duty_cycle as f64 + overlap).min(1.0);
        let fade_start = fade_end - overlap;
        if fraction >= fade_start {
            let next = ((fraction - fade_start) / overlap).clamp(0.0, 1.0) as f32;
            return (1.0 - next, next);
        }
    }
    if fraction < duty_cycle as f64 {
        (1.0, 0.0)
    } else {
        (0.0, 0.0)
    }
}

fn chaser_block_level_for_steps(
    runtime: &RuntimeChaserEffect,
    step_levels: &[u16],
    absolute_slot: i64,
) -> u16 {
    chaser_block_level_for_order(
        &runtime.step_order,
        step_levels,
        runtime.request.active_step_count as usize,
        absolute_slot,
    )
}

fn chaser_block_level_for_order(
    step_order: &[usize],
    step_levels: &[u16],
    active_step_count: usize,
    absolute_slot: i64,
) -> u16 {
    if step_order.is_empty() {
        return 0;
    }
    let mut level = 0;
    let mut seen_steps = [0_u64; 4];
    let mut selected_count = 0_usize;
    for path_offset in 0..step_order.len() {
        let order_index =
            (absolute_slot - path_offset as i64).rem_euclid(step_order.len() as i64) as usize;
        let step_index = step_order[order_index];
        let word = step_index / 64;
        let mask = 1_u64 << (step_index % 64);
        if seen_steps[word] & mask != 0 {
            continue;
        }
        seen_steps[word] |= mask;
        selected_count += 1;
        level = level.max(step_levels.get(step_index).copied().unwrap_or(0));
        if selected_count >= active_step_count {
            break;
        }
    }
    level
}

fn chaser_build_up_down_level_for_steps(
    runtime: &RuntimeChaserEffect,
    step_levels: &[u16],
    step_maxima: &CompiledChaserStepMaxima,
    absolute_slot: i64,
    current_weight: f32,
    next_weight: f32,
) -> f32 {
    let step_count = runtime.step_order.len();
    if step_count == 0 {
        return 0.0;
    }
    let cycle_position = absolute_slot.rem_euclid((step_count * 2) as i64) as usize;
    let filling = cycle_position < step_count;
    let frontier = if filling {
        cycle_position
    } else {
        cycle_position - step_count
    };
    let fading = runtime.request.overlap > f32::EPSILON;
    let frontier_step = runtime.step_order[frontier];
    let frontier_level =
        step_levels.get(frontier_step).copied().unwrap_or(0) as f32 / u16::MAX as f32;
    if filling {
        let completed = step_maxima.prefix[frontier] as f32 / u16::MAX as f32;
        let frontier_weight = if fading { next_weight } else { 1.0 };
        completed.max(frontier_level * frontier_weight)
    } else {
        let remaining = step_maxima.suffix[frontier + 1] as f32 / u16::MAX as f32;
        let frontier_weight = if fading { current_weight } else { 0.0 };
        remaining.max(frontier_level * frontier_weight)
    }
}

