    #[test]
    fn project_swap_disarmed_preserves_desired_role_for_explicit_rearm() {
        let gate = OutputOwnershipGate::for_role(MachineOutputRole::Both);
        let transition = gate.begin_transition(MachineOutputRole::Standby).unwrap();
        let status = transition.complete_project_swap_disarmed().unwrap();

        assert_eq!(status.role, MachineOutputRole::Standby);
        assert_eq!(status.effective_role, MachineOutputRole::Standby);
        assert_eq!(status.desired_role, MachineOutputRole::Both);
        assert_eq!(status.persisted_role, Some(MachineOutputRole::Both));
        assert_eq!(status.state, OutputOwnershipState::Ready);
        assert_eq!(status.generation, 1);
        assert_eq!(status.epoch, 1);
        assert!(!status.lighting_allowed);
        assert!(!status.video_allowed);
        assert_eq!(
            status.lighting_reason,
            OutputOwnershipReason::ProjectSwapDisarmed
        );
        assert_eq!(
            status.video_reason,
            OutputOwnershipReason::ProjectSwapDisarmed
        );
        assert_eq!(status.error, None);
        assert!(gate.acquire(OutputCapability::Lighting).is_err());
        assert!(gate.acquire(OutputCapability::Video).is_err());

        let rearm = gate.begin_transition(status.desired_role).unwrap();
        let rearmed = rearm.complete().unwrap();
        assert_eq!(rearmed.effective_role, MachineOutputRole::Both);
        assert_eq!(rearmed.desired_role, MachineOutputRole::Both);
        assert_eq!(rearmed.persisted_role, Some(MachineOutputRole::Both));
        assert!(gate.acquire(OutputCapability::Lighting).is_ok());
        assert!(gate.acquire(OutputCapability::Video).is_ok());
    }

    #[test]
    fn fail_closed_engine_start_emits_no_artnet_before_initialization() {
        let receiver = UdpSocket::bind("127.0.0.1:0").unwrap();
        receiver
            .set_read_timeout(Some(Duration::from_millis(150)))
            .unwrap();
        let engine = EngineHandle::start(DmxOutputConfig {
            enabled: true,
            protocol: DmxOutputProtocol::ArtNet,
            target_ip: "127.0.0.1".to_string(),
            port: receiver.local_addr().unwrap().port(),
            ..DmxOutputConfig::default()
        });

        let mut packet = [0_u8; 700];
        let error = receiver.recv_from(&mut packet).unwrap_err();
        assert!(matches!(
            error.kind(),
            std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
        ));
        assert_eq!(
            engine.output_ownership_status().effective_role,
            MachineOutputRole::Standby
        );
        assert!(!engine.output_ownership_status().lighting_allowed);
    }

    #[test]
    fn output_sender_preparation_failure_stays_failed_and_all_denied() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        engine
            .send(EngineCommand::SetOutput(DmxOutputConfig {
                enabled: true,
                protocol: DmxOutputProtocol::EnttecOpenDmx,
                serial_port: "Syndocal-invalid-output-port".to_string(),
                ..DmxOutputConfig::default()
            }))
            .unwrap();
        thread::sleep(Duration::from_millis(30));

        let transition = engine
            .begin_output_ownership_transition(MachineOutputRole::Both)
            .unwrap();
        engine.fence_output_ownership().unwrap();
        let error = engine
            .prepare_output_ownership_role(MachineOutputRole::Both)
            .unwrap_err();
        assert!(!error.is_empty());
        transition.fail(error);

        let status = engine.output_ownership_status();
        assert_eq!(status.state, OutputOwnershipState::Failed);
        assert_eq!(status.effective_role, MachineOutputRole::Standby);
        assert!(!status.lighting_allowed);
        assert!(!status.video_allowed);
    }

    /// Physical serial rig demo/acceptance: drives the operator's 121ch rig
    /// (ch1 master dimmer + 40x RGB cells) with a moving rainbow built from
    /// three phase-shifted PositionWave effects, through the real Enttec Open
    /// DMX worker (break/MAB pacing included). Run manually with:
    ///   SYNDOCAL_PHYSICAL_SERIAL=COM3 cargo test -p engine --locked \
    ///     physical_serial_rainbow_demo -- --ignored --nocapture
    #[test]
    #[ignore]
    fn physical_serial_rainbow_demo_drives_master_dimmer_and_rgb_cells() {
        let Some(serial_port) = std::env::var("SYNDOCAL_PHYSICAL_SERIAL")
            .ok()
            .filter(|port| !port.is_empty())
        else {
            eprintln!("Skipping physical serial demo: SYNDOCAL_PHYSICAL_SERIAL is unset");
            return;
        };
        let master_byte: u8 = std::env::var("SYNDOCAL_PHYSICAL_MASTER")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(20);
        let seconds: u64 = std::env::var("SYNDOCAL_PHYSICAL_SECONDS")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(60);

        let master_profile = FixtureProfileSummary {
            source_path: "memory://physical-demo-master.gdtf".to_string(),
            manufacturer: "Syndocal".to_string(),
            name: "Demo Master Dimmer".to_string(),
            short_name: None,
            fixture_type_id: None,
            dmx_modes: vec![DmxModeSummary {
                name: "Standard".to_string(),
                controls: vec![AttributeControl {
                    attribute: "Dimmer".to_string(),
                    channel_name: "Dimmer".to_string(),
                    geometry: None,
                    offsets: vec![1],
                    resolution: AttributeResolution::EightBit,
                    default_value: 0,
                    functions: Vec::new(),
                }],
            }],
            geometries: sample_geometries(),
            warnings: Vec::new(),
        };
        let rgb_profile = FixtureProfileSummary {
            source_path: "memory://physical-demo-rgb.gdtf".to_string(),
            manufacturer: "Syndocal".to_string(),
            name: "Demo RGB Cell".to_string(),
            short_name: None,
            fixture_type_id: None,
            dmx_modes: vec![DmxModeSummary {
                name: "Standard".to_string(),
                controls: ["ColorRed", "ColorGreen", "ColorBlue"]
                    .iter()
                    .enumerate()
                    .map(|(index, attribute)| AttributeControl {
                        attribute: (*attribute).to_string(),
                        channel_name: (*attribute).to_string(),
                        geometry: None,
                        offsets: vec![index as u16 + 1],
                        resolution: AttributeResolution::EightBit,
                        default_value: 0,
                        functions: Vec::new(),
                    })
                    .collect(),
            }],
            geometries: sample_geometries(),
            warnings: Vec::new(),
        };

        let output = DmxOutputConfig {
            enabled: true,
            protocol: DmxOutputProtocol::EnttecOpenDmx,
            target_ip: String::new(),
            port: 0,
            universe: 0,
            serial_port,
            serial_baud_rate: 250_000,
        };
        let engine = EngineHandle::start_for_tests(output);

        let master_id = engine.allocate_fixture_id();
        engine
            .send(EngineCommand::PatchFixture {
                fixture_id: master_id,
                request: PatchFixtureRequest {
                    profile_path: master_profile.source_path.clone(),
                    mode_name: Some("Standard".to_string()),
                    label: "Master".to_string(),
                    universe: 0,
                    address: 1,
                    group_ids: Vec::new(),
                    position: Vec3::default(),
                    rotation: Default::default(),
                },
                profile: master_profile,
            })
            .unwrap();

        let mut cell_ids = Vec::new();
        for cell in 0..40u16 {
            let fixture_id = engine.allocate_fixture_id();
            engine
                .send(EngineCommand::PatchFixture {
                    fixture_id,
                    request: PatchFixtureRequest {
                        profile_path: rgb_profile.source_path.clone(),
                        mode_name: Some("Standard".to_string()),
                        label: format!("Cell {}", cell + 1),
                        universe: 0,
                        address: 2 + cell * 3,
                        group_ids: Vec::new(),
                        position: Vec3 {
                            x: cell as f32 * 0.5,
                            y: 0.0,
                            z: 0.0,
                        },
                        rotation: Default::default(),
                    },
                    profile: rgb_profile.clone(),
                })
                .unwrap();
            cell_ids.push(fixture_id);
        }

        engine
            .send(EngineCommand::SetAttribute {
                fixture_id: master_id,
                attribute: "Dimmer".to_string(),
                value: u16::from(master_byte) << 8,
            })
            .unwrap();

        for (attribute, phase) in [
            ("ColorRed", 0.0_f32),
            ("ColorGreen", 1.0 / 3.0),
            ("ColorBlue", 2.0 / 3.0),
        ] {
            let effect_id = engine.allocate_effect_id();
            engine
                .send(EngineCommand::AddPositionWaveEffect {
                    effect_id,
                    request: PositionWaveEffectRequest {
                        label: format!("Rainbow {attribute}"),
                        fixture_ids: cell_ids.clone(),
                        target_group_ids: Vec::new(),
                        attribute: attribute.to_string(),
                        video_targets: Vec::new(),
                        shape: LfoShape::Sine,
                        origin: Vec3::default(),
                        direction: Vec3 {
                            x: 1.0,
                            y: 0.0,
                            z: 0.0,
                        },
                        speed: 0.6,
                        wavelength: 10.0,
                        clock_sync: None,
                        low: 0,
                        high: u16::MAX,
                        phase,
                        blend_mode: EffectBlendMode::Override,
                    },
                })
                .unwrap();
        }

        let deadline = std::time::Instant::now() + Duration::from_secs(seconds);
        let mut last_report = std::time::Instant::now();
        while std::time::Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(500));
            let snapshot = engine.snapshot();
            assert_eq!(
                snapshot.telemetry.last_dmx_send_failure_count, 0,
                "serial route must not report send failures during the demo"
            );
            if last_report.elapsed() >= Duration::from_secs(10) {
                last_report = std::time::Instant::now();
                let preview = &snapshot.dmx_preview;
                eprintln!(
                    "demo running: master={} cell1 rgb=({},{},{}) sends={}",
                    preview[0],
                    preview[1],
                    preview[2],
                    preview[3],
                    snapshot.telemetry.total_dmx_send_success_count
                );
            }
        }

        let snapshot = engine.snapshot();
        assert_eq!(snapshot.dmx_preview[0], master_byte);
        assert!(
            snapshot.telemetry.total_dmx_send_success_count > 0,
            "the serial route should have delivered frames"
        );
        assert!(
            snapshot
                .dmx_preview
                .iter()
                .skip(1)
                .take(120)
                .any(|value| *value != 0),
            "the RGB cells should carry non-zero rainbow data"
        );
    }

    #[test]
    fn engine_sends_rendered_fixture_state_to_multiple_artnet_routes() {
        let receiver_a = UdpSocket::bind("127.0.0.1:0").unwrap();
        receiver_a
            .set_read_timeout(Some(Duration::from_secs(2)))
            .unwrap();
        let receiver_b = UdpSocket::bind("127.0.0.1:0").unwrap();
        receiver_b
            .set_read_timeout(Some(Duration::from_secs(2)))
            .unwrap();
        let port_a = receiver_a.local_addr().unwrap().port();
        let port_b = receiver_b.local_addr().unwrap().port();
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        engine
            .send(EngineCommand::SetDmxOutputs(vec![
                DmxOutputConfig {
                    enabled: true,
                    protocol: DmxOutputProtocol::ArtNet,
                    target_ip: "127.0.0.1".to_string(),
                    port: port_a,
                    universe: 0,
                    serial_port: String::new(),
                    serial_baud_rate: 57_600,
                },
                DmxOutputConfig {
                    enabled: true,
                    protocol: DmxOutputProtocol::ArtNet,
                    target_ip: "127.0.0.1".to_string(),
                    port: port_b,
                    universe: 1,
                    serial_port: String::new(),
                    serial_baud_rate: 57_600,
                },
            ]))
            .unwrap();
        for universe in [0_u16, 1_u16] {
            let fixture_id = engine.allocate_fixture_id();
            engine
                .send(EngineCommand::PatchFixture {
                    fixture_id,
                    request: PatchFixtureRequest {
                        profile_path: "memory://fixture.gdtf".to_string(),
                        mode_name: Some("Standard".to_string()),
                        label: format!("Fixture U{universe}"),
                        universe,
                        address: 1,
                        group_ids: Vec::new(),
                        position: Vec3::default(),
                        rotation: Default::default(),
                    },
                    profile: sample_profile(),
                })
                .unwrap();
            engine
                .send(EngineCommand::SetAttribute {
                    fixture_id,
                    attribute: "Dimmer".to_string(),
                    value: 0xffff,
                })
                .unwrap();
        }

        let mut buffer = [0u8; 600];
        let mut saw_a = false;
        let mut saw_b = false;
        for _ in 0..20 {
            let (received, _) = receiver_a.recv_from(&mut buffer).unwrap();
            let packet = parse_art_dmx_packet(&buffer[..received]).unwrap();
            if packet.universe == 0 && packet.data[0] == 255 {
                saw_a = true;
                break;
            }
        }
        for _ in 0..20 {
            let (received, _) = receiver_b.recv_from(&mut buffer).unwrap();
            let packet = parse_art_dmx_packet(&buffer[..received]).unwrap();
            if packet.universe == 1 && packet.data[0] == 255 {
                saw_b = true;
                break;
            }
        }

        assert!(saw_a);
        assert!(saw_b);
        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.telemetry.last_dmx_output_count == 2
                && snapshot.telemetry.last_dmx_send_success_count == 2
            {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }
        assert_eq!(snapshot.dmx_outputs.len(), 2);
        assert_eq!(snapshot.dmx_outputs[1].universe, 1);
        assert_eq!(
            snapshot
                .dmx_previews
                .iter()
                .map(|preview| preview.universe)
                .collect::<Vec<_>>(),
            vec![0, 1]
        );
        assert_eq!(
            snapshot
                .dmx_previews
                .iter()
                .find(|preview| preview.universe == 1)
                .and_then(|preview| preview.values.first())
                .copied(),
            Some(255)
        );
        assert_eq!(snapshot.telemetry.last_dmx_output_count, 2);
        assert_eq!(snapshot.telemetry.last_dmx_send_success_count, 2);
        assert_eq!(snapshot.telemetry.last_dmx_send_failure_count, 0);
        assert_eq!(snapshot.telemetry.last_dmx_route_results.len(), 2);
        assert!(snapshot
            .telemetry
            .last_dmx_route_results
            .iter()
            .all(|result| result.attempted && result.success && result.bytes > 0));
        assert_eq!(snapshot.telemetry.last_dmx_route_results[0].index, 0);
        assert_eq!(snapshot.telemetry.last_dmx_route_results[1].index, 1);
        assert_eq!(snapshot.telemetry.last_dmx_route_results[1].universe, 1);
        assert!(snapshot.telemetry.total_dmx_send_success_count >= 2);
    }

    #[test]
    fn engine_sustains_one_tick_across_128_enabled_artnet_universes() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        engine
            .send(EngineCommand::SetDmxOutputs(
                (0..128)
                    .map(|universe| DmxOutputConfig {
                        enabled: true,
                        protocol: DmxOutputProtocol::ArtNet,
                        target_ip: "127.0.0.1".to_string(),
                        port: 6454,
                        universe,
                        serial_port: String::new(),
                        serial_baud_rate: 57_600,
                    })
                    .collect(),
            ))
            .unwrap();

        let deadline = Instant::now() + Duration::from_secs(2);
        let snapshot = loop {
            let snapshot = engine.snapshot();
            if snapshot.telemetry.last_dmx_send_success_count == 128 || Instant::now() >= deadline {
                break snapshot;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
        };

        assert_eq!(snapshot.dmx_outputs.len(), 128);
        assert_eq!(snapshot.telemetry.last_dmx_output_count, 128);
        assert_eq!(snapshot.telemetry.last_dmx_send_success_count, 128);
        assert_eq!(snapshot.telemetry.last_dmx_send_failure_count, 0);
        assert!(snapshot.telemetry.last_error.is_none());
    }

