    #[test]
    fn persistence_snapshot_keeps_rendered_video_separate_from_authored_state() {
        let mut runtime = EngineRuntime::new(DmxOutputConfig::default());
        // FC27: node graph 1 node 3 outputs to fixture 1 ("Dimmer"), so the
        // seeded current-schema image must carry that referentially valid
        // fixture instead of relying on silent graph sanitization.
        runtime.fixtures.push(test_runtime_color_fixture(
            1,
            Vec::new(),
            sample_profile().dmx_modes[0].controls.clone(),
        ));
        let base = Instant::now();
        add_runtime_test_video_layer(
            &mut runtime,
            1,
            VideoLayerState {
                opacity: 0.8,
                ..VideoLayerState::default()
            },
        );
        let mut graph = sample_node_graph(1, 1);
        graph.nodes[0].kind = NodeGraphNodeKind::Audio;
        graph.nodes[0].lfo = None;
        graph.nodes[0].audio = Some(protocol::NodeGraphAudioNode {
            source: AudioSpectrumSource::Live,
            feature: AudioReactiveFeature::Rms,
            gain: 1.0,
            ..protocol::NodeGraphAudioNode::default()
        });
        graph.nodes[2]
            .output
            .as_mut()
            .unwrap()
            .video_targets
            .push(VideoEffectTarget {
                layer_ids: vec![1],
                param: VideoParam::Opacity,
                low: 0.0,
                high: 0.25,
                position: None,
            });
        runtime
            .node_graphs
            .push(runtime_node_graph_from_summary(graph, base));
        let mut frame = test_live_audio_frame(1, 1, &[]);
        frame.features.rms = 1.0;
        runtime.apply_live_audio_frame(frame, base, base);
        runtime.update_audio_reactive_nodes(base + DMX_TICK_INTERVAL);

        let persisted = runtime.build_persistence_snapshot();
        assert!((persisted.video.layers[0].state.opacity - 0.25).abs() < 0.000_1);
        let authored_video = persisted.authored_video.as_ref().unwrap();
        assert!((authored_video.layers[0].state.opacity - 0.8).abs() < 0.000_1);
        assert_eq!(authored_video.compositions, persisted.video.compositions);
        assert_eq!(authored_video.outputs, persisted.video.outputs);
        assert_eq!(
            authored_video.mapping_presets,
            persisted.video.mapping_presets
        );
        assert_eq!(
            authored_video.master_opacity,
            persisted.video.master_opacity
        );
        assert_eq!(authored_video.blackout, persisted.video.blackout);
        assert_eq!(authored_video.auto_vj, persisted.video.auto_vj);

        let mut reloaded = EngineRuntime::new(DmxOutputConfig::default());
        reloaded.load_project_snapshot(persisted);
        reloaded.update_audio_reactive_nodes(base + DMX_TICK_INTERVAL * 2);
        assert!((reloaded.video_snapshot().layers[0].state.opacity - 0.8).abs() < 0.000_1);
    }

    #[test]
    fn audio_reactive_curves_are_finite_and_monotonic() {
        let input = 0.25;
        assert_eq!(
            apply_audio_reactive_curve(input, AudioReactiveCurve::Linear),
            input
        );
        assert!(apply_audio_reactive_curve(input, AudioReactiveCurve::Exponential) < input);
        assert!(apply_audio_reactive_curve(input, AudioReactiveCurve::Logarithmic) > input);
        assert!(
            (apply_audio_reactive_curve(0.5, AudioReactiveCurve::Smoothstep) - 0.5).abs() < 0.000_1
        );
        for curve in [
            AudioReactiveCurve::Linear,
            AudioReactiveCurve::Smoothstep,
            AudioReactiveCurve::Exponential,
            AudioReactiveCurve::Logarithmic,
        ] {
            assert_eq!(apply_audio_reactive_curve(f32::NAN, curve), 0.0);
            assert_eq!(apply_audio_reactive_curve(f32::INFINITY, curve), 0.0);
        }
    }

    #[test]
    #[ignore = "manual release-mode Audio Rack routing benchmark"]
    fn audio_reactive_64x200_routing_meets_release_budget() {
        const GRAPH_COUNT: usize = 64;
        const FIXTURE_COUNT: u64 = 200;
        const SAMPLES: usize = 1_000;

        let mut runtime = EngineRuntime::new(DmxOutputConfig::default());
        let base = Instant::now();
        for graph_index in 0..GRAPH_COUNT {
            let mut graph = sample_node_graph(graph_index as u64 + 1, 1);
            graph.nodes[0].kind = NodeGraphNodeKind::Audio;
            graph.nodes[0].lfo = None;
            graph.nodes[0].audio = Some(protocol::NodeGraphAudioNode {
                source: AudioSpectrumSource::Live,
                feature: AudioReactiveFeature::Band,
                band_index: (graph_index % LIVE_AUDIO_FEATURE_BAND_CAPACITY) as u8,
                gain: 1.0,
                ..protocol::NodeGraphAudioNode::default()
            });
            graph.nodes[2].output.as_mut().unwrap().fixture_ids = (1..=FIXTURE_COUNT).collect();
            runtime
                .node_graphs
                .push(runtime_node_graph_from_summary(graph, base));
        }
        let mut frame = test_live_audio_frame(1, 1, &[]);
        frame.features.band_count = LIVE_AUDIO_FEATURE_BAND_CAPACITY as u8;
        frame.features.bands.fill(0.5);
        runtime.apply_live_audio_frame(frame, base, base);
        let sample_at = base + DMX_TICK_INTERVAL;
        runtime.update_audio_reactive_nodes(sample_at);
        let clock = runtime.clock.snapshot(sample_at);

        let mut durations = Vec::with_capacity(SAMPLES);
        let mut checksum = 0.0_f32;
        for _ in 0..SAMPLES {
            let started = Instant::now();
            runtime.update_audio_reactive_nodes(sample_at);
            for fixture_id in 1..=FIXTURE_COUNT {
                for graph in &runtime.node_graphs {
                    let output = &graph.outputs[0];
                    if output.output.fixture_ids.binary_search(&fixture_id).is_ok() {
                        checksum += evaluate_node_graph_output_normalized(
                            graph,
                            output,
                            Vec3::default(),
                            sample_at,
                            &clock,
                        )
                        .unwrap_or_default();
                    }
                }
            }
            durations.push(started.elapsed());
        }
        std::hint::black_box(checksum);
        durations.sort_unstable();
        let p99 = durations[(SAMPLES * 99 / 100).min(SAMPLES - 1)];
        let max = *durations.last().unwrap();
        eprintln!(
            "Audio Rack 64x200 routing: p99={}us max={}us",
            p99.as_micros(),
            max.as_micros()
        );
        if !cfg!(debug_assertions) {
            assert!(p99 <= Duration::from_millis(1), "p99 was {p99:?}");
            assert!(max <= Duration::from_millis(2), "max was {max:?}");
        }
    }

    #[test]
    fn node_graph_position_wave_uses_fixture_and_video_positions() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let fixture_id = engine.allocate_fixture_id();
        let layer_id = engine.allocate_video_layer_id();
        let mut fixture_request = sample_patch_request("Fixture 1", 1);
        fixture_request.position = Vec3::default();
        engine
            .send(EngineCommand::PatchFixture {
                fixture_id,
                request: fixture_request,
                profile: sample_profile(),
            })
            .unwrap();
        engine
            .send(EngineCommand::AddVideoLayer {
                layer_id,
                label: "Layer 1".to_string(),
                source: VideoSourceSummary {
                    kind: protocol::VideoSourceKind::StillImage,
                    path: Some("memory://still.png".to_string()),
                    name: None,
                    codec: None,
                    metadata: None,
                },
            })
            .unwrap();

        let mut graph = sample_node_graph(engine.allocate_node_graph_id(), fixture_id);
        graph.nodes[0].label = "Wave".to_string();
        graph.nodes[0].kind = NodeGraphNodeKind::PositionWave;
        graph.nodes[0].lfo = None;
        graph.nodes[0].position_wave = Some(protocol::NodeGraphPositionWaveNode {
            shape: LfoShape::Square,
            origin: Vec3::default(),
            direction: Vec3 {
                x: 1.0,
                y: 0.0,
                z: 0.0,
            },
            speed: 0.0,
            wavelength: 4.0,
            clock_sync: None,
            phase: 0.25,
        });
        if let Some(output) = graph.nodes[2].output.as_mut() {
            output.video_targets.push(VideoEffectTarget {
                layer_ids: vec![layer_id],
                param: VideoParam::Opacity,
                low: 0.0,
                high: 1.0,
                position: Some(Vec3 {
                    x: 2.0,
                    y: 0.0,
                    z: 0.0,
                }),
            });
        }
        engine.send(EngineCommand::UpsertNodeGraph(graph)).unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            let opacity = snapshot
                .video
                .layers
                .iter()
                .find(|layer| layer.id == layer_id)
                .map(|layer| layer.state.opacity)
                .unwrap_or_default();
            if snapshot.dmx_preview.first().copied() == Some(255) && opacity.abs() < 0.001 {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }

        assert_eq!(snapshot.dmx_preview[0], 255);
        let layer = snapshot
            .video
            .layers
            .iter()
            .find(|layer| layer.id == layer_id)
            .unwrap();
        assert!(layer.state.opacity.abs() < 0.001);
    }

    #[test]
    fn project_snapshot_load_reconciles_video_graph_references() {
        let mut runtime = EngineRuntime::new(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let source = VideoSourceSummary {
            kind: protocol::VideoSourceKind::StillImage,
            path: Some("memory://still.png".to_string()),
            name: None,
            codec: None,
            metadata: None,
        };
        let output = |id, label: &str, composition_id, width, height, opacity| VideoOutputSummary {
            id,
            label: label.to_string(),
            kind: VideoOutputKind::Display,
            enabled: true,
            composition_id,
            fullscreen: false,
            monitor_id: Some(0),
            monitor_identity: None,
            width,
            height,
            endpoint_name: None,
            opacity,
            blackout: false,
            mapping: VideoOutputMapping {
                scale_x: f32::NAN,
                aspect_ratio: 100.0,
                ..VideoOutputMapping::default()
            },
        };
        let snapshot = EngineSnapshot {
            video: VideoSnapshot {
                layers: vec![
                    VideoLayerSummary {
                        id: 2,
                        label: " Layer 1 ".to_string(),
                        source: source.clone(),
                        media_asset_id: None,
                        blend_mode: VideoBlendMode::Normal,
                        state: VideoLayerState::default(),
                        isf_effect: None,
                        clip_slots: Vec::new(),
                        default_clip_slot_id: None,
                    },
                    VideoLayerSummary {
                        id: 2,
                        label: "Duplicate Layer".to_string(),
                        source: source.clone(),
                        media_asset_id: None,
                        blend_mode: VideoBlendMode::Add,
                        state: VideoLayerState::default(),
                        isf_effect: None,
                        clip_slots: Vec::new(),
                        default_clip_slot_id: None,
                    },
                    VideoLayerSummary {
                        id: 0,
                        label: "Invalid Layer".to_string(),
                        source,
                        media_asset_id: None,
                        blend_mode: VideoBlendMode::Normal,
                        state: VideoLayerState::default(),
                        isf_effect: None,
                        clip_slots: Vec::new(),
                        default_clip_slot_id: None,
                    },
                ],
                compositions: vec![
                    CompositionSummary {
                        id: 0,
                        label: "Zero Composition".to_string(),
                        layer_ids: vec![2],
                        output_ids: vec![6],
                    },
                    CompositionSummary {
                        id: 4,
                        label: " Aux ".to_string(),
                        layer_ids: vec![2, 99, 2],
                        output_ids: vec![99],
                    },
                    CompositionSummary {
                        id: 4,
                        label: "Duplicate Aux".to_string(),
                        layer_ids: vec![2],
                        output_ids: Vec::new(),
                    },
                ],
                outputs: vec![
                    output(5, " ", 4, 0, 0, f32::NAN),
                    output(6, "Orphan", 99, 1920, 1080, 0.5),
                    output(5, "Duplicate Output", 1, 1920, 1080, 0.5),
                    output(0, "Invalid Output", 1, 1920, 1080, 0.5),
                ],
                ..VideoSnapshot::default()
            },
            ..EngineSnapshot::default()
        };

        runtime.load_project_snapshot(snapshot);
        let loaded = runtime.build_snapshot(0);

        assert_eq!(loaded.video.layers.len(), 1);
        assert_eq!(loaded.video.layers[0].id, 2);
        assert_eq!(loaded.video.layers[0].label, "Layer 1");
        assert_eq!(loaded.video.compositions.len(), 2);
        assert_eq!(loaded.video.compositions[0].id, 1);
        assert_eq!(loaded.video.compositions[0].layer_ids, vec![2]);
        assert_eq!(loaded.video.compositions[0].output_ids, vec![6]);
        assert_eq!(loaded.video.compositions[1].id, 4);
        assert_eq!(loaded.video.compositions[1].label, "Aux");
        assert_eq!(loaded.video.compositions[1].layer_ids, vec![2]);
        assert_eq!(loaded.video.compositions[1].output_ids, vec![5]);
        assert_eq!(loaded.video.outputs.len(), 2);
        assert_eq!(loaded.video.outputs[0].id, 5);
        assert_eq!(loaded.video.outputs[0].label, "Video Output 5");
        assert_eq!(loaded.video.outputs[0].composition_id, 4);
        assert_eq!(loaded.video.outputs[0].width, 1);
        assert_eq!(loaded.video.outputs[0].height, 1);
        assert_eq!(loaded.video.outputs[0].opacity, 1.0);
        assert_eq!(loaded.video.outputs[0].mapping.scale_x, 1.0);
        assert_eq!(loaded.video.outputs[0].mapping.aspect_ratio, 10.0);
        assert_eq!(loaded.video.outputs[1].id, 6);
        assert_eq!(loaded.video.outputs[1].composition_id, 1);
    }

