    #[test]
    fn dmx_input_supports_htp_ltp_signal_clear_and_blackout() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            universe: 0,
            ..DmxOutputConfig::default()
        });
        let fixture_id = engine.allocate_fixture_id();
        engine
            .send(EngineCommand::PatchFixture {
                fixture_id,
                request: sample_patch_request("Fixture 1", 1),
                profile: sample_profile(),
            })
            .unwrap();
        engine
            .send(EngineCommand::SetAttribute {
                fixture_id,
                attribute: "Dimmer".to_string(),
                value: 32_768,
            })
            .unwrap();
        let mut input = Box::new([0u8; 512]);
        input[0] = 200;
        engine
            .send(EngineCommand::SetDmxInputFrame {
                universe: 0,
                values: input,
                merge_mode: DmxMergeMode::Htp,
            })
            .unwrap();
        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.dmx_preview.first() == Some(&200) {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }
        assert_eq!(snapshot.dmx_preview[0], 200);

        let mut input = Box::new([0u8; 512]);
        input[0] = 25;
        engine
            .send(EngineCommand::SetDmxInputFrame {
                universe: 0,
                values: input,
                merge_mode: DmxMergeMode::Ltp,
            })
            .unwrap();
        std::thread::sleep(DMX_TICK_INTERVAL * 2);
        assert_eq!(engine.snapshot().dmx_preview[0], 25);

        engine.send(EngineCommand::ClearDmxInput(0)).unwrap();
        std::thread::sleep(DMX_TICK_INTERVAL * 2);
        assert_eq!(engine.snapshot().dmx_preview[0], 128);

        engine
            .send(EngineCommand::SetDmxInputFrame {
                universe: 0,
                values: Box::new([255u8; 512]),
                merge_mode: DmxMergeMode::Htp,
            })
            .unwrap();
        engine.send(EngineCommand::Blackout(true)).unwrap();
        std::thread::sleep(DMX_TICK_INTERVAL * 2);
        assert_eq!(engine.snapshot().dmx_preview[0], 0);
    }

    #[test]
    fn safety_blackout_is_priority_latched_idempotent_and_never_persisted() {
        let mut runtime = EngineRuntime::new(DmxOutputConfig {
            enabled: false,
            universe: 0,
            ..DmxOutputConfig::default()
        });
        runtime.blackout = false;
        runtime.last_frame[0] = 123;
        let before = runtime.build_persistence_snapshot();
        assert!(!before.blackout);

        let published = RwLock::new(runtime.build_snapshot(0));
        let (ack, receiver) = mpsc::sync_channel(1);
        let outcome = Arc::new(Mutex::new(None));
        runtime.apply_command(EngineCommand::SafetyBlackoutEngagePublished {
            expires_at: Instant::now() + Duration::from_secs(1),
            completion: SafetyBlackoutPublicationCompletion {
                ack,
                outcome: Arc::clone(&outcome),
            },
        });
        runtime.publish_pending_command_acks(0, &published);
        receiver.recv().unwrap().unwrap();
        assert_eq!(
            outcome.lock().unwrap().take(),
            Some(SafetyBlackoutEngageDisposition::Applied)
        );
        assert!(runtime.build_snapshot(0).blackout);
        assert_eq!(
            runtime.render_dmx_frame_for_universe(0, Instant::now()),
            [0; 512]
        );
        assert_eq!(runtime.build_persistence_snapshot(), before);

        // Neither an ordinary clear nor a project replacement can release the
        // emergency runtime latch.
        runtime.apply_command(EngineCommand::Blackout(false));
        runtime.load_project_snapshot(before.clone());
        assert!(runtime.build_snapshot(0).blackout);
        assert!(!runtime.build_persistence_snapshot().blackout);

        let (retry_ack, retry_receiver) = mpsc::sync_channel(1);
        let retry_outcome = Arc::new(Mutex::new(None));
        runtime.apply_command(EngineCommand::SafetyBlackoutEngagePublished {
            expires_at: Instant::now() + Duration::from_secs(1),
            completion: SafetyBlackoutPublicationCompletion {
                ack: retry_ack,
                outcome: Arc::clone(&retry_outcome),
            },
        });
        runtime.publish_pending_command_acks(0, &published);
        retry_receiver.recv().unwrap().unwrap();
        assert_eq!(
            retry_outcome.lock().unwrap().take(),
            Some(SafetyBlackoutEngageDisposition::NoOp)
        );

        let engaged_authority = runtime.shared_telemetry.safety_blackout_authority();
        assert!(engaged_authority.engaged);

        // A stale release cannot clear the latch or consume a successor.
        let (stale_ack, stale_receiver) = mpsc::sync_channel(1);
        let stale_outcome = Arc::new(Mutex::new(None));
        runtime.apply_command(EngineCommand::SafetyBlackoutReleasePublished {
            expected_epoch: engaged_authority.epoch,
            expected_generation: engaged_authority.generation + 1,
            expires_at: Instant::now() + Duration::from_secs(1),
            completion: SafetyBlackoutReleasePublicationCompletion {
                ack: stale_ack,
                outcome: Arc::clone(&stale_outcome),
            },
        });
        runtime.publish_pending_command_acks(0, &published);
        assert!(stale_receiver.recv().unwrap().is_err());
        assert_eq!(*stale_outcome.lock().unwrap(), None);
        assert_eq!(
            runtime.shared_telemetry.safety_blackout_authority(),
            engaged_authority
        );
        assert!(runtime.build_snapshot(0).blackout);

        // Release is the less-safe direction. A publication failure restores
        // both the latch and its exact authority pair before acknowledging.
        let (failed_ack, failed_receiver) = mpsc::sync_channel(1);
        let failed_outcome = Arc::new(Mutex::new(None));
        runtime.apply_command(EngineCommand::SafetyBlackoutReleasePublished {
            expected_epoch: engaged_authority.epoch,
            expected_generation: engaged_authority.generation,
            expires_at: Instant::now() + Duration::from_secs(1),
            completion: SafetyBlackoutReleasePublicationCompletion {
                ack: failed_ack,
                outcome: Arc::clone(&failed_outcome),
            },
        });
        runtime.fail_next_pending_publication = true;
        runtime.publish_pending_command_acks(0, &published);
        assert!(failed_receiver.recv().unwrap().is_err());
        assert_eq!(
            failed_outcome.lock().unwrap().take(),
            Some(SafetyBlackoutReleaseDisposition::Applied)
        );
        assert_eq!(
            runtime.shared_telemetry.safety_blackout_authority(),
            engaged_authority
        );
        assert!(runtime.build_snapshot(0).blackout);
        assert!(!runtime.build_persistence_snapshot().blackout);

        let (release_ack, release_receiver) = mpsc::sync_channel(1);
        let release_outcome = Arc::new(Mutex::new(None));
        runtime.apply_command(EngineCommand::SafetyBlackoutReleasePublished {
            expected_epoch: engaged_authority.epoch,
            expected_generation: engaged_authority.generation,
            expires_at: Instant::now() + Duration::from_secs(1),
            completion: SafetyBlackoutReleasePublicationCompletion {
                ack: release_ack,
                outcome: Arc::clone(&release_outcome),
            },
        });
        runtime.publish_pending_command_acks(0, &published);
        release_receiver.recv().unwrap().unwrap();
        assert_eq!(
            release_outcome.lock().unwrap().take(),
            Some(SafetyBlackoutReleaseDisposition::Applied)
        );
        let released_authority = runtime.shared_telemetry.safety_blackout_authority();
        assert!(!released_authority.engaged);
        assert_ne!(released_authority, engaged_authority);
        assert!(!runtime.build_snapshot(0).blackout);
        assert!(!runtime.build_persistence_snapshot().blackout);

        assert!(!EngineCommand::SafetyBlackoutEngagePublished {
            expires_at: Instant::now(),
            completion: SafetyBlackoutPublicationCompletion {
                ack: mpsc::sync_channel(1).0,
                outcome: Arc::new(Mutex::new(None)),
            },
        }
        .mutates_persistence_snapshot());
        assert!(EngineCommand::SafetyBlackoutEngagePublished {
            expires_at: Instant::now(),
            completion: SafetyBlackoutPublicationCompletion {
                ack: mpsc::sync_channel(1).0,
                outcome: Arc::new(Mutex::new(None)),
            },
        }
        .requests_low_latency_dmx_tick());
        assert!(!EngineCommand::SafetyBlackoutReleasePublished {
            expected_epoch: released_authority.epoch,
            expected_generation: released_authority.generation,
            expires_at: Instant::now(),
            completion: SafetyBlackoutReleasePublicationCompletion {
                ack: mpsc::sync_channel(1).0,
                outcome: Arc::new(Mutex::new(None)),
            },
        }
        .mutates_persistence_snapshot());
        assert!(EngineCommand::SafetyBlackoutReleasePublished {
            expected_epoch: released_authority.epoch,
            expected_generation: released_authority.generation,
            expires_at: Instant::now(),
            completion: SafetyBlackoutReleasePublicationCompletion {
                ack: mpsc::sync_channel(1).0,
                outcome: Arc::new(Mutex::new(None)),
            },
        }
        .requests_low_latency_dmx_tick());
    }

    #[test]
    fn programmer_blind_non_active_scene_commit_preserves_live_output_and_active_cue() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let fixture_id = engine.allocate_fixture_id();
        engine
            .send(EngineCommand::PatchFixture {
                fixture_id,
                request: sample_patch_request("Fixture 1", 1),
                profile: sample_profile(),
            })
            .unwrap();
        let active_cue_id = engine.allocate_cue_id();
        let edited_cue_id = engine.allocate_cue_id();
        engine
            .send(EngineCommand::CreateCue {
                authored_beats: None,
                cue_id: active_cue_id,
                label: "Active white scene".to_string(),
                fade_ms: 0,
                targets: vec![CueFixtureTarget {
                    fixture_id,
                    values: vec![AttributeValueSummary {
                        attribute: "Dimmer".to_string(),
                        value: 1_000,
                    }],
                }],
                video_targets: Vec::new(),
                video_output_targets: Vec::new(),
                node_graph_targets: Vec::new(),
                effect_targets: Vec::new(),
            })
            .unwrap();
        engine
            .send(EngineCommand::CreateCue {
                authored_beats: None,
                cue_id: edited_cue_id,
                label: "Edited scene".to_string(),
                fade_ms: 0,
                targets: vec![CueFixtureTarget {
                    fixture_id,
                    values: vec![AttributeValueSummary {
                        attribute: "Dimmer".to_string(),
                        value: 10_000,
                    }],
                }],
                video_targets: Vec::new(),
                video_output_targets: Vec::new(),
                node_graph_targets: Vec::new(),
                effect_targets: Vec::new(),
            })
            .unwrap();
        engine
            .send(EngineCommand::TriggerCue(active_cue_id))
            .unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.active_cue_id == Some(active_cue_id) && snapshot.dmx_preview[0] <= 5 {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }
        assert_eq!(snapshot.active_cue_id, Some(active_cue_id));
        assert_eq!(snapshot.cue_lists[0].active_cue_id, Some(active_cue_id));
        let live_before_blind = snapshot.dmx_previews.clone();

        engine
            .send(EngineCommand::SetProgrammerMode {
                enabled: true,
                blind: true,
                edited_scene_cue_id: None,
            })
            .unwrap();
        engine
            .send(EngineCommand::SetProgrammerAttribute {
                fixture_id,
                attribute: "Dimmer".to_string(),
                value: 50_000,
            })
            .unwrap();
        engine
            .send(EngineCommand::UpdateCue {
                cue_id: edited_cue_id,
                label: "Edited scene".to_string(),
                fade_ms: 0,
                targets: vec![CueFixtureTarget {
                    fixture_id,
                    values: vec![AttributeValueSummary {
                        attribute: "Dimmer".to_string(),
                        value: 50_000,
                    }],
                }],
                video_targets: Vec::new(),
                video_output_targets: Vec::new(),
                node_graph_targets: Vec::new(),
                effect_targets: Vec::new(),
            })
            .unwrap();
        engine
            .send(EngineCommand::CommitProgrammer {
                edited_scene_cue_id: Some(edited_cue_id),
            })
            .unwrap();

        for _ in 0..20 {
            snapshot = engine.snapshot();
            let edited_value = snapshot
                .cues
                .iter()
                .find(|cue| cue.id == edited_cue_id)
                .map(|cue| cue.targets[0].values[0].value);
            if snapshot.programmer.values.is_empty() && edited_value == Some(50_000) {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
        }
        assert!(snapshot.programmer.values.is_empty());
        assert!(!snapshot.programmer.enabled);
        assert!(!snapshot.programmer.blind);
        assert_eq!(snapshot.active_cue_id, Some(active_cue_id));
        assert_eq!(snapshot.cue_lists[0].active_cue_id, Some(active_cue_id));
        assert_eq!(snapshot.dmx_previews, live_before_blind);
        assert_eq!(
            snapshot
                .cues
                .iter()
                .find(|cue| cue.id == edited_cue_id)
                .unwrap()
                .targets[0]
                .values[0]
                .value,
            50_000
        );
        std::thread::sleep(DMX_TICK_INTERVAL * 2);
        let settled = engine.snapshot();
        assert_eq!(settled.active_cue_id, Some(active_cue_id));
        assert_eq!(settled.cue_lists[0].active_cue_id, Some(active_cue_id));
        assert_eq!(settled.dmx_previews, live_before_blind);
    }

    #[test]
    fn programmer_blind_active_scene_keeps_dmx_frozen_then_explicit_commit_applies_once() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let fixture_id = engine.allocate_fixture_id();
        engine
            .send(EngineCommand::PatchFixture {
                fixture_id,
                request: sample_patch_request("Fixture 1", 1),
                profile: sample_profile(),
            })
            .unwrap();
        let cue_id = engine.allocate_cue_id();
        engine
            .send(EngineCommand::CreateCue {
                authored_beats: None,
                cue_id,
                label: "Red live scene".to_string(),
                fade_ms: 0,
                targets: vec![CueFixtureTarget {
                    fixture_id,
                    values: vec![AttributeValueSummary {
                        attribute: "Dimmer".to_string(),
                        value: 1_000,
                    }],
                }],
                video_targets: Vec::new(),
                video_output_targets: Vec::new(),
                node_graph_targets: Vec::new(),
                effect_targets: Vec::new(),
            })
            .unwrap();
        engine.send(EngineCommand::TriggerCue(cue_id)).unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.active_cue_id == Some(cue_id) && snapshot.dmx_preview[0] <= 5 {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }
        assert_eq!(snapshot.active_cue_id, Some(cue_id));
        let live_before_blind = snapshot.dmx_previews.clone();

        engine
            .send(EngineCommand::SetProgrammerMode {
                enabled: true,
                blind: true,
                edited_scene_cue_id: None,
            })
            .unwrap();
        engine
            .send(EngineCommand::SetProgrammerAttribute {
                fixture_id,
                attribute: "Dimmer".to_string(),
                value: 50_000,
            })
            .unwrap();
        engine
            .send(EngineCommand::UpdateCue {
                cue_id,
                label: "Red live scene".to_string(),
                fade_ms: 0,
                targets: vec![CueFixtureTarget {
                    fixture_id,
                    values: vec![AttributeValueSummary {
                        attribute: "Dimmer".to_string(),
                        value: 50_000,
                    }],
                }],
                video_targets: Vec::new(),
                video_output_targets: Vec::new(),
                node_graph_targets: Vec::new(),
                effect_targets: Vec::new(),
            })
            .unwrap();

        for _ in 0..20 {
            if snapshot.programmer.values.len() == 1 && !snapshot.fixtures.is_empty() {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }
        assert!(snapshot.programmer.enabled);
        assert!(snapshot.programmer.blind);
        assert_eq!(snapshot.fixtures[0].attribute_values[0].value, 1_000);
        assert_eq!(snapshot.programmer.values[0].value, 50_000);
        assert!(snapshot.programmer.dmx_previews[0].values[0] >= 194);
        assert_eq!(snapshot.active_cue_id, Some(cue_id));
        assert_eq!(snapshot.dmx_previews, live_before_blind);

        engine
            .send(EngineCommand::CommitProgrammer {
                edited_scene_cue_id: Some(cue_id),
            })
            .unwrap();
        for _ in 0..20 {
            snapshot = engine.snapshot();
            if snapshot.programmer.values.is_empty() && snapshot.dmx_preview[0] >= 194 {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
        }
        assert!(snapshot.programmer.values.is_empty());
        assert!(!snapshot.programmer.enabled);
        assert!(!snapshot.programmer.blind);
        assert_eq!(snapshot.active_cue_id, Some(cue_id));
        assert_eq!(snapshot.cue_lists[0].active_cue_id, Some(cue_id));
        assert_eq!(snapshot.fixtures[0].attribute_values[0].value, 50_000);
        assert_eq!(snapshot.cues[0].targets[0].values[0].value, 50_000);
        assert!(snapshot.dmx_preview[0] >= 194);
        let committed_dmx = snapshot.dmx_previews.clone();
        std::thread::sleep(DMX_TICK_INTERVAL * 2);
        let settled = engine.snapshot();
        assert_eq!(settled.active_cue_id, Some(cue_id));
        assert_eq!(settled.cue_lists[0].active_cue_id, Some(cue_id));
        assert_eq!(settled.dmx_previews, committed_dmx);

        engine.send(EngineCommand::ReleaseCue(cue_id)).unwrap();
        for _ in 0..20 {
            snapshot = engine.snapshot();
            if snapshot.active_cue_id.is_none() && snapshot.dmx_preview[0] <= 5 {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
        }
        assert_eq!(snapshot.active_cue_id, None);
        assert_eq!(snapshot.cue_lists[0].active_cue_id, None);
        assert!(snapshot.dmx_preview[0] <= 5);
    }

    #[test]
    fn programmer_blind_discard_keeps_live_dmx_byte_identical() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let fixture_id = engine.allocate_fixture_id();
        engine
            .send(EngineCommand::PatchFixture {
                fixture_id,
                request: sample_patch_request("Fixture 1", 1),
                profile: sample_profile(),
            })
            .unwrap();
        engine
            .send(EngineCommand::SetAttribute {
                fixture_id,
                attribute: "Dimmer".to_string(),
                value: 1_000,
            })
            .unwrap();
        std::thread::sleep(DMX_TICK_INTERVAL * 2);
        let live_before_blind = engine.snapshot().dmx_previews;

        engine
            .send(EngineCommand::SetProgrammerMode {
                enabled: true,
                blind: true,
                edited_scene_cue_id: None,
            })
            .unwrap();
        engine
            .send(EngineCommand::SetProgrammerAttribute {
                fixture_id,
                attribute: "Dimmer".to_string(),
                value: 50_000,
            })
            .unwrap();
        std::thread::sleep(DMX_TICK_INTERVAL * 2);
        assert_eq!(engine.snapshot().dmx_previews, live_before_blind);

        engine.send(EngineCommand::ClearProgrammer).unwrap();
        std::thread::sleep(DMX_TICK_INTERVAL * 2);
        let discarded = engine.snapshot();
        assert_eq!(discarded.dmx_previews, live_before_blind);
        assert!(discarded.programmer.values.is_empty());
        assert!(!discarded.programmer.enabled);
        assert!(!discarded.programmer.blind);
        assert_eq!(discarded.fixtures[0].attribute_values[0].value, 1_000);
    }

