    #[test]
    fn video_layer_source_is_asset_owned_and_legacy_setter_rejects_without_mutation() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let layer_id = engine.allocate_video_layer_id();
        engine
            .send(EngineCommand::AddVideoLayer {
                layer_id,
                label: "Clip".to_string(),
                source: VideoSourceSummary {
                    kind: protocol::VideoSourceKind::File,
                    path: Some("memory://old.mp4".to_string()),
                    name: None,
                    codec: Some("H264".to_string()),
                    metadata: None,
                },
            })
            .unwrap();
        engine
            .send(EngineCommand::SetVideoLayerState {
                layer_id,
                state: VideoLayerState {
                    opacity: 0.25,
                    playing: true,
                    position_ms: 500,
                    ..VideoLayerState::default()
                },
            })
            .unwrap();
        engine
            .send(EngineCommand::SetVideoLayerSource {
                layer_id,
                source: VideoSourceSummary {
                    kind: protocol::VideoSourceKind::File,
                    path: Some("memory://new.mov".to_string()),
                    name: None,
                    codec: Some("prores".to_string()),
                    metadata: Some(protocol::VideoMediaMetadata {
                        duration_ms: Some(2_000),
                        width: Some(1920),
                        height: Some(1080),
                        frame_rate: Some(30.0),
                        has_audio: false,
                    }),
                },
            })
            .unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot
                .telemetry
                .last_error
                .as_deref()
                .is_some_and(|error| error.contains("source is owned by its media asset"))
            {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }
        let layer = snapshot
            .video
            .layers
            .iter()
            .find(|layer| layer.id == layer_id)
            .unwrap();
        assert_eq!(layer.source.path.as_deref(), Some("memory://old.mp4"));
        assert_eq!(layer.source.codec.as_deref(), Some("H264"));
        assert_eq!(layer.state.opacity, 0.25);
        assert!(layer.state.playing);
        assert!(layer.state.position_ms >= 500);
    }

