    #[test]
    fn media_asset_legacy_creator_uses_independent_ids_with_orphan_and_divergent_maxima() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let referenced_source = media_asset_test_source("referenced");
        let orphan_source = media_asset_test_source("orphan");
        engine
            .load_project_snapshot_and_wait(EngineSnapshot {
                video: VideoSnapshot {
                    media_assets: vec![
                        media_asset_test_summary(3, "Referenced", referenced_source.clone()),
                        media_asset_test_summary(80, "Orphan", orphan_source),
                    ],
                    layers: vec![media_asset_test_layer(
                        40,
                        3,
                        "Existing layer",
                        referenced_source,
                    )],
                    ..VideoSnapshot::default()
                },
                ..EngineSnapshot::default()
            })
            .unwrap();

        let new_layer_id = engine.allocate_video_layer_id();
        assert_eq!(new_layer_id, 41);
        engine
            .send(EngineCommand::AddVideoLayer {
                layer_id: new_layer_id,
                label: "Compatibility layer".to_string(),
                source: media_asset_test_source("compatibility"),
            })
            .unwrap();

        let deadline = Instant::now() + Duration::from_secs(1);
        let snapshot = loop {
            let snapshot = engine.snapshot();
            if snapshot.video.layers.len() == 2 {
                break snapshot;
            }
            assert!(
                Instant::now() < deadline,
                "compatibility creator did not reach the runtime"
            );
            std::thread::yield_now();
        };
        let created_layer = snapshot
            .video
            .layers
            .iter()
            .find(|layer| layer.id == new_layer_id)
            .unwrap();
        assert_eq!(created_layer.media_asset_id, Some(81));
        assert_ne!(created_layer.media_asset_id, Some(new_layer_id));
        assert!(snapshot
            .video
            .media_assets
            .iter()
            .any(|asset| asset.id == 80));
        assert_eq!(
            snapshot
                .video
                .media_assets
                .iter()
                .find(|asset| asset.id == 81)
                .map(|asset| &asset.source),
            Some(&created_layer.source)
        );
    }

    #[test]
    fn media_asset_allocator_max_boundary_rejects_explicit_and_issues_last_once() {
        let rejected = allocator_test_handle(Arc::new(RwLock::new(EngineSnapshot::default())));
        let error = rejected
            .send(EngineCommand::LoadProjectSnapshot(
                snapshot_with_allocator_candidate(AllocatorDomain::MediaAssets, u64::MAX - 1),
            ))
            .unwrap_err()
            .to_string();
        assert_eq!(
            error,
            allocator_capacity_error(AllocatorDomain::MediaAssets, u64::MAX - 1)
        );
        assert!(rejected.queue.pop().is_none());
        assert_eq!(rejected.allocate_media_asset_id(), 1);

        let accepted = allocator_test_handle(Arc::new(RwLock::new(EngineSnapshot::default())));
        accepted
            .send(EngineCommand::LoadProjectSnapshot(
                snapshot_with_allocator_candidate(AllocatorDomain::MediaAssets, u64::MAX - 2),
            ))
            .unwrap();
        assert_eq!(accepted.allocate_media_asset_id(), u64::MAX - 1);
        let exhausted = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            accepted.allocate_media_asset_id()
        }));
        assert!(exhausted.is_err());
        assert_eq!(
            allocator_counter_value(&accepted, AllocatorDomain::MediaAssets),
            u64::MAX
        );
    }

    #[test]
    fn exclusive_video_take_is_a_publication_barrier() {
        let mut runtime = EngineRuntime::new(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        add_runtime_test_video_layer(
            &mut runtime,
            1,
            VideoLayerState {
                playing: true,
                opacity: 1.0,
                ..VideoLayerState::default()
            },
        );
        add_runtime_test_video_layer(&mut runtime, 2, VideoLayerState::default());
        let published = RwLock::new(runtime.build_snapshot(0));
        let (ack, receiver) = mpsc::sync_channel(1);
        let queue = ArrayQueue::new(2);
        assert!(queue
            .push(QueuedEngineCommand {
                command: EngineCommand::ExclusiveVideoTake {
                    request: ExclusiveVideoTakeRequest {
                        target_layer_id: 2,
                        fade_ms: 0,
                        preview_position_ms: Some(1_234),
                        preview_speed: Some(0.0),
                    },
                    expires_at: Instant::now() + Duration::from_secs(1),
                    ack,
                },
                queued_at: Instant::now(),
            })
            .is_ok());
        assert!(queue
            .push(QueuedEngineCommand {
                command: EngineCommand::SetVideoLayerPlaying {
                    layer_id: 2,
                    playing: false,
                },
                queued_at: Instant::now(),
            })
            .is_ok());

        runtime.consume_commands(&queue);
        assert_eq!(queue.len(), 1);
        runtime.publish_pending_command_acks(queue.len(), &published);
        assert_eq!(receiver.recv().unwrap(), Ok(()));
        let snapshot = published.read().unwrap();
        let retired = snapshot
            .video
            .layers
            .iter()
            .find(|layer| layer.id == 1)
            .unwrap();
        let target = snapshot
            .video
            .layers
            .iter()
            .find(|layer| layer.id == 2)
            .unwrap();
        assert!(!retired.state.playing);
        assert!(target.state.playing);
        assert_eq!(target.state.position_ms, 1_234);
        drop(snapshot);

        runtime.consume_commands(&queue);
        assert!(!runtime_video_layer_state(&runtime, 2).playing);
        assert!(
            published
                .read()
                .unwrap()
                .video
                .layers
                .iter()
                .find(|layer| layer.id == 2)
                .unwrap()
                .state
                .playing
        );
    }

    #[test]
    fn exclusive_video_take_rolls_back_if_snapshot_publication_is_busy() {
        let mut runtime = EngineRuntime::new(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        add_runtime_test_video_layer(
            &mut runtime,
            1,
            VideoLayerState {
                playing: true,
                opacity: 0.75,
                position_ms: 600,
                ..VideoLayerState::default()
            },
        );
        add_runtime_test_video_layer(&mut runtime, 2, VideoLayerState::default());
        runtime.video_layer_fades.push(RuntimeVideoLayerFade {
            layer_id: 1,
            started_at: runtime.last_tick,
            duration: Duration::from_secs(4),
            start_opacity: 0.75,
            target_opacity: 0.25,
        });
        let before_states = runtime
            .video_layers
            .iter()
            .map(|layer| (layer.id, layer.state.clone()))
            .collect::<Vec<_>>();
        let before_fade = runtime.video_layer_fades[0].clone();
        let busy_snapshot = RwLock::new(runtime.build_snapshot(0));
        let (ack, receiver) = mpsc::sync_channel(1);
        runtime.apply_command(EngineCommand::ExclusiveVideoTake {
            request: ExclusiveVideoTakeRequest {
                target_layer_id: 2,
                fade_ms: 1_000,
                preview_position_ms: Some(900),
                preview_speed: Some(-1.0),
            },
            expires_at: Instant::now() + Duration::from_secs(1),
            ack,
        });
        assert!(runtime_video_layer_state(&runtime, 2).playing);

        let read_guard = busy_snapshot.read().unwrap();
        runtime.publish_pending_command_acks(0, &busy_snapshot);
        assert!(receiver
            .recv()
            .unwrap()
            .unwrap_err()
            .contains("rolled back"));
        assert_eq!(
            runtime
                .video_layers
                .iter()
                .map(|layer| (layer.id, layer.state.clone()))
                .collect::<Vec<_>>(),
            before_states
        );
        assert_eq!(runtime.video_layer_fades.len(), 1);
        assert_eq!(runtime.video_layer_fades[0].layer_id, before_fade.layer_id);
        assert_eq!(
            runtime.video_layer_fades[0].started_at,
            before_fade.started_at
        );
        assert_eq!(
            runtime.video_layer_fades[0].target_opacity,
            before_fade.target_opacity
        );
        drop(read_guard);
    }

    #[test]
    fn exclusive_video_take_handle_returns_after_snapshot_publication() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let source = |id| VideoSourceSummary {
            kind: protocol::VideoSourceKind::File,
            path: Some(format!("memory://take-{id}.mp4")),
            name: None,
            codec: Some("h264".to_string()),
            metadata: None,
        };
        for layer_id in [1, 2] {
            engine
                .send(EngineCommand::AddVideoLayer {
                    layer_id,
                    label: format!("Layer {layer_id}"),
                    source: source(layer_id),
                })
                .unwrap();
        }
        for _ in 0..20 {
            if engine.snapshot().video.layers.len() == 2 {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
        }
        assert_eq!(engine.snapshot().video.layers.len(), 2);

        engine
            .exclusive_video_take(ExclusiveVideoTakeRequest {
                target_layer_id: 2,
                fade_ms: 0,
                preview_position_ms: Some(2_345),
                preview_speed: Some(0.0),
            })
            .unwrap();
        let snapshot = engine.snapshot();
        let target = snapshot
            .video
            .layers
            .iter()
            .find(|layer| layer.id == 2)
            .unwrap();
        assert!(target.state.playing);
        assert_eq!(target.state.position_ms, 2_345);
        assert_eq!(target.state.speed, 0.0);
    }

    #[test]
    fn video_layer_blend_mode_and_default_composition_are_in_snapshot() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let layer_id = engine.allocate_video_layer_id();
        engine
            .send(EngineCommand::AddVideoLayer {
                layer_id,
                label: "Layer 1".to_string(),
                source: VideoSourceSummary {
                    kind: protocol::VideoSourceKind::File,
                    path: Some("memory://clip.mp4".to_string()),
                    name: None,
                    codec: Some("H264".to_string()),
                    metadata: None,
                },
            })
            .unwrap();
        engine
            .send(EngineCommand::SetVideoLayerBlendMode {
                layer_id,
                blend_mode: VideoBlendMode::Screen,
            })
            .unwrap();
        engine
            .send(EngineCommand::SetVideoLayerParam {
                layer_id,
                param: VideoParam::Opacity,
                value: 0.4,
            })
            .unwrap();
        engine
            .send(EngineCommand::SetVideoMasterOpacity(0.5))
            .unwrap();
        engine.send(EngineCommand::SetVideoBlackout(true)).unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot
                .video
                .layers
                .first()
                .map(|layer| layer.blend_mode == VideoBlendMode::Screen)
                == Some(true)
                && snapshot
                    .video
                    .layers
                    .first()
                    .map(|layer| (0.39..=0.41).contains(&layer.state.opacity))
                    == Some(true)
                && snapshot.video.master_opacity == 0.5
                && snapshot.video.blackout
            {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }

        let layer = snapshot.video.layers.first().unwrap();
        assert_eq!(layer.blend_mode, VideoBlendMode::Screen);
        assert!((0.39..=0.41).contains(&layer.state.opacity));
        assert_eq!(snapshot.video.compositions.len(), 1);
        assert_eq!(snapshot.video.compositions[0].label, "Main");
        assert_eq!(snapshot.video.compositions[0].layer_ids, vec![layer_id]);
        assert_eq!(snapshot.video.master_opacity, 0.5);
        assert!(snapshot.video.blackout);
    }

    #[test]
    fn all_blackout_sets_lighting_and_video_blackout_together() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });

        engine.send(EngineCommand::SetAllBlackout(true)).unwrap();
        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.blackout && snapshot.video.blackout {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }
        assert!(snapshot.blackout);
        assert!(snapshot.video.blackout);

        engine.send(EngineCommand::SetAllBlackout(false)).unwrap();
        for _ in 0..20 {
            snapshot = engine.snapshot();
            if !snapshot.blackout && !snapshot.video.blackout {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
        }
        assert!(!snapshot.blackout);
        assert!(!snapshot.video.blackout);
    }

    #[test]
    fn video_layer_order_updates_main_composition_order() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let layer_one = engine.allocate_video_layer_id();
        let layer_two = engine.allocate_video_layer_id();
        let layer_three = engine.allocate_video_layer_id();
        for (layer_id, label) in [
            (layer_one, "Layer 1"),
            (layer_two, "Layer 2"),
            (layer_three, "Layer 3"),
        ] {
            engine
                .send(EngineCommand::AddVideoLayer {
                    layer_id,
                    label: label.to_string(),
                    source: VideoSourceSummary {
                        kind: protocol::VideoSourceKind::File,
                        path: Some(format!("memory://{label}.mp4")),
                        name: None,
                        codec: Some("H264".to_string()),
                        metadata: None,
                    },
                })
                .unwrap();
        }
        engine
            .send(EngineCommand::SetVideoLayerOrder(vec![
                layer_three,
                layer_one,
                99_999,
                layer_three,
            ]))
            .unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            let order = snapshot
                .video
                .layers
                .iter()
                .map(|layer| layer.id)
                .collect::<Vec<_>>();
            if order == vec![layer_three, layer_one, layer_two] {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }

        let layer_order = snapshot
            .video
            .layers
            .iter()
            .map(|layer| layer.id)
            .collect::<Vec<_>>();
        assert_eq!(layer_order, vec![layer_three, layer_one, layer_two]);
        assert_eq!(
            snapshot.video.compositions[0].layer_ids,
            vec![layer_three, layer_one, layer_two]
        );
    }

