                && snapshot
                    .cues
                    .first()
                    .map(|cue| cue.video_targets.is_empty())
                    == Some(true)
                && snapshot.timeline.video_automations.is_empty()
                && snapshot.effects.is_empty()
                && snapshot.active_fade.is_none()
