    #[test]
    fn daslight_pulse_preserves_carrier_but_corrects_duration_scaled_amplitude() {
        let samples = [0.0, 0.125, 0.25, 0.375, 0.5, 0.625, 0.75, 0.875]
            .map(|position| corrected_pulse_curve_source_value(position, 1, 0.5, 0.0, 0.0));
        let expected = [0.5, 0.625, 0.5, 0.125, 0.5, 0.875, 0.5, 0.375];
        for (actual, expected) in samples.into_iter().zip(expected) {
            assert!(
                (actual - expected).abs() < 0.000_01,
                "{actual} != {expected}"
            );
        }

        let corrected_peak = corrected_pulse_curve_source_value(0.5, 1, 0.5, 0.75, 0.0);
        assert!(
            (corrected_peak - 1.0).abs() < 0.000_01,
            "corrected peak {corrected_peak}"
        );
        let daslight_fixed_slope_peak: f32 = 0.5 + 0.5 * (12.0 * 0.005);
        assert!((daslight_fixed_slope_peak - 0.53).abs() < f32::EPSILON);

        let mut request = test_lfo_request(
            "Imported Pulse",
            LfoShape::Pulse,
            16_000,
            0.0,
            EffectBlendMode::Override,
            0,
            u16::MAX,
        );
        request.daslight_curve = Some(DaslightCurveSource {
            rate: 1.0,
            size: 0.5,
            offset: 0.0,
            sample_ms: 40,
            rng_seed: None,
        });
        validate_lfo_effect_request(&request).unwrap();
        let started = Instant::now();
        let clock = ClockSnapshot::default();
        assert_eq!(
            evaluate_lfo_effect(&request, started, started, &clock),
            32_768
        );
        assert_ne!(
            evaluate_lfo_effect(
                &request,
                started,
                started + Duration::from_millis(39),
                &clock,
            ),
            32_768,
            "corrected Pulse must not hold the first sample for 40 ms"
        );
        assert!((40_900..=41_030).contains(&evaluate_lfo_effect(
            &request,
            started,
            started + Duration::from_millis(2_000),
            &clock,
        )));
    }

    #[test]
    fn corrected_dvc_square_uses_equal_bands_without_terminal_integer_residue() {
        let rate_three = (0..400)
            .map(|sample| {
                corrected_square_curve_source_value(sample as f32 / 400.0, 3, 1.0, 0.0, 0.0)
            })
            .collect::<Vec<_>>();
        assert_eq!(
            rate_three.iter().filter(|value| **value == 1.0).count(),
            267
        );
        assert!(rate_three[..134].iter().all(|value| *value == 1.0));
        assert!(rate_three[134..267].iter().all(|value| *value == 0.0));
        assert!(rate_three[267..].iter().all(|value| *value == 1.0));

        let phase_shifted = (0..25)
            .map(|sample| {
                corrected_square_curve_source_value(sample as f32 / 25.0, 3, 0.75, 0.25, 0.1)
            })
            .collect::<Vec<_>>();
        assert!(phase_shifted[..15]
            .iter()
            .all(|value| (*value - 0.85).abs() < f32::EPSILON));
        assert!(phase_shifted[15..23]
            .iter()
            .all(|value| (*value - 0.1).abs() < f32::EPSILON));
        assert!(phase_shifted[23..]
            .iter()
            .all(|value| (*value - 0.85).abs() < f32::EPSILON));

        let mut request = test_lfo_request(
            "Imported Square",
            LfoShape::Square,
            1_000,
            0.25,
            EffectBlendMode::Override,
            6_554,
            55_705,
        );
        request.daslight_curve = Some(DaslightCurveSource {
            rate: 3.0,
            size: 0.75,
            offset: 0.1,
            sample_ms: 40,
            rng_seed: None,
        });
        validate_lfo_effect_request(&request).unwrap();
        let started = Instant::now();
        let clock = ClockSnapshot::default();
        assert_eq!(
            evaluate_lfo_effect(
                &request,
                started,
                started + Duration::from_millis(560),
                &clock,
            ),
            55_705
        );
        assert_eq!(
            evaluate_lfo_effect(
                &request,
                started,
                started + Duration::from_millis(600),
                &clock,
            ),
            6_554
        );
    }

    #[test]
    fn corrected_dvc_sinus_preserves_source_phase_without_sample_hold() {
        let mut request = test_lfo_request(
            "Imported Sinus",
            LfoShape::Sine,
            1_000,
            0.0,
            EffectBlendMode::Override,
            0,
            u16::MAX,
        );
        request.daslight_curve = Some(DaslightCurveSource {
            rate: 2.0,
            size: 1.0,
            offset: 0.0,
            sample_ms: 40,
            rng_seed: None,
        });
        let started = Instant::now();
        let clock = ClockSnapshot::default();
        let at_zero = evaluate_lfo_effect(&request, started, started, &clock);
        let before_next_sample = evaluate_lfo_effect(
            &request,
            started,
            started + Duration::from_millis(39),
            &clock,
        );
        let after_next_sample = evaluate_lfo_effect(
            &request,
            started,
            started + Duration::from_millis(41),
            &clock,
        );
        let near_peak = evaluate_lfo_effect(
            &request,
            started,
            started + Duration::from_millis(241),
            &clock,
        );
        assert_eq!(at_zero, 32_768);
        assert_ne!(before_next_sample, at_zero);
        assert!(after_next_sample > before_next_sample);
        assert!(near_peak > 65_000);

        request.phase = 0.25;
        assert_eq!(evaluate_lfo_effect(&request, started, started, &clock), 0);
    }

