    #[test]
    fn identity_colors_set_clear_and_survive_snapshot_roundtrip() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });

        let cue = CueSummary {
            id: 5,
            cue_number: "1".to_string(),
            label: "Colored".to_string(),
            group_id: Some("Front".to_string()),
            ..CueSummary::default()
        };
        let mut snapshot = EngineSnapshot {
            cues: vec![cue],
            ..EngineSnapshot::default()
        };
        snapshot.output.enabled = false;
        snapshot.dmx_outputs = vec![snapshot.output.clone()];
        engine
            .send(EngineCommand::LoadProjectSnapshot(snapshot))
            .unwrap();
        for _ in 0..100 {
            if engine.snapshot().cues.len() == 1 {
                break;
            }
            thread::sleep(Duration::from_millis(10));
        }

        engine
            .set_cue_color_published(5, Some("#ff3366".to_string()))
            .unwrap();
        engine
            .set_group_color_published("Front".to_string(), Some("#22aa88".to_string()))
            .unwrap();
        let colored = engine.snapshot();
        assert_eq!(colored.cues[0].color.as_deref(), Some("#ff3366"));
        assert_eq!(
            colored.group_colors.get("Front").map(String::as_str),
            Some("#22aa88")
        );

        // The colors are project data: a save/load roundtrip preserves them.
        engine
            .send(EngineCommand::LoadProjectSnapshot(colored.clone()))
            .unwrap();
        let mut reloaded = engine.snapshot();
        for _ in 0..100 {
            if reloaded
                .cues
                .first()
                .and_then(|cue| cue.color.clone())
                .is_some()
            {
                break;
            }
            thread::sleep(Duration::from_millis(10));
            reloaded = engine.snapshot();
        }
        assert_eq!(reloaded.cues[0].color.as_deref(), Some("#ff3366"));
        assert_eq!(
            reloaded.group_colors.get("Front").map(String::as_str),
            Some("#22aa88")
        );

        // Clearing removes the persisted values again.
        engine.set_cue_color_published(5, None).unwrap();
        engine
            .set_group_color_published("Front".to_string(), None)
            .unwrap();
        let cleared = engine.snapshot();
        assert!(cleared.cues[0].color.is_none());
        assert!(cleared.group_colors.is_empty());

        // Unknown cue ids fail the ack instead of silently succeeding.
        assert!(engine
            .set_cue_color_published(999, Some("#ffffff".to_string()))
            .is_err());
    }

    #[test]
    fn fixture_group_state_publication_is_atomic_and_waits_for_definitive_ack() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        engine
            .send(EngineCommand::PatchFixture {
                fixture_id: 1,
                request: sample_patch_request("Atomic group fixture", 1),
                profile: sample_profile(),
            })
            .unwrap();
        let ready_deadline = Instant::now() + Duration::from_secs(1);
        while engine.snapshot().fixtures.len() != 1 {
            assert!(
                Instant::now() < ready_deadline,
                "fixture did not reach runtime"
            );
            thread::yield_now();
        }
        let before = engine.persistence_snapshot().unwrap();

        // Full validation occurs before the runtime mutates the valid fixture.
        let invalid = engine.apply_fixture_group_state_published(
            vec![
                (1, vec!["Front".to_string()]),
                (99, vec!["Missing".to_string()]),
            ],
            BTreeMap::from([("Front".to_string(), "#22aa88".to_string())]),
        );
        assert!(invalid.is_err());
        assert_eq!(
            engine.persistence_snapshot().unwrap().fixtures,
            before.fixtures
        );
        assert_eq!(
            engine.persistence_snapshot().unwrap().group_colors,
            before.group_colors
        );

        // A deadline which is already expired cannot late-apply a candidate.
        let expired = engine.apply_fixture_group_state_published_with_timeout(
            vec![(1, vec!["Front".to_string()])],
            BTreeMap::from([("Front".to_string(), "#22aa88".to_string())]),
            Duration::ZERO,
        );
        assert!(expired.is_err());
        thread::sleep(Duration::from_millis(20));
        assert_eq!(
            engine.persistence_snapshot().unwrap().fixtures,
            before.fixtures
        );
        assert_eq!(
            engine.persistence_snapshot().unwrap().group_colors,
            before.group_colors
        );

        // After runtime admission, a busy shared snapshot is not a caller
        // timeout followed by a late B publish. The caller waits for the
        // definitive publication acknowledgement, then sees all B at once.
        let published_guard = engine.snapshot.read().unwrap();
        let caller_engine = engine.clone();
        let caller = thread::spawn(move || {
            caller_engine.apply_fixture_group_state_published(
                vec![(1, vec!["Front".to_string()])],
                BTreeMap::from([("Front".to_string(), "#22aa88".to_string())]),
            )
        });
        thread::sleep(Duration::from_millis(25));
        assert!(!caller.is_finished());
        assert_eq!(published_guard.fixtures, before.fixtures);
        assert_eq!(published_guard.group_colors, before.group_colors);
        drop(published_guard);
        assert_eq!(caller.join().unwrap(), Ok(()));
        let after = engine.persistence_snapshot().unwrap();
        assert_eq!(after.fixtures[0].group_ids, vec!["Front".to_string()]);
        assert_eq!(
            after.group_colors.get("Front").map(String::as_str),
            Some("#22aa88")
        );
    }

    #[test]
    fn fixture_patch_batch_publishes_all_candidates_or_applies_none() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });

        // The acknowledgement comes only after one shared B snapshot contains
        // every candidate. There is no observable first-fixture publication.
        engine
            .patch_fixtures_published(vec![
                sample_fixture_patch_candidate(1, "Batch A", 1),
                sample_fixture_patch_candidate(2, "Batch B", 4),
            ])
            .unwrap();
        let published = engine.persistence_snapshot().unwrap();
        assert_eq!(published.fixtures.len(), 2);
        assert_eq!(
            published
                .fixtures
                .iter()
                .map(|fixture| fixture.id)
                .collect::<Vec<_>>(),
            vec![1, 2]
        );

        let before = published.clone();
        // Candidate two conflicts with candidate one. Validation stages both
        // before applying either, so neither ID 3 nor ID 4 leaks into B.
        let conflict = engine.patch_fixtures_published(vec![
            sample_fixture_patch_candidate(3, "Would apply first", 7),
            sample_fixture_patch_candidate(4, "Conflicts second", 8),
        ]);
        assert!(conflict.is_err());
        assert_eq!(
            engine.persistence_snapshot().unwrap().fixtures,
            before.fixtures
        );

        // An already-expired queued admission is cancelled before runtime
        // mutation and cannot late-apply after the caller returned.
        let expired = engine.patch_fixtures_published_with_timeout(
            vec![sample_fixture_patch_candidate(5, "Expired", 7)],
            Duration::ZERO,
        );
        assert!(expired.is_err());
        thread::sleep(Duration::from_millis(20));
        assert_eq!(
            engine.persistence_snapshot().unwrap().fixtures,
            before.fixtures
        );
    }

    #[test]
    fn fixture_patch_batch_waits_after_admission_for_shared_snapshot_publication() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let before = engine.snapshot();
        let published_guard = engine.snapshot.read().unwrap();
        let caller_engine = engine.clone();
        let caller = thread::spawn(move || {
            caller_engine.patch_fixtures_published(vec![sample_fixture_patch_candidate(
                1,
                "Blocked publication",
                1,
            )])
        });
        thread::sleep(Duration::from_millis(25));
        assert!(
            !caller.is_finished(),
            "admitted PATCH must wait for definitive shared publication"
        );
        assert_eq!(published_guard.fixtures, before.fixtures);
        drop(published_guard);
        assert_eq!(caller.join().unwrap(), Ok(()));
        assert_eq!(engine.snapshot().fixtures.len(), 1);
    }

    #[test]
    fn fixture_patch_allocator_transaction_rolls_back_failures_and_serializes_competitors() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });

        let timeout = engine.patch_fixtures_allocated_published_with_timeout(
            vec![(sample_patch_request("Expired", 1), sample_profile())],
            Duration::ZERO,
        );
        assert!(timeout.is_err());
        assert_eq!(engine.allocate_fixture_id(), 1);

        let conflict = engine.patch_fixtures_allocated_published(vec![
            (
                sample_patch_request("Would apply first", 1),
                sample_profile(),
            ),
            (
                sample_patch_request("Conflicts second", 1),
                sample_profile(),
            ),
        ]);
        assert!(conflict.is_err());
        assert_eq!(engine.allocate_fixture_id(), 2);

        engine.force_next_pending_publication_failure_for_tests();
        let publication = engine.patch_fixtures_allocated_published(vec![(
            sample_patch_request("Rolled back publication", 1),
            sample_profile(),
        )]);
        assert!(publication.is_err());
        assert_eq!(engine.allocate_fixture_id(), 3);

        let published_guard = engine.snapshot.read().unwrap();
        let patch_engine = engine.clone();
        let patch = thread::spawn(move || {
            patch_engine.patch_fixtures_allocated_published(vec![(
                sample_patch_request("Published", 1),
                sample_profile(),
            )])
        });
        thread::sleep(Duration::from_millis(25));
        let allocation_engine = engine.clone();
        let competing = thread::spawn(move || allocation_engine.allocate_fixture_id());
        thread::sleep(Duration::from_millis(10));
        assert!(
            !competing.is_finished(),
            "a competing fixture allocation must wait for the definitive PATCH result"
        );
        drop(published_guard);
        assert_eq!(patch.join().unwrap().unwrap(), vec![4]);
        assert_eq!(competing.join().unwrap(), 5);
    }

    #[test]
    fn fixture_patch_allocator_exhaustion_is_a_no_panic_no_delta_error() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        engine
            .next_fixture_id
            .store(u64::MAX - 1, Ordering::Relaxed);
        let result = engine.patch_fixtures_allocated_published(vec![(
            sample_patch_request("Exhausted", 1),
            sample_profile(),
        )]);
        assert!(result.is_err());
        assert_eq!(engine.next_fixture_id.load(Ordering::Relaxed), u64::MAX - 1);
        assert!(engine.persistence_snapshot().unwrap().fixtures.is_empty());

        let wire_engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let wire_max = protocol::control_plane_command::MAX_SAFE_JAVASCRIPT_INTEGER;
        wire_engine
            .next_fixture_id
            .store(wire_max, Ordering::Relaxed);
        assert_eq!(
            wire_engine
                .patch_fixtures_allocated_published(vec![(
                    sample_patch_request("Wire max", 1),
                    sample_profile(),
                )])
                .unwrap(),
            vec![wire_max]
        );
        let before = wire_engine.persistence_snapshot().unwrap();
        let above_wire = wire_engine.patch_fixtures_allocated_published(vec![(
            sample_patch_request("Above wire max", 7),
            sample_profile(),
        )]);
        assert!(above_wire.is_err());
        assert_eq!(
            wire_engine.persistence_snapshot().unwrap().fixtures,
            before.fixtures
        );
        assert_eq!(
            wire_engine.next_fixture_id.load(Ordering::Relaxed),
            wire_max + 1
        );
    }

    #[test]
    fn admitted_fixture_patch_ack_disconnect_is_not_allocator_rewind_safe() {
        let admission = ProjectSnapshotLoadAdmission::new();
        assert!(admission.try_admit_before(Instant::now() + Duration::from_secs(1)));
        let (sender, receiver) = mpsc::sync_channel::<Result<(), String>>(1);
        drop(sender);
        let error = receive_fixture_patch_allocated_ack(
            receiver,
            &admission,
            Instant::now() + Duration::from_secs(1),
            Duration::from_secs(1),
        )
        .unwrap_err();
        assert!(!error.allocator_rewind_safe);
        assert!(error.message.contains("remain reserved"));
    }

