    #[test]
    fn color_mappings_bounce_rng_glyph_and_frame_count_are_exact() {
        let request = test_bounce_request(ColorEffectSpatialBounceItem::Shape, false, true, 30_000);
        let compiled = CompiledDaslightBounce::compile(&request).unwrap().unwrap();
        assert_eq!(compiled.random_a.len(), 5_000);
        for index in [0_usize, 1, 2, 2_499, 4_999] {
            let even = (index as u64 * 2).wrapping_mul(0x9E37_79B9_7F4A_7C15);
            let odd = (index as u64 * 2 + 1).wrapping_mul(0x9E37_79B9_7F4A_7C15);
            let expected = ((splitmix64(0x21A5_5A21 ^ even) >> 49) as u16) as f32 / 32_767.0;
            let _discarded = splitmix64(0x21A5_5A21 ^ odd) >> 49;
            assert_eq!(compiled.random_a[index].to_bits(), expected.to_bits());
        }
        let wrapped = CompiledDaslightBounce::initial_state(
            ColorEffectSpatialBounceItem::Points,
            501,
            10,
            &compiled.random_a,
        );
        for values in [&wrapped.x, &wrapped.y, &wrapped.vx, &wrapped.vy] {
            assert_eq!(values[5_000].to_bits(), values[0].to_bits());
        }
        assert_eq!(compiled.rendered_frame_count, 750);
        for (period, expected) in [(1, 1), (40, 1), (5_000, 125), (30_000, 750), (40_000, 750)] {
            let value = CompiledDaslightBounce::compile(&test_bounce_request(
                ColorEffectSpatialBounceItem::Shape,
                false,
                false,
                period,
            ))
            .unwrap()
            .unwrap();
            assert_eq!(value.rendered_frame_count, expected, "period={period}");
        }

        let glyph = CompiledDaslightBounceGlyph::compile();
        let bbox = glyph.outer.iter().fold(
            (
                f32::INFINITY,
                f32::INFINITY,
                f32::NEG_INFINITY,
                f32::NEG_INFINITY,
            ),
            |(min_x, min_y, max_x, max_y), &(x, y)| {
                (min_x.min(x), min_y.min(y), max_x.max(x), max_y.max(y))
            },
        );
        assert_eq!(bbox, (64.0, -64.0, 965.0, 960.0));
        assert!(glyph.contains(-314.5, 0.0, 0.0, 0.0, 400.0));
        assert!(!glyph.contains(189.5, -320.0, 0.0, 0.0, 400.0));
        assert!(
            glyph.outer.len() > 20,
            "off-curve points must create implicit quadratic spans"
        );
        assert!(
            glyph.inner.len() > 12,
            "inner contour must remain an even-odd hole"
        );
    }

    #[test]
    fn color_mappings_bounce_update_boundary_collision_and_paths_are_exact() {
        let mut points = CompiledDaslightBounce::compile(&test_bounce_request(
            ColorEffectSpatialBounceItem::Points,
            true,
            false,
            5_000,
        ))
        .unwrap()
        .unwrap();
        let initial = (*points.initial_state).clone();
        let mut generation_zero = initial.clone();
        points.advance_state_dimensions(&mut generation_zero, 100.0, 100.0);
        assert_eq!(
            generation_zero.x[0],
            initial.x[0] + initial.vx[0] * points.speed,
            "generation zero must update before painting"
        );
        assert_ne!(generation_zero.x[0].to_bits(), initial.x[0].to_bits());

        let mut non_square = initial.clone();
        non_square.x[0] = 16.0;
        non_square.y[0] = 26.0;
        non_square.vx[0] = 1.0;
        non_square.vy[0] = 1.0;
        points.speed = 10.0;
        points.advance_state_dimensions(&mut non_square, 20.0, 30.0);
        assert_eq!(non_square.x[0], 26.0);
        assert_eq!(
            non_square.vx[0], 1.0,
            "X compares against H, preserving the swap"
        );
        assert_eq!(
            non_square.y[0], 36.0,
            "boundary response must not clamp overshoot"
        );
        assert_eq!(
            non_square.vy[0], -1.0,
            "Y compares against W, preserving the swap"
        );

        points.points = 4;
        points.number = 1;
        points.size = 2.0;
        let square = CompiledDaslightBounceState {
            x: vec![10.0, 20.0, 20.0, 10.0],
            y: vec![10.0, 10.0, 20.0, 20.0],
            vx: vec![0.0; 4],
            vy: vec![0.0; 4],
        };
        points.fill = true;
        assert!(points.point_hits_closed_path(&square, 0, 15.0, 15.0));
        assert!(!points.point_hits_closed_path(&square, 0, 25.0, 15.0));
        points.fill = false;
        assert!(
            points.point_hits_closed_path(&square, 0, 10.0, 15.0),
            "closing edge must be stroked"
        );
        assert!(!points.point_hits_closed_path(&square, 0, 15.0, 15.0));

        let mut shape = CompiledDaslightBounce::compile(&test_bounce_request(
            ColorEffectSpatialBounceItem::Shape,
            false,
            true,
            5_000,
        ))
        .unwrap()
        .unwrap();
        shape.number = 2;
        shape.speed = 0.0;
        shape.size = 20.0;
        let mut approach = CompiledDaslightBounceState {
            x: vec![10.0, 20.0],
            y: vec![10.0, 10.0],
            vx: vec![1.0, -1.0],
            vy: vec![0.0, 0.0],
        };
        shape.advance_state_dimensions(&mut approach, 100.0, 100.0);
        assert_eq!(approach.vx, vec![-1.0, 1.0]);
        let mut separating = CompiledDaslightBounceState {
            vx: vec![-1.0, 1.0],
            ..approach.clone()
        };
        shape.advance_state_dimensions(&mut separating, 100.0, 100.0);
        assert_eq!(separating.vx, vec![-1.0, 1.0]);
        let mut coincident = CompiledDaslightBounceState {
            x: vec![10.0, 10.0],
            y: vec![10.0, 10.0],
            vx: vec![1.0, -1.0],
            vy: vec![2.0, -2.0],
        };
        shape.advance_state_dimensions(&mut coincident, 100.0, 100.0);
        assert_eq!(coincident.vx, vec![1.0, -1.0], "dist2 zero must be skipped");
        assert!(coincident.vx.iter().all(|value| value.is_finite()));
    }

    #[test]
    fn color_mappings_bounce_reference_frames_fallback_and_arc_clone_are_exact() {
        let targets = test_particle_mask_targets();
        for (item, fill, collide) in [
            (ColorEffectSpatialBounceItem::Shape, false, false),
            (ColorEffectSpatialBounceItem::Shape, false, true),
            (ColorEffectSpatialBounceItem::Points, false, false),
            (ColorEffectSpatialBounceItem::Points, true, false),
        ] {
            let request = test_bounce_request(item, fill, collide, 5_000);
            let full = CompiledDaslightBounce::compile(&request).unwrap().unwrap();
            let supported = CompiledDaslightBounce::compile_for_targets(&request, &targets)
                .unwrap()
                .unwrap();
            assert!(supported.raster_cache.is_none());
            assert_eq!(supported.rendered_frame_count, 125);
            let frames = supported.precomputed_frames.as_ref().unwrap();
            assert_eq!(frames.sampled_pixel_count, 200);
            assert_eq!(frames.red.len(), 125 * 200);
            for generation in [0_usize, 1, 63, 124] {
                let phase = (generation as f64 + 0.25) / 125.0;
                for target in &targets {
                    assert_eq!(
                        supported.sample_at_phase(phase, target.x, target.z),
                        full.sample_at_phase(phase, target.x, target.z),
                        "item={item:?} fill={fill} collide={collide} generation={generation}"
                    );
                }
            }
            let pointers = supported.storage_pointers();
            let clone = supported.clone();
            assert_eq!(clone.storage_pointers(), pointers);
            assert_eq!(Arc::strong_count(&supported.random_a), 2);
            assert_eq!(Arc::strong_count(&supported.palette), 2);
            assert_eq!(
                Arc::strong_count(supported.precomputed_frames.as_ref().unwrap()),
                2
            );
        }

        let request = test_bounce_request(ColorEffectSpatialBounceItem::Points, true, false, 5_000);
        let fallback_targets = (0..201)
            .map(|index| {
                test_spatial_color_target(
                    index,
                    201,
                    (index % 100) as f32 / 99.0,
                    (index / 100) as f32 / 2.0,
                )
            })
            .collect::<Vec<_>>();
        let fallback = CompiledDaslightBounce::compile_for_targets(&request, &fallback_targets)
            .unwrap()
            .unwrap();
        assert!(fallback.precomputed_frames.is_none());
        let pointers = fallback.storage_pointers();
        for target in fallback_targets.iter().take(20) {
            let _ = fallback.sample_at_phase(63.25 / 125.0, target.x, target.z);
        }
        assert_eq!(
            fallback.cache_state(),
            (Some(63), 1),
            "same generation rebuilds once"
        );
        let full = CompiledDaslightBounce::compile(&request).unwrap().unwrap();
        for target in fallback_targets.iter().take(20) {
            assert_eq!(
                fallback.sample_at_phase(63.25 / 125.0, target.x, target.z),
                full.sample_at_phase(63.25 / 125.0, target.x, target.z)
            );
        }
        let _ = fallback.sample_at_phase(64.25 / 125.0, 0.0, 0.0);
        assert_eq!(fallback.cache_state(), (Some(64), 2));
        assert_eq!(
            fallback.storage_pointers(),
            pointers,
            "fallback must not reallocate"
        );
    }

    #[test]
    fn color_mappings_bounce_palette_later_wins_qgray_and_validation_are_exact() {
        let mut request =
            test_bounce_request(ColorEffectSpatialBounceItem::Shape, false, false, 5_000);
        let mut compiled = CompiledDaslightBounce::compile(&request).unwrap().unwrap();
        compiled.number = 2;
        compiled.size = 100.0;
        let overlapping = CompiledDaslightBounceState {
            x: vec![50.0, 50.0],
            y: vec![50.0, 50.0],
            vx: vec![0.0; 2],
            vy: vec![0.0; 2],
        };
        let color = compiled.sampled_color(&overlapping, 20, 50);
        assert_eq!(
            color, compiled.palette[2],
            "later item must win and use 1+i%(N-1)"
        );
        compiled.grayscale = true;
        assert_eq!(
            compiled.sampled_color(&overlapping, 20, 50),
            daslight_grayscale_color(color)
        );

        validate_color_effect_request(&request).unwrap();
        if let ColorEffectSpatialRecipe::Bounce { item, shape, .. } =
            &mut request.spatial_pattern.as_mut().unwrap().recipe
        {
            *item = ColorEffectSpatialBounceItem::Shape;
            *shape = 1;
        }
        assert_eq!(
            validate_color_effect_request(&request).unwrap_err(),
            "Bounce supports only XEEL glyph Shape 0"
        );
        if let ColorEffectSpatialRecipe::Bounce { item, shape, .. } =
            &mut request.spatial_pattern.as_mut().unwrap().recipe
        {
            *item = ColorEffectSpatialBounceItem::Points;
            *shape = 28;
        }
        validate_color_effect_request(&request).unwrap();
        request.stops.truncate(1);
        assert_eq!(
            validate_color_effect_request(&request).unwrap_err(),
            "Bounce requires between 2 and 255 palette stops"
        );
    }

    #[test]
    fn color_mappings_bounce_cue_transition_shares_supported_backing_storage() {
        fn request(seed: u32) -> ColorEffectRequest {
            let mut request =
                test_bounce_request(ColorEffectSpatialBounceItem::Shape, false, true, 5_000);
            let pattern = request.spatial_pattern.as_mut().unwrap();
            let ColorEffectSpatialRecipe::Bounce { rng_seed, .. } = &mut pattern.recipe else {
                unreachable!();
            };
            *rng_seed = seed;
            pattern.placement.as_mut().unwrap().target_coordinates[0] =
                protocol::ColorEffectSpatialPlacementTarget {
                    fixture_id: 1,
                    beam_index: 0,
                    patch_x: 50,
                    patch_y: 50,
                };
            request
        }
        fn bounce(effect: &RuntimeEffect) -> &CompiledDaslightBounce {
            let RuntimeEffectKind::Color(color) = &effect.kind else {
                panic!("expected Color transition effect");
            };
            color
                .spatial
                .as_ref()
                .unwrap()
                .daslight_bounce
                .as_ref()
                .unwrap()
        }

        let mut runtime = runtime_with_mixed_effect_fixtures(1);
        let created_at = Instant::now();
        let make_effect = |runtime: &mut EngineRuntime, seed| RuntimeEffect {
            id: 21,
            kind: RuntimeEffectKind::Color(
                runtime.resolve_color_effect_request(request(seed)).unwrap(),
            ),
            enabled: true,
            created_at,
        };
        let outgoing = make_effect(&mut runtime, 0x21AC_0001);
        let incoming = make_effect(&mut runtime, 0x21AC_0002);
        runtime.effect_activations = vec![
            RuntimeEffectActivation {
                effect: outgoing,
                key: Some(RuntimeEffectActivationKey::CueList {
                    cue_list_id: DEFAULT_CUE_LIST_ID,
                    cue_id: 1,
                }),
                rate: 1.0,
                source_loop_fill: None,
                transition_ms: None,
                transition: None,
            },
            RuntimeEffectActivation {
                effect: incoming,
                key: None,
                rate: 1.0,
                source_loop_fill: None,
                transition_ms: Some(1_000),
                transition: None,
            },
        ];
        runtime.active_effect_activation_indices = vec![0];

        let outgoing = bounce(&runtime.effect_activations[0].effect);
        let pointers = outgoing.storage_pointers();
        assert_eq!(Arc::strong_count(&outgoing.random_a), 1);
        assert_eq!(Arc::strong_count(&outgoing.palette), 1);
        assert_eq!(
            Arc::strong_count(outgoing.precomputed_frames.as_ref().unwrap()),
            1
        );
        let sources = runtime.cue_list_effect_transition_sources(DEFAULT_CUE_LIST_ID);
        let source = bounce(&sources[0].0);
        assert_eq!(source.storage_pointers(), pointers);
        assert_eq!(Arc::strong_count(&source.random_a), 2);
        assert_eq!(Arc::strong_count(&source.palette), 2);
        assert_eq!(
            Arc::strong_count(source.precomputed_frames.as_ref().unwrap()),
            2
        );
        runtime.activate_cue_effect_range_with_transitions(
            RuntimeEffectActivationRange { start: 1, len: 1 },
            RuntimeEffectActivationKey::CueList {
                cue_list_id: DEFAULT_CUE_LIST_ID,
                cue_id: 2,
            },
            created_at,
            &sources,
        );
        let transition = bounce(
            &runtime.effect_activations[1]
                .transition
                .as_ref()
                .unwrap()
                .from,
        );
        assert_eq!(transition.storage_pointers(), pointers);
        assert_eq!(Arc::strong_count(&transition.random_a), 3);
        assert_eq!(Arc::strong_count(&transition.palette), 3);
        assert_eq!(
            Arc::strong_count(transition.precomputed_frames.as_ref().unwrap()),
            3
        );
    }

    #[test]
    fn color_mappings_particle_sample_mask_matches_reference_row_spans_bit_exact() {
        let background = test_color(777, 1_234, 4_321);
        let mut reference = [background; DASLIGHT_PARTICLE_RASTER_PIXELS];
        let mut masked = [background; DASLIGHT_PARTICLE_RASTER_PIXELS];
        let mut sampled_rows = [0_u128; DASLIGHT_PARTICLE_RASTER_SIZE];
        for (y, sampled_row) in sampled_rows.iter_mut().enumerate() {
            for x in 0..DASLIGHT_PARTICLE_RASTER_SIZE {
                if x == 0 || x == 99 || y == 0 || y == 99 || (x * 17 + y * 31) % 47 == 0 {
                    *sampled_row |= 1_u128 << x;
                }
            }
        }
        let sampled_y_rows = sampled_rows
            .iter()
            .enumerate()
            .fold(0_u128, |mask, (row, sampled)| {
                mask | (u128::from(*sampled != 0) << row)
            });
        let mut sampled_pixel_count = 0;
        let sampled_descriptors = sampled_rows.map(|x_mask| {
            let row = CompiledDaslightParticleSampleRow {
                x_mask,
                slot_start: sampled_pixel_count,
            };
            sampled_pixel_count += x_mask.count_ones() as usize;
            row
        });
        let mut compact = CompiledDaslightParticleRasterCache::new(background, sampled_pixel_count);
        let cases = [
            (-50.25, -20.75, 100.0, test_color(65_535, 0, 0), 1.0),
            (-0.5, 0.25, 1.0, test_color(0, 65_535, 0), 0.5),
            (0.0, 0.0, 4.0, test_color(0, 0, 65_535), 0.25),
            (
                16.125,
                83.875,
                10.0,
                test_color(12_345, 54_321, 2_222),
                0.995,
            ),
            (49.5, 49.5, 100.0, test_color(30_000, 30_000, 30_000), 0.0),
            (98.75, 98.25, 100.0, test_color(65_535, 65_535, 0), 0.9),
            (100.25, 100.75, 5.0, test_color(0, 65_535, 65_535), 1.0),
        ];
        for (x, y, size, color, opacity) in cases {
            CompiledDaslightParticles::source_over_ellipse_reference(
                &mut reference,
                x,
                y,
                size,
                color,
                opacity,
            );
            CompiledDaslightParticles::source_over_ellipse_masked(
                &sampled_rows,
                sampled_y_rows,
                &mut masked,
                (x, y, size),
                color,
                opacity,
            );
            CompiledDaslightParticles::source_over_ellipse_sampled(
                &sampled_descriptors,
                sampled_y_rows,
                &mut compact,
                (x, y, size),
                color,
                opacity,
            );
        }
        for index in 0..256_u64 {
            let x = f64::from(syndocal_sparkle_unit_fraction(index ^ 0xA5A5)) * 160.0 - 30.0;
            let y = f64::from(syndocal_sparkle_unit_fraction(index ^ 0x5A5A)) * 160.0 - 30.0;
            let size = f64::from(syndocal_sparkle_unit_fraction(index ^ 0xC3C3)) * 99.0 + 1.0;
            let opacity = syndocal_sparkle_unit_fraction(index ^ 0x3C3C);
            let color = test_color(
                index.wrapping_mul(257) as u16,
                index.wrapping_mul(997) as u16,
                index.wrapping_mul(4_093) as u16,
            );
            CompiledDaslightParticles::source_over_ellipse_reference(
                &mut reference,
                x,
                y,
                size,
                color,
                opacity,
            );
            CompiledDaslightParticles::source_over_ellipse_masked(
                &sampled_rows,
                sampled_y_rows,
                &mut masked,
                (x, y, size),
                color,
                opacity,
            );
            CompiledDaslightParticles::source_over_ellipse_sampled(
                &sampled_descriptors,
                sampled_y_rows,
                &mut compact,
                (x, y, size),
                color,
                opacity,
            );
        }
        for (y, sampled_row) in sampled_rows.iter().enumerate() {
            for x in 0..DASLIGHT_PARTICLE_RASTER_SIZE {
                let index = y * DASLIGHT_PARTICLE_RASTER_SIZE + x;
                if *sampled_row & (1_u128 << x) != 0 {
                    assert_eq!(masked[index], reference[index], "masked pixel ({x},{y})");
                    let row = sampled_descriptors[y];
                    let slot =
                        row.slot_start + (row.x_mask & ((1_u128 << x) - 1)).count_ones() as usize;
                    assert_eq!(
                        compact.color(slot),
                        reference[index],
                        "compact SoA pixel ({x},{y})"
                    );
                } else {
                    assert_eq!(masked[index], background, "unobserved pixel ({x},{y})");
                }
            }
        }
    }

    #[test]
    fn color_mappings_particle_target_mask_and_full_effect_generations_are_bit_exact() {
        let targets = test_particle_mask_targets();
        for recipe in [test_explosion_recipe(0x47A5), test_starfield_recipe(0x48A5)] {
            let mut request = test_particle_request(recipe, 5_000);
            match &mut request.spatial_pattern.as_mut().unwrap().recipe {
                ColorEffectSpatialRecipe::Explosion { grayscale, .. }
                | ColorEffectSpatialRecipe::Starfield { grayscale, .. } => *grayscale = true,
                _ => unreachable!(),
            }
            let full = CompiledDaslightParticles::compile(&request)
                .unwrap()
                .unwrap();
            let masked = CompiledDaslightParticles::compile_for_targets(&request, &targets)
                .unwrap()
                .unwrap();
            assert_eq!(
                masked
                    .sampled_rows
                    .iter()
                    .map(|row| row.x_mask.count_ones())
                    .sum::<u32>(),
                200
            );
            assert_eq!(masked.sampled_rows[0].x_mask, (1_u128 << 100) - 1);
            assert_eq!(masked.sampled_rows[99].x_mask, (1_u128 << 100) - 1);
            assert!(masked.sampled_rows[1..99].iter().all(|row| row.x_mask == 0));

            for generation in 0..125_usize {
                let phase = generation as f64 / 125.0;
                for target in &targets {
                    assert_eq!(
                        masked.sample_at_phase(phase, target.x, target.z),
                        full.sample_at_phase(phase, target.x, target.z),
                        "generation={generation} target=({}, {})",
                        target.x,
                        target.z
                    );
                }
            }
        }
    }

    #[test]
    fn color_mappings_particle_deep_generation_goldens() {
        let targets = vec![
            test_spatial_color_target(0, 3, 0.0, 0.0),
            test_spatial_color_target(1, 3, 0.5, 0.5),
            test_spatial_color_target(2, 3, 1.0, 1.0),
        ];
        let recipes = [
            ColorEffectSpatialRecipe::Explosion {
                grayscale: false,
                rng_seed: 0x47DE_E749,
                shape: 0,
                explosion_number: 50,
                explosion_size: 10,
                particle_number: 1,
                particle_size: 100,
                particle_life: 0.9,
                trail_size: 25,
                gravity: 10.0,
            },
            ColorEffectSpatialRecipe::Starfield {
                grayscale: false,
                rng_seed: 0x48DE_E749,
                shape: 0,
                particles: 10,
                size: 10,
                trail: 25,
                rotation: 0.125,
            },
        ];
        for (recipe_index, recipe) in recipes.into_iter().enumerate() {
            let request = test_particle_request(recipe, 30_000);
            let compiled = CompiledDaslightParticles::compile_for_targets(&request, &targets)
                .unwrap()
                .unwrap();
            let values = [124_usize, 125, 749]
                .into_iter()
                .map(|generation| {
                    let phase = (generation as f64 + 0.25) / 750.0;
                    targets
                        .iter()
                        .map(|target| compiled.sample_at_phase(phase, target.x, target.z))
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>();
            let expected = if recipe_index == 0 {
                vec![
                    vec![
                        test_color(0, 0, 0),
                        test_color(0, 0, 0),
                        test_color(65_535, 0, 0),
                    ],
                    vec![
                        test_color(0, 0, 0),
                        test_color(0, 0, 0),
                        test_color(65_535, 0, 0),
                    ],
                    vec![
                        test_color(0, 0, 0),
                        test_color(0, 0, 0),
                        test_color(1_018, 64_251, 0),
                    ],
                ]
            } else {
                vec![
                    vec![
                        test_color(0, 0, 0),
                        test_color(17_651, 25_690, 0),
                        test_color(0, 65_534, 0),
                    ],
                    vec![
                        test_color(0, 0, 0),
                        test_color(16_248, 23_089, 0),
                        test_color(0, 65_535, 0),
                    ],
                    vec![
                        test_color(0, 0, 0),
                        test_color(65_526, 6, 0),
                        test_color(0, 0, 0),
                    ],
                ]
            };
            assert_eq!(values, expected);
        }
    }

    #[test]
    fn color_mappings_particle_one_pass_trajectory_matches_age_zero_replay_bit_exact() {
        for case in 0..64_u64 {
            let first = syndocal_sparkle_unit_fraction(case ^ 0x4711);
            let second = syndocal_sparkle_unit_fraction(case ^ 0x4722);
            let third = syndocal_sparkle_unit_fraction(case ^ 0x4733);
            let fourth = syndocal_sparkle_unit_fraction(case ^ 0x4744);
            let center_x = 16.0 + first * 67.0;
            let center_y = 16.0 + second * 67.0;
            let velocity_x = 4.0 * third - 2.0;
            let velocity_y = 4.0 * fourth - 2.0;
            let motion = first * 10.0;
            let gravity = second * 10.0;
            let angle = second * 360.0;
            let rotation = third * 10.0 - 5.0;
            let radius = (fourth * 10.0 + 5.0).trunc();
            let random_age = (splitmix64(case ^ 0x47A6_E749) % 750) as usize;
            for age in [0, 1, 2, 24, 25, 26, 124, 125, 374, 749, random_age] {
                let actual = CompiledDaslightParticles::explosion_position(
                    center_x, center_y, velocity_x, velocity_y, motion, gravity, age,
                );
                let reference = CompiledDaslightParticles::explosion_position_reference(
                    center_x, center_y, velocity_x, velocity_y, motion, gravity, age,
                );
                assert_eq!(
                    (actual.0.to_bits(), actual.1.to_bits()),
                    (reference.0.to_bits(), reference.1.to_bits())
                );

                let actual =
                    CompiledDaslightParticles::starfield_position(angle, rotation, radius, age);
                let reference = CompiledDaslightParticles::starfield_position_reference(
                    angle, rotation, radius, age,
                );
                assert_eq!(
                    (actual.0.to_bits(), actual.1.to_bits()),
                    (reference.0.to_bits(), reference.1.to_bits())
                );
            }
        }
    }

    #[test]
    fn color_mappings_particles_constants_rng_frame_cap_and_motion_are_exact() {
        let compiled = CompiledDaslightParticles::compile(&test_particle_request(
            test_explosion_recipe(0x1234_5678),
            30_040,
        ))
        .unwrap()
        .unwrap();
        let compiled_again = CompiledDaslightParticles::compile(&test_particle_request(
            test_explosion_recipe(0x1234_5678),
            30_040,
        ))
        .unwrap()
        .unwrap();
        let different_seed = CompiledDaslightParticles::compile(&test_particle_request(
            test_explosion_recipe(0x1234_5679),
            30_040,
        ))
        .unwrap()
        .unwrap();
        assert_eq!(compiled.source_frame_count, 751);
        assert_eq!(compiled.rendered_frame_count, 750);
        assert_eq!(compiled.random_pairs.len(), 5_000);
        assert_eq!(compiled.random_pairs, compiled_again.random_pairs);
        assert_ne!(compiled.random_pairs, different_seed.random_pairs);
        assert_eq!(compiled.generation(0.0), 0);
        assert_eq!(compiled.generation(1.0 - f64::EPSILON), 749);
        assert_eq!(
            CompiledDaslightParticles::explosion_spawn_period(125, 50),
            2
        );
        assert_eq!(
            CompiledDaslightParticles::explosion_spawn_count(125, 50, 124),
            63,
            "source integer period deliberately permits more spawns than ExplosionNumber"
        );

        let explosion_position =
            CompiledDaslightParticles::explosion_position(10.0, 20.0, 2.0, -1.0, 0.5, 10.0, 3);
        assert!((explosion_position.0 - 13.0).abs() < 1.0e-5);
        assert!((explosion_position.1 - 18.8).abs() < 1.0e-5);
        assert_eq!(
            CompiledDaslightParticles::starfield_position(0.0, 90.0, 5.0, 0),
            (55.0, 50.0)
        );
        assert_eq!(
            CompiledDaslightParticles::starfield_position(0.0, 90.0, 5.0, 1),
            (56.0, 50.0)
        );
        let generation_two = CompiledDaslightParticles::starfield_position(0.0, 90.0, 5.0, 2);
        assert!((generation_two.0 - 50.0).abs() < 1.0e-5);
        assert!((generation_two.1 - 57.0).abs() < 1.0e-5);
        assert_eq!(
            CompiledDaslightParticles::starfield_position(45.0, 0.0, 5.0, 0),
            (53.0, 53.0),
            "Starfield initial placement uses trunc(cos/sin * radius)"
        );
        let fractional_rotation =
            CompiledDaslightParticles::starfield_position(37.25, 0.125, 14.0, 17);
        assert_eq!(fractional_rotation, (73.697_556, 69.361_71));
    }

    #[test]
    fn color_mappings_particles_use_top_left_ellipse_children_before_parent_and_qgray_last() {
        let black = test_color(0, 0, 0);
        let red = test_color(u16::MAX, 0, 0);
        let green = test_color(0, u16::MAX, 0);
        let mut raster = [black; DASLIGHT_PARTICLE_RASTER_PIXELS];
        CompiledDaslightParticles::source_over_ellipse(&mut raster, 10.0, 20.0, 4.0, red, 1.0);
        assert_eq!(
            raster[20 * 100 + 10],
            black,
            "ellipse corner remains unpainted"
        );
        assert_eq!(raster[20 * 100 + 11], red);
        assert_eq!(raster[23 * 100 + 12], red);
        assert_eq!(raster[24 * 100 + 12], black);

        raster.fill(black);
        CompiledDaslightParticles::paint_layers(
            &mut raster,
            &[(10.0, 20.0, 4.0, red, 0.5), (10.0, 20.0, 4.0, green, 0.5)],
        );
        let child_then_parent = raster[20 * 100 + 11];
        raster.fill(black);
        CompiledDaslightParticles::paint_layers(
            &mut raster,
            &[(10.0, 20.0, 4.0, green, 0.5), (10.0, 20.0, 4.0, red, 0.5)],
        );
        assert_ne!(child_then_parent, raster[20 * 100 + 11]);
        assert!(child_then_parent.green > child_then_parent.red);

        let final_gray = daslight_grayscale_color(child_then_parent);
        raster.fill(black);
        CompiledDaslightParticles::paint_layers(
            &mut raster,
            &[
                (10.0, 20.0, 4.0, daslight_grayscale_color(red), 0.5),
                (10.0, 20.0, 4.0, daslight_grayscale_color(green), 0.5),
            ],
        );
        assert_ne!(
            final_gray,
            raster[20 * 100 + 11],
            "qGray is applied to the completed RGB raster, not individual layers"
        );
    }

    #[test]
    fn color_mappings_particles_validate_maxima_dynamic_fallback_and_clamp_endpoint() {
        let explosion = ColorEffectSpatialRecipe::Explosion {
            grayscale: true,
            rng_seed: u32::MAX,
            shape: 0,
            explosion_number: 50,
            explosion_size: 100,
            particle_number: 100,
            particle_size: 100,
            particle_life: 0.9,
            trail_size: 25,
            gravity: 10.0,
        };
        let starfield = ColorEffectSpatialRecipe::Starfield {
            grayscale: true,
            rng_seed: u32::MAX,
            shape: 0,
            particles: 10,
            size: 100,
            trail: 25,
            rotation: 5.0,
        };
        validate_color_spatial_recipe(&explosion).unwrap();
        validate_color_spatial_recipe(&starfield).unwrap();
        let mut invalid = starfield.clone();
        if let ColorEffectSpatialRecipe::Starfield { shape, .. } = &mut invalid {
            *shape = 1;
        }
        assert!(validate_color_spatial_recipe(&invalid)
            .unwrap_err()
            .contains("Shape 0"));

        let compiled = CompiledDaslightParticles::compile(&test_particle_request(
            test_starfield_recipe(7),
            5_000,
        ))
        .unwrap()
        .unwrap();
        compiled.sample_at_phase(0.0, 0.5, 0.5);
        compiled.sample_at_phase(0.0, 0.6, 0.5);
        assert_eq!(compiled.cache_state(), (Some(0), 1));
        compiled.sample_at_phase(0.5, 0.5, 0.5);
        assert_eq!(compiled.cache_state(), (Some(62), 2));

        let mut fallback_targets = test_particle_mask_targets();
        fallback_targets.push(fallback_targets[0].clone());
        let fallback = CompiledDaslightParticles::compile_for_targets(
            &test_particle_request(test_starfield_recipe(8), 5_000),
            &fallback_targets,
        )
        .unwrap()
        .unwrap();
        assert!(fallback.precomputed_frames.is_none());
        fallback.sample_at_phase(0.0, fallback_targets[0].x, fallback_targets[0].z);
        assert_eq!(fallback.cache_state(), (Some(0), 1));

        let palette_count = 3_usize;
        let endpoint =
            (1 + ((palette_count - 1) as f64 * 1.0_f64).trunc() as usize).min(palette_count - 1);
        assert_eq!(endpoint, palette_count - 1);
    }

    #[test]
    fn color_mappings_particle_cue_transition_shares_all_supported_backing_storage() {
        fn particle_request(rng_seed: u32) -> ColorEffectRequest {
            let mut request = test_particle_request(test_starfield_recipe(rng_seed), 30_000);
            request.fixture_ids = vec![1];
            let pattern = request.spatial_pattern.as_mut().unwrap();
            pattern.beam_targets = vec![protocol::ColorEffectBeamTarget {
                fixture_id: 1,
                beam_index: 0,
                selection_index: 0,
                feature_attribute: None,
            }];
            let placement = pattern.placement.as_mut().unwrap();
            placement.target_coordinates = vec![protocol::ColorEffectSpatialPlacementTarget {
                fixture_id: 1,
                beam_index: 0,
                patch_x: 50,
                patch_y: 50,
            }];
            request
        }

        fn particles(effect: &RuntimeEffect) -> &CompiledDaslightParticles {
            let RuntimeEffectKind::Color(color) = &effect.kind else {
                panic!("expected Color transition effect");
            };
            color
                .spatial
                .as_ref()
                .unwrap()
                .daslight_particles
                .as_ref()
                .unwrap()
        }

        let mut runtime = runtime_with_mixed_effect_fixtures(1);
        let created_at = Instant::now();
        let outgoing = RuntimeEffect {
            id: 47,
            kind: RuntimeEffectKind::Color(
                runtime
                    .resolve_color_effect_request(particle_request(0x47AC_0001))
                    .unwrap(),
            ),
            enabled: true,
            created_at,
        };
        let incoming = RuntimeEffect {
            id: 47,
            kind: RuntimeEffectKind::Color(
                runtime
                    .resolve_color_effect_request(particle_request(0x47AC_0002))
                    .unwrap(),
            ),
            enabled: true,
            created_at,
        };
        runtime.effect_activations = vec![
            RuntimeEffectActivation {
                effect: outgoing,
                key: Some(RuntimeEffectActivationKey::CueList {
                    cue_list_id: DEFAULT_CUE_LIST_ID,
                    cue_id: 1,
                }),
                rate: 1.0,
                source_loop_fill: None,
                transition_ms: None,
                transition: None,
            },
            RuntimeEffectActivation {
                effect: incoming,
                key: None,
                rate: 1.0,
                source_loop_fill: None,
                transition_ms: Some(1_000),
                transition: None,
            },
        ];
        runtime.active_effect_activation_indices = vec![0];

        let outgoing_particles = particles(&runtime.effect_activations[0].effect);
        assert!(outgoing_particles.raster_cache.is_none());
        assert_eq!(Arc::strong_count(&outgoing_particles.palette), 1);
        assert_eq!(Arc::strong_count(&outgoing_particles.random_pairs), 1);
        assert_eq!(
            Arc::strong_count(outgoing_particles.precomputed_frames.as_ref().unwrap()),
            1
        );
        let outgoing_pointers = outgoing_particles.storage_pointers();
        assert_eq!(outgoing_pointers.2, 0);
        assert_eq!(outgoing_pointers.3, 0);
        assert_eq!(outgoing_pointers.4, 0);
        let outgoing_sample = outgoing_particles.sample_at_phase(749.25 / 750.0, 0.5, 0.5);

        let sources = runtime.cue_list_effect_transition_sources(DEFAULT_CUE_LIST_ID);
        assert_eq!(sources.len(), 1);
        let source_particles = particles(&sources[0].0);
        assert_eq!(source_particles.storage_pointers(), outgoing_pointers);
        assert_eq!(Arc::strong_count(&source_particles.palette), 2);
        assert_eq!(Arc::strong_count(&source_particles.random_pairs), 2);
        assert_eq!(
            Arc::strong_count(source_particles.precomputed_frames.as_ref().unwrap()),
            2
        );

        runtime.activate_cue_effect_range_with_transitions(
            RuntimeEffectActivationRange { start: 1, len: 1 },
            RuntimeEffectActivationKey::CueList {
                cue_list_id: DEFAULT_CUE_LIST_ID,
                cue_id: 2,
            },
            created_at,
            &sources,
        );
        let transition = runtime.effect_activations[1].transition.as_ref().unwrap();
        let transition_particles = particles(&transition.from);
        assert!(transition_particles.raster_cache.is_none());
        assert_eq!(transition_particles.storage_pointers(), outgoing_pointers);
        assert_eq!(Arc::strong_count(&transition_particles.palette), 3);
        assert_eq!(Arc::strong_count(&transition_particles.random_pairs), 3);
        assert_eq!(
            Arc::strong_count(transition_particles.precomputed_frames.as_ref().unwrap()),
            3
        );
        assert_eq!(
            transition_particles.sample_at_phase(749.25 / 750.0, 0.5, 0.5),
            outgoing_sample
        );
        drop(sources);
        let outgoing_particles = particles(&runtime.effect_activations[0].effect);
        assert_eq!(Arc::strong_count(&outgoing_particles.palette), 2);
        assert_eq!(Arc::strong_count(&outgoing_particles.random_pairs), 2);
        assert_eq!(
            Arc::strong_count(outgoing_particles.precomputed_frames.as_ref().unwrap()),
            2
        );
    }

    #[test]
    fn max_explosion_starfield_release_stack_meets_44hz_budget() {
        const EXPLOSION_EFFECTS: usize = 32;
        const STARFIELD_EFFECTS: usize = 32;
        const MAX_PALETTE_STOPS: usize = 255;
        const RASTER_WIDTH: i64 = 100;
        const RASTER_HEIGHT: i64 = 100;
        const MINIMUM_GENERATION_EXERCISING_PERIOD_MS: u64 = 80;

        assert_eq!(
            EXPLOSION_EFFECTS + STARFIELD_EFFECTS,
            RELEASE_GATE_EFFECT_COUNT
        );
        assert_eq!(RELEASE_GATE_EFFECT_COUNT, 64);
        assert_eq!(RELEASE_GATE_FIXTURE_COUNT, 200);
        assert_eq!(RELEASE_GATE_HZ, 44);
        assert_eq!(
            RELEASE_GATE_SAMPLES,
            if cfg!(debug_assertions) { 20 } else { 1_000 }
        );
        assert_eq!(MAX_PALETTE_STOPS, 255);
        assert_eq!((RASTER_WIDTH, RASTER_HEIGHT), (100, 100));
        assert_eq!(RELEASE_GATE_P95_LIMIT, Duration::from_millis(5));
        assert_eq!(RELEASE_GATE_P99_LIMIT, Duration::from_millis(8));
        assert_eq!(RELEASE_GATE_MAX_LIMIT, Duration::from_millis(12));
        assert_eq!(
            1_000_000 / DMX_TICK_INTERVAL.as_micros(),
            u128::from(RELEASE_GATE_HZ)
        );

        let mut runtime = runtime_with_mixed_effect_fixtures(RELEASE_GATE_FIXTURE_COUNT as u64);
        let fixture_ids = (1..=RELEASE_GATE_FIXTURE_COUNT as u64).collect::<Vec<_>>();
        let beam_targets = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(selection_index, fixture_id)| protocol::ColorEffectBeamTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    selection_index: selection_index as u32,
                    feature_attribute: None,
                },
            )
            .collect::<Vec<_>>();
        let target_coordinates = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(selection_index, fixture_id)| protocol::ColorEffectSpatialPlacementTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    patch_x: (selection_index % RASTER_WIDTH as usize) as i64,
                    patch_y: if selection_index < RASTER_WIDTH as usize {
                        0
                    } else {
                        RASTER_HEIGHT - 1
                    },
                },
            )
            .collect::<Vec<_>>();
        assert_eq!(fixture_ids.len(), RELEASE_GATE_FIXTURE_COUNT);
        assert_eq!(beam_targets.len(), RELEASE_GATE_FIXTURE_COUNT);
        assert_eq!(target_coordinates.len(), RELEASE_GATE_FIXTURE_COUNT);

        let palette = (0..MAX_PALETTE_STOPS)
            .map(|stop| protocol::ColorEffectStop {
                position: stop as f32 / (MAX_PALETTE_STOPS - 1) as f32,
                color: test_color(
                    stop as u16 * 257,
                    u16::MAX - stop as u16 * 257,
                    stop as u16 * 193,
                ),
            })
            .collect::<Vec<_>>();
        let created_at = Instant::now();
        let compile_started = Instant::now();
        for index in 0..RELEASE_GATE_EFFECT_COUNT {
            let recipe = if index < EXPLOSION_EFFECTS {
                ColorEffectSpatialRecipe::Explosion {
                    grayscale: true,
                    rng_seed: 0x4700_0000 ^ index as u32,
                    shape: 0,
                    explosion_number: 50,
                    explosion_size: 100,
                    particle_number: 100,
                    particle_size: 100,
                    particle_life: 0.9,
                    trail_size: 25,
                    gravity: 10.0,
                }
            } else {
                ColorEffectSpatialRecipe::Starfield {
                    grayscale: true,
                    rng_seed: 0x4800_0000 ^ index as u32,
                    shape: 0,
                    particles: 10,
                    size: 100,
                    trail: 25,
                    rotation: 5.0,
                }
            };
            let mut request = test_spatial_color_request(recipe);
            request.fixture_ids = fixture_ids.clone();
            request.stops = palette.clone();
            request.period_ms = MINIMUM_GENERATION_EXERCISING_PERIOD_MS;
            let mut placement = test_patch_canvas_placement(0, 0, RASTER_WIDTH, RASTER_HEIGHT, 0.0);
            placement.target_coordinates = target_coordinates.clone();
            let pattern = request.spatial_pattern.as_mut().unwrap();
            pattern.beam_targets = beam_targets.clone();
            pattern.placement = Some(placement);
            validate_color_effect_request(&request).unwrap();
            let kind = RuntimeEffectKind::Color(
                runtime
                    .resolve_color_effect_request(request)
                    .expect("maximum particle request must compile"),
            );
            runtime.effects.push(RuntimeEffect {
                id: index as EffectId + 1,
                kind,
                enabled: true,
                created_at,
            });
        }
        let compile_elapsed = compile_started.elapsed();
        assert_eq!(runtime.effects.len(), RELEASE_GATE_EFFECT_COUNT);
        assert_eq!(runtime.fixtures.len(), RELEASE_GATE_FIXTURE_COUNT);

        let before_storage = runtime
            .effects
            .iter()
            .map(|effect| {
                let RuntimeEffectKind::Color(color) = &effect.kind else {
                    unreachable!();
                };
                assert_eq!(color.request.fixture_ids.len(), RELEASE_GATE_FIXTURE_COUNT);
                assert_eq!(color.request.stops.len(), MAX_PALETTE_STOPS);
                let pattern = color.request.spatial_pattern.as_ref().unwrap();
                assert_eq!(pattern.beam_targets.len(), RELEASE_GATE_FIXTURE_COUNT);
                assert_eq!(
                    (
                        pattern.placement.as_ref().unwrap().sx,
                        pattern.placement.as_ref().unwrap().sy,
                    ),
                    (RASTER_WIDTH, RASTER_HEIGHT)
                );
                let compiled = color
                    .spatial
                    .as_ref()
                    .unwrap()
                    .daslight_particles
                    .as_ref()
                    .expect("particle recipe must compile the retained raster");
                assert_eq!(compiled.random_pairs.len(), 5_000);
                assert_eq!(compiled.rendered_frame_count, 2);
                assert_eq!(compiled.cache_state(), (None, 0));
                let frames = compiled
                    .precomputed_frames
                    .as_ref()
                    .expect("supported 200-target shape must precompute every generation");
                let unique_sampled_pixels = compiled
                    .sampled_rows
                    .iter()
                    .map(|row| row.x_mask.count_ones() as usize)
                    .sum::<usize>();
                assert!((1..=RELEASE_GATE_FIXTURE_COUNT).contains(&unique_sampled_pixels));
                assert_eq!(frames.sampled_pixel_count, unique_sampled_pixels);
                assert_eq!(frames.red.len(), 2 * unique_sampled_pixels);
                compiled.storage_pointers()
            })
            .collect::<Vec<_>>();

        let mut expected_rebuild_count = 0_u64;
        let mut previous_generation = None;
        for sample in 0..RELEASE_GATE_SAMPLES {
            let elapsed = DMX_TICK_INTERVAL * (sample as u32 + 1);
            let phase =
                elapsed.as_secs_f64() / (MINIMUM_GENERATION_EXERCISING_PERIOD_MS as f64 / 1_000.0);
            let generation = (phase.rem_euclid(1.0) * 2.0).floor() as usize;
            if previous_generation != Some(generation) {
                expected_rebuild_count += 1;
                previous_generation = Some(generation);
            }
        }

        let (p95, p99, max) =
            measure_release_gate(created_at, |at| {
                runtime.fixtures.iter().fold(0_u64, |checksum, fixture| {
                    checksum.wrapping_add(runtime.apply_effects_with_transition_policy(
                        fixture, "ColorRed", 16_384, at, false,
                    ) as u64)
                })
            });
        let after_storage = runtime
            .effects
            .iter()
            .map(|effect| {
                let RuntimeEffectKind::Color(color) = &effect.kind else {
                    unreachable!();
                };
                let compiled = color
                    .spatial
                    .as_ref()
                    .unwrap()
                    .daslight_particles
                    .as_ref()
                    .unwrap();
                assert_eq!(
                    compiled.cache_state(),
                    (None, 0),
                    "precomputed supported-target frames never rebuild on the 44 Hz path"
                );
                compiled.storage_pointers()
            })
            .collect::<Vec<_>>();
        assert_eq!(
            after_storage, before_storage,
            "the 44 Hz path retains random, fallback SoA, and precomputed RGB allocations per effect"
        );
        eprintln!(
            "Explosion32+Starfield32 x200 (255 stops, 100x100, max recipe literals, R=F=2 frequent generation transitions={} with realized child_count<=1, runtime rebuilds=0): compile={}ms p95={}us p99={}us max={}us",
            expected_rebuild_count,
            compile_elapsed.as_millis(),
            p95.as_micros(),
            p99.as_micros(),
            max.as_micros(),
        );
        assert_release_gate_percentiles(p95, p99, max);
    }

    #[test]
    fn max_fire_release_stack_meets_44hz_budget() {
        const FIRE_EFFECTS: usize = 64;
        const PALETTE_STOPS: usize = 4;
        const FLAMES: u16 = 100;
        const WIDTH: u16 = 200;
        const HEIGHT: u16 = 100;
        const HOTSPOT: u16 = 255;
        const PERIOD_MS: u64 = 5_000;
        const SOURCE_FRAMES: usize = 125;
        const RASTER_SIZE: i64 = 100;
        const TRANSFORM: u8 = 2;
        const ROTATION: f32 = 360.0;

        assert_eq!(FIRE_EFFECTS, RELEASE_GATE_EFFECT_COUNT);
        assert_eq!(RELEASE_GATE_EFFECT_COUNT, 64);
        assert_eq!(RELEASE_GATE_FIXTURE_COUNT, 200);
        assert_eq!(RELEASE_GATE_HZ, 44);
        assert_eq!(PALETTE_STOPS, 4);
        assert_eq!((FLAMES, WIDTH, HEIGHT, HOTSPOT), (100, 200, 100, 255));
        assert_eq!(PERIOD_MS / 40, SOURCE_FRAMES as u64);
        assert_eq!(TRANSFORM, 2);
        assert_eq!(ROTATION, 360.0);
        assert_eq!(RELEASE_GATE_P95_LIMIT, Duration::from_millis(5));
        assert_eq!(RELEASE_GATE_P99_LIMIT, Duration::from_millis(8));
        assert_eq!(RELEASE_GATE_MAX_LIMIT, Duration::from_millis(12));
        assert_eq!(
            1_000_000 / DMX_TICK_INTERVAL.as_micros(),
            u128::from(RELEASE_GATE_HZ)
        );

        let mut runtime = runtime_with_mixed_effect_fixtures(RELEASE_GATE_FIXTURE_COUNT as u64);
        let fixture_ids = (1..=RELEASE_GATE_FIXTURE_COUNT as u64).collect::<Vec<_>>();
        let beam_targets = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(selection_index, fixture_id)| protocol::ColorEffectBeamTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    selection_index: selection_index as u32,
                    feature_attribute: None,
                },
            )
            .collect::<Vec<_>>();
        let target_coordinates = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(selection_index, fixture_id)| protocol::ColorEffectSpatialPlacementTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    // Keep all 200 authored pixels strictly inside the finite
                    // raster. At the legal 360-degree maximum, f32-to-radian
                    // rounding can rotate exact edge coordinates a fraction
                    // outside the transparent boundary.
                    patch_x: 25 + (selection_index % 50) as i64,
                    patch_y: 25 + (selection_index / 50) as i64,
                },
            )
            .collect::<Vec<_>>();
        assert_eq!(
            target_coordinates
                .iter()
                .map(|target| (target.patch_x, target.patch_y))
                .collect::<HashSet<_>>()
                .len(),
            RELEASE_GATE_FIXTURE_COUNT,
            "the authored max Fire target set must contain 200 distinct patch pixels"
        );
        let palette = [
            test_color(0, 0, 0),
            test_color(u16::MAX, 0, 0),
            test_color(u16::MAX, 32_768, 0),
            test_color(u16::MAX, u16::MAX, u16::MAX),
        ];
        let created_at = Instant::now();
        let compile_started = Instant::now();
        for index in 0..FIRE_EFFECTS {
            let mut request = test_fire_request(
                true,
                0x2900_0000 ^ index as u32,
                FLAMES,
                WIDTH,
                HEIGHT,
                HOTSPOT,
                PERIOD_MS,
            );
            request.fixture_ids = fixture_ids.clone();
            request.stops = palette
                .iter()
                .enumerate()
                .map(|(stop, color)| protocol::ColorEffectStop {
                    position: stop as f32 / (PALETTE_STOPS - 1) as f32,
                    color: *color,
                })
                .collect();
            let pattern = request.spatial_pattern.as_mut().unwrap();
            pattern.beam_targets = beam_targets.clone();
            let placement = pattern.placement.as_mut().unwrap();
            placement.sx = RASTER_SIZE;
            placement.sy = RASTER_SIZE;
            placement.horizontal_symmetry = TRANSFORM == 2;
            placement.raster_rotation_degrees = ROTATION;
            placement.target_coordinates = target_coordinates.clone();
            validate_color_effect_request(&request).unwrap();
            runtime.effects.push(RuntimeEffect {
                id: index as EffectId + 1,
                kind: RuntimeEffectKind::Color(
                    runtime
                        .resolve_color_effect_request(request)
                        .expect("maximum Fire request must compile"),
                ),
                enabled: true,
                created_at,
            });
        }
        let compile_elapsed = compile_started.elapsed();
        assert_eq!(runtime.effects.len(), FIRE_EFFECTS);
        assert_eq!(runtime.fixtures.len(), RELEASE_GATE_FIXTURE_COUNT);

        let before_storage = runtime
            .effects
            .iter()
            .map(|effect| {
                let RuntimeEffectKind::Color(color) = &effect.kind else {
                    unreachable!();
                };
                assert_eq!(color.request.fixture_ids.len(), RELEASE_GATE_FIXTURE_COUNT);
                assert_eq!(color.request.stops.len(), PALETTE_STOPS);
                let pattern = color.request.spatial_pattern.as_ref().unwrap();
                assert!(matches!(
                    pattern.recipe,
                    ColorEffectSpatialRecipe::Fire {
                        grayscale: true,
                        flames: FLAMES,
                        width: WIDTH,
                        height: HEIGHT,
                        hotspot: HOTSPOT,
                        ..
                    }
                ));
                let placement = pattern.placement.as_ref().unwrap();
                assert!(placement.horizontal_symmetry);
                assert_eq!(placement.raster_rotation_degrees, ROTATION);
                assert_eq!(
                    placement.target_coordinates.len(),
                    RELEASE_GATE_FIXTURE_COUNT
                );
                let spatial = color.spatial.as_ref().unwrap();
                assert_eq!(spatial.targets.len(), RELEASE_GATE_FIXTURE_COUNT);
                let compiled = spatial
                    .daslight_fire
                    .as_ref()
                    .expect("Fire must compile the corrected heat raster");
                assert_eq!(compiled.random_q15.len(), 5_000);
                assert_eq!(compiled.rendered_frame_count, SOURCE_FRAMES);
                assert_eq!(compiled.cache_state(), (None, 0));
                assert!(compiled.raster_cache.is_none());
                let frames = compiled.precomputed_frames.as_ref().unwrap();
                assert!((1..=RELEASE_GATE_FIXTURE_COUNT).contains(&frames.sampled_pixel_count));
                assert_eq!(
                    frames.heat.len(),
                    SOURCE_FRAMES * frames.sampled_pixel_count
                );
                compiled.storage_pointers()
            })
            .collect::<Vec<_>>();

        let visited_generations = (0..RELEASE_GATE_SAMPLES)
            .map(|sample| {
                let elapsed = DMX_TICK_INTERVAL * (sample as u32 + 1);
                ((elapsed.as_secs_f64() / (PERIOD_MS as f64 / 1_000.0)).rem_euclid(1.0)
                    * SOURCE_FRAMES as f64)
                    .floor() as usize
            })
            .collect::<HashSet<_>>();
        if cfg!(debug_assertions) {
            assert_eq!(visited_generations, (0..=11).collect::<HashSet<_>>());
        } else {
            assert_eq!(
                visited_generations,
                (0..SOURCE_FRAMES).collect::<HashSet<_>>(),
                "the release schedule must visit all 125 precomputed Fire generations"
            );
        }

        let (p95, p99, max) =
            measure_release_gate(created_at, |at| {
                runtime.fixtures.iter().fold(0_u64, |checksum, fixture| {
                    checksum.wrapping_add(runtime.apply_effects_with_transition_policy(
                        fixture, "ColorRed", 16_384, at, false,
                    ) as u64)
                })
            });
        let after_storage = runtime
            .effects
            .iter()
            .map(|effect| {
                let RuntimeEffectKind::Color(color) = &effect.kind else {
                    unreachable!();
                };
                let compiled = color
                    .spatial
                    .as_ref()
                    .unwrap()
                    .daslight_fire
                    .as_ref()
                    .unwrap();
                assert_eq!(compiled.cache_state(), (None, 0));
                compiled.storage_pointers()
            })
            .collect::<Vec<_>>();
        assert_eq!(
            after_storage, before_storage,
            "Fire's supported 44 Hz path must retain q15, LUT, and frame backing storage"
        );
        eprintln!(
            "Fire64 x200 (4 stops, 100x100, max Flames=100 Width=200 Height=100 Hotspot=255, period=5000/F125, Grayscale=1 Transform=2 Rotation=360, runtime rebuilds=0): compile={}ms p95={}us p99={}us max={}us",
            compile_elapsed.as_millis(),
            p95.as_micros(),
            p99.as_micros(),
            max.as_micros(),
        );
        assert_release_gate_percentiles(p95, p99, max);
    }

    #[test]
    fn max_bounce_release_stack_meets_44hz_budget() {
        const BOUNCE_EFFECTS: usize = 64;
        const SHAPE_EFFECTS: usize = 32;
        const POINT_EFFECTS: usize = 32;
        const PALETTE_STOPS: usize = 255;
        const PERIOD_MS: u64 = 30_000;
        const SOURCE_FRAMES: usize = 750;
        const NUMBER: u16 = 20;
        const SIZE: u16 = 100;
        const SPEED: u16 = 10;
        const POINTS: u16 = 10;
        const ROTATION: f32 = 360.0;

        assert_eq!(BOUNCE_EFFECTS, RELEASE_GATE_EFFECT_COUNT);
        assert_eq!(SHAPE_EFFECTS + POINT_EFFECTS, BOUNCE_EFFECTS);
        assert_eq!(RELEASE_GATE_FIXTURE_COUNT, 200);
        assert_eq!(RELEASE_GATE_HZ, 44);
        assert_eq!(PERIOD_MS / 40, SOURCE_FRAMES as u64);
        assert_eq!(
            RELEASE_GATE_SAMPLES,
            if cfg!(debug_assertions) { 20 } else { 1_000 }
        );
        assert_eq!(RELEASE_GATE_P95_LIMIT, Duration::from_millis(5));
        assert_eq!(RELEASE_GATE_P99_LIMIT, Duration::from_millis(8));
        assert_eq!(RELEASE_GATE_MAX_LIMIT, Duration::from_millis(12));

        let mut runtime = runtime_with_mixed_effect_fixtures(RELEASE_GATE_FIXTURE_COUNT as u64);
        let fixture_ids = (1..=RELEASE_GATE_FIXTURE_COUNT as u64).collect::<Vec<_>>();
        let beam_targets = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(selection_index, fixture_id)| protocol::ColorEffectBeamTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    selection_index: selection_index as u32,
                    feature_attribute: None,
                },
            )
            .collect::<Vec<_>>();
        let target_coordinates = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(index, fixture_id)| protocol::ColorEffectSpatialPlacementTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    patch_x: 25 + (index % 50) as i64,
                    patch_y: 25 + (index / 50) as i64,
                },
            )
            .collect::<Vec<_>>();
        assert_eq!(
            target_coordinates
                .iter()
                .map(|target| (target.patch_x, target.patch_y))
                .collect::<HashSet<_>>()
                .len(),
            RELEASE_GATE_FIXTURE_COUNT,
            "Bounce release gate must author 200 distinct target pixels"
        );
        let palette = (0..PALETTE_STOPS)
            .map(|index| protocol::ColorEffectStop {
                position: index as f32 / (PALETTE_STOPS - 1) as f32,
                color: test_color(
                    (index as u16).wrapping_mul(257),
                    (PALETTE_STOPS as u16 - 1 - index as u16).wrapping_mul(257),
                    (index as u16).wrapping_mul(997),
                ),
            })
            .collect::<Vec<_>>();
        let created_at = Instant::now();
        let compile_started = Instant::now();
        for index in 0..BOUNCE_EFFECTS {
            let item = if index < SHAPE_EFFECTS {
                ColorEffectSpatialBounceItem::Shape
            } else {
                ColorEffectSpatialBounceItem::Points
            };
            let fill = item == ColorEffectSpatialBounceItem::Points
                && index >= SHAPE_EFFECTS + POINT_EFFECTS / 2;
            let mut request = test_bounce_request(
                item,
                fill,
                item == ColorEffectSpatialBounceItem::Shape,
                PERIOD_MS,
            );
            request.fixture_ids = fixture_ids.clone();
            request.stops = palette.clone();
            request.phase = index as f32 / BOUNCE_EFFECTS as f32;
            let pattern = request.spatial_pattern.as_mut().unwrap();
            pattern.beam_targets = beam_targets.clone();
            let ColorEffectSpatialRecipe::Bounce {
                grayscale,
                rng_seed,
                shape,
                number,
                size,
                speed,
                collide,
                points,
                ..
            } = &mut pattern.recipe
            else {
                unreachable!();
            };
            *grayscale = true;
            *rng_seed = 0x2100_0000 ^ index as u32;
            *shape = if item == ColorEffectSpatialBounceItem::Points {
                28
            } else {
                0
            };
            *number = NUMBER;
            *size = SIZE;
            *speed = SPEED;
            *collide = item == ColorEffectSpatialBounceItem::Shape;
            *points = POINTS;
            let placement = pattern.placement.as_mut().unwrap();
            placement.horizontal_symmetry = true;
            placement.raster_rotation_degrees = ROTATION;
            placement.target_coordinates = target_coordinates.clone();
            validate_color_effect_request(&request).unwrap();
            runtime.effects.push(RuntimeEffect {
                id: index as EffectId + 1,
                kind: RuntimeEffectKind::Color(
                    runtime
                        .resolve_color_effect_request(request)
                        .expect("maximum Bounce request must compile"),
                ),
                enabled: true,
                created_at,
            });
        }
        let compile_elapsed = compile_started.elapsed();
        assert_eq!(runtime.effects.len(), BOUNCE_EFFECTS);
        assert_eq!(runtime.fixtures.len(), RELEASE_GATE_FIXTURE_COUNT);

        let before_storage = runtime
            .effects
            .iter()
            .enumerate()
            .map(|(index, effect)| {
                let RuntimeEffectKind::Color(color) = &effect.kind else {
                    unreachable!();
                };
                assert_eq!(color.request.fixture_ids.len(), RELEASE_GATE_FIXTURE_COUNT);
                assert_eq!(color.request.stops.len(), PALETTE_STOPS);
                let pattern = color.request.spatial_pattern.as_ref().unwrap();
                let ColorEffectSpatialRecipe::Bounce {
                    grayscale: true,
                    item,
                    shape,
                    number: NUMBER,
                    size: SIZE,
                    speed: SPEED,
                    collide,
                    fill,
                    points: POINTS,
                    ..
                } = pattern.recipe
                else {
                    panic!("release effect {index} must retain maximum Bounce literals");
                };
                if index < SHAPE_EFFECTS {
                    assert_eq!(item, ColorEffectSpatialBounceItem::Shape);
                    assert_eq!(shape, 0);
                    assert!(collide);
                    assert!(!fill);
                } else {
                    assert_eq!(item, ColorEffectSpatialBounceItem::Points);
                    assert_eq!(shape, 28, "Points inactive Shape maximum must remain legal");
                    assert!(!collide);
                    assert_eq!(fill, index >= SHAPE_EFFECTS + POINT_EFFECTS / 2);
                }
                let placement = pattern.placement.as_ref().unwrap();
                assert!(placement.horizontal_symmetry);
                assert_eq!(placement.raster_rotation_degrees, ROTATION);
                assert_eq!(
                    placement.target_coordinates.len(),
                    RELEASE_GATE_FIXTURE_COUNT
                );
                let spatial = color.spatial.as_ref().unwrap();
                assert_eq!(spatial.targets.len(), RELEASE_GATE_FIXTURE_COUNT);
                let compiled = spatial.daslight_bounce.as_ref().unwrap();
                assert_eq!(compiled.rendered_frame_count, SOURCE_FRAMES);
                assert_eq!(compiled.cache_state(), (None, 0));
                assert!(compiled.raster_cache.is_none());
                let frames = compiled.precomputed_frames.as_ref().unwrap();
                assert!((1..=RELEASE_GATE_FIXTURE_COUNT).contains(&frames.sampled_pixel_count));
                assert_eq!(frames.red.len(), SOURCE_FRAMES * frames.sampled_pixel_count);
                assert_eq!(frames.green.len(), frames.red.len());
                assert_eq!(frames.blue.len(), frames.red.len());
                compiled.storage_pointers()
            })
            .collect::<Vec<_>>();

        let visited_generations = runtime
            .effects
            .iter()
            .flat_map(|effect| {
                let RuntimeEffectKind::Color(color) = &effect.kind else {
                    unreachable!();
                };
                (0..RELEASE_GATE_SAMPLES).map(move |sample| {
                    let elapsed = DMX_TICK_INTERVAL * (sample as u32 + 1);
                    ((elapsed.as_secs_f64() / (PERIOD_MS as f64 / 1_000.0)
                        + f64::from(color.request.phase))
                    .rem_euclid(1.0)
                        * SOURCE_FRAMES as f64)
                        .floor() as usize
                })
            })
            .collect::<HashSet<_>>();
        assert!(visited_generations.contains(&0));
        assert!(visited_generations
            .iter()
            .any(|generation| *generation >= 700));
        if !cfg!(debug_assertions) {
            assert_eq!(visited_generations.len(), SOURCE_FRAMES);
        }

        let (p95, p99, max) =
            measure_release_gate(created_at, |at| {
                runtime.fixtures.iter().fold(0_u64, |checksum, fixture| {
                    checksum.wrapping_add(runtime.apply_effects_with_transition_policy(
                        fixture, "ColorRed", 16_384, at, false,
                    ) as u64)
                })
            });
        let after_storage = runtime
            .effects
            .iter()
            .map(|effect| {
                let RuntimeEffectKind::Color(color) = &effect.kind else {
                    unreachable!();
                };
                let compiled = color
                    .spatial
                    .as_ref()
                    .unwrap()
                    .daslight_bounce
                    .as_ref()
                    .unwrap();
                assert_eq!(compiled.cache_state(), (None, 0));
                compiled.storage_pointers()
            })
            .collect::<Vec<_>>();
        assert_eq!(after_storage, before_storage);
        eprintln!(
            "Bounce32ShapeCollide+32PointsFillSplit x200 (255 stops, 100x100, Number20 Size100 Speed10 Points10, period30000/F750, Grayscale1 Transform2 Rotation360, runtime rebuilds=0): compile={}ms generations={} p95={}us p99={}us max={}us",
            compile_elapsed.as_millis(),
            visited_generations.len(),
            p95.as_micros(),
            p99.as_micros(),
            max.as_micros(),
        );
        assert_release_gate_percentiles(p95, p99, max);
    }

    #[test]
    fn deep_explosion_starfield_release_stack_meets_44hz_budget() {
        const EXPLOSION_EFFECTS: usize = 32;
        const MAX_PALETTE_STOPS: usize = 255;
        const RASTER_SIZE: i64 = 100;
        const CAPTURED_PERIOD_MS: u64 = 5_000;
        const SOURCE_FRAMES: usize = 125;
        const FIRST_DEEP_GENERATION: usize = 93;

        assert_eq!(RELEASE_GATE_EFFECT_COUNT, 64);
        assert_eq!(RELEASE_GATE_FIXTURE_COUNT, 200);
        assert_eq!(RELEASE_GATE_HZ, 44);
        assert_eq!(RELEASE_GATE_P95_LIMIT, Duration::from_millis(5));
        assert_eq!(RELEASE_GATE_P99_LIMIT, Duration::from_millis(8));
        assert_eq!(RELEASE_GATE_MAX_LIMIT, Duration::from_millis(12));
        assert_eq!(FIRST_DEEP_GENERATION, 93);
        assert_eq!(FIRST_DEEP_GENERATION + EXPLOSION_EFFECTS - 1, 124);

        let mut runtime = runtime_with_mixed_effect_fixtures(RELEASE_GATE_FIXTURE_COUNT as u64);
        let fixture_ids = (1..=RELEASE_GATE_FIXTURE_COUNT as u64).collect::<Vec<_>>();
        let beam_targets = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(selection_index, fixture_id)| protocol::ColorEffectBeamTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    selection_index: selection_index as u32,
                    feature_attribute: None,
                },
            )
            .collect::<Vec<_>>();
        let target_coordinates = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(selection_index, fixture_id)| protocol::ColorEffectSpatialPlacementTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    patch_x: (selection_index % RASTER_SIZE as usize) as i64,
                    patch_y: if selection_index < RASTER_SIZE as usize {
                        0
                    } else {
                        RASTER_SIZE - 1
                    },
                },
            )
            .collect::<Vec<_>>();
        let palette = (0..MAX_PALETTE_STOPS)
            .map(|stop| protocol::ColorEffectStop {
                position: stop as f32 / (MAX_PALETTE_STOPS - 1) as f32,
                color: test_color(
                    stop as u16 * 257,
                    u16::MAX - stop as u16 * 257,
                    stop as u16 * 193,
                ),
            })
            .collect::<Vec<_>>();
        let created_at = Instant::now();
        let compile_started = Instant::now();
        for index in 0..RELEASE_GATE_EFFECT_COUNT {
            let local_index = index % EXPLOSION_EFFECTS;
            let recipe = if index < EXPLOSION_EFFECTS {
                ColorEffectSpatialRecipe::Explosion {
                    grayscale: true,
                    rng_seed: 0x47D0_0000 ^ index as u32,
                    shape: 0,
                    explosion_number: 50,
                    explosion_size: 100,
                    particle_number: 100,
                    particle_size: 100,
                    particle_life: 0.9,
                    trail_size: 25,
                    gravity: 10.0,
                }
            } else {
                ColorEffectSpatialRecipe::Starfield {
                    grayscale: true,
                    rng_seed: 0x48D0_0000 ^ index as u32,
                    shape: 0,
                    particles: 10,
                    size: 100,
                    trail: 25,
                    rotation: 5.0,
                }
            };
            let mut request = test_spatial_color_request(recipe);
            request.fixture_ids = fixture_ids.clone();
            request.stops = palette.clone();
            request.period_ms = CAPTURED_PERIOD_MS;
            request.phase = (FIRST_DEEP_GENERATION + local_index) as f32 / SOURCE_FRAMES as f32;
            let mut placement = test_patch_canvas_placement(0, 0, RASTER_SIZE, RASTER_SIZE, 0.0);
            placement.target_coordinates = target_coordinates.clone();
            let pattern = request.spatial_pattern.as_mut().unwrap();
            pattern.beam_targets = beam_targets.clone();
            pattern.placement = Some(placement);
            validate_color_effect_request(&request).unwrap();
            runtime.effects.push(RuntimeEffect {
                id: index as EffectId + 1,
                kind: RuntimeEffectKind::Color(
                    runtime
                        .resolve_color_effect_request(request)
                        .expect("deep maximum particle request must compile"),
                ),
                enabled: true,
                created_at,
            });
        }
        let compile_elapsed = compile_started.elapsed();

        let before_storage = runtime
            .effects
            .iter()
            .map(|effect| {
                let RuntimeEffectKind::Color(color) = &effect.kind else {
                    unreachable!();
                };
                assert_eq!(color.request.fixture_ids.len(), RELEASE_GATE_FIXTURE_COUNT);
                assert_eq!(color.request.stops.len(), MAX_PALETTE_STOPS);
                let spatial = color.spatial.as_ref().unwrap();
                assert_eq!(spatial.targets.len(), RELEASE_GATE_FIXTURE_COUNT);
                let compiled = spatial.daslight_particles.as_ref().unwrap();
                assert_eq!(compiled.source_frame_count, SOURCE_FRAMES);
                assert_eq!(compiled.rendered_frame_count, SOURCE_FRAMES);
                let frames = compiled
                    .precomputed_frames
                    .as_ref()
                    .expect("supported 200-target shape must precompute every generation");
                let mut expected_rows = [0_u128; DASLIGHT_PARTICLE_RASTER_SIZE];
                for target in &spatial.targets {
                    let pixel_x = CompiledDaslightParticles::raster_pixel(target.x);
                    let pixel_y = CompiledDaslightParticles::raster_pixel(target.z);
                    expected_rows[pixel_y] |= 1_u128 << pixel_x;
                }
                assert_eq!(
                    compiled
                        .sampled_rows
                        .iter()
                        .map(|row| row.x_mask)
                        .collect::<Vec<_>>(),
                    expected_rows
                );
                let unique_sampled_pixels = expected_rows
                    .iter()
                    .map(|row| row.count_ones() as usize)
                    .sum::<usize>();
                assert!((1..=RELEASE_GATE_FIXTURE_COUNT).contains(&unique_sampled_pixels));
                assert_eq!(frames.sampled_pixel_count, unique_sampled_pixels);
                assert_eq!(frames.red.len(), SOURCE_FRAMES * unique_sampled_pixels);
                compiled.storage_pointers()
            })
            .collect::<Vec<_>>();

        let expected_rebuilds_and_deep_hits = runtime
            .effects
            .iter()
            .map(|effect| {
                let RuntimeEffectKind::Color(color) = &effect.kind else {
                    unreachable!();
                };
                let mut rebuilds = 0_u64;
                let mut deep_hits = 0_u64;
                let mut previous = None;
                for sample in 0..RELEASE_GATE_SAMPLES {
                    let elapsed = DMX_TICK_INTERVAL * (sample as u32 + 1);
                    let phase = (elapsed.as_secs_f64() / (CAPTURED_PERIOD_MS as f64 / 1_000.0)
                        + f64::from(color.request.phase))
                    .rem_euclid(1.0);
                    let generation = (phase * SOURCE_FRAMES as f64).floor() as usize;
                    deep_hits += u64::from(generation == SOURCE_FRAMES - 1);
                    if previous != Some(generation) {
                        rebuilds += 1;
                        previous = Some(generation);
                    }
                }
                (rebuilds, deep_hits)
            })
            .collect::<Vec<_>>();
        if cfg!(debug_assertions) {
            assert!(
                expected_rebuilds_and_deep_hits
                    .iter()
                    .map(|(_, deep_hits)| *deep_hits)
                    .sum::<u64>()
                    > 0,
                "the reduced 20-sample debug gate must still reach generation 124"
            );
        } else {
            assert!(
                expected_rebuilds_and_deep_hits
                    .iter()
                    .all(|(_, deep_hits)| *deep_hits > 0),
                "the 1000-sample release gate must reach generation 124 for every effect"
            );
        }

        let (p95, p99, max) =
            measure_release_gate(created_at, |at| {
                runtime.fixtures.iter().fold(0_u64, |checksum, fixture| {
                    checksum.wrapping_add(runtime.apply_effects_with_transition_policy(
                        fixture, "ColorRed", 16_384, at, false,
                    ) as u64)
                })
            });
        let after_storage = runtime
            .effects
            .iter()
            .zip(&expected_rebuilds_and_deep_hits)
            .map(|(effect, (expected_rebuilds, _))| {
                let RuntimeEffectKind::Color(color) = &effect.kind else {
                    unreachable!();
                };
                let compiled = color
                    .spatial
                    .as_ref()
                    .unwrap()
                    .daslight_particles
                    .as_ref()
                    .unwrap();
                assert!(*expected_rebuilds > 0);
                assert_eq!(
                    compiled.cache_state(),
                    (None, 0),
                    "precomputed supported-target frames never rebuild on the 44 Hz path"
                );
                compiled.storage_pointers()
            })
            .collect::<Vec<_>>();
        assert_eq!(after_storage, before_storage);
        eprintln!(
            "Deep Explosion32+Starfield32 x200 (255 stops, 100x100, max recipe literals, captured period 5000/F125, staggered gen93..124 incl Trail25, runtime rebuilds=0): compile={}ms p95={}us p99={}us max={}us deep_gen124_hits={}",
            compile_elapsed.as_millis(),
            p95.as_micros(),
            p99.as_micros(),
            max.as_micros(),
            expected_rebuilds_and_deep_hits
                .iter()
                .map(|(_, hits)| *hits)
                .sum::<u64>()
        );
        assert_release_gate_percentiles(p95, p99, max);
    }

    #[test]
    fn color_mappings_grid_constants_anchors_overlap_background_and_continuity() {
        for (size, expected_spacing, expected_layers) in
            [(1, 50, 1), (2, 25, 2), (3, 16, 3), (4, 12, 4), (5, 10, 5)]
        {
            let request = test_grid_lines_request(
                ColorEffectSpatialRecipe::Grid {
                    grayscale: false,
                    size,
                    width: 2,
                },
                &[1_000, 2_000, 3_000, 4_000, 5_000],
            );
            let Some(CompiledDaslightGridLines::Grid {
                spacing,
                layer_count,
                ..
            }) = CompiledDaslightGridLines::compile(&request).unwrap()
            else {
                panic!("Grid must compile its dedicated raster state");
            };
            assert_eq!((spacing, layer_count), (expected_spacing, expected_layers));
        }

        let request = test_grid_lines_request(
            ColorEffectSpatialRecipe::Grid {
                grayscale: false,
                size: 3,
                width: 2,
            },
            &[1_000, 2_000, 3_000, 4_000],
        );
        let compiled = CompiledDaslightGridLines::compile(&request)
            .unwrap()
            .unwrap();
        assert_eq!(compiled.sample_at_phase(0.0, 0.0, 0.50).red, 2_000);
        assert_eq!(compiled.sample_at_phase(0.0, 0.50, 0.50).red, 1_000);
        assert_eq!(compiled.sample_at_phase(0.0, 0.0, 0.15).red, 3_000);
        assert_eq!(compiled.sample_at_phase(0.0, 1.0, 0.50).red, 2_000);
        assert_eq!(
            compiled.sample_at_phase(0.100_0, 0.33, 0.67),
            compiled.sample_at_phase(0.100_1, 0.33, 0.67),
            "continuous close phases must not jump unless a moving half-open edge crosses the pixel"
        );
    }

