    fn compiled_sparkle_state(
        compiled: &CompiledSyndocalRandomFx,
    ) -> &RefCell<SyndocalSparkleState> {
        let CompiledSyndocalRandomFx::Sparkle { state, .. } = compiled else {
            panic!("expected compiled corrected Sparkle state");
        };
        state
    }

    fn activation_sparkle_fx(
        runtime: &EngineRuntime,
        activation_index: usize,
    ) -> &CompiledSyndocalRandomFx {
        let RuntimeEffectKind::Color(color) =
            &runtime.effect_activations[activation_index].effect.kind
        else {
            panic!("expected a Color activation");
        };
        color
            .spatial
            .as_deref()
            .and_then(|spatial| spatial.syndocal_random_fx.as_ref())
            .expect("expected compiled corrected Sparkle state")
    }

    fn test_color_control(attribute: &str, offset: u16) -> AttributeControl {
        AttributeControl {
            attribute: attribute.to_string(),
            channel_name: attribute.to_string(),
            geometry: None,
            offsets: vec![offset],
            resolution: AttributeResolution::EightBit,
            default_value: 0,
            functions: Vec::new(),
        }
    }

    fn test_emitter_control(
        attribute: &str,
        offset: u16,
        name: &str,
        color: Option<[f32; 3]>,
    ) -> AttributeControl {
        let mut control = test_color_control(attribute, offset);
        control.functions = vec![protocol::ChannelFunctionSummary {
            name: attribute.to_string(),
            attribute: attribute.to_string(),
            parent_function: None,
            dmx_from: 0,
            dmx_to: u16::MAX,
            physical_from: None,
            physical_to: None,
            wheel_slot: None,
            wheel_slot_name: None,
            wheel_slot_color: None,
            wheel_slot_media: None,
            emitter: Some(protocol::EmitterCalibrationSummary {
                name: name.to_string(),
                color: color.map(|color| protocol::CieColorSummary {
                    x: color[0],
                    y: color[1],
                    luminance: color[2],
                }),
                dominant_wavelength_nm: color.is_none().then_some(365.0),
            }),
        }];
        control
    }

    fn test_runtime_color_fixture(
        id: FixtureId,
        group_ids: Vec<String>,
        controls: Vec<AttributeControl>,
    ) -> RuntimeFixture {
        let color_binding = compile_runtime_color_binding(&controls);
        RuntimeFixture {
            id,
            request: PatchFixtureRequest {
                profile_path: format!("memory://color-{id}.gdtf"),
                mode_name: Some("Color".to_string()),
                label: format!("Color {id}"),
                universe: 0,
                address: 1,
                group_ids,
                position: Vec3::default(),
                rotation: Rotation3::default(),
            },
            profile: FixtureProfileSummary {
                source_path: format!("memory://color-{id}.gdtf"),
                manufacturer: "Syndocal".to_string(),
                name: "Color Test".to_string(),
                short_name: None,
                fixture_type_id: None,
                dmx_modes: vec![DmxModeSummary {
                    name: "Color".to_string(),
                    controls,
                }],
                geometries: Vec::new(),
                warnings: Vec::new(),
            },
            mode_index: 0,
            limits: FixtureLimits::default(),
            color_binding,
        }
    }

    fn evaluate_test_binding(
        controls: Vec<AttributeControl>,
        color: ColorEffectColor,
        attribute: &str,
        base: u16,
        blend_mode: EffectBlendMode,
    ) -> u16 {
        let binding = compile_runtime_color_binding(&controls).expect("color binding");
        let mut request = test_color_request(vec![1], color);
        request.blend_mode = blend_mode;
        let runtime = RuntimeColorEffect {
            request,
            targets: vec![RuntimeColorTarget {
                fixture_id: 1,
                phase_offset: 0.0,
                cached: Cell::new(None),
            }],
            target_indices: HashMap::from([(1, 0)]),
            spatial: None,
        };
        let now = Instant::now();
        evaluate_runtime_color_attribute(
            &runtime,
            &binding,
            1,
            attribute,
            base,
            10,
            RuntimeColorEvaluationTiming {
                created_at: now,
                now,
                clock: &ClockSnapshot::default(),
            },
        )
        .unwrap_or(base)
    }

    #[test]
    fn color_effect_validation_enforces_stop_and_timing_invariants() {
        let valid = test_color_request(vec![1], test_color(u16::MAX, 0, 0));
        assert!(validate_runtime_color_effect_request(&valid).is_ok());

        let mut one_stop = valid.clone();
        one_stop.stops.truncate(1);
        assert!(validate_runtime_color_effect_request(&one_stop).is_ok());
        assert_eq!(
            evaluate_cycle_color(&one_stop, 0.73),
            one_stop.stops[0].color
        );

        let mut maximum = valid.clone();
        let maximum_last = u8::MAX - 1;
        maximum.stops = (0..=maximum_last)
            .map(|index| protocol::ColorEffectStop {
                position: f32::from(index) / f32::from(maximum_last),
                color: test_color(u16::from(index) * 257, 0, 0),
            })
            .collect();
        assert!(validate_runtime_color_effect_request(&maximum).is_ok());
        let exact_stop_position = maximum.stops[127].position;
        assert_eq!(
            evaluate_cycle_color(&maximum, exact_stop_position),
            maximum.stops[127].color
        );
        assert_eq!(
            evaluate_linear_stop_color(&maximum, exact_stop_position),
            maximum.stops[127].color
        );

        let mut oversized = maximum;
        let oversized_last = u16::from(u8::MAX) + 1;
        oversized.stops = (0..=oversized_last)
            .map(|index| protocol::ColorEffectStop {
                position: f32::from(index) / f32::from(oversized_last),
                color: test_color(index * 255, 0, 0),
            })
            .collect();
        assert!(validate_runtime_color_effect_request(&oversized)
            .unwrap_err()
            .contains("between 1 and 255"));

        let mut unordered = valid.clone();
        unordered.stops[1].position = 0.0;
        assert!(validate_runtime_color_effect_request(&unordered)
            .unwrap_err()
            .contains("strictly increasing"));

        let mut invalid_clock = valid.clone();
        invalid_clock.clock_sync = Some(protocol::EffectClockSync { beats: 0.0 });
        assert!(validate_runtime_color_effect_request(&invalid_clock).is_err());

        for fixture_spread in [-0.001, 1.001] {
            let mut invalid_spread = valid.clone();
            invalid_spread.fixture_spread = fixture_spread;
            assert!(validate_runtime_color_effect_request(&invalid_spread)
                .unwrap_err()
                .contains("within 0..1"));
        }
    }

    #[test]
    fn color_spatial_patch_canvas_rectangle_keeps_continuous_local_coordinates() {
        let id_521 = CompiledColorSpatialPlacement::compile(&test_patch_canvas_placement(
            2_630, -140, 140, 50, 0.0,
        ))
        .unwrap();
        for (patch_x, expected_normalized_x) in [
            (2_640, 10.0 / 140.0),
            (2_670, 40.0 / 140.0),
            (2_700, 70.0 / 140.0),
            (2_730, 100.0 / 140.0),
        ] {
            let sample = id_521.sample(patch_x, -130).unwrap();
            assert!((sample.normalized_x - expected_normalized_x).abs() < 1.0e-6);
            assert!((sample.normalized_y - 0.2).abs() < 1.0e-6);
        }

        let id_36 = CompiledColorSpatialPlacement::compile(&test_patch_canvas_placement(
            1_994, 166, 513, 52, 0.0,
        ))
        .unwrap();
        let first = id_36.sample(2_004, 176).unwrap();
        assert!((first.normalized_x - 10.0 / 513.0).abs() < 1.0e-6);
        assert!((first.normalized_y - 10.0 / 52.0).abs() < 1.0e-6);
        let second = id_36.sample(2_467, 178).unwrap();
        assert!((second.normalized_x - 473.0 / 513.0).abs() < 1.0e-6);
        assert!((second.normalized_y - 12.0 / 52.0).abs() < 1.0e-6);
    }

    #[test]
    fn color_spatial_patch_canvas_521_runtime_rebuild_uses_all_saved_cells() {
        let mut controls = Vec::new();
        let mut offset = 1_u16;
        for segment in 0..4 {
            let suffix = if segment == 0 {
                String::new()
            } else {
                format!(" {}", segment + 1)
            };
            for component in ["Red", "Green", "Blue"] {
                controls.push(test_color_control(
                    &format!("Color{component}{suffix}"),
                    offset,
                ));
                offset += 1;
            }
        }
        let fixtures = vec![test_runtime_color_fixture(1, Vec::new(), controls)];
        let mut request = test_spatial_color_request(ColorEffectSpatialRecipe::Rainbow {
            grayscale: false,
            vertical_symmetry: false,
            horizontal_symmetry: false,
            rotation_degrees: 0.0,
            color_width: 0.0,
            angle_degrees: 0.0,
            gradient: 100.0,
        });
        let pattern = request.spatial_pattern.as_mut().unwrap();
        pattern.beam_targets = (0_u16..4)
            .map(|beam_index| protocol::ColorEffectBeamTarget {
                fixture_id: 1,
                beam_index,
                selection_index: u32::from(beam_index),
                feature_attribute: Some("Dimmer".to_string()),
            })
            .collect();
        let mut placement = test_patch_canvas_placement(2_630, -140, 140, 50, 0.0);
        placement.target_coordinates = [2_640, 2_670, 2_700, 2_730]
            .into_iter()
            .enumerate()
            .map(
                |(beam_index, patch_x)| protocol::ColorEffectSpatialPlacementTarget {
                    fixture_id: 1,
                    beam_index: beam_index as u16,
                    patch_x,
                    patch_y: -130,
                },
            )
            .collect();
        pattern.placement = Some(placement);

        let runtime = runtime_color_effect_from_request(request, &fixtures).unwrap();
        let targets = &runtime.spatial.as_ref().unwrap().targets;
        assert_eq!(targets.len(), 4);
        for (target, expected_x) in targets.iter().zip([10.0, 40.0, 70.0, 100.0]) {
            assert!((target.x - expected_x / 140.0).abs() < 1.0e-6);
            assert!((target.z - 0.2).abs() < 1.0e-6);
        }
        assert_eq!(
            targets
                .iter()
                .map(|target| {
                    ((target.rainbow_projected_coordinate.unwrap() + 0.5) * 100.0).round()
                        as i32
                })
                .collect::<Vec<_>>(),
            vec![7, 29, 50, 71],
            "runtime Rainbow projection must use continuous Patch-local coordinates, not stage normalization or integer cells"
        );
    }

