    #[test]
    fn corrected_random_fill_compiles_seeded_no_replacement_continuous_cells() {
        let request_for_seed = |rng_seed| {
            let mut request = test_spatial_color_request(ColorEffectSpatialRecipe::RandomFill {
                grayscale: false,
                vertical_symmetry: false,
                rng_seed,
                point_width: 200.0 / 11.0,
                source_point_height: Some(7),
            });
            request.stops[0].color = test_color(u16::MAX, 0, 0);
            request.stops[1].color = test_color(0, 0, u16::MAX);
            request
        };
        let request = request_for_seed(0x1234_5678);
        validate_color_effect_request(&request).unwrap();
        let compiled = CompiledSyndocalRandomFx::compile(&request, 11)
            .unwrap()
            .unwrap();
        let CompiledSyndocalRandomFx::RandomFill {
            cell_count,
            rank_order,
            ..
        } = &compiled
        else {
            panic!("corrected Random fill must compile its rank table");
        };
        let SyndocalRandomFillRankOrder::DenseOneDimensional(ranks) = rank_order else {
            panic!("unplaced Random Fill must preserve its dense 1D rank table");
        };
        assert_eq!(*cell_count, 6, "div_ceil must retain the one-cell tail");
        for transition in ranks.chunks_exact(*cell_count) {
            let mut sorted = transition.to_vec();
            sorted.sort_unstable();
            assert_eq!(sorted, (0..*cell_count as u32).collect::<Vec<_>>());
        }
        assert_eq!(
            ranks.as_ref(),
            &[0, 2, 5, 1, 4, 3, 0, 3, 4, 1, 5, 2],
            "the existing one-dimensional stable order is a compatibility golden"
        );
        let repeated = CompiledSyndocalRandomFx::compile(&request_for_seed(0x1234_5678), 11)
            .unwrap()
            .unwrap();
        let changed = CompiledSyndocalRandomFx::compile(&request_for_seed(0x8765_4321), 11)
            .unwrap()
            .unwrap();
        let ranks_of = |compiled: &CompiledSyndocalRandomFx| match compiled {
            CompiledSyndocalRandomFx::RandomFill {
                rank_order: SyndocalRandomFillRankOrder::DenseOneDimensional(ranks),
                ..
            } => ranks.to_vec(),
            _ => unreachable!(),
        };
        assert_eq!(ranks_of(&compiled), ranks_of(&repeated));
        assert_ne!(ranks_of(&compiled), ranks_of(&changed));

        let mut without_provenance_height = request.clone();
        let ColorEffectSpatialRecipe::RandomFill {
            source_point_height,
            ..
        } = &mut without_provenance_height
            .spatial_pattern
            .as_mut()
            .unwrap()
            .recipe
        else {
            unreachable!();
        };
        *source_point_height = None;
        let without_provenance_height =
            CompiledSyndocalRandomFx::compile(&without_provenance_height, 11)
                .unwrap()
                .unwrap();
        assert_eq!(
            ranks_of(&compiled),
            ranks_of(&without_provenance_height),
            "unplaced source PointHeight must remain evaluator-dead"
        );

        let cell = ranks[..*cell_count]
            .iter()
            .position(|rank| *rank == 2)
            .unwrap();
        let phase_for_amount = |amount: f64| (2.0 + amount) / *cell_count as f64 / 2.0;
        let at = Instant::now();
        let first = compiled.sample_at_time(phase_for_amount(0.25), cell * 2, 11, at, at);
        let second = compiled.sample_at_time(phase_for_amount(0.50), cell * 2, 11, at, at);
        assert_ne!(
            first, second,
            "cell transition must be continuous, not frame-stepped"
        );
        assert_ne!(
            compiled.sample_at_time(0.10, 10, 11, at, at),
            black_color(),
            "Random fill must transition palette-to-palette without a black reset"
        );
        for phase in [0.0, 0.1, 0.37, 0.9] {
            for index in 0..11 {
                assert_eq!(
                    compiled.sample_at_time(phase, index, 11, at, at),
                    without_provenance_height.sample_at_time(phase, index, 11, at, at),
                    "legacy one-dimensional output changed at phase {phase}, index {index}"
                );
            }
        }
    }

    #[test]
    fn placed_random_fill_uses_one_stable_two_dimensional_cell_ranking() {
        assert_eq!(daslight_mapping_raster_pixel(0.0), 0);
        assert_eq!(daslight_mapping_raster_pixel(0.0099), 0);
        assert_eq!(daslight_mapping_raster_pixel(0.01), 1);
        assert_eq!(daslight_mapping_raster_pixel(0.99), 99);
        assert_eq!(daslight_mapping_raster_pixel(1.0), 99);

        let request_for = |rng_seed, point_width, point_height| {
            let mut request = test_spatial_color_request(ColorEffectSpatialRecipe::RandomFill {
                grayscale: false,
                vertical_symmetry: false,
                rng_seed,
                point_width,
                source_point_height: Some(point_height),
            });
            request.spatial_pattern.as_mut().unwrap().placement =
                Some(test_patch_canvas_placement(0, 0, 100, 100, 0.0));
            request
        };
        for invalid_width in [0.5, 11.0] {
            assert!(
                validate_color_effect_request(&request_for(1, invalid_width, 1))
                    .unwrap_err()
                    .contains("integer within 1..10")
            );
        }
        let mut legacy_unplaced = request_for(1, 0.5, 7);
        legacy_unplaced.spatial_pattern.as_mut().unwrap().placement = None;
        validate_color_effect_request(&legacy_unplaced)
            .expect("unplaced legacy width and provenance height must keep their prior domain");
        let request = request_for(0x372D, 10.0, 10);
        let compiled = CompiledSyndocalRandomFx::compile(&request, 100)
            .unwrap()
            .unwrap();
        let CompiledSyndocalRandomFx::RandomFill {
            point_width,
            point_height,
            cell_columns,
            cell_count,
            rank_order,
            ..
        } = &compiled
        else {
            unreachable!();
        };
        assert_eq!(
            (*point_width, *point_height, *cell_columns, *cell_count),
            (10, Some(10), 10, 100)
        );
        let SyndocalRandomFillRankOrder::AffineTwoDimensional {
            base_ranks,
            permutations,
        } = rank_order
        else {
            panic!(
                "placed Random Fill must compile a scrambled base plus compact affine permutations"
            );
        };
        assert_eq!(base_ranks.len(), *cell_count);
        assert_eq!(permutations.len(), request.stops.len());
        let mut sorted_base = base_ranks.to_vec();
        sorted_base.sort_unstable();
        assert_eq!(sorted_base, (0..*cell_count as u32).collect::<Vec<_>>());
        assert_eq!(
            &base_ranks[..16],
            &[72, 12, 63, 22, 57, 9, 53, 2, 60, 1, 98, 44, 55, 87, 59, 24],
            "the splitmix base rank keeps a deterministic spatial-scramble golden"
        );
        for permutation in permutations.iter().copied() {
            assert_eq!(
                greatest_common_divisor_u32(permutation.multiplier, *cell_count as u32),
                1,
                "the affine multiplier must be coprime to the cell count"
            );
            let mut sorted = (0..*cell_count)
                .map(|cell| permutation.rank(base_ranks[cell] as usize, *cell_count))
                .collect::<Vec<_>>();
            sorted.sort_unstable();
            assert_eq!(sorted, (0..*cell_count).collect::<Vec<_>>());
        }
        let repeated = CompiledSyndocalRandomFx::compile(&request_for(0x372D, 10.0, 10), 100)
            .unwrap()
            .unwrap();
        let changed = CompiledSyndocalRandomFx::compile(&request_for(0x372E, 10.0, 10), 100)
            .unwrap()
            .unwrap();
        let compact_order_of = |compiled: &CompiledSyndocalRandomFx| match compiled {
            CompiledSyndocalRandomFx::RandomFill {
                rank_order:
                    SyndocalRandomFillRankOrder::AffineTwoDimensional {
                        base_ranks,
                        permutations,
                    },
                ..
            } => (base_ranks.to_vec(), permutations.to_vec()),
            _ => unreachable!(),
        };
        assert_eq!(compact_order_of(&compiled), compact_order_of(&repeated));
        assert_ne!(compact_order_of(&compiled), compact_order_of(&changed));

        let at = Instant::now();
        let separating_phase = |first_cell: usize, second_cell: usize| {
            (rank_order
                .rank(0, first_cell, *cell_count)
                .min(rank_order.rank(0, second_cell, *cell_count)) as f64
                + 0.5)
                / *cell_count as f64
                / 2.0
        };
        assert_ne!(
            compiled.sample_at_mapping_time(separating_phase(0, 1), 0, 100, 0.0, 0.0, (at, at)),
            compiled.sample_at_mapping_time(separating_phase(0, 1), 0, 100, 0.1, 0.0, (at, at)),
            "changing X must select a different flat cell rank"
        );
        assert_ne!(
            compiled.sample_at_mapping_time(separating_phase(0, 10), 0, 100, 0.0, 0.0, (at, at)),
            compiled.sample_at_mapping_time(separating_phase(0, 10), 0, 100, 0.0, 0.1, (at, at)),
            "changing Y must select a different flat cell rank"
        );

        let partial = CompiledSyndocalRandomFx::compile(&request_for(0x372D, 6.0, 6), 100)
            .unwrap()
            .unwrap();
        let CompiledSyndocalRandomFx::RandomFill {
            cell_columns,
            cell_count,
            rank_order,
            ..
        } = &partial
        else {
            unreachable!();
        };
        assert_eq!((*cell_columns, *cell_count), (17, 17 * 17));
        let tail_cell = 16 * *cell_columns + 16;
        let tail_phase =
            (rank_order.rank(0, tail_cell, *cell_count) as f64 + 0.5) / *cell_count as f64 / 2.0;
        assert_ne!(
            partial.sample_at_mapping_time(tail_phase, 0, 100, 1.0, 1.0, (at, at)),
            black_color(),
            "the partial right/bottom cell covering source pixel 99 must be sampled"
        );

        let mut maximum = request_for(0x37FF, 1.0, 1);
        maximum.stops = (0..255)
            .map(|stop| protocol::ColorEffectStop {
                position: stop as f32 / 254.0,
                color: test_color(stop as u16 * 257, 0, u16::MAX - stop as u16 * 257),
            })
            .collect();
        let maximum = CompiledSyndocalRandomFx::compile(&maximum, 100)
            .unwrap()
            .unwrap();
        let CompiledSyndocalRandomFx::RandomFill {
            cell_count,
            rank_order:
                SyndocalRandomFillRankOrder::AffineTwoDimensional {
                    base_ranks,
                    permutations,
                },
            ..
        } = &maximum
        else {
            panic!("maximum placed Random Fill must remain compact");
        };
        assert_eq!(*cell_count, 10_000);
        assert_eq!(base_ranks.len(), 10_000);
        assert_eq!(permutations.len(), 255);
        assert_eq!(
            base_ranks.len() * std::mem::size_of::<u32>()
                + permutations.len() * std::mem::size_of::<SyndocalRandomFillAffinePermutation>(),
            42_040
        );
        assert!(42_040 < base_ranks.len() * permutations.len() * std::mem::size_of::<u32>());
        let mut seen = vec![false; *cell_count];
        for permutation in permutations.iter().copied() {
            assert_eq!(
                greatest_common_divisor_u32(permutation.multiplier, *cell_count as u32),
                1
            );
            seen.fill(false);
            for cell in 0..*cell_count {
                let rank = permutation.rank(base_ranks[cell] as usize, *cell_count);
                assert!(!seen[rank], "compact transition repeated rank {rank}");
                seen[rank] = true;
            }
            assert!(seen.iter().all(|rank| *rank));
        }
    }

    #[test]
    fn placed_random_fill_consumes_placement_transform_rotation_and_qgray() {
        let request_for = |grayscale| {
            let mut request = test_spatial_color_request(ColorEffectSpatialRecipe::RandomFill {
                grayscale,
                vertical_symmetry: false,
                rng_seed: 0x372D,
                point_width: 10.0,
                source_point_height: Some(10),
            });
            request.stops[0].color = test_color(u16::MAX, 0, 0);
            request.stops[1].color = test_color(0, 0, u16::MAX);
            request.spatial_pattern.as_mut().unwrap().placement =
                Some(test_patch_canvas_placement(0, 0, 100, 100, 0.0));
            request
        };
        let request = request_for(false);
        let compiled = CompiledSyndocalRandomFx::compile(&request, 100)
            .unwrap()
            .unwrap();
        let CompiledSyndocalRandomFx::RandomFill {
            cell_columns,
            cell_count,
            rank_order,
            ..
        } = &compiled
        else {
            unreachable!();
        };
        let cell_for = |sample: CompiledColorSpatialPlacementSample| {
            let (x, y) = sample.normalized();
            (daslight_mapping_raster_pixel(y) / 10) * *cell_columns
                + daslight_mapping_raster_pixel(x) / 10
        };
        let mut placement = test_patch_canvas_placement(0, 0, 100, 100, 0.0);
        let plain = CompiledColorSpatialPlacement::compile(&placement)
            .unwrap()
            .sample(25, 50)
            .unwrap();
        let rotation_plain = CompiledColorSpatialPlacement::compile(&placement)
            .unwrap()
            .sample(75, 50)
            .unwrap();
        placement.vertical_symmetry = true;
        let transformed = CompiledColorSpatialPlacement::compile(&placement)
            .unwrap()
            .sample(25, 50)
            .unwrap();
        placement.vertical_symmetry = false;
        placement.raster_rotation_degrees = 90.0;
        let rotated = CompiledColorSpatialPlacement::compile(&placement)
            .unwrap()
            .sample(75, 50)
            .unwrap();
        assert_ne!(cell_for(plain), cell_for(transformed));
        assert_ne!(cell_for(rotation_plain), cell_for(rotated));

        let at = Instant::now();
        let assert_samples_differ =
            |first: CompiledColorSpatialPlacementSample,
             second: CompiledColorSpatialPlacementSample| {
                let first_cell = cell_for(first);
                let second_cell = cell_for(second);
                let phase = (rank_order
                    .rank(0, first_cell, *cell_count)
                    .min(rank_order.rank(0, second_cell, *cell_count))
                    as f64
                    + 0.5)
                    / *cell_count as f64
                    / 2.0;
                let (first_x, first_y) = first.normalized();
                let (second_x, second_y) = second.normalized();
                assert_ne!(
                    compiled.sample_at_mapping_time(phase, 0, 100, first_x, first_y, (at, at)),
                    compiled.sample_at_mapping_time(phase, 0, 100, second_x, second_y, (at, at))
                );
            };
        assert_samples_differ(plain, transformed);
        assert_samples_differ(rotation_plain, rotated);

        let phase = 0.173;
        let (x, y) = transformed.normalized();
        let color = compiled.sample_at_mapping_time(phase, 0, 100, x, y, (at, at));
        let grayscale = CompiledSyndocalRandomFx::compile(&request_for(true), 100)
            .unwrap()
            .unwrap()
            .sample_at_mapping_time(phase, 0, 100, x, y, (at, at));
        assert_eq!(grayscale, daslight_grayscale_color(color));
    }

    #[test]
    fn corrected_sparkle_is_reload_stable_continuous_and_single_palette_safe() {
        let request_for = |rng_seed, lifetime_ms, width: f32| {
            let mut request = test_spatial_color_request(ColorEffectSpatialRecipe::Sparkle {
                grayscale: false,
                vertical_symmetry: false,
                raster_mode: ColorEffectSpatialSparkleRasterMode::Sparkle,
                rng_seed,
                number: 1,
                lifetime_ms: Some(lifetime_ms),
                source_lifespan: Some(0.0),
                width,
                height: None,
            });
            request.stops[0].color = black_color();
            request.stops[1].color = test_color(u16::MAX, u16::MAX, u16::MAX);
            request
        };
        let request = request_for(91, 100, 300.0 / 17.0);
        validate_color_effect_request(&request).unwrap();
        let compiled = CompiledSyndocalRandomFx::compile(&request, 17)
            .unwrap()
            .unwrap();
        let repeated = CompiledSyndocalRandomFx::compile(&request_for(91, 100, 300.0 / 17.0), 17)
            .unwrap()
            .unwrap();
        let changed = CompiledSyndocalRandomFx::compile(&request_for(92, 100, 300.0 / 17.0), 17)
            .unwrap()
            .unwrap();
        let at = Instant::now();
        let samples = |compiled: &CompiledSyndocalRandomFx| {
            (0..17)
                .map(|index| compiled.sample_at_time(0.013, index, 17, at, at))
                .collect::<Vec<_>>()
        };
        assert_eq!(samples(&compiled), samples(&repeated));
        assert_ne!(samples(&compiled), samples(&changed));
        let single = CompiledSyndocalRandomFx::compile(&request_for(91, 100, 100.0), 1)
            .unwrap()
            .unwrap();
        let single_at_spawn = single.sample_at_time(0.0, 0, 1, at, at);
        let single_one_ms_later =
            single.sample_at_time(0.001, 0, 1, at, at + Duration::from_millis(1));
        assert!(single_at_spawn.red > single_one_ms_later.red);
        assert!(single_one_ms_later.red > 0);

        let mut single_palette = request_for(91, 100, 100.0);
        single_palette.stops.truncate(1);
        single_palette.stops[0].color = test_color(12_345, 23_456, 34_567);
        let compiled = CompiledSyndocalRandomFx::compile(&single_palette, 1)
            .unwrap()
            .unwrap();
        assert_ne!(compiled.sample_at_time(0.001, 0, 1, at, at), black_color());
    }

    #[test]
    fn corrected_sparkle_cold_start_synthesizes_trailing_visual_epochs() {
        let request = test_corrected_sparkle_request(0x1234_5678, 10, 1_000, 1, false, false);
        let compiled = CompiledSyndocalRandomFx::compile(&request, 17)
            .unwrap()
            .unwrap();
        let created_at = Instant::now();
        let now = created_at + Duration::from_millis(7_000);
        for index in 0..17 {
            compiled.sample_at_time(5.0, index, 17, created_at, now);
        }

        let state = compiled_sparkle_state(&compiled).borrow();
        assert_eq!(state.max_particles, 260);
        assert_eq!(state.particles.len(), 250);
        assert_eq!(
            state.render_count, 1,
            "the complete strip is built once per update"
        );
        assert_eq!(state.particles.first().unwrap().generation_epoch, 101);
        assert_eq!(state.particles.last().unwrap().generation_epoch, 125);
        for (offset, generation) in state.particles.chunks_exact(10).enumerate() {
            let epoch = 101 + offset as u64;
            assert!(generation.iter().all(|particle| {
                particle.generation_epoch == epoch && particle.born_visual_ms == epoch as f64 * 40.0
            }));
            assert_eq!(
                generation
                    .iter()
                    .map(|particle| particle.particle_index)
                    .collect::<Vec<_>>(),
                (0..10).collect::<Vec<_>>()
            );
        }
    }

    #[test]
    fn corrected_sparkle_expires_on_100_and_1000_ms_visual_clock_boundaries() {
        let assert_boundary = |lifetime_ms: u16| {
            let request =
                test_corrected_sparkle_request(0xCAFE_BABE, 1, lifetime_ms, 1, false, false);
            let compiled = CompiledSyndocalRandomFx::compile(&request, 1)
                .unwrap()
                .unwrap();
            let created_at = Instant::now();
            compiled.sample_at_time(0.0, 0, 1, created_at, created_at);
            let before = u64::from(lifetime_ms - 1);
            compiled.sample_at_time(
                before as f64 / 1_000.0,
                0,
                1,
                created_at,
                created_at + Duration::from_millis(1),
            );
            {
                let state = compiled_sparkle_state(&compiled).borrow();
                assert!(state
                    .particles
                    .iter()
                    .any(|particle| particle.generation_epoch == 0));
                assert!(state.particles.iter().any(|particle| {
                    particle.generation_epoch == 1 && particle.born_visual_ms == 40.0
                }));
            }
            let boundary = u64::from(lifetime_ms);
            compiled.sample_at_time(
                boundary as f64 / 1_000.0,
                0,
                1,
                created_at,
                created_at + Duration::from_millis(2),
            );
            assert!(!compiled_sparkle_state(&compiled)
                .borrow()
                .particles
                .iter()
                .any(|particle| particle.generation_epoch == 0));
        };

        assert_boundary(100);
        assert_boundary(1_000);
    }

    #[test]
    fn corrected_sparkle_births_use_crossed_visual_epoch_boundaries() {
        let request = test_corrected_sparkle_request(31, 2, 1_000, 1, false, false);
        let compiled = CompiledSyndocalRandomFx::compile(&request, 1)
            .unwrap()
            .unwrap();
        let created_at = Instant::now();
        compiled.sample_at_time(0.0, 0, 1, created_at, created_at);
        let now = created_at + Duration::from_millis(100);
        compiled.sample_at_time(0.08, 0, 1, created_at, now);

        let state = compiled_sparkle_state(&compiled).borrow();
        for particle_index in 0..2 {
            assert!(state.particles.iter().any(|particle| {
                particle.generation_epoch == 1
                    && particle.particle_index == particle_index
                    && particle.born_visual_ms == 40.0
            }));
            assert!(state.particles.iter().any(|particle| {
                particle.generation_epoch == 2
                    && particle.particle_index == particle_index
                    && particle.born_visual_ms == 80.0
            }));
        }
    }

    #[test]
    fn corrected_sparkle_visual_lifetime_and_population_are_tempo_invariant() {
        let target = test_spatial_color_target(0, 1, 0.5, 0.5);
        let created_at = Instant::now();
        let evaluate = |request: &ColorEffectRequest,
                        compiled: &CompiledSyndocalRandomFx,
                        now: Instant,
                        clock: &ClockSnapshot| {
            evaluate_color_spatial_sample_at_rate(
                request,
                &target,
                None,
                None,
                None,
                Some(compiled),
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                97,
                created_at,
                now,
                clock,
                1.0,
            )
            .color
        };

        let mut double_speed_request =
            test_corrected_sparkle_request(0xA5A5_5A5A, 1, 100, 1, false, false);
        double_speed_request.clock_sync = Some(EffectClockSync { beats: 1.0 });
        let double_speed = CompiledSyndocalRandomFx::compile(&double_speed_request, 1)
            .unwrap()
            .unwrap();
        evaluate(
            &double_speed_request,
            &double_speed,
            created_at,
            &ClockSnapshot::default(),
        );
        evaluate(
            &double_speed_request,
            &double_speed,
            created_at + Duration::from_millis(49),
            &ClockSnapshot {
                bpm: 120.0,
                beat_phase: 0.098,
                ..ClockSnapshot::default()
            },
        );
        assert!(compiled_sparkle_state(&double_speed)
            .borrow()
            .particles
            .iter()
            .any(|particle| particle.generation_epoch == 0));
        evaluate(
            &double_speed_request,
            &double_speed,
            created_at + Duration::from_millis(50),
            &ClockSnapshot {
                bpm: 120.0,
                beat_phase: 0.1,
                ..ClockSnapshot::default()
            },
        );
        assert!(!compiled_sparkle_state(&double_speed)
            .borrow()
            .particles
            .iter()
            .any(|particle| particle.generation_epoch == 0));

        let free_request = test_corrected_sparkle_request(0xA5A5_5A5A, 10, 1_000, 1, false, false);
        let mut slow_request = free_request.clone();
        slow_request.clock_sync = Some(EffectClockSync { beats: 4.0 });
        let mut fast_request = free_request.clone();
        fast_request.clock_sync = Some(EffectClockSync { beats: 0.25 });
        let free = CompiledSyndocalRandomFx::compile(&free_request, 1)
            .unwrap()
            .unwrap();
        let slow = CompiledSyndocalRandomFx::compile(&slow_request, 1)
            .unwrap()
            .unwrap();
        let fast = CompiledSyndocalRandomFx::compile(&fast_request, 1)
            .unwrap()
            .unwrap();
        evaluate(
            &free_request,
            &free,
            created_at + Duration::from_secs(5),
            &ClockSnapshot::default(),
        );
        evaluate(
            &slow_request,
            &slow,
            created_at + Duration::from_secs(20),
            &ClockSnapshot {
                bpm: 60.0,
                beat_counter: 20,
                ..ClockSnapshot::default()
            },
        );
        evaluate(
            &fast_request,
            &fast,
            created_at + Duration::from_millis(313),
            &ClockSnapshot {
                bpm: 240.0,
                beat_counter: 1,
                beat_phase: 0.25,
                ..ClockSnapshot::default()
            },
        );
        let populations = [&free, &slow, &fast]
            .map(|compiled| compiled_sparkle_state(compiled).borrow().particles.len());
        assert_eq!(populations, [250; 3]);
    }

    #[test]
    fn corrected_sparkle_reverse_seek_and_wall_jump_reset_with_full_history() {
        let request = test_corrected_sparkle_request(77, 3, 500, 2, false, false);
        let compiled = CompiledSyndocalRandomFx::compile(&request, 9)
            .unwrap()
            .unwrap();
        let created_at = Instant::now();
        compiled.sample_at_time(0.0, 0, 9, created_at, created_at);
        compiled.sample_at_time(
            0.08,
            0,
            9,
            created_at,
            created_at + Duration::from_millis(80),
        );
        compiled.sample_at_time(
            0.04,
            0,
            9,
            created_at,
            created_at + Duration::from_millis(100),
        );
        {
            let state = compiled_sparkle_state(&compiled).borrow();
            assert_eq!(state.particles.len(), 6);
            assert!(state.particles.iter().all(|particle| {
                (particle.generation_epoch == 0 && particle.born_visual_ms == 0.0)
                    || (particle.generation_epoch == 1 && particle.born_visual_ms == 40.0)
            }));
            assert_eq!(state.reset_count, 2);
        }

        let seek_created_at = created_at + Duration::from_millis(20);
        compiled.sample_at_time(
            0.05,
            0,
            9,
            seek_created_at,
            created_at + Duration::from_millis(120),
        );
        {
            let state = compiled_sparkle_state(&compiled).borrow();
            assert_eq!(state.particles.len(), 6);
            assert_eq!(state.particles.first().unwrap().generation_epoch, 0);
            assert_eq!(state.particles.last().unwrap().generation_epoch, 1);
            assert_eq!(state.reset_count, 3);
        }

        let jumped_at = created_at + Duration::from_secs(2);
        let jumped = (0..9)
            .map(|index| compiled.sample_at_time(2.0, index, 9, seek_created_at, jumped_at))
            .collect::<Vec<_>>();
        let fresh = CompiledSyndocalRandomFx::compile(&request, 9)
            .unwrap()
            .unwrap();
        let fresh_at_jump = (0..9)
            .map(|index| fresh.sample_at_time(2.0, index, 9, seek_created_at, jumped_at))
            .collect::<Vec<_>>();
        assert_eq!(jumped, fresh_at_jump);
        let state = compiled_sparkle_state(&compiled).borrow();
        assert_eq!(state.particles.len(), 39);
        assert_eq!(state.particles.first().unwrap().generation_epoch, 38);
        assert_eq!(state.particles.last().unwrap().generation_epoch, 50);
        assert!(state.particles.iter().all(|particle| {
            particle.born_visual_ms
                == particle.generation_epoch as f64 * SYNDOCAL_SPARKLE_GENERATION_MS
        }));
        assert_eq!(state.reset_count, 4);
    }

    #[test]
    fn corrected_sparkle_fast_sync_saturates_without_capacity_wipes() {
        let mut request = test_corrected_sparkle_request(0xDEAD_BEEF, 10, 1_000, 90, false, false);
        request.clock_sync = Some(EffectClockSync { beats: 0.25 });
        let compiled = CompiledSyndocalRandomFx::compile(&request, 100)
            .unwrap()
            .unwrap();
        let target = test_spatial_color_target(0, 100, 0.0, 0.5);
        let created_at = Instant::now();
        let mut maximum_population = 0;
        let mut minimum_warm_population = usize::MAX;

        for tick in 0..=88_u64 {
            let wall_ms = tick * 23;
            let beat_position = wall_ms as f64 / 1_000.0 * 160.0 / 60.0;
            let beat_counter = beat_position.floor() as u64;
            let beat_phase = beat_position.fract() as f32;
            evaluate_color_spatial_sample_at_rate(
                &request,
                &target,
                None,
                None,
                None,
                Some(&compiled),
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                97,
                created_at,
                created_at + Duration::from_millis(wall_ms),
                &ClockSnapshot {
                    bpm: 160.0,
                    beat_counter,
                    beat_phase,
                    ..ClockSnapshot::default()
                },
                1.0,
            );
            let visual_ms = beat_position / 0.25 * 1_000.0;
            let state = compiled_sparkle_state(&compiled).borrow();
            maximum_population = maximum_population.max(state.particles.len());
            if visual_ms >= 1_000.0 {
                minimum_warm_population = minimum_warm_population.min(state.particles.len());
                assert!(
                    state.particles.len() > 10,
                    "the saturated field must never collapse to one Number-sized epoch"
                );
            }
            assert!(state.particles.len() <= state.max_particles);
            assert_eq!(state.reset_count, 1, "tick={tick} visual_ms={visual_ms}");
        }

        let state = compiled_sparkle_state(&compiled).borrow();
        assert_eq!(state.max_particles, 260);
        assert!(maximum_population <= 260);
        assert!(minimum_warm_population > 10);
    }

    #[test]
    fn corrected_sparkle_epoch_jump_threshold_resets_to_full_history() {
        let request = test_corrected_sparkle_request(0x1234_5678, 2, 1_000, 1, false, false);
        let compiled = CompiledSyndocalRandomFx::compile(&request, 5)
            .unwrap()
            .unwrap();
        let created_at = Instant::now();
        compiled.sample_at_time(1.0, 0, 5, created_at, created_at);
        let jumped_visual_ms = 1_000.0
            + SYNDOCAL_SPARKLE_EPOCH_JUMP_RESET_THRESHOLD as f64 * SYNDOCAL_SPARKLE_GENERATION_MS;
        compiled.sample_at_time(
            jumped_visual_ms / 1_000.0,
            0,
            5,
            created_at,
            created_at + Duration::from_millis(1),
        );

        let state = compiled_sparkle_state(&compiled).borrow();
        let current_epoch = SyndocalSparkleState::generation_epoch(jumped_visual_ms);
        assert_eq!(state.reset_count, 2);
        assert_eq!(state.particles.len(), 50);
        assert_eq!(
            state.particles.first().unwrap().generation_epoch,
            current_epoch - 24
        );
        assert_eq!(
            state.particles.last().unwrap().generation_epoch,
            current_epoch
        );
    }

