        let created_at = Instant::now();
        let clock = ClockSnapshot::default();

        let start = evaluate_daslight_move_delta(
            &effect,
            &effect.targets[0],
            created_at,
            created_at,
            &clock,
            1.0,
        );
        let before_authored_cycle = evaluate_daslight_move_delta(
            &effect,
            &effect.targets[0],
            created_at,
            created_at + Duration::from_millis(1_000),
            &clock,
            1.0,
        );
