    fn populate_mixed_release_effects(
        runtime: &mut EngineRuntime,
        fixture_ids: &[FixtureId],
        created_at: Instant,
        effect_count: usize,
    ) {
        let mut chaser_base = test_chaser_request(fixture_ids);
        chaser_base.active_step_count = 4;
        chaser_base.wings = 2;
        chaser_base.duty_cycle = 0.75;
        chaser_base.overlap = 0.25;
        chaser_base.fixture_spread = 0.5;
        let mut move_base = test_move_request(fixture_ids);
        move_base.interpolation = protocol::MoveInterpolation::DaslightCircle;
        move_base.beam_targets = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(selection_index, fixture_id)| protocol::MoveEffectBeamTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    selection_index: selection_index as u32,
                },
            )
            .collect();
        let curve_base = test_curve_request(fixture_ids);
        let mapping_base = test_mapping_request(fixture_ids);
        let color_mapping_base = test_color_mapping_request(fixture_ids.to_vec());
        for index in 0..effect_count {
            let phase = index as f32 / effect_count as f32;
            let kind = match index % 6 {
                0 => {
                    let mut request = test_color_request(
                        fixture_ids.to_vec(),
                        test_color(
                            ((index + 1) * 977) as u16,
                            ((index + 1) * 431) as u16,
                            ((index + 1) * 211) as u16,
                        ),
                    );
                    request.stops.insert(
                        1,
                        protocol::ColorEffectStop {
                            position: 0.5,
                            color: test_color(
                                ((index + 7) * 613) as u16,
                                ((index + 3) * 389) as u16,
                                ((index + 5) * 149) as u16,
                            ),
                        },
                    );
                    request.algorithm = ColorEffectAlgorithm::Cycle;
                    request.interpolation = ColorEffectInterpolation::HsvShortest;
                    request.fixture_spread = 1.0;
                    request.phase = phase;
                    if index == 0 {
                        let beam_targets = fixture_ids
                            .iter()
                            .enumerate()
                            .map(
                                |(target_index, fixture_id)| protocol::ColorEffectBeamTarget {
                                    fixture_id: *fixture_id,
                                    beam_index: 0,
                                    selection_index: target_index as u32,
                                    feature_attribute: None,
                                },
                            )
                            .collect::<Vec<_>>();
                        let target_coordinates = fixture_ids
                            .iter()
                            .enumerate()
                            .map(|(target_index, fixture_id)| {
                                protocol::ColorEffectSpatialPlacementTarget {
                                    fixture_id: *fixture_id,
                                    beam_index: 0,
                                    patch_x: target_index as i64,
                                    patch_y: 0,
                                }
                            })
                            .collect::<Vec<_>>();
                        request.spatial_pattern = Some(Box::new(
                            protocol::ColorEffectSpatialPattern {
                            parameter_model_version:
                                protocol::COLOR_EFFECT_SPATIAL_PARAMETER_MODEL_VERSION,
                            recipe: ColorEffectSpatialRecipe::Rainbow {
                                grayscale: true,
                                vertical_symmetry: false,
                                horizontal_symmetry: false,
                                rotation_degrees: 31.0,
                                color_width: 50.0,
                                angle_degrees: 17.0,
                                gradient: 100.0,
                            },
                            beam_targets,
                            placement: Some(protocol::ColorEffectSpatialPlacement {
                                source_coordinate_frame:
                                    ColorEffectSpatialCoordinateFrame::DaslightPatchCanvas,
                                mapping_shape: ColorEffectSpatialMappingShape::Rectangle,
                                x: 0,
                                y: 0,
                                sx: fixture_ids.len() as i64,
                                sy: 1,
                                mapping_angle_degrees: 0.0,
                                sampling_rule: ColorEffectSpatialSamplingRule::RotatedInclusionMaskAxisAlignedRaster,
                                vertical_symmetry: false,
                                horizontal_symmetry: false,
                                raster_rotation_degrees: 0.0,
                                target_coordinates,
                            }),
                            },
                        ));
                    }
                    RuntimeEffectKind::Color(runtime.resolve_color_effect_request(request).unwrap())
                }
                1 => {
                    let mut request = chaser_base.clone();
                    request.phase = phase;
                    RuntimeEffectKind::Chaser(Box::new(
                        runtime.resolve_chaser_effect_request(request).unwrap(),
                    ))
                }
                2 => {
                    let mut request = move_base.clone();
                    request.phase = phase;
                    RuntimeEffectKind::Move(runtime.resolve_move_effect_request(request).unwrap())
                }
                3 => {
                    let mut request = curve_base.clone();
                    request.phase = phase;
                    RuntimeEffectKind::Curve(runtime.resolve_curve_effect_request(request).unwrap())
                }
                4 => {
                    let mut request = mapping_base.clone();
                    request.phase = phase;
                    request.repetitions = 1.0 + (index % 4) as f32;
                    RuntimeEffectKind::Mapping(
                        runtime.resolve_mapping_effect_request(request).unwrap(),
                    )
                }
                _ => {
                    let mut request = color_mapping_base.clone();
                    request.phase = phase;
                    request.offset_u = index as f32 / effect_count as f32;
                    request.sampling = ColorMappingSampling::Bilinear;
                    RuntimeEffectKind::ColorMapping(
                        runtime
                            .resolve_color_mapping_effect_request(request)
                            .unwrap(),
                    )
                }
            };
            runtime.effects.push(RuntimeEffect {
                id: index as EffectId + 1,
                kind,
                enabled: true,
                created_at,
            });
        }
    }

    fn populate_corrected_knight_release_effects(
        runtime: &mut EngineRuntime,
        fixture_ids: &[FixtureId],
        created_at: Instant,
        effect_count: usize,
    ) {
        for index in 0..effect_count {
            let one_way = index % 4 < 2;
            let go_outside = index % 2 == 0;
            let stop_count = if index == 0 { 255 } else { 32 };
            let palette_red = (0..stop_count)
                .map(|stop| {
                    ((stop as f64 / (stop_count - 1) as f64) * f64::from(u16::MAX)).round() as u16
                })
                .collect::<Vec<_>>();
            let mut request = test_daslight_knight_request(
                30_040,
                100,
                one_way,
                true,
                go_outside,
                50.0,
                index % 2 == 1,
                &palette_red,
            );
            request.fixture_ids = fixture_ids.to_vec();
            if index == 0 {
                request.clock_sync = Some(EffectClockSync { beats: 0.25 });
            }
            request.phase = index as f32 / effect_count as f32;
            let kind = RuntimeEffectKind::Color(
                runtime
                    .resolve_color_effect_request(request)
                    .expect("exact Knight Rider benchmark request must compile"),
            );
            runtime.effects.push(RuntimeEffect {
                id: index as EffectId + 1,
                kind,
                enabled: true,
                created_at,
            });
        }
    }

