    fn populate_corrected_spatial_release_effects(
        runtime: &mut EngineRuntime,
        fixture_ids: &[FixtureId],
        created_at: Instant,
        effect_count: usize,
    ) {
        for index in 0..effect_count {
            let recipe_ordinal = index.saturating_sub(1) / 3;
            let strip_count = fixture_ids.len().max(1) as f32;
            let source_span = fixture_ids.len().saturating_sub(1).max(1) as f32;
            let recipe = if index == 0 {
                ColorEffectSpatialRecipe::KnightRider {
                    grayscale: false,
                    vertical_symmetry: false,
                    size: 10_000.0 / strip_count,
                    one_way: false,
                    fading: true,
                    go_outside: true,
                    gradient: 50.0,
                }
            } else {
                match (index - 1) % 3 {
                    0 => ColorEffectSpatialRecipe::Perlin {
                        grayscale: recipe_ordinal % 3 == 2,
                        vertical_symmetry: recipe_ordinal % 2 == 1,
                        horizontal_symmetry: false,
                        rotation_degrees: ((recipe_ordinal * 37) % 361) as f32,
                        octaves: 1 + (recipe_ordinal % 9) as u8,
                        zoom: (5 + recipe_ordinal % 20) as f32 / source_span,
                        direction_degrees: ((recipe_ordinal * 17) % 100) as f32 * 360.0 / 99.0,
                        speed: (1 + recipe_ordinal % 10) as f32,
                        amplitude: (50 + recipe_ordinal % 51) as f32,
                    },
                    1 => ColorEffectSpatialRecipe::RandomFill {
                        grayscale: recipe_ordinal % 3 == 1,
                        vertical_symmetry: recipe_ordinal % 2 == 1,
                        rng_seed: 0xA5A5_0000 ^ index as u32,
                        point_width: (1 + (recipe_ordinal % 10)) as f32 * 100.0 / strip_count,
                        source_point_height: Some(1 + (recipe_ordinal % 10) as u16),
                    },
                    _ => ColorEffectSpatialRecipe::Sparkle {
                        grayscale: recipe_ordinal % 3 == 1,
                        vertical_symmetry: recipe_ordinal % 2 == 1,
                        raster_mode: ColorEffectSpatialSparkleRasterMode::Sparkle,
                        rng_seed: 0x5A5A_0000 ^ index as u32,
                        number: if recipe_ordinal < 2 {
                            10
                        } else {
                            1 + (recipe_ordinal % 5) as u16
                        },
                        lifetime_ms: Some(if recipe_ordinal < 2 {
                            1_000
                        } else {
                            100 + (recipe_ordinal % 5) as u16 * 100
                        }),
                        source_lifespan: Some((recipe_ordinal % 10) as f32 / 10.0),
                        height: None,
                        width: if recipe_ordinal < 2 {
                            9_000.0 / strip_count
                        } else {
                            (1 + (recipe_ordinal % 8)) as f32 * 100.0 / strip_count
                        },
                    },
                }
            };
            let mut request = test_spatial_color_request(recipe);
            let fast_clock_row = match &request.spatial_pattern.as_ref().unwrap().recipe {
                ColorEffectSpatialRecipe::Sparkle {
                    number,
                    lifetime_ms,
                    ..
                } => *number == 10 && *lifetime_ms == Some(1_000),
                ColorEffectSpatialRecipe::KnightRider { .. } => true,
                _ => false,
            };
            if fast_clock_row {
                request.clock_sync = Some(EffectClockSync { beats: 0.25 });
            }
            if matches!(
                request
                    .spatial_pattern
                    .as_ref()
                    .map(|pattern| &pattern.recipe),
                Some(ColorEffectSpatialRecipe::Perlin { .. })
            ) {
                let beam_targets = fixture_ids
                    .iter()
                    .enumerate()
                    .map(
                        |(selection_index, fixture_id)| protocol::ColorEffectBeamTarget {
                            fixture_id: *fixture_id,
                            beam_index: 0,
                            selection_index: selection_index as u32,
                            feature_attribute: None,
                        },
                    )
                    .collect::<Vec<_>>();
                let target_coordinates = fixture_ids
                    .iter()
                    .enumerate()
                    .map(|(selection_index, fixture_id)| {
                        protocol::ColorEffectSpatialPlacementTarget {
                            fixture_id: *fixture_id,
                            beam_index: 0,
                            patch_x: selection_index as i64,
                            patch_y: 0,
                        }
                    })
                    .collect();
                let mut placement =
                    test_patch_canvas_placement(0, 0, fixture_ids.len() as i64, 1, 0.0);
                placement.target_coordinates = target_coordinates;
                let pattern = request.spatial_pattern.as_mut().unwrap();
                pattern.beam_targets = beam_targets;
                pattern.placement = Some(placement);
            }
            request.label = format!("Corrected spatial benchmark {index}");
            request.fixture_ids = fixture_ids.to_vec();
            request.period_ms = 1_003 + (index % 7) as u64 * 137;
            request.phase = index as f32 / effect_count as f32;
            request.stops = if matches!(
                request
                    .spatial_pattern
                    .as_ref()
                    .map(|pattern| &pattern.recipe),
                Some(ColorEffectSpatialRecipe::KnightRider { .. })
            ) {
                (0..255)
                    .map(|stop| protocol::ColorEffectStop {
                        position: stop as f32 / 254.0,
                        color: test_color(stop as u16 * 258, 0, u16::MAX - stop as u16 * 258),
                    })
                    .collect()
            } else {
                vec![
                    protocol::ColorEffectStop {
                        position: 0.0,
                        color: black_color(),
                    },
                    protocol::ColorEffectStop {
                        position: 0.33,
                        color: test_color(u16::MAX, 8_192, 0),
                    },
                    protocol::ColorEffectStop {
                        position: 0.67,
                        color: test_color(0, u16::MAX, 16_384),
                    },
                    protocol::ColorEffectStop {
                        position: 1.0,
                        color: test_color(24_576, 0, u16::MAX),
                    },
                ]
            };
            let kind = RuntimeEffectKind::Color(
                runtime
                    .resolve_color_effect_request(request)
                    .expect("corrected spatial benchmark request must compile"),
            );
            runtime.effects.push(RuntimeEffect {
                id: index as EffectId + 1,
                kind,
                enabled: true,
                created_at,
            });
        }
    }

    #[test]
    fn corrected_perlin_random_fill_and_sparkle_release_stack_meets_44hz_budget() {
        const FIXTURE_COUNT: u64 = 200;
        const EFFECT_COUNT: usize = 64;
        const SAMPLES: usize = if cfg!(debug_assertions) { 20 } else { 1_000 };
        const ATTRIBUTES: [&str; 1] = ["ColorRed"];

        let mut runtime = runtime_with_mixed_effect_fixtures(FIXTURE_COUNT);
        let fixture_ids = (1..=FIXTURE_COUNT).collect::<Vec<_>>();
        let created_at = Instant::now();
        // Request validation, 200-fixture target expansion, Random fill rank
        // construction, and Perlin octave/hash compilation all happen before
        // the timed 44 Hz runtime sampling loop.
        populate_corrected_spatial_release_effects(
            &mut runtime,
            &fixture_ids,
            created_at,
            EFFECT_COUNT,
        );
        assert_eq!(runtime.effects.len(), EFFECT_COUNT);

        let mut recipe_counts = [0_usize; 3];
        let mut perlin_octaves = 0_u16;
        let mut perlin_direction_min = f32::INFINITY;
        let mut perlin_direction_max = f32::NEG_INFINITY;
        let mut saw_plain_perlin = false;
        let mut saw_folded_perlin = false;
        let mut saw_rotated_perlin = false;
        let mut max_sparkle_rows = 0;
        let mut max_knight_rows = 0;
        for effect in &runtime.effects {
            let RuntimeEffectKind::Color(color) = &effect.kind else {
                panic!("corrected spatial benchmark must contain only Color effects");
            };
            let spatial = color
                .spatial
                .as_ref()
                .expect("corrected spatial benchmark must compile spatial state");
            assert_eq!(spatial.targets.len(), FIXTURE_COUNT as usize);
            let recipe = &color
                .request
                .spatial_pattern
                .as_ref()
                .expect("corrected spatial benchmark must retain recipe")
                .recipe;
            match recipe {
                ColorEffectSpatialRecipe::Perlin {
                    vertical_symmetry,
                    rotation_degrees,
                    octaves,
                    direction_degrees,
                    ..
                } => {
                    recipe_counts[0] += 1;
                    perlin_octaves |= 1_u16 << u32::from(*octaves);
                    perlin_direction_min = perlin_direction_min.min(*direction_degrees);
                    perlin_direction_max = perlin_direction_max.max(*direction_degrees);
                    saw_plain_perlin |= !*vertical_symmetry;
                    saw_folded_perlin |= *vertical_symmetry;
                    saw_rotated_perlin |= *rotation_degrees != 0.0;
                    let compiled = spatial
                        .daslight_perlin
                        .as_ref()
                        .expect("corrected Perlin must compile its hot-path state");
                    assert!(compiled
                        .targets
                        .iter()
                        .all(|target| target.octaves.len() == usize::from(*octaves)));
                    assert!(spatial.syndocal_random_fx.is_none());
                }
                ColorEffectSpatialRecipe::RandomFill { .. } => {
                    recipe_counts[1] += 1;
                    assert!(matches!(
                        spatial.syndocal_random_fx.as_ref(),
                        Some(CompiledSyndocalRandomFx::RandomFill { .. })
                    ));
                    assert!(spatial.daslight_perlin.is_none());
                }
                ColorEffectSpatialRecipe::Sparkle {
                    number,
                    lifetime_ms,
                    ..
                } => {
                    recipe_counts[2] += 1;
                    let Some(CompiledSyndocalRandomFx::Sparkle { state, .. }) =
                        spatial.syndocal_random_fx.as_ref()
                    else {
                        panic!("corrected Sparkle must compile its visual-clock state");
                    };
                    if *number == 10
                        && *lifetime_ms == Some(1_000)
                        && color
                            .request
                            .clock_sync
                            .is_some_and(|clock_sync| clock_sync.beats == 0.25)
                    {
                        max_sparkle_rows += 1;
                    }
                    let lifetime_ms = f64::from(lifetime_ms.unwrap());
                    let expected_max_particles = usize::from(*number).saturating_mul(
                        usize::try_from(SyndocalSparkleState::lifetime_generations(lifetime_ms))
                            .unwrap()
                            .saturating_add(1),
                    );
                    assert_eq!(state.borrow().max_particles, expected_max_particles);
                    assert!(spatial.daslight_perlin.is_none());
                }
                ColorEffectSpatialRecipe::KnightRider { size, .. } => {
                    let expected_size = 10_000.0 / color.request.fixture_ids.len() as f32;
                    assert!((*size - expected_size).abs() <= f32::EPSILON);
                    assert_eq!(color.request.stops.len(), 255);
                    assert!(color
                        .request
                        .clock_sync
                        .is_some_and(|clock_sync| clock_sync.beats == 0.25));
                    assert_eq!(
                        spatial
                            .daslight_knight_rider
                            .as_ref()
                            .expect("maximum Knight Rider descriptor")
                            .lanes
                            .len(),
                        254
                    );
                    max_knight_rows += 1;
                    assert!(spatial.syndocal_random_fx.is_none());
                    assert!(spatial.daslight_perlin.is_none());
                }
                _ => panic!("unexpected corrected spatial benchmark recipe"),
            }
        }
        assert_eq!(recipe_counts, [21, 21, 21]);
        assert_eq!(max_sparkle_rows, 2);
        assert_eq!(max_knight_rows, 1);
        assert!(perlin_octaves.count_ones() >= 3);
        assert!(perlin_direction_max > perlin_direction_min);
        assert!(saw_plain_perlin && saw_folded_perlin && saw_rotated_perlin);

        let mut durations = Vec::with_capacity(SAMPLES);
        let mut checksum = 0_u64;
        for sample in 0..SAMPLES {
            let at = created_at + DMX_TICK_INTERVAL * (sample as u32 + 1);
            let started = Instant::now();
            for fixture in &runtime.fixtures {
                for attribute in ATTRIBUTES {
                    checksum =
                        checksum.wrapping_add(runtime.apply_effects_with_transition_policy(
                            fixture, attribute, 16_384, at, false,
                        ) as u64);
                }
            }
            durations.push(started.elapsed());
        }
        std::hint::black_box(checksum);
        assert_ne!(checksum, 0);
        durations.sort_unstable();
        let p95 = durations[(SAMPLES * 95 / 100).min(SAMPLES - 1)];
        let p99 = durations[(SAMPLES * 99 / 100).min(SAMPLES - 1)];
        let max = *durations.last().unwrap();
        eprintln!(
            "Corrected Perlin/RandomFill/Sparkle/Knight 64x200 max-row stack per-tick evaluation: p95={}us p99={}us max={}us",
            p95.as_micros(),
            p99.as_micros(),
            max.as_micros()
        );
        // Preserve the established full-rig 5/8/12ms release gate. The hard
        // maximum remains well inside one 22.7ms DMX tick.
        if !cfg!(debug_assertions) {
            assert!(p95 <= Duration::from_millis(5), "p95 was {p95:?}");
            assert!(p99 <= Duration::from_millis(8), "p99 was {p99:?}");
            assert!(max <= Duration::from_millis(12), "max was {max:?}");
        }
    }

    #[test]
    fn max_placed_random_fill_release_stack_meets_44hz_budget() {
        const MAX_PALETTE_STOPS: usize = 255;
        const MAX_TARGET_COUNT: usize = 200;
        const MAX_RASTER_WIDTH: i64 = 100;
        const MAX_RASTER_HEIGHT: i64 = 100;
        const MAX_CELL_COUNT: usize = 10_000;
        const MAX_CELL_POINT_WIDTH_PERCENT: f32 = 1.0;
        const MAX_CELL_POINT_HEIGHT_PERCENT: u16 = 1;
        const MAX_COMPACT_RANK_BYTES: usize = 42_040;
        const DENSE_PER_TRANSITION_RANK_BYTES: usize = 10_200_000;

        assert_eq!(RELEASE_GATE_EFFECT_COUNT, 64);
        assert_eq!(RELEASE_GATE_FIXTURE_COUNT, 200);
        assert_eq!(RELEASE_GATE_HZ, 44);
        assert_eq!(
            RELEASE_GATE_SAMPLES,
            if cfg!(debug_assertions) { 20 } else { 1_000 }
        );
        assert_eq!(MAX_PALETTE_STOPS, 255);
        assert_eq!(MAX_TARGET_COUNT, 200);
        assert_eq!(MAX_RASTER_WIDTH, 100);
        assert_eq!(MAX_RASTER_HEIGHT, 100);
        assert_eq!(MAX_CELL_COUNT, 10_000);
        assert_eq!(MAX_CELL_POINT_WIDTH_PERCENT, 1.0);
        assert_eq!(MAX_CELL_POINT_HEIGHT_PERCENT, 1);
        assert_eq!(MAX_COMPACT_RANK_BYTES, 42_040);
        assert_eq!(DENSE_PER_TRANSITION_RANK_BYTES, 10_200_000);
        assert_eq!(RELEASE_GATE_P95_LIMIT, Duration::from_millis(5));
        assert_eq!(RELEASE_GATE_P99_LIMIT, Duration::from_millis(8));
        assert_eq!(RELEASE_GATE_MAX_LIMIT, Duration::from_millis(12));
        assert_eq!(
            1_000_000 / DMX_TICK_INTERVAL.as_micros(),
            u128::from(RELEASE_GATE_HZ)
        );

        let mut runtime = runtime_with_mixed_effect_fixtures(RELEASE_GATE_FIXTURE_COUNT as u64);
        let fixture_ids = (1..=RELEASE_GATE_FIXTURE_COUNT as u64).collect::<Vec<_>>();
        let beam_targets = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(selection_index, fixture_id)| protocol::ColorEffectBeamTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    selection_index: selection_index as u32,
                    feature_attribute: None,
                },
            )
            .collect::<Vec<_>>();
        let target_coordinates = fixture_ids
            .iter()
            .enumerate()
            .map(
                |(selection_index, fixture_id)| protocol::ColorEffectSpatialPlacementTarget {
                    fixture_id: *fixture_id,
                    beam_index: 0,
                    patch_x: (selection_index % MAX_RASTER_WIDTH as usize) as i64,
                    patch_y: if selection_index < MAX_RASTER_WIDTH as usize {
                        0
                    } else {
                        MAX_RASTER_HEIGHT - 1
                    },
                },
            )
            .collect::<Vec<_>>();
        assert_eq!(fixture_ids.len(), MAX_TARGET_COUNT);
        assert_eq!(beam_targets.len(), MAX_TARGET_COUNT);
        assert_eq!(target_coordinates.len(), MAX_TARGET_COUNT);

        let mut base = test_spatial_color_request(ColorEffectSpatialRecipe::RandomFill {
            grayscale: false,
            vertical_symmetry: false,
            rng_seed: 0x37FF_0000,
            point_width: MAX_CELL_POINT_WIDTH_PERCENT,
            source_point_height: Some(MAX_CELL_POINT_HEIGHT_PERCENT),
        });
        base.fixture_ids = fixture_ids;
        base.period_ms = 1_000;
        base.stops = (0..MAX_PALETTE_STOPS)
            .map(|stop| protocol::ColorEffectStop {
                position: stop as f32 / (MAX_PALETTE_STOPS - 1) as f32,
                color: test_color(
                    stop as u16 * 257,
                    u16::MAX - stop as u16 * 257,
                    stop as u16 * 193,
                ),
            })
            .collect();
        let mut placement =
            test_patch_canvas_placement(0, 0, MAX_RASTER_WIDTH, MAX_RASTER_HEIGHT, 0.0);
        placement.target_coordinates = target_coordinates;
        let pattern = base.spatial_pattern.as_mut().unwrap();
        pattern.beam_targets = beam_targets;
        pattern.placement = Some(placement);
        validate_color_effect_request(&base).unwrap();
        assert_eq!(base.stops.len(), MAX_PALETTE_STOPS);

        let created_at = Instant::now();
        for index in 0..RELEASE_GATE_EFFECT_COUNT {
            let mut request = base.clone();
            let ColorEffectSpatialRecipe::RandomFill { rng_seed, .. } =
                &mut request.spatial_pattern.as_mut().unwrap().recipe
            else {
                unreachable!();
            };
            *rng_seed ^= index as u32;
            request.phase = index as f32 / RELEASE_GATE_EFFECT_COUNT as f32;
            let kind = RuntimeEffectKind::Color(
                runtime
                    .resolve_color_effect_request(request)
                    .expect("maximum placed Random Fill request must compile"),
            );
            runtime.effects.push(RuntimeEffect {
                id: index as EffectId + 1,
                kind,
                enabled: true,
                created_at,
            });
        }
        assert_eq!(runtime.effects.len(), RELEASE_GATE_EFFECT_COUNT);
        assert_eq!(
            runtime
                .effects
                .iter()
                .filter(|effect| effect.enabled)
                .count(),
            64
        );
        assert_eq!(runtime.fixtures.len(), RELEASE_GATE_FIXTURE_COUNT);

        for effect in &runtime.effects {
            let RuntimeEffectKind::Color(color) = &effect.kind else {
                unreachable!("maximum placed Random Fill gate contains only Color effects");
            };
            assert_eq!(color.request.fixture_ids.len(), MAX_TARGET_COUNT);
            assert_eq!(color.request.stops.len(), MAX_PALETTE_STOPS);
            let pattern = color.request.spatial_pattern.as_ref().unwrap();
            assert!(matches!(
                pattern.recipe,
                ColorEffectSpatialRecipe::RandomFill {
                    point_width: 1.0,
                    source_point_height: Some(1),
                    ..
                }
            ));
            assert_eq!(pattern.beam_targets.len(), MAX_TARGET_COUNT);
            let placement = pattern.placement.as_ref().unwrap();
            assert_eq!((placement.sx, placement.sy), (100, 100));
            assert_eq!(placement.target_coordinates.len(), MAX_TARGET_COUNT);
            let spatial = color.spatial.as_ref().unwrap();
            assert_eq!(spatial.targets.len(), MAX_TARGET_COUNT);
            let Some(CompiledSyndocalRandomFx::RandomFill {
                point_width,
                point_height,
                cell_columns,
                cell_count,
                rank_order:
                    SyndocalRandomFillRankOrder::AffineTwoDimensional {
                        base_ranks,
                        permutations,
                    },
                ..
            }) = spatial.syndocal_random_fx.as_ref()
            else {
                panic!(
                    "maximum placed Random Fill must use a scrambled base plus compact affine ranks"
                );
            };
            assert_eq!(
                (*point_width, *point_height, *cell_columns, *cell_count),
                (1, Some(1), 100, MAX_CELL_COUNT)
            );
            assert_eq!(base_ranks.len(), MAX_CELL_COUNT);
            assert_eq!(permutations.len(), MAX_PALETTE_STOPS);
            let compact_rank_bytes = base_ranks.len() * std::mem::size_of::<u32>()
                + permutations.len() * std::mem::size_of::<SyndocalRandomFillAffinePermutation>();
            assert_eq!(compact_rank_bytes, MAX_COMPACT_RANK_BYTES);
            assert!(compact_rank_bytes < DENSE_PER_TRANSITION_RANK_BYTES);
        }

        let (p95, p99, max) =
            measure_release_gate(created_at, |at| {
                runtime.fixtures.iter().fold(0_u64, |checksum, fixture| {
                    checksum.wrapping_add(runtime.apply_effects_with_transition_policy(
                        fixture, "ColorRed", 16_384, at, false,
                    ) as u64)
                })
            });
        eprintln!(
            "Max placed RandomFill 64x200 (255 stops, 100x100, Point 1x1): p95={}us p99={}us max={}us",
            p95.as_micros(),
            p99.as_micros(),
            max.as_micros()
        );
        assert_release_gate_percentiles(p95, p99, max);
    }

