    #[test]
    fn activation_scoped_manual_recall_replaces_prior_cue_list_instance_and_releases() {
        let mut runtime = runtime_with_lfo_effects(&[]);
        runtime.values.insert((1, "Dimmer".to_string()), 20_000);
        create_effect_only_cue(
            &mut runtime,
            1,
            vec![owned_lfo_target(
                101,
                test_lfo_request(
                    "First manual",
                    LfoShape::Square,
                    1_000,
                    0.25,
                    EffectBlendMode::Override,
                    0,
                    u16::MAX,
                ),
            )],
        );
        create_effect_only_cue(
            &mut runtime,
            2,
            vec![owned_lfo_target(
                102,
                test_lfo_request(
                    "Second manual",
                    LfoShape::Square,
                    1_000,
                    0.75,
                    EffectBlendMode::Override,
                    0,
                    u16::MAX,
                ),
            )],
        );
        let recalled_at = Instant::now();

        runtime.request_cue(1, recalled_at);
        assert_eq!(runtime.active_effect_activation_indices.len(), 1);
        assert_eq!(
            runtime.render_dmx_frame_for_universe(0, recalled_at)[0],
            255
        );

        runtime.request_cue(2, recalled_at);
        assert_eq!(runtime.active_effect_activation_indices.len(), 1);
        assert!(matches!(
            runtime.effect_activations[runtime.active_effect_activation_indices[0]].key,
            Some(RuntimeEffectActivationKey::CueList { cue_id: 2, .. })
        ));
        assert_eq!(runtime.render_dmx_frame_for_universe(0, recalled_at)[0], 0);

        assert!(
            runtime.cue_value_release_plan(2).target_values.is_empty(),
            "effect-only Cue must not claim static values for release"
        );
        runtime.apply_command(EngineCommand::ReleaseCue(2));
        assert!(runtime.active_effect_activation_indices.is_empty());
        assert_eq!(
            runtime.render_dmx_frame_for_universe(0, recalled_at)[0],
            (20_000_u16 >> 8) as u8,
            "effect-only release must reveal the untouched authored base value"
        );
        assert_eq!(runtime.cue_lists[0].active_cue_id, None);
        runtime.rebuild_effect_activations(recalled_at + Duration::from_millis(1));
        assert!(
            runtime.active_effect_activation_indices.is_empty(),
            "a later pool rebuild resurrected the released Cue"
        );
    }

    #[test]
    fn cue_owned_effect_transition_crossfades_matching_params_and_expires() {
        let mut runtime = runtime_with_lfo_effects(&[]);
        let first = owned_lfo_target(
            101,
            test_lfo_request(
                "First state",
                LfoShape::Square,
                1_000,
                0.0,
                EffectBlendMode::Override,
                u16::MAX,
                u16::MAX,
            ),
        );
        let mut second = owned_lfo_target(
            101,
            test_lfo_request(
                "Second state",
                LfoShape::Square,
                1_000,
                0.0,
                EffectBlendMode::Override,
                0,
                0,
            ),
        );
        second.transition_ms = Some(1_000);
        create_effect_only_cue(&mut runtime, 1, vec![first]);
        create_effect_only_cue(&mut runtime, 2, vec![second]);

        let recalled_at = Instant::now();
        runtime.start_cue(1, recalled_at, PendingCueTriggerSource::Manual);
        runtime.start_cue(2, recalled_at, PendingCueTriggerSource::Manual);

        let activation_index = runtime.active_effect_activation_indices[0];
        assert!(runtime.effect_activations[activation_index]
            .transition
            .is_some());
        let fixture = &runtime.fixtures[0];
        assert_eq!(
            runtime.apply_effects(fixture, "Dimmer", 20_000, recalled_at),
            u16::MAX,
            "the incoming Cue must begin at the outgoing live result"
        );
        runtime.rebuild_effect_activations(recalled_at + Duration::from_millis(500));
        let activation_index = runtime.active_effect_activation_indices[0];
        assert!(runtime.effect_activations[activation_index]
            .transition
            .is_some());
        let fixture = &runtime.fixtures[0];
        assert_eq!(
            runtime.apply_effects(
                fixture,
                "Dimmer",
                20_000,
                recalled_at + Duration::from_millis(500),
            ),
            32_768,
        );
        assert_eq!(
            runtime.apply_effects(
                fixture,
                "Dimmer",
                20_000,
                recalled_at + Duration::from_millis(1_000),
            ),
            0,
        );

        runtime.expire_effect_transitions(recalled_at + Duration::from_millis(999));
        assert!(runtime.effect_activations[activation_index]
            .transition
            .is_some());
        runtime.expire_effect_transitions(recalled_at + Duration::from_millis(1_000));
        assert!(runtime.effect_activations[activation_index]
            .transition
            .is_none());
    }

    #[test]
    fn cue_list_transition_shared_clock_fast_path_matches_general_evaluation() {
        let mut runtime = runtime_with_lfo_effects(&[]);
        let mut first_request = test_lfo_request(
            "First clocked state",
            LfoShape::Sine,
            1_000,
            0.125,
            EffectBlendMode::Override,
            4_000,
            54_000,
        );
        first_request.clock_sync = Some(protocol::EffectClockSync { beats: 2.0 });
        let mut second_request = test_lfo_request(
            "Second clocked state",
            LfoShape::Triangle,
            1_000,
            0.625,
            EffectBlendMode::Override,
            1_000,
            61_000,
        );
        second_request.clock_sync = Some(protocol::EffectClockSync { beats: 0.5 });
        let first = owned_lfo_target(101, first_request);
        let mut second = owned_lfo_target(101, second_request);
        second.transition_ms = Some(1_000);
        create_effect_only_cue(&mut runtime, 1, vec![first]);
        create_effect_only_cue(&mut runtime, 2, vec![second]);

        let recalled_at = Instant::now();
        runtime.start_cue(1, recalled_at, PendingCueTriggerSource::Manual);
        runtime.start_cue(2, recalled_at, PendingCueTriggerSource::Manual);
        let activation =
            runtime.effect_activations[runtime.active_effect_activation_indices[0]].clone();
        assert!(cue_list_activation_uses_shared_clock(&activation));

        let fixture = &runtime.fixtures[0];
        for (elapsed_ms, discrete) in [(0, false), (137, false), (500, true), (999, false)] {
            let at = recalled_at + Duration::from_millis(elapsed_ms);
            let clock = runtime.clock.snapshot(at);
            let fast_activation = activation.clone();
            let general_activation = activation.clone();
            let fast = runtime.apply_cue_list_activation_with_shared_clock(
                &fast_activation,
                fixture,
                "Dimmer",
                20_000,
                at,
                &clock,
                discrete,
            );
            let general = runtime.apply_effect_activation_general(
                &general_activation,
                fixture,
                "Dimmer",
                20_000,
                at,
                &clock,
                discrete,
            );
            assert_eq!(fast, general, "mismatch at {elapsed_ms} ms");
        }

        let mut non_unit_rate = activation.clone();
        non_unit_rate.rate = 0.5;
        assert!(!cue_list_activation_uses_shared_clock(&non_unit_rate));
        let mut explicit_loop_fill = activation.clone();
        explicit_loop_fill.source_loop_fill = Some(true);
        assert!(!cue_list_activation_uses_shared_clock(&explicit_loop_fill));
        let mut outgoing_non_unit_rate = activation;
        outgoing_non_unit_rate
            .transition
            .as_mut()
            .expect("test activation must retain an outgoing transition")
            .from_rate = 2.0;
        assert!(!cue_list_activation_uses_shared_clock(
            &outgoing_non_unit_rate
        ));
    }

