    #[test]
    fn cue_list_delete_rejects_locked_placement_before_any_mutation() {
        let mut runtime = cue_list_delete_lock_test_runtime(10, 11);
        runtime.timeline_events = vec![
            timeline_test_event(100, 20, 0, 10, 100, 1),
            timeline_test_event(200, 21, 500, 11, 100, 1),
        ];
        runtime.recompute_timeline_event_layers().unwrap();
        let before = runtime.build_persistence_snapshot();
        let before_values = runtime.values.clone();
        let before_events = timeline_event_test_summaries(&runtime);
        let before_cue_lists = runtime.cue_lists.clone();
        let before_cue_ids = runtime.cues.iter().map(|cue| cue.id).collect::<Vec<_>>();

        let error = runtime.delete_cue_list_state(2).unwrap_err();
        assert!(error.contains("locked"), "unexpected error: {error}");
        assert!(error.contains("Cue List 2"), "unexpected error: {error}");
        assert_eq!(runtime.build_persistence_snapshot(), before);
        assert_eq!(timeline_event_test_summaries(&runtime), before_events);
        assert_eq!(runtime.cue_lists, before_cue_lists);
        assert_eq!(
            runtime.cues.iter().map(|cue| cue.id).collect::<Vec<_>>(),
            before_cue_ids
        );
        assert_eq!(runtime.values, before_values);
        assert!(runtime.active_fade.is_some());
        assert_eq!(runtime.active_cue_id, Some(1));
    }

    #[test]
    fn cue_list_delete_rejects_protected_incoming_jump_before_any_mutation() {
        let mut runtime = cue_list_delete_lock_test_runtime(10, 11);
        let mut locked_source = timeline_test_event(100, 1, 0, 10, 100, 1);
        locked_source.jump_to_event_id = Some(200);
        runtime.timeline_events = vec![
            locked_source,
            timeline_test_event(200, 20, 500, 11, 100, 1),
            timeline_test_event(300, 21, 900, 11, 100, 1),
        ];
        runtime.recompute_timeline_event_layers().unwrap();
        let before = runtime.build_persistence_snapshot();
        let before_values = runtime.values.clone();
        let before_events = timeline_event_test_summaries(&runtime);
        let before_jump_landed = runtime.timeline_jump_landed_event_id;

        let error = runtime.delete_cue_list_state(2).unwrap_err();
        assert!(error.contains("locked"), "unexpected error: {error}");
        assert!(error.contains("jumps"), "unexpected error: {error}");
        assert_eq!(runtime.build_persistence_snapshot(), before);
        assert_eq!(timeline_event_test_summaries(&runtime), before_events);
        assert_eq!(runtime.values, before_values);
        assert!(runtime.active_fade.is_some());
        assert_eq!(runtime.timeline_jump_landed_event_id, before_jump_landed);
        assert!(runtime.cues.iter().any(|cue| cue.id == 2));
        assert!(runtime.cues.iter().any(|cue| cue.id == 20));
        assert!(runtime.cues.iter().any(|cue| cue.id == 21));
        assert!(runtime.timeline_events.iter().any(|event| event.id == 100));
        assert!(runtime.timeline_events.iter().any(|event| event.id == 200));
        assert!(runtime.timeline_events.iter().any(|event| event.id == 300));
    }

    #[test]
    fn cue_list_delete_without_locked_references_still_succeeds() {
        let mut runtime = cue_list_delete_lock_test_runtime(10, 11);
        let mut unlocked_source = timeline_test_event(110, 2, 300, 11, 100, 1);
        unlocked_source.jump_to_event_id = Some(200);
        runtime.timeline_events = vec![
            unlocked_source,
            timeline_test_event(200, 20, 500, 11, 100, 1),
            timeline_test_event(300, 21, 900, 11, 100, 1),
        ];
        runtime.recompute_timeline_event_layers().unwrap();
        runtime.timeline_playing = true;
        runtime.timeline_position_ms = 600;
        runtime.timeline_jump_landed_event_id = Some(200);
        runtime.active_cue_id = Some(20);
        runtime.active_fade = None;
        runtime.active_group_cue_ids.insert("main".to_string(), 20);
        runtime.cue_list_effect_activation_cues.insert(2, 20);
        runtime.playback_executors.push(PlaybackExecutorSummary {
            id: 2,
            label: "Bank 2 executor".to_string(),
            cue_list_id: 2,
            page: 1,
            slot: 2,
            level: 1.0,
        });

        assert_eq!(runtime.delete_cue_list_state(2), Ok(()));
        assert!(runtime.cue_lists.iter().all(|cue_list| cue_list.id != 2));
        assert!(runtime.cues.iter().all(|cue| cue.cue_list_id != 2));
        assert!(runtime.cues.iter().any(|cue| cue.id == 2));
        assert!(runtime
            .playback_executors
            .iter()
            .all(|executor| executor.cue_list_id != 2));
        assert!(runtime
            .timeline_events
            .iter()
            .all(|event| !matches!(event.id, 200 | 300)));
        assert_eq!(
            runtime.timeline_events[0].jump_to_event_id, None,
            "unlocked incoming jump must be cleared"
        );
        assert_eq!(runtime.timeline_jump_landed_event_id, None);
        assert_eq!(runtime.active_cue_id, None);
        assert!(!runtime
            .active_group_cue_ids
            .values()
            .any(|cue_id| *cue_id == 20));
        assert!(!runtime.cue_list_effect_activation_cues.contains_key(&2));
    }

    #[test]
    fn timeline_layer_commands_normalize_and_remove_with_explicit_reassignment() {
        let mut runtime = runtime_with_lfo_effects(&[]);
        create_effect_only_cue(&mut runtime, 1, Vec::new());
        runtime
            .add_timeline_cue_event_state(100, 1, 0, None, TimelineTrackKind::Lighting, None)
            .unwrap();
        let published = RwLock::new(runtime.build_snapshot(0));

        let (add_ack, add_receiver) = mpsc::sync_channel(1);
        runtime.apply_command(EngineCommand::AddTimelineLayer {
            layer: timeline_test_layer(2, 99, false, false, false, TimelineLayerKind::Lighting),
            expires_at: Instant::now() + Duration::from_secs(1),
            ack: add_ack,
        });
        runtime.publish_pending_command_acks(0, &published);
        assert_eq!(add_receiver.recv().unwrap(), Ok(()));
        assert_eq!(
            runtime
                .timeline_layers
                .iter()
                .map(|layer| (layer.id, layer.order))
                .collect::<Vec<_>>(),
            vec![(0, 0), (2, 1), (1, 2)]
        );
        assert_eq!(runtime.timeline_events[0].layer_id, Some(0));

        let (reorder_ack, reorder_receiver) = mpsc::sync_channel(1);
        runtime.apply_command(EngineCommand::ReorderTimelineLayers {
            layer_ids: vec![2, 0, 1],
            expires_at: Instant::now() + Duration::from_secs(1),
            ack: reorder_ack,
        });
        runtime.publish_pending_command_acks(0, &published);
        assert_eq!(reorder_receiver.recv().unwrap(), Ok(()));
        assert_eq!(
            runtime
                .timeline_layers
                .iter()
                .map(|layer| (layer.id, layer.order))
                .collect::<Vec<_>>(),
            vec![(2, 0), (0, 1), (1, 2)]
        );

        let before_failed_remove = timeline_event_test_summaries(&runtime);
        let (failed_ack, failed_receiver) = mpsc::sync_channel(1);
        runtime.apply_command(EngineCommand::RemoveTimelineLayer {
            layer_id: 0,
            reassign_to_layer_id: None,
            expires_at: Instant::now() + Duration::from_secs(1),
            ack: failed_ack,
        });
        runtime.publish_pending_command_acks(0, &published);
        assert!(failed_receiver
            .recv()
            .unwrap()
            .unwrap_err()
            .contains("not empty"));
        assert_eq!(
            timeline_event_test_summaries(&runtime),
            before_failed_remove
        );

        let (remove_ack, remove_receiver) = mpsc::sync_channel(1);
        runtime.apply_command(EngineCommand::RemoveTimelineLayer {
            layer_id: 0,
            reassign_to_layer_id: Some(2),
            expires_at: Instant::now() + Duration::from_secs(1),
            ack: remove_ack,
        });
        runtime.publish_pending_command_acks(0, &published);
        assert_eq!(remove_receiver.recv().unwrap(), Ok(()));
        assert_eq!(runtime.timeline_events[0].layer_id, Some(2));
        assert_eq!(runtime.timeline_events[0].resolved_layer_id, 2);
        assert!(runtime.timeline_layers.iter().all(|layer| layer.id != 0));
    }

    #[test]
    fn timeline_layer_legacy_none_automation_occupancy_rejects_update_and_remove_atomically() {
        let mut runtime = runtime_with_lfo_effects(&[]);
        runtime.timeline_automations = vec![RuntimeTimelineAutomation {
            id: 501,
            fixture_id: 1,
            attribute: "Dimmer".to_string(),
            track: TimelineTrackKind::Lighting,
            timeline_layer_id: None,
            keyframes: Vec::new(),
            enabled: true,
        }];
        runtime.timeline_video_automations = vec![RuntimeTimelineVideoAutomation {
            id: 502,
            layer_id: 1,
            timeline_layer_id: None,
            param: VideoParam::Opacity,
            track: TimelineTrackKind::Video,
            keyframes: Vec::new(),
            enabled: true,
        }];
        let assert_legacy_state = |runtime: &EngineRuntime| {
            assert!(runtime.timeline_layers.is_empty());
            assert_eq!(runtime.timeline_automations.len(), 1);
            assert_eq!(runtime.timeline_automations[0].timeline_layer_id, None);
            assert_eq!(runtime.timeline_video_automations.len(), 1);
            assert_eq!(
                runtime.timeline_video_automations[0].timeline_layer_id,
                None
            );
        };

        let lighting_update_error = runtime
            .update_timeline_layer_state(timeline_test_layer(
                0,
                0,
                false,
                false,
                false,
                TimelineLayerKind::Video,
            ))
            .unwrap_err();
        assert!(lighting_update_error.contains("Lighting automation"));
        assert_legacy_state(&runtime);

        let video_update_error = runtime
            .update_timeline_layer_state(timeline_test_layer(
                1,
                1,
                false,
                false,
                false,
                TimelineLayerKind::Lighting,
            ))
            .unwrap_err();
        assert!(video_update_error.contains("Video automation"));
        assert_legacy_state(&runtime);

        let lighting_remove_error = runtime.remove_timeline_layer_state(0, None).unwrap_err();
        assert!(lighting_remove_error.contains("not empty"));
        assert_legacy_state(&runtime);

        let video_remove_error = runtime.remove_timeline_layer_state(1, None).unwrap_err();
        assert!(video_remove_error.contains("not empty"));
        assert_legacy_state(&runtime);

        let lighting_target_error = runtime.remove_timeline_layer_state(0, Some(1)).unwrap_err();
        assert!(lighting_target_error.contains("Lighting automation"));
        assert_legacy_state(&runtime);

        let video_target_error = runtime.remove_timeline_layer_state(1, Some(0)).unwrap_err();
        assert!(video_target_error.contains("Video automation"));
        assert_legacy_state(&runtime);
    }

    #[test]
    fn timeline_layer_legacy_none_automations_materialize_and_reassign_by_kind() {
        let mut runtime = runtime_with_lfo_effects(&[]);
        runtime.timeline_automations = vec![RuntimeTimelineAutomation {
            id: 501,
            fixture_id: 1,
            attribute: "Dimmer".to_string(),
            track: TimelineTrackKind::Lighting,
            timeline_layer_id: None,
            keyframes: Vec::new(),
            enabled: true,
        }];
        runtime.timeline_video_automations = vec![RuntimeTimelineVideoAutomation {
            id: 502,
            layer_id: 1,
            timeline_layer_id: None,
            param: VideoParam::Opacity,
            track: TimelineTrackKind::Video,
            keyframes: Vec::new(),
            enabled: true,
        }];

        runtime.materialize_legacy_timeline_layers();
        assert_eq!(
            runtime
                .timeline_layers
                .iter()
                .map(|layer| (layer.id, layer.kind))
                .collect::<Vec<_>>(),
            vec![
                (0, TimelineLayerKind::Lighting),
                (1, TimelineLayerKind::Video),
            ]
        );
        assert_eq!(runtime.timeline_automations[0].timeline_layer_id, Some(0));
        assert_eq!(
            runtime.timeline_video_automations[0].timeline_layer_id,
            Some(1)
        );

        runtime
            .add_timeline_layer_state(timeline_test_layer(
                2,
                2,
                false,
                false,
                false,
                TimelineLayerKind::Lighting,
            ))
            .unwrap();
        runtime
            .add_timeline_layer_state(timeline_test_layer(
                3,
                3,
                false,
                false,
                false,
                TimelineLayerKind::Video,
            ))
            .unwrap();

        assert!(runtime.remove_timeline_layer_state(0, None).is_err());
        runtime.remove_timeline_layer_state(0, Some(2)).unwrap();
        assert_eq!(runtime.timeline_automations[0].timeline_layer_id, Some(2));
        assert!(runtime.timeline_layers.iter().all(|layer| layer.id != 0));

        assert!(runtime.remove_timeline_layer_state(1, None).is_err());
        runtime.remove_timeline_layer_state(1, Some(3)).unwrap();
        assert_eq!(
            runtime.timeline_video_automations[0].timeline_layer_id,
            Some(3)
        );
        assert!(runtime.timeline_layers.iter().all(|layer| layer.id != 1));
    }

    #[test]
    fn timeline_layer_reassignment_preserves_automation_lane_identity_and_rolls_back() {
        let mut runtime = runtime_with_lfo_effects(&[]);
        runtime.timeline_layers = vec![
            timeline_test_layer(10, 0, false, false, false, TimelineLayerKind::Lighting),
            timeline_test_layer(11, 1, false, false, false, TimelineLayerKind::Lighting),
            timeline_test_layer(20, 2, false, false, false, TimelineLayerKind::Video),
            timeline_test_layer(21, 3, false, false, false, TimelineLayerKind::Video),
        ];
        runtime.timeline_automations = vec![RuntimeTimelineAutomation {
            id: 501,
            fixture_id: 1,
            attribute: "Dimmer".to_string(),
            track: TimelineTrackKind::Lighting,
            timeline_layer_id: Some(10),
            keyframes: Vec::new(),
            enabled: true,
        }];
        runtime.timeline_video_automations = vec![RuntimeTimelineVideoAutomation {
            id: 502,
            layer_id: 1,
            timeline_layer_id: Some(20),
            param: VideoParam::Opacity,
            track: TimelineTrackKind::Video,
            keyframes: Vec::new(),
            enabled: true,
        }];
        runtime.timeline_video_clips = vec![TimelineVideoClipSummary {
            id: TimelineVideoClipId(503),
            layer_id: 20,
            media_asset_id: 1,
            start_ms: 0,
            offset_ms: 0,
            duration_ms: 1_000,
            fade_in_ms: 0,
            fade_out_ms: 0,
        }];

        let kind_error = runtime
            .update_timeline_layer_state(timeline_test_layer(
                10,
                0,
                false,
                false,
                false,
                TimelineLayerKind::Video,
            ))
            .unwrap_err();
        assert!(kind_error.contains("Lighting automation"));
        let target_error = runtime
            .remove_timeline_layer_state(10, Some(21))
            .unwrap_err();
        assert!(target_error.contains("Lighting automation"));
        assert_eq!(runtime.timeline_automations[0].timeline_layer_id, Some(10));

        let lighting_before = runtime.timeline_automations.clone();
        let published = RwLock::new(runtime.build_snapshot(0));
        runtime.fail_next_pending_publication = true;
        let (ack, receiver) = mpsc::sync_channel(1);
        runtime.apply_command(EngineCommand::RemoveTimelineLayer {
            layer_id: 10,
            reassign_to_layer_id: Some(11),
            expires_at: Instant::now() + Duration::from_secs(1),
            ack,
        });
        runtime.publish_pending_command_acks(0, &published);
        assert!(receiver.recv().unwrap().is_err());
        assert!(runtime.timeline_layers.iter().any(|layer| layer.id == 10));
        assert_eq!(
            runtime
                .timeline_automations
                .iter()
                .map(|automation| automation.timeline_layer_id)
                .collect::<Vec<_>>(),
            lighting_before
                .iter()
                .map(|automation| automation.timeline_layer_id)
                .collect::<Vec<_>>()
        );

        runtime.remove_timeline_layer_state(10, Some(11)).unwrap();
        assert_eq!(runtime.timeline_automations[0].timeline_layer_id, Some(11));
        assert!(runtime.timeline_layers.iter().all(|layer| layer.id != 10));

        runtime.remove_timeline_layer_state(20, Some(21)).unwrap();
        assert_eq!(runtime.timeline_video_automations[0].layer_id, 1);
        assert_eq!(
            runtime.timeline_video_automations[0].timeline_layer_id,
            Some(21)
        );
        assert_eq!(runtime.timeline_video_clips[0].layer_id, 21);
        assert!(runtime.timeline_layers.iter().all(|layer| layer.id != 20));
    }

