    fn super_scene_test_runtime(rate: f32) -> EngineRuntime {
        let child = ChildTimelineSummary {
            events: vec![
                TimelineCueEventSummary {
                    id: 201,
                    cue_id: 2,
                    time_ms: 0,
                    track: TimelineTrackKind::Lighting,
                    duration_ms: 4_000,
                    ..TimelineCueEventSummary::default()
                },
                TimelineCueEventSummary {
                    id: 202,
                    cue_id: 3,
                    time_ms: 2_000,
                    track: TimelineTrackKind::Lighting,
                    ..TimelineCueEventSummary::default()
                },
            ],
            duration_ms: 4_000,
            ..ChildTimelineSummary::default()
        };
        let cues = [
            CueSummary {
                id: 1,
                label: "Super".to_string(),
                child_timeline: Some(child),
                ..CueSummary::default()
            },
            CueSummary {
                id: 2,
                label: "Child zero".to_string(),
                ..CueSummary::default()
            },
            CueSummary {
                id: 3,
                label: "Child two".to_string(),
                ..CueSummary::default()
            },
        ];
        let mut runtime = EngineRuntime::new(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        runtime.cues = cues.iter().map(runtime_cue_from_summary).collect();
        // The parent event targets the explicit legacy lane identity, so the
        // seeded current-schema image must carry that layer entry for its
        // references to stay raw-integrity valid.
        runtime.timeline_layers = vec![TimelineLayerSummary {
            id: 0,
            label: "Legacy Lane".to_string(),
            order: 0,
            muted: false,
            locked: false,
            solo: false,
            expanded: false,
            kind: TimelineLayerKind::Lighting,
        }];
        let mut parent = timeline_test_event(100, 1, 10_000, 0, 5_000, 1);
        parent.rate = Some(rate);
        runtime.timeline_events = vec![parent];
        runtime.rebuild_effect_activations(Instant::now());
        runtime
    }

    #[test]
    fn child_timeline_fires_at_absolute_parent_times_including_rate_two() {
        for (rate, second_parent_time) in [(1.0, 12_000), (2.0, 11_000)] {
            let mut runtime = super_scene_test_runtime(rate);
            runtime.timeline_playing = true;
            runtime.timeline_position_ms = 9_999;
            runtime.last_tick_interval = Duration::from_millis(1);
            runtime.advance_timeline(Instant::now());
            assert_eq!(runtime.timeline_position_ms, 10_000);
            assert_eq!(runtime.active_cue_id, Some(2));

            runtime.last_tick_interval =
                Duration::from_millis(second_parent_time - runtime.timeline_position_ms);
            runtime.advance_timeline(Instant::now());
            assert_eq!(runtime.timeline_position_ms, second_parent_time);
            assert_eq!(runtime.active_cue_id, Some(3));
        }
    }

    #[test]
    fn child_timeline_audio_uses_published_transport_position_and_derives_legacy_clip_zero() {
        let mut snapshot = super_scene_test_runtime(2.0).build_persistence_snapshot();
        snapshot.timeline.playing = true;
        snapshot.timeline.position_ms = 10_500;
        snapshot.timeline.active_child_transports = vec![ChildTimelineTransportRuntimeSummary {
            owner_cue_id: 1,
            root: ChildTimelineTransportRootSummary::Timeline {
                parent_event_id: 100,
                parent_iteration: 0,
            },
            path: Vec::new(),
            position_ms: 1_000,
        }];
        let child = snapshot.cues[0].child_timeline.as_mut().unwrap();
        child.layers = vec![timeline_test_layer(
            50,
            0,
            false,
            false,
            false,
            TimelineLayerKind::Audio,
        )];
        let mut clip = timeline_test_audio_clip(77, 50);
        clip.start_ms = 750;
        clip.duration_ms = 500;
        child.audio_clips = vec![clip];

        let mapped = child_timeline_audio_runtime_clips(&snapshot);
        assert_eq!(mapped.len(), 1);
        assert_eq!(
            mapped[0].root,
            ChildTimelineAudioRuntimeRoot::Timeline {
                parent_event_id: 100,
                parent_iteration: 0,
            }
        );
        assert_eq!(mapped[0].position_ms, 1_000);
        assert_eq!(mapped[0].clip.id, 77);

        let child = snapshot.cues[0].child_timeline.as_mut().unwrap();
        child.audio_clips.clear();
        child.audio = Some(AudioAnalysisSummary {
            path: "C:/media/legacy-child.wav".to_string(),
            sample_rate: 48_000,
            channels: 2,
            duration_ms: 2_000,
            estimated_bpm: None,
            waveform: Vec::new(),
            spectrum: Vec::new(),
            beats: Vec::new(),
        });
        let legacy = child_timeline_audio_runtime_clips(&snapshot);
        assert_eq!(legacy.len(), 1);
        assert_eq!(legacy[0].clip.id, 0);
        assert_eq!(legacy[0].clip.path, "C:/media/legacy-child.wav");

        snapshot.cues[0].child_timeline.as_mut().unwrap().layers[0].muted = true;
        assert!(child_timeline_audio_runtime_clips(&snapshot).is_empty());
        snapshot.cues[0].child_timeline.as_mut().unwrap().layers[0].muted = false;
        {
            let child = snapshot.cues[0].child_timeline.as_mut().unwrap();
            child.layers.push(timeline_test_layer(
                49,
                9,
                false,
                false,
                false,
                TimelineLayerKind::Audio,
            ));
        }
        let stable = child_timeline_audio_runtime_clips(&snapshot);
        assert_eq!(stable[0].clip.layer_id, 49);
        {
            let layers = &mut snapshot.cues[0].child_timeline.as_mut().unwrap().layers;
            layers[0].order = 100;
            layers[1].order = 0;
        }
        assert_eq!(
            child_timeline_audio_runtime_clips(&snapshot)[0]
                .clip
                .layer_id,
            49
        );
        snapshot.cues[0]
            .child_timeline
            .as_mut()
            .unwrap()
            .layers
            .clear();
        let implicit = child_timeline_audio_runtime_clips(&snapshot);
        assert_eq!(implicit[0].clip.layer_id, LEGACY_AUDIO_TIMELINE_LAYER_ID);
        snapshot.cues[1].child_timeline = Some(ChildTimelineSummary::default());
        assert_eq!(
            child_timeline_audio_runtime_clips(&snapshot).len(),
            1,
            "a valid nested child must not suppress its parent's audio"
        );
    }

    #[test]
    fn child_timeline_audio_uses_audio_only_mute_solo_and_ignores_lane_reorder() {
        let mut snapshot = super_scene_test_runtime(1.0).build_persistence_snapshot();
        snapshot.timeline.active_child_transports = vec![ChildTimelineTransportRuntimeSummary {
            owner_cue_id: 1,
            root: ChildTimelineTransportRootSummary::Timeline {
                parent_event_id: 100,
                parent_iteration: 0,
            },
            path: Vec::new(),
            position_ms: 1_000,
        }];
        let child = snapshot.cues[0].child_timeline.as_mut().unwrap();
        child.layers = vec![
            timeline_test_layer(50, 0, false, false, false, TimelineLayerKind::Audio),
            timeline_test_layer(51, 1, false, false, false, TimelineLayerKind::Audio),
            timeline_test_layer(52, 2, false, false, true, TimelineLayerKind::Video),
        ];
        let mut first = timeline_test_audio_clip(77, 50);
        first.start_ms = 750;
        first.duration_ms = 500;
        let mut second = timeline_test_audio_clip(78, 51);
        second.start_ms = 750;
        second.duration_ms = 500;
        child.audio_clips = vec![first, second];

        let ids = |snapshot: &EngineSnapshot| {
            child_timeline_audio_runtime_clips(snapshot)
                .into_iter()
                .map(|child| child.clip.id)
                .collect::<Vec<_>>()
        };
        assert_eq!(ids(&snapshot), vec![77, 78]);

        snapshot.cues[0].child_timeline.as_mut().unwrap().layers[0].muted = true;
        assert_eq!(ids(&snapshot), vec![78]);

        {
            let layers = &mut snapshot.cues[0].child_timeline.as_mut().unwrap().layers;
            layers[0].muted = false;
            layers[1].solo = true;
        }
        assert_eq!(ids(&snapshot), vec![78]);

        snapshot.cues[0].child_timeline.as_mut().unwrap().layers[0].solo = true;
        assert_eq!(ids(&snapshot), vec![77, 78]);

        {
            let layers = &mut snapshot.cues[0].child_timeline.as_mut().unwrap().layers;
            layers[0].solo = false;
            layers[1].solo = false;
            layers[0].order = 10;
            layers[1].order = 0;
        }
        assert_eq!(ids(&snapshot), vec![77, 78]);
    }

